fn main() {
    // Forward Cargo's `TARGET` env var into the compiled binary so the
    // runtime can locate dev-mode sidecars at
    // `apps/tauri/src-tauri/binaries/<name>-<TARGET>`. Tauri 2's bundler
    // strips the target-triple suffix in prod, but `tauri dev` doesn't —
    // and `app.shell().sidecar(name)` doesn't expose the resolved path
    // back to the caller, so we recompute it.
    println!(
        "cargo:rustc-env=BUILD_TARGET={}",
        std::env::var("TARGET").unwrap_or_else(|_| "unknown".into())
    );
    tauri_build::build()
}

// SpiritStream Desktop — Tauri 2 shell.
//
// `main.rs` is a 3-line entrypoint; everything wireable lives here so
// the iOS / Android shells (which can't have a `main` of their own) can
// call `run()` from their `mobile_entry_point`-marked function.

mod server;
mod settings;
mod updater;

use tauri::{AppHandle, Manager, RunEvent};
use tauri_plugin_log::{Target, TargetKind};

use server::{launch, ServerProcess};
use updater::updater_supported;

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_http::init())
        .plugin(tauri_plugin_shell::init())
        .plugin(tauri_plugin_fs::init())
        .plugin(tauri_plugin_dialog::init())
        // App self-update via GitHub Releases. The plugin verifies each
        // `.sig` file (locally signed by the maintainer) against the
        // `pubkey` embedded in `tauri.conf.json`. Linux .deb / .rpm
        // installs opt out at the UI layer via `updater_supported`;
        // the plugin itself is always registered so any platform can
        // call into it.
        .plugin(tauri_plugin_updater::Builder::new().build())
        .plugin(tauri_plugin_process::init())
        // Global system-wide hotkeys (panic shortcut). The frontend
        // registers / unregisters bindings via the JS side of the
        // plugin; this initializer just exposes the OS hook so the
        // shortcut fires even when SpiritStream isn't focused.
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .manage(ServerProcess::new())
        .invoke_handler(tauri::generate_handler![updater_supported])
        .setup(|app| {
            let mut targets = vec![
                Target::new(TargetKind::LogDir {
                    file_name: Some("spiritstream".to_string()),
                }),
                Target::new(TargetKind::Webview),
            ];
            if cfg!(debug_assertions) {
                targets.push(Target::new(TargetKind::Stdout));
            }
            app.handle().plugin(
                tauri_plugin_log::Builder::default()
                    .level(log::LevelFilter::Info)
                    .targets(targets)
                    .build(),
            )?;

            // No window declared in `tauri.conf.json` — we build it
            // programmatically in `server::launch`, AFTER the backend's
            // TCP socket is accepting connections. This is the only
            // architecture in Tauri 2 that prevents the React bundle
            // from executing before the backend exists: `visible: false`
            // doesn't stop JS execution (per Tauri issues #5583, #7669,
            // #10950), and there is no `navigate_later` API. The
            // webview must not exist at all until the gate passes.
            launch(app.handle());

            log::info!("SpiritStream Desktop initialized");

            Ok(())
        })
        .build(tauri::generate_context!())
        .expect("error while building tauri application")
        .run(handle_run_event);
}

fn handle_run_event(app_handle: &AppHandle, event: RunEvent) {
    if let RunEvent::Exit = event {
        log::info!("SpiritStream Desktop exiting");
        if let Some(server_state) = app_handle.try_state::<ServerProcess>() {
            server_state.kill_on_exit();
        }
    }
}

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    spiritstream_desktop_lib::run();
}

use std::{env, sync::Mutex, time::Duration};
use tauri::{image::Image, AppHandle, Emitter, Manager, Runtime};
use tauri_plugin_shell::{
    process::{CommandChild, CommandEvent},
    ShellExt,
};

use crate::settings::load_settings;

const DEFAULT_HOST: &str = "127.0.0.1";
const DEFAULT_PORT: &str = "8008";

/// Holds the server child process so we can kill it on exit. Managed
/// by Tauri as application state; `kill_on_exit` is invoked from the
/// `RunEvent::Exit` handler in `lib.rs`.
pub struct ServerProcess(pub Mutex<Option<CommandChild>>);

impl ServerProcess {
    pub fn new() -> Self {
        Self(Mutex::new(None))
    }

    pub fn kill_on_exit(&self) {
        match self.0.lock() {
            Ok(mut guard) => {
                if let Some(child) = guard.take() {
                    log::info!("Terminating backend server process");
                    if let Err(e) = child.kill() {
                        log::warn!("Failed to kill server process: {e}");
                    }
                }
            }
            Err(e) => log::error!(
                "ServerProcess lock poisoned — sidecar may not be killed and could leak as a zombie: {e}"
            ),
        }
    }
}

/// Spawn the backend launcher off the Tauri runtime. Caller-side fire-
/// and-forget; errors during boot are logged and surfaced to the
/// webview via the `server-error` event.
pub fn launch<R: Runtime>(app: &AppHandle<R>) {
    let app_handle = app.clone();
    tauri::async_runtime::spawn(async move {
        if let Err(error) = run_launcher(&app_handle).await {
            log::error!("Launcher failed: {error}");
        }
    });
}

async fn run_launcher<R: Runtime>(app: &AppHandle<R>) -> Result<(), String> {
    let settings = load_settings(app).unwrap_or_default();

    // Bind args (host/port/token) are resolved server-side from the
    // active profile's `settings.backend` (`crates/transport-http/src/lib.rs`
    // ~2403). The shell never invents host/port/token defaults; the
    // server owns that decision exclusively. Operator overrides via
    // `SPIRITSTREAM_HOST` / `SPIRITSTREAM_PORT` / `SPIRITSTREAM_API_TOKEN`
    // in the launcher's parent environment are inherited by the
    // spawned child automatically (process-default env-var inheritance).
    //
    // The webview always loads from `127.0.0.1:8008` regardless of
    // server bind: the CSP allow-list in `tauri.conf.json` hardcodes
    // that origin, and the server always answers on localhost too —
    // toggling "Allow remote web access" widens the bind from
    // `127.0.0.1:8008` to `0.0.0.0:8008`, never moves the port.
    let host = DEFAULT_HOST;
    let port = DEFAULT_PORT;

    kill_existing_servers();

    #[cfg(desktop)]
    spawn_server(app)?;
    #[cfg(not(desktop))]
    {
        let _ = app; // mobile: server is linked in-process; nothing to spawn.
        log::info!("Mobile build: skipping sidecar spawn (server linked in-process)");
    }

    // Wait until the server's TCP socket is accepting connections. The
    // webview is NOT created yet — the React bundle is not running and
    // cannot fire any HTTP requests. Once this returns, we build the
    // window programmatically; React mounts knowing the backend is
    // reachable, and `/api/v1/ready` either returns 200 immediately
    // (fast path) or long-polls until services finish initializing.
    //
    // This ordering is the entire reason there are no console errors
    // during boot: nothing in the webview exists to make a failed
    // request. Tauri's `visible: false` does not provide this guarantee
    // (issues #5583 / #7669 / #10950) — only deferred window creation
    // does.
    wait_for_tcp_listening(host, port).await;

    // Build the main webview window. `WebviewUrl::default()` resolves
    // to `App("index.html".into())`, which Tauri swaps to the dev URL
    // (`http://localhost:1420`) in `tauri dev` and to the bundled SPA
    // in release. Same call site, both modes.
    let window = match tauri::WebviewWindowBuilder::new(
        app,
        "main",
        tauri::WebviewUrl::default(),
    )
    .title("SpiritStream")
    .inner_size(1500.0, 1000.0)
    .min_inner_size(1024.0, 600.0)
    .resizable(true)
    .center()
    .background_color(tauri::utils::config::Color(0x0F, 0x0A, 0x14, 0xFF))
    .build()
    {
        Ok(w) => w,
        Err(e) => return Err(format!("failed to create main window: {e}")),
    };

    let icon_bytes = include_bytes!("../icons/icon.png").to_vec();
    if let Ok(icon) = Image::from_bytes(&icon_bytes) {
        if let Err(e) = window.set_icon(icon) {
            log::warn!("Failed to set window icon: {e}");
        }
    }

    if settings.start_minimized {
        if let Err(e) = window.minimize() {
            log::warn!("Failed to minimize window: {e}");
        }
        log::info!("Window minimized per user settings");
    }

    log::info!("Main window created — backend was reachable when bundle loaded");
    Ok(())
}

/// Spawn the bundled `spiritstream-server` sidecar. Desktop only —
/// J1: iOS/Android Tauri 2 builds cannot host an out-of-process
/// sidecar (mobile sandbox + signing constraints), so the
/// `tauri-plugin-shell` `sidecar(...)` call is unavailable on those
/// targets. Mobile clients must link `spiritstream-core` directly and
/// bind Axum in-process (the mobile shell entry point handles this).
/// Compiling this for mobile would fail link-time on the missing
/// sidecar binary anyway.
#[cfg(desktop)]
fn spawn_server<R: Runtime>(app: &AppHandle<R>) -> Result<(), String> {
    // `SPIRITSTREAM_SERVER_PATH` lets the dev iteration loop point at a
    // freshly-rebuilt server binary outside the bundle. In RELEASE
    // builds this would be a privilege-escalation vector: anyone who
    // can set the user's env (compromised shell-rc, supply chain,
    // shared host) could replace the backend binary the next time
    // SpiritStream launched. Gate behind debug_assertions so release
    // builds always use the bundled, signed sidecar.
    #[cfg(debug_assertions)]
    let mut command = if let Ok(server_path) = env::var("SPIRITSTREAM_SERVER_PATH") {
        log::warn!(
            "SPIRITSTREAM_SERVER_PATH={server_path} overriding bundled sidecar — debug build only"
        );
        app.shell().command(server_path)
    } else {
        app.shell()
            .sidecar("spiritstream-server")
            .map_err(|e| e.to_string())?
    };
    #[cfg(not(debug_assertions))]
    let mut command = app
        .shell()
        .sidecar("spiritstream-server")
        .map_err(|e| e.to_string())?;

    // Local AppData (not Roaming) keeps everything in one machine-
    // specific location that doesn't sync; profiles / settings don't
    // need to follow the user across domain machines.
    let app_data_dir = app
        .path()
        .app_local_data_dir()
        .map_err(|e| format!("Failed to resolve app local data dir: {e}"))?;
    let log_dir = app_data_dir.join("logs");

    std::fs::create_dir_all(&app_data_dir).ok();
    std::fs::create_dir_all(&log_dir).ok();

    let themes_dir = resolve_themes_dir(app);

    if env::var("SPIRITSTREAM_DATA_DIR").is_err() {
        command = command.env("SPIRITSTREAM_DATA_DIR", &app_data_dir);
    }
    if env::var("SPIRITSTREAM_LOG_DIR").is_err() {
        command = command.env("SPIRITSTREAM_LOG_DIR", &log_dir);
    }
    if env::var("SPIRITSTREAM_THEMES_DIR").is_err() {
        if let Some(themes) = &themes_dir {
            command = command.env("SPIRITSTREAM_THEMES_DIR", themes);
        }
    }
    // SPIRITSTREAM_HOST / SPIRITSTREAM_PORT / SPIRITSTREAM_API_TOKEN
    // are deliberately NOT set here. The server resolves bind args
    // from the active profile's `settings.backend` — injecting env-var
    // defaults from the shell would silently override that resolution
    // and was the root cause of remote-access being silently broken
    // pre-fix. Operator overrides in the parent launcher's environment
    // still propagate via standard env-var inheritance to the child.

    if env::var("SPIRITSTREAM_UI_DIR").is_err() {
        if let Ok(resource_dir) = app.path().resource_dir() {
            let dist_dir = resource_dir.join("dist");
            if dist_dir.exists() {
                command = command.env("SPIRITSTREAM_UI_DIR", dist_dir);
            }
        }
    }

    // Tauri 2 sidecar FFmpeg (Option A — no runtime download).
    //
    // On macOS / Windows the build pipeline fetches FFmpeg from the
    // ffmpeg.org-recommended source (evermeet.cx / BtbN) and places it
    // at `binaries/ffmpeg-<TARGET>(.exe)`. The bundler copies that into
    // the .app / install dir alongside `spiritstream-server`.
    //
    // On Linux the placeholder file is empty — the .deb / .rpm
    // dependency on `ffmpeg` delivers the binary, and the server falls
    // through to `$PATH` lookup. We detect the placeholder by file size
    // in `resolve_ffmpeg_sidecar` and skip the env injection.
    if env::var("SPIRITSTREAM_FFMPEG_PATH").is_err() {
        match resolve_ffmpeg_sidecar() {
            Some(path) => {
                log::info!("Injecting bundled FFmpeg sidecar path: {path:?}");
                command = command.env("SPIRITSTREAM_FFMPEG_PATH", &path);
            }
            None => {
                log::info!(
                    "No bundled FFmpeg sidecar resolved (placeholder, missing, or unknown target); \
                     server will look up `ffmpeg` on $PATH (Linux distro dep or `brew install`)."
                );
            }
        }
    }

    let (mut rx, child) = command.spawn().map_err(|e| {
        log::error!("Failed to spawn server: {e}");
        format!("Failed to spawn server: {e}")
    })?;

    if let Some(server_state) = app.try_state::<ServerProcess>() {
        if let Ok(mut guard) = server_state.0.lock() {
            *guard = Some(child);
        }
    }

    let app_handle = app.clone();
    tauri::async_runtime::spawn(async move {
        let mut startup_errors: Vec<String> = Vec::new();
        let mut terminated_early = false;

        while let Some(event) = rx.recv().await {
            match event {
                CommandEvent::Stdout(line) => {
                    let msg = String::from_utf8_lossy(&line);
                    log::info!("[server] {}", msg);
                }
                CommandEvent::Stderr(line) => {
                    let msg = String::from_utf8_lossy(&line).to_string();
                    log::warn!("[server] {}", msg);
                    startup_errors.push(msg);
                }
                CommandEvent::Error(error) => {
                    log::error!("[server] {error}");
                    startup_errors.push(error.clone());
                }
                CommandEvent::Terminated(payload) => {
                    log::error!(
                        "[server] terminated unexpectedly (code: {:?}, signal: {:?})",
                        payload.code,
                        payload.signal
                    );
                    terminated_early = true;

                    let error_msg = if startup_errors.is_empty() {
                        format!(
                            "Server process terminated with code {:?}",
                            payload.code.unwrap_or(-1)
                        )
                    } else {
                        startup_errors.join("\n")
                    };

                    let _ = app_handle.emit("server-error", &error_msg);
                    log::error!("Server startup failed: {}", error_msg);
                    break;
                }
                _ => {}
            }
        }

        if terminated_early {
            log::error!("Server terminated during startup - check logs for details");
        }
    });

    Ok(())
}

fn has_theme_files(dir: &std::path::Path) -> bool {
    std::fs::read_dir(dir)
        .map(|entries| {
            entries.flatten().any(|entry| {
                entry
                    .path()
                    .extension()
                    .map(|ext| ext == "jsonc" || ext == "json")
                    .unwrap_or(false)
            })
        })
        .unwrap_or(false)
}

fn count_theme_files(dir: &std::path::Path) -> usize {
    std::fs::read_dir(dir)
        .map(|entries| {
            entries
                .flatten()
                .filter(|entry| {
                    entry
                        .path()
                        .extension()
                        .map(|ext| ext == "jsonc" || ext == "json")
                        .unwrap_or(false)
                })
                .count()
        })
        .unwrap_or(0)
}

/// Locate the themes directory. Bundled resources first; on dev a chain
/// of relative-path candidates anchored at the current working dir
/// covers `pnpm dev:desktop` (apps/tauri) and `cargo run -p
/// spiritstream-desktop` (apps/tauri/src-tauri) launch contexts.
fn resolve_themes_dir<R: Runtime>(app: &AppHandle<R>) -> Option<std::path::PathBuf> {
    let bundled = app.path().resource_dir().ok().map(|dir| dir.join("themes"));

    if let Some(ref path) = bundled {
        log::info!("Checking bundled themes at: {:?}", path);
        log::info!("  exists: {}, is_dir: {}", path.exists(), path.is_dir());

        if path.exists() {
            let count = count_theme_files(path);
            log::info!("  theme files found: {}", count);

            if let Ok(entries) = std::fs::read_dir(path) {
                let files: Vec<_> = entries
                    .flatten()
                    .map(|e| e.file_name().to_string_lossy().to_string())
                    .collect();
                log::info!("  contents: {:?}", files);
            }
        }
    }

    if bundled
        .as_ref()
        .map(|p| p.exists() && has_theme_files(p))
        .unwrap_or(false)
    {
        log::info!("Using bundled themes directory");
        return bundled;
    }

    let cwd = std::env::current_dir().ok();
    let cwd_themes = cwd.as_ref().map(|d| d.join("themes"));
    if cwd_themes.as_ref().map(|p| has_theme_files(p)).unwrap_or(false) {
        log::info!("Using CWD themes directory: {:?}", cwd_themes);
        return cwd_themes;
    }

    let parent_themes = cwd
        .as_ref()
        .and_then(|d| d.join("../../themes").canonicalize().ok());
    if parent_themes
        .as_ref()
        .map(|p| has_theme_files(p))
        .unwrap_or(false)
    {
        log::info!("Using parent themes directory: {:?}", parent_themes);
        return parent_themes;
    }

    let grandparent_themes = cwd
        .as_ref()
        .and_then(|d| d.join("../../../themes").canonicalize().ok());
    if grandparent_themes
        .as_ref()
        .map(|p| has_theme_files(p))
        .unwrap_or(false)
    {
        log::info!("Using grandparent themes directory: {:?}", grandparent_themes);
        return grandparent_themes;
    }

    log::warn!("No themes directory found with theme files!");
    log::warn!("  Tried bundled: {:?}", bundled);
    log::warn!("  Tried CWD: {:?}", cwd_themes);
    log::warn!("  Tried parent: {:?}", parent_themes);
    log::warn!("  Tried grandparent: {:?}", grandparent_themes);
    bundled
}

/// Resolve the FFmpeg sidecar path for both `tauri dev` and packaged builds.
/// Returns `None` when the resolved path is missing OR a zero-byte placeholder
/// (Linux `.deb` / `.rpm` ships placeholders because the distro `ffmpeg` package
/// supplies the real binary).
///
/// **Debug builds prefer the dev path first.** `tauri build` leaves a stale
/// `target/debug/ffmpeg` next to the dev exe when run on the same workspace
/// (the bundler renames sidecars in place during packaging, and `cargo clean`
/// is the only thing that removes them). If the dev resolver checked
/// `target/debug/ffmpeg` first, it would resolve to that stale copy — which
/// might be the wrong architecture, an outdated version, or otherwise
/// mismatched against the suffixed sidecar in `binaries/`. So in debug we
/// check the target-triple-suffixed sidecar first.
///
/// **Release builds prefer the bundled path** next to the exe — that's where
/// Tauri's installer lands the renamed sidecar. `BUILD_TARGET` is injected by
/// `build.rs` from Cargo's `TARGET` env var (still used for fallback in case
/// a release-build user manually places a suffixed binary).
fn resolve_ffmpeg_sidecar() -> Option<std::path::PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let exe_dir = exe.parent()?;

    let bundled_name = if cfg!(windows) { "ffmpeg.exe" } else { "ffmpeg" };
    let target_triple: &str = env!("BUILD_TARGET");
    let dev_name = if cfg!(windows) {
        format!("ffmpeg-{target_triple}.exe")
    } else {
        format!("ffmpeg-{target_triple}")
    };

    let workspace_root_candidate = exe_dir.parent().and_then(|p| p.parent());
    let dev_candidate = workspace_root_candidate.map(|root| {
        root.join("apps")
            .join("tauri")
            .join("src-tauri")
            .join("binaries")
            .join(&dev_name)
    });

    let prod_candidate = exe_dir.join(bundled_name);

    let order: [&Option<std::path::PathBuf>; 2] = if cfg!(debug_assertions) {
        [&dev_candidate, &Some(prod_candidate.clone())]
    } else {
        [&Some(prod_candidate.clone()), &dev_candidate]
    };
    for candidate in order {
        let Some(path) = candidate.as_ref() else { continue };
        let Ok(meta) = std::fs::metadata(path) else { continue };
        if meta.is_file() && meta.len() > 0 {
            return Some(path.clone());
        }
    }
    None
}

/// Kill any zombie spiritstream-server processes from previous runs to
/// avoid port conflicts. Unix uses `pkill -f`; Windows uses `taskkill`
/// plus a port-availability re-check loop because taskkill returns
/// before the kernel actually frees the bound port.
fn kill_existing_servers() {
    #[cfg(unix)]
    {
        use std::process::Command;
        let _ = Command::new("pkill")
            .args(["-f", "spiritstream-server"])
            .output();
        std::thread::sleep(Duration::from_millis(1000));
        log::info!("Killed any existing spiritstream-server processes");
    }
    #[cfg(windows)]
    {
        use std::process::Command;
        let result = Command::new("taskkill")
            .args(["/F", "/IM", "spiritstream-server.exe"])
            .output();

        if let Ok(output) = &result {
            if output.status.success() {
                log::info!("Taskkill succeeded for spiritstream-server.exe");
            }
        }

        std::thread::sleep(Duration::from_millis(1500));

        for attempt in 1..=3 {
            if is_port_available(8008) {
                log::info!("Port 8008 is available after {} attempt(s)", attempt);
                break;
            }
            log::warn!("Port 8008 still in use, waiting... (attempt {})", attempt);
            std::thread::sleep(Duration::from_millis(1000));
        }

        log::info!("Killed any existing spiritstream-server processes");
    }
}

#[cfg(windows)]
fn is_port_available(port: u16) -> bool {
    use std::net::TcpListener;
    TcpListener::bind(format!("127.0.0.1:{}", port)).is_ok()
}

/// Wait for the server's TCP socket to be accepting connections.
///
/// Fast (~10–200ms typical, since spawn_server only returns after the
/// child has been fork-execed and the server binds immediately on startup).
/// 5-second worst-case bound; on giveup, the webview will surface the
/// `/api/v1/ready` failure path itself via the React `unreachable` overlay.
///
/// This is the entire shell-side readiness coordination — services
/// initialization is observed *through the server*, not the shell, via the
/// long-poll on `/api/v1/ready`. Single source of readiness truth.
async fn wait_for_tcp_listening(host: &str, port: &str) {
    let addr = format!("{host}:{port}");
    for attempt in 0..50 {
        if tokio::net::TcpStream::connect(&addr).await.is_ok() {
            log::info!("Backend listening at {addr} (attempt {})", attempt + 1);
            return;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    log::warn!(
        "Backend did not begin listening at {addr} within 5s — \
         the webview's /ready long-poll will surface the failure to the user"
    );
}

use serde::{Deserialize, Serialize};
use tauri::{AppHandle, Manager, Runtime};

/// Slim shadow of `crates/core/src/models/Settings` — only the fields
/// the Tauri shell itself needs at launch time. Backend host/port/token
/// live in `ProfileSettings.backend` and are resolved server-side by
/// `crates/transport-http`; the shell never injects them as env vars
/// (it used to, which silently masked the profile-based resolution).
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct Settings {
    #[serde(default)]
    pub start_minimized: bool,
}

pub fn load_settings<R: Runtime>(app: &AppHandle<R>) -> Option<Settings> {
    let app_data_dir = app.path().app_data_dir().ok()?;
    let settings_path = app_data_dir.join("settings.json");

    if !settings_path.exists() {
        return None;
    }

    let content = match std::fs::read_to_string(&settings_path) {
        Ok(c) => c,
        Err(e) => {
            log::warn!("settings: failed to read {settings_path:?}: {e}");
            return None;
        }
    };
    match serde_json::from_str(&content) {
        Ok(settings) => Some(settings),
        Err(e) => {
            // Don't silently reset the user's settings — if the JSON is
            // corrupt (truncated mid-write, hand-edited typo), surface
            // it loud so the operator can decide whether to repair the
            // file vs accept the defaults.
            log::warn!(
                "settings: failed to parse {settings_path:?}, falling back to defaults: {e}"
            );
            None
        }
    }
}

/// Whether the running build supports the self-updater. Returns:
/// - `true` on macOS, Windows, and Linux AppImage installs.
/// - `false` on Linux `.deb` / `.rpm` installs (system package manager
///   owns updates — running our updater there fights the distro and
///   leaves files orphaned in `/usr/...` outside `apt`/`dnf`'s tracking).
///
/// AppImage detection is per appimage.org's runtime contract: the
/// AppImage runtime sets `APPIMAGE` to the mounted .AppImage's absolute
/// path before launching the embedded binary. `.deb`/`.rpm` users never
/// see this env var, so `is_some()` cleanly separates the two install
/// types without heuristics on `argv[0]` paths.
///
/// docs: https://docs.appimage.org/packaging-guide/environment-variables.html
#[tauri::command]
pub fn updater_supported() -> bool {
    #[cfg(target_os = "linux")]
    {
        std::env::var_os("APPIMAGE").is_some()
    }
    #[cfg(not(target_os = "linux"))]
    {
        true
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// Halt the build with a diagnostic that includes the offending file
/// path and the parser/structural detail. M6: pre-fix every read /
/// parse / shape-check used `.expect("…")` which surfaced as a bare
/// rustc panic with no breadcrumb back to `streaming-platforms.json`.
/// `eprintln!` + `process::exit(1)` keeps Cargo happy and gives the
/// operator something to grep.
fn die(prefix: &str, path: &Path, detail: impl std::fmt::Display) -> ! {
    eprintln!(
        "spiritstream-core build.rs: {prefix} ({path}): {detail}",
        path = path.display(),
    );
    std::process::exit(1)
}

fn main() -> ExitCode {
    // Read the streaming platforms JSON (workspace root: ../../data/...).
    let json_path = PathBuf::from("..")
        .join("..")
        .join("data")
        .join("streaming-platforms.json");

    println!("cargo:rerun-if-changed={}", json_path.display());

    let json_content = match fs::read_to_string(&json_path) {
        Ok(s) => s,
        Err(e) => die("Failed to read streaming-platforms.json", &json_path, e),
    };

    let data: serde_json::Value = match serde_json::from_str(&json_content) {
        Ok(v) => v,
        Err(e) => die(
            "Failed to parse streaming-platforms.json (invalid JSON)",
            &json_path,
            format!("line {}, column {}: {}", e.line(), e.column(), e),
        ),
    };

    let services = match data.get("services").and_then(|v| v.as_array()) {
        Some(arr) => arr,
        None => die(
            "Failed to parse streaming-platforms.json",
            &json_path,
            "missing or non-array `services` field",
        ),
    };

    // Generate enum variants
    let mut enum_code = String::from(
        "// Auto-generated from data/streaming-platforms.json\n\
         // DO NOT EDIT MANUALLY\n\n\
         #[allow(clippy::enum_variant_names, clippy::upper_case_acronyms)]\n\
         #[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash, Default, ts_rs::TS)]\n\
         #[ts(export, export_to = \"../../../packages/types/src/generated/\")]\n\
         pub enum Platform {\n",
    );

    let mut variant_counts: HashMap<String, usize> = HashMap::new();
    let mut first_variant: Option<String> = None;

    for service in services {
        let name = match service.get("name").and_then(|v| v.as_str()) {
            Some(s) => s,
            None => die(
                "platform entry missing or non-string `name` field",
                &json_path,
                serde_json::to_string(service).unwrap_or_default(),
            ),
        };

        let default_url = match service.get("defaultUrl").and_then(|v| v.as_str()) {
            Some(s) => s,
            None => die(
                "platform entry missing or non-string `defaultUrl` field",
                &json_path,
                name,
            ),
        };

        let placement = match service.get("streamKeyPlacement").and_then(|v| v.as_str()) {
            Some(s) => s,
            None => die(
                "platform entry missing or non-string `streamKeyPlacement` field",
                &json_path,
                name,
            ),
        };

        // Filter: only include RTMP/RTMPS with "append" or "in_url_template" placement
        if !default_url.starts_with("rtmp://") && !default_url.starts_with("rtmps://") {
            continue;
        }

        if placement != "append" && placement != "in_url_template" {
            continue;
        }

        // Sanitize the name to a valid Rust identifier
        let variant = sanitize_to_variant(name);

        // Handle duplicate variants by appending a number
        let final_variant = if let Some(count) = variant_counts.get(&variant) {
            let new_count = count + 1;
            variant_counts.insert(variant.clone(), new_count);
            format!("{variant}{new_count}")
        } else {
            variant_counts.insert(variant.clone(), 1);
            variant.clone()
        };

        let is_first = first_variant.is_none();
        if is_first {
            first_variant = Some(final_variant.clone());
        }

        if is_first {
            enum_code.push_str(&format!(
                "    #[serde(rename = \"{name}\")]\n    #[default]\n    {final_variant},\n"
            ));
        } else {
            enum_code.push_str(&format!(
                "    #[serde(rename = \"{name}\")]\n    {final_variant},\n"
            ));
        }
    }

    enum_code.push_str("}\n");

    // Write to OUT_DIR. Cargo guarantees OUT_DIR is set when build
    // scripts run; failure to read it is a Cargo-internal issue.
    let out_dir = match env::var("OUT_DIR") {
        Ok(v) => v,
        Err(e) => die(
            "OUT_DIR is not set (cargo invocation broken?)",
            &json_path,
            e,
        ),
    };
    let dest_path = PathBuf::from(out_dir).join("generated_platforms.rs");
    if let Err(e) = fs::write(&dest_path, enum_code) {
        die("Failed to write generated_platforms.rs", &dest_path, e);
    }
    ExitCode::SUCCESS
}

/// Sanitize a platform name to a valid Rust enum variant
/// - Remove special characters
/// - Convert to PascalCase
/// - Ensure it starts with a letter
fn sanitize_to_variant(name: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;

    for ch in name.chars() {
        if ch.is_alphanumeric() {
            if capitalize_next {
                result.push(ch.to_ascii_uppercase());
                capitalize_next = false;
            } else {
                result.push(ch);
            }
        } else {
            // Skip special characters, but capitalize the next letter
            capitalize_next = true;
        }
    }

    // Ensure it starts with a letter
    if result.is_empty() || result.chars().next().unwrap().is_numeric() {
        result.insert(0, 'P');
    }

    result
}

// SpiritStream Commands
// Command handlers for the HTTP server

mod system;

pub use system::*;

//! Encoder discovery — query FFmpeg's `-encoders` list, probe the host
//! GPU, and emit an `Encoders` snapshot. Empty list when FFmpeg isn't
//! installed (discovery, not execution: `CoreError::FfmpegNotFound`
//! lives on the start-stream path).

use std::process::Command;

use crate::errors::CoreError;
use crate::models::{EncoderKind, EncoderMeta, Encoders};

use super::{find_ffmpeg, hide_console};

/// Get available video and audio encoders by querying FFmpeg and hardware.
///
/// This is a *discovery* endpoint. When FFmpeg isn't installed the honest
/// answer is "no encoders available" — an empty result, not an error.
/// Distinguishes from *execution* paths (start stream, test encoder) where
/// FFmpeg-missing is a hard failure that surfaces `CoreError::FfmpegNotFound`.
/// Frontend uses `/system/ffmpeg/test` to detect installation status; this
/// endpoint just enumerates what's available given the current install.
pub fn get_encoders() -> Result<Encoders, CoreError> {
    let ffmpeg_path = find_ffmpeg();
    let mut cmd = Command::new(&ffmpeg_path);
    cmd.args(["-encoders", "-hide_banner"]);
    hide_console(&mut cmd);
    let output = match cmd.output() {
        Ok(out) => out,
        Err(err) => {
            log::warn!("FFmpeg not available for encoder discovery: {err}");
            return Ok(Encoders::default());
        }
    };
    if !output.status.success() {
        return Ok(Encoders::default());
    }
    let encoder_list = String::from_utf8_lossy(&output.stdout);

    let (has_nvidia, has_amd, has_intel) = detect_gpus();
    let (video, audio) = select_encoders(&encoder_list, has_nvidia, has_amd, has_intel);

    let mut metadata = std::collections::HashMap::new();
    for name in video.iter().chain(audio.iter()) {
        metadata.insert(name.clone(), classify(name));
    }

    Ok(Encoders {
        video,
        audio,
        metadata,
    })
}

/// Filters FFmpeg's `-encoders` listing into the (video, audio) encoder names
/// SpiritStream offers, gating hardware encoders on the detected GPU vendors.
/// Pure — `get_encoders` owns the FFmpeg + GPU probe I/O. Always yields at
/// least `libx264` / `aac` so the UI never shows an empty encoder picker.
fn select_encoders(
    encoder_list: &str,
    has_nvidia: bool,
    has_amd: bool,
    has_intel: bool,
) -> (Vec<String>, Vec<String>) {
    let mut video = Vec::new();
    let mut audio = Vec::new();

    for (name, vendor) in video_encoder_table().iter() {
        if encoder_list.contains(*name) {
            match *vendor {
                None => video.push((*name).to_string()),
                Some("nvidia") if has_nvidia => video.push((*name).to_string()),
                Some("amd") if has_amd => video.push((*name).to_string()),
                Some("intel") if has_intel => video.push((*name).to_string()),
                Some("vaapi") if has_amd || has_intel => video.push((*name).to_string()),
                Some("apple") if cfg!(target_os = "macos") => video.push((*name).to_string()),
                _ => {}
            }
        }
    }

    let audio_encoder_names = ["aac", "libmp3lame", "libopus"];
    for name in audio_encoder_names.iter() {
        if encoder_list.contains(*name) {
            audio.push((*name).to_string());
        }
    }

    if video.is_empty() {
        video.push("libx264".to_string());
    }
    if audio.is_empty() {
        audio.push("aac".to_string());
    }

    (video, audio)
}

/// Per-OS GPU probe. Returns `(has_nvidia, has_amd, has_intel)`.
fn detect_gpus() -> (bool, bool, bool) {
    let mut has_nvidia = false;
    let mut has_amd = false;
    let mut has_intel = false;

    #[cfg(windows)]
    {
        // Use PowerShell for consistent UTF-8 output (WMIC outputs UTF-16 on some systems)
        let mut ps_cmd = Command::new("powershell");
        ps_cmd.args([
            "-NoProfile",
            "-Command",
            "Get-CimInstance -ClassName Win32_VideoController | Select-Object -ExpandProperty Name",
        ]);
        hide_console(&mut ps_cmd);
        let ps_result = ps_cmd.output();

        // Fall back to WMIC if PowerShell fails
        let gpu_output = match ps_result {
            Ok(output) if output.status.success() => Some(output.stdout),
            _ => {
                let mut wmic_cmd = Command::new("wmic");
                wmic_cmd.args(["path", "win32_VideoController", "get", "name"]);
                hide_console(&mut wmic_cmd);
                wmic_cmd.output().ok().map(|o| o.stdout)
            }
        };

        if let Some(stdout) = gpu_output {
            let gpu_list = String::from_utf8_lossy(&stdout).to_lowercase();
            log::debug!("GPU detection output: {}", gpu_list.trim());

            if gpu_list.contains("nvidia")
                || gpu_list.contains("geforce")
                || gpu_list.contains("quadro")
            {
                has_nvidia = true;
                log::info!("Detected NVIDIA GPU");
            }
            if gpu_list.contains("amd") || gpu_list.contains("radeon") {
                has_amd = true;
                log::info!("Detected AMD GPU");
            }
            if gpu_list.contains("intel") || gpu_list.contains("arc ") {
                has_intel = true;
                log::info!("Detected Intel GPU");
            }
        }
    }
    #[cfg(target_os = "linux")]
    {
        if let Ok(output) = Command::new("lspci").output() {
            if let Ok(gpu_list) = String::from_utf8(output.stdout) {
                let gpu_list = gpu_list.to_lowercase();
                if gpu_list.contains("nvidia") {
                    has_nvidia = true;
                }
                if gpu_list.contains("amd") || gpu_list.contains("radeon") {
                    has_amd = true;
                }
                if gpu_list.contains("intel") {
                    has_intel = true;
                }
            }
        }
    }
    #[cfg(target_os = "macos")]
    {
        if let Ok(output) = Command::new("system_profiler")
            .args(["SPDisplaysDataType"])
            .output()
        {
            if let Ok(gpu_list) = String::from_utf8(output.stdout) {
                let gpu_list = gpu_list.to_lowercase();
                if gpu_list.contains("nvidia") {
                    has_nvidia = true;
                }
                if gpu_list.contains("amd") || gpu_list.contains("radeon") {
                    has_amd = true;
                }
                if gpu_list.contains("intel") {
                    has_intel = true;
                }
            }
        }
    }

    (has_nvidia, has_amd, has_intel)
}

/// Build the video-encoder capability table, with vaapi entries only on
/// Linux (where Mesa exposes the VAAPI runtime by default).
fn video_encoder_table() -> Vec<(&'static str, Option<&'static str>)> {
    #[cfg_attr(not(target_os = "linux"), allow(unused_mut))]
    let mut table: Vec<(&str, Option<&str>)> = vec![
        ("libx264", None),
        ("h264_nvenc", Some("nvidia")),
        ("hevc_nvenc", Some("nvidia")),
        ("av1_nvenc", Some("nvidia")),
        ("h264_amf", Some("amd")),
        ("hevc_amf", Some("amd")),
        ("av1_amf", Some("amd")),
        ("h264_qsv", Some("intel")),
        ("hevc_qsv", Some("intel")),
        ("av1_qsv", Some("intel")),
        ("h264_videotoolbox", Some("apple")),
        ("hevc_videotoolbox", Some("apple")),
        ("av1_videotoolbox", Some("apple")),
    ];
    #[cfg(target_os = "linux")]
    table.extend([
        ("h264_vaapi", Some("vaapi")),
        ("hevc_vaapi", Some("vaapi")),
        ("av1_vaapi", Some("vaapi")),
    ]);
    table
}

/// Classify an encoder name into kind + preset family. Frontend uses
/// this to render the hardware/software badge and to pick the preset
/// list for the codec the user selected, without local substring
/// matching.
fn classify(name: &str) -> EncoderMeta {
    if name == "copy" {
        return EncoderMeta {
            kind: EncoderKind::Passthrough,
            family: String::new(),
        };
    }
    if name == "libx264" {
        return EncoderMeta {
            kind: EncoderKind::Software,
            family: "libx264".to_string(),
        };
    }
    if name == "libx265" {
        return EncoderMeta {
            kind: EncoderKind::Software,
            family: "libx265".to_string(),
        };
    }
    if name.ends_with("_nvenc") {
        return EncoderMeta {
            kind: EncoderKind::Hardware,
            family: "nvenc".to_string(),
        };
    }
    if name.ends_with("_amf") {
        return EncoderMeta {
            kind: EncoderKind::Hardware,
            family: "amf".to_string(),
        };
    }
    if name.ends_with("_qsv") {
        return EncoderMeta {
            kind: EncoderKind::Hardware,
            family: "qsv".to_string(),
        };
    }
    if name.ends_with("_videotoolbox") {
        return EncoderMeta {
            kind: EncoderKind::Hardware,
            family: "videotoolbox".to_string(),
        };
    }
    if name.ends_with("_vaapi") {
        return EncoderMeta {
            kind: EncoderKind::Hardware,
            family: "vaapi".to_string(),
        };
    }
    // Audio encoders and anything unclassified.
    EncoderMeta {
        kind: EncoderKind::Software,
        family: String::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::{classify, select_encoders, video_encoder_table};
    use crate::models::EncoderKind;

    #[test]
    fn classify_passthrough_has_no_family() {
        let meta = classify("copy");
        assert_eq!(meta.kind, EncoderKind::Passthrough);
        assert!(meta.family.is_empty());
    }

    #[test]
    fn classify_software_x264_and_x265() {
        let x264 = classify("libx264");
        assert_eq!(x264.kind, EncoderKind::Software);
        assert_eq!(x264.family, "libx264");

        let x265 = classify("libx265");
        assert_eq!(x265.kind, EncoderKind::Software);
        assert_eq!(x265.family, "libx265");
    }

    #[test]
    fn classify_maps_hardware_suffixes_to_their_family() {
        for (name, family) in [
            ("h264_nvenc", "nvenc"),
            ("hevc_amf", "amf"),
            ("av1_qsv", "qsv"),
            ("h264_videotoolbox", "videotoolbox"),
            ("hevc_vaapi", "vaapi"),
        ] {
            let meta = classify(name);
            assert_eq!(meta.kind, EncoderKind::Hardware, "{name}");
            assert_eq!(meta.family, family, "{name}");
        }
    }

    #[test]
    fn classify_unknown_falls_back_to_software_no_family() {
        let meta = classify("aac");
        assert_eq!(meta.kind, EncoderKind::Software);
        assert!(meta.family.is_empty());
    }

    #[test]
    fn encoder_table_lists_software_x264_with_no_vendor() {
        let table = video_encoder_table();
        let x264 = table
            .iter()
            .find(|(name, _)| *name == "libx264")
            .expect("libx264 present");
        assert_eq!(x264.1, None);
        // Every hardware entry carries a vendor tag.
        for (name, vendor) in table.iter().filter(|(n, _)| *n != "libx264") {
            assert!(vendor.is_some(), "{name} should have a vendor");
        }
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn encoder_table_includes_vaapi_on_linux() {
        let table = video_encoder_table();
        assert!(table.iter().any(|(name, _)| *name == "h264_vaapi"));
    }

    #[test]
    fn select_software_video_and_all_audio_present() {
        let list = "libx264 aac libopus libmp3lame";
        let (video, audio) = select_encoders(list, false, false, false);
        assert_eq!(video, vec!["libx264"]);
        assert!(audio.contains(&"aac".to_string()));
        assert!(audio.contains(&"libopus".to_string()));
        assert!(audio.contains(&"libmp3lame".to_string()));
    }

    #[test]
    fn select_empty_list_falls_back_to_x264_and_aac() {
        let (video, audio) = select_encoders("", false, false, false);
        assert_eq!(video, vec!["libx264"]);
        assert_eq!(audio, vec!["aac"]);
    }

    #[test]
    fn select_gates_nvenc_on_detected_nvidia() {
        let list = "h264_nvenc hevc_nvenc";
        let (without, _) = select_encoders(list, false, false, false);
        // No vendor match + no libx264 in the list → fallback to libx264.
        assert_eq!(without, vec!["libx264"]);

        let (with, _) = select_encoders(list, true, false, false);
        assert!(with.contains(&"h264_nvenc".to_string()));
        assert!(with.contains(&"hevc_nvenc".to_string()));
        assert!(!with.contains(&"libx264".to_string()));
    }

    #[test]
    fn select_gates_amf_on_detected_amd() {
        let list = "h264_amf";
        assert!(!select_encoders(list, false, false, false)
            .0
            .contains(&"h264_amf".to_string()));
        assert!(select_encoders(list, false, true, false)
            .0
            .contains(&"h264_amf".to_string()));
    }

    #[test]
    fn select_gates_qsv_on_detected_intel() {
        let list = "h264_qsv";
        assert!(!select_encoders(list, false, false, false)
            .0
            .contains(&"h264_qsv".to_string()));
        assert!(select_encoders(list, false, false, true)
            .0
            .contains(&"h264_qsv".to_string()));
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn select_gates_vaapi_on_amd_or_intel() {
        let list = "h264_vaapi";
        assert!(!select_encoders(list, false, false, false)
            .0
            .contains(&"h264_vaapi".to_string()));
        assert!(select_encoders(list, false, true, false)
            .0
            .contains(&"h264_vaapi".to_string()));
        assert!(select_encoders(list, false, false, true)
            .0
            .contains(&"h264_vaapi".to_string()));
    }
}

//! FFmpeg probes — `test_ffmpeg` (existence + version) and
//! `validate_ffmpeg_path` (operator-supplied override).

use std::path::Path;
use std::process::Command;

use crate::errors::{CoreError, ValidationIssue};

use super::{find_ffmpeg, hide_console};

/// Test FFmpeg installation and return version string
pub fn test_ffmpeg() -> Result<String, CoreError> {
    let ffmpeg_path = find_ffmpeg();

    let mut cmd = Command::new(&ffmpeg_path);
    cmd.args(["-version"]);
    hide_console(&mut cmd);
    let output = cmd.output().map_err(|_| CoreError::FfmpegNotFound)?;

    if !output.status.success() {
        return Err(CoreError::FfmpegNotFound);
    }

    let version_output = String::from_utf8_lossy(&output.stdout);

    let version_line = version_output
        .lines()
        .next()
        .unwrap_or("Unknown version")
        .to_string();

    Ok(version_line)
}

/// Validate a specific FFmpeg path and return version if valid
pub fn validate_ffmpeg_path(path: String) -> Result<String, CoreError> {
    fn invalid(msg: impl Into<String>) -> CoreError {
        CoreError::ValidationFailed {
            reasons: vec![ValidationIssue {
                code: "invalid_ffmpeg_path".into(),
                message: msg.into(),
                path: Some("/path".into()),
            }],
        }
    }

    let path_obj = Path::new(&path);

    if !path_obj.exists() {
        return Err(invalid("Path does not exist"));
    }

    if !path_obj.is_file() {
        return Err(invalid("Path is not a file"));
    }

    // Try to run it with -version to verify it's actually FFmpeg
    let mut cmd = Command::new(&path);
    cmd.args(["-version"]);
    hide_console(&mut cmd);
    let output = cmd
        .output()
        .map_err(|_| invalid("Failed to execute as FFmpeg"))?;

    if !output.status.success() {
        return Err(invalid("File is not a valid FFmpeg executable"));
    }

    let version_output = String::from_utf8_lossy(&output.stdout);

    // Verify this is actually FFmpeg by checking for "ffmpeg" in output
    if !version_output.to_lowercase().contains("ffmpeg") {
        return Err(invalid("File is not FFmpeg"));
    }

    let version_line = version_output
        .lines()
        .next()
        .unwrap_or("Unknown version")
        .to_string();

    Ok(version_line)
}

#[cfg(test)]
mod tests {
    use super::validate_ffmpeg_path;
    use crate::errors::CoreError;

    fn validation_code(err: CoreError) -> String {
        match err {
            CoreError::ValidationFailed { reasons } => {
                reasons.into_iter().next().expect("a reason").code
            }
            other => panic!("expected ValidationFailed, got {other:?}"),
        }
    }

    #[test]
    fn missing_path_is_rejected_before_exec() {
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("no-such-ffmpeg");
        let err = validate_ffmpeg_path(missing.to_string_lossy().into_owned()).unwrap_err();
        assert_eq!(validation_code(err), "invalid_ffmpeg_path");
    }

    #[test]
    fn directory_path_is_rejected_before_exec() {
        let dir = tempfile::tempdir().unwrap();
        let err = validate_ffmpeg_path(dir.path().to_string_lossy().into_owned()).unwrap_err();
        assert_eq!(validation_code(err), "invalid_ffmpeg_path");
    }
}

//! System commands — encoder discovery, FFmpeg probes, RTMP test.
//!
//! Submodules:
//! - [`encoder`] — `get_encoders` (FFmpeg `-encoders` + per-OS GPU probe).
//! - [`ffmpeg`] — `test_ffmpeg`, `validate_ffmpeg_path`.
//! - [`rtmp`] — `test_rtmp_target`, `RtmpTestResult`, RTMP URL parser.
//!
//! `find_ffmpeg` is the shared discovery entry point; all submodules
//! call into it instead of duplicating the lookup chain. Windows
//! console-hide flags live here too because every submodule needs them.

use std::process::Command;

mod encoder;
mod ffmpeg;
mod rtmp;

pub use encoder::get_encoders;
pub use ffmpeg::{test_ffmpeg, validate_ffmpeg_path};
pub use rtmp::{test_rtmp_target, RtmpTestResult};

#[cfg(windows)]
pub(super) use std::os::windows::process::CommandExt;
#[cfg(windows)]
pub(super) const CREATE_NO_WINDOW: u32 = 0x08000000;

/// Find FFmpeg path. Delegates to `FFmpegLocator::discover` so this
/// honors the single discovery chain rule documented in
/// `crates/core/src/services/ffmpeg_locator.rs`:
///   1. settings.ffmpeg_path (operator override)
///   2. SPIRITSTREAM_FFMPEG_PATH env (Tauri shell bundled sidecar)
///   3. $PATH lookup (Linux distro / Docker / brew)
///   4. None → caller refuses
///
/// Returns a literal `"ffmpeg"` string when discovery finds nothing, so
/// `Command::new(path).spawn()` produces a clean ENOENT the caller maps
/// to `CoreError::FfmpegNotFound` without losing the diagnostic.
pub(super) fn find_ffmpeg() -> String {
    use crate::services::FFmpegLocator;
    use crate::services::SettingsManager;
    match FFmpegLocator::discover(None::<&SettingsManager>) {
        Some(path) => path.to_string_lossy().to_string(),
        None => {
            #[cfg(windows)]
            {
                "ffmpeg.exe".to_string()
            }
            #[cfg(not(windows))]
            {
                "ffmpeg".to_string()
            }
        }
    }
}

/// Apply per-OS hardening to a spawned `Command`. On Windows that
/// means hiding the console window for child processes; on Unix the
/// helper is a no-op so submodules call it unconditionally without
/// `cfg!` noise.
pub(super) fn hide_console(_cmd: &mut Command) {
    #[cfg(windows)]
    {
        _cmd.creation_flags(CREATE_NO_WINDOW);
    }
}

//! RTMP target connectivity test — TCP-only probe followed by a 2-second
//! FFmpeg publish to verify the endpoint accepts streams.

use std::net::TcpStream;
use std::process::Command;
use std::time::{Duration, Instant};

use crate::errors::{CoreError, ValidationIssue};

use super::{find_ffmpeg, hide_console};

/// Result of testing an RTMP target
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, ts_rs::TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub struct RtmpTestResult {
    pub success: bool,
    pub message: String,
    /// Time taken in milliseconds. JSON `number` — handshake latency
    /// is bounded by single-digit seconds; precision is moot.
    #[ts(type = "number | null")]
    pub latency_ms: Option<u64>,
}

/// Test RTMP target connectivity by attempting a brief connection.
///
/// 1. TCP connectivity test to the RTMP host:port
/// 2. Brief FFmpeg publish attempt to verify the endpoint accepts streams
pub fn test_rtmp_target(url: String, stream_key: String) -> Result<RtmpTestResult, CoreError> {
    let start = Instant::now();

    let (host, port) = parse_rtmp_url(&url)?;

    // TCP connectivity test (fast check)
    let tcp_timeout = Duration::from_secs(5);
    let addr = format!("{host}:{port}");

    match TcpStream::connect_timeout(
        &addr.parse().map_err(|e| CoreError::Internal {
            context: format!("Invalid address {addr}: {e}"),
        })?,
        tcp_timeout,
    ) {
        Ok(_) => {
            log::info!("TCP connection to {addr} successful");
        }
        Err(e) => {
            return Ok(RtmpTestResult {
                success: false,
                message: format!("Cannot reach {addr} - {e}"),
                latency_ms: Some(start.elapsed().as_millis() as u64),
            });
        }
    }

    // FFmpeg publish test: generate a 2-second test pattern and attempt
    // to publish.
    let ffmpeg_path = find_ffmpeg();
    let full_url = if url.ends_with('/') {
        format!("{url}{stream_key}")
    } else {
        format!("{url}/{stream_key}")
    };

    let mut cmd = Command::new(&ffmpeg_path);
    cmd.args([
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "testsrc=duration=2:size=320x240:rate=30",
        "-f",
        "lavfi",
        "-i",
        "anullsrc=r=44100:cl=stereo",
        "-t",
        "2",
        "-c:v",
        "libx264",
        "-preset",
        "ultrafast",
        "-tune",
        "zerolatency",
        "-b:v",
        "500k",
        "-c:a",
        "aac",
        "-b:a",
        "64k",
        "-f",
        "flv",
        &full_url,
    ]);

    hide_console(&mut cmd);

    let output = cmd.output().map_err(|_| CoreError::FfmpegNotFound)?;

    let elapsed = start.elapsed().as_millis() as u64;

    if output.status.success() {
        Ok(RtmpTestResult {
            success: true,
            message: "Connection successful - stream accepted".to_string(),
            latency_ms: Some(elapsed),
        })
    } else {
        let stderr = String::from_utf8_lossy(&output.stderr);
        Ok(RtmpTestResult {
            success: false,
            message: classify_rtmp_error(&stderr),
            latency_ms: Some(elapsed),
        })
    }
}

/// Maps FFmpeg's RTMP-probe stderr to a user-friendly failure message.
/// Pure — the network/spawn I/O lives in the caller.
fn classify_rtmp_error(stderr: &str) -> String {
    if stderr.contains("Connection refused") {
        "Connection refused - server not accepting connections".to_string()
    } else if stderr.contains("Connection timed out") {
        "Connection timed out - server not responding".to_string()
    } else if stderr.contains("Server returned 404")
        || stderr.contains("NetStream.Publish.BadName")
    {
        "Stream key rejected - check your stream key".to_string()
    } else if stderr.contains("Authorization")
        || stderr.contains("auth")
        || stderr.contains("401")
    {
        "Authentication failed - invalid stream key".to_string()
    } else if stderr.contains("NetConnection.Connect.Rejected") {
        "Connection rejected by server - may need authentication".to_string()
    } else if stderr.contains("Already publishing") {
        // This actually means the key is valid; someone is already using it.
        "Stream key is valid but already in use".to_string()
    } else if stderr.is_empty() {
        "Connection failed - unknown error".to_string()
    } else {
        let truncated: String = stderr.chars().take(200).collect();
        format!("Connection failed: {}", truncated.trim())
    }
}

/// Parse an RTMP URL to extract host and port.
fn parse_rtmp_url(url: &str) -> Result<(String, u16), CoreError> {
    fn bad(msg: impl Into<String>) -> CoreError {
        CoreError::ValidationFailed {
            reasons: vec![ValidationIssue {
                code: "invalid_rtmp_url".into(),
                message: msg.into(),
                path: Some("/url".into()),
            }],
        }
    }

    let url = url.trim();

    let (is_secure, rest) = if let Some(rest) = url.strip_prefix("rtmps://") {
        (true, rest)
    } else if let Some(rest) = url.strip_prefix("rtmp://") {
        (false, rest)
    } else {
        return Err(bad("Invalid RTMP URL: must start with rtmp:// or rtmps://"));
    };

    // URL format: rtmp://host:port/app/stream or rtmp://host/app/stream
    let host_port = rest.split('/').next().unwrap_or(rest);

    let (host, port) = if host_port.contains(':') {
        let parts: Vec<&str> = host_port.splitn(2, ':').collect();
        let port: u16 = parts[1]
            .parse()
            .map_err(|_| bad(format!("Invalid port in URL: {}", parts[1])))?;
        (parts[0].to_string(), port)
    } else {
        let default_port = if is_secure { 443 } else { 1935 };
        (host_port.to_string(), default_port)
    };

    if host.is_empty() {
        return Err(bad("Empty host in RTMP URL"));
    }

    Ok((host, port))
}

#[cfg(test)]
mod tests {
    use super::{classify_rtmp_error, parse_rtmp_url};
    use crate::errors::CoreError;

    fn validation_codes(err: CoreError) -> Vec<String> {
        match err {
            CoreError::ValidationFailed { reasons } => {
                reasons.into_iter().map(|r| r.code).collect()
            }
            other => panic!("expected ValidationFailed, got {other:?}"),
        }
    }

    #[test]
    fn plain_rtmp_defaults_to_port_1935() {
        let (host, port) = parse_rtmp_url("rtmp://live.example.com/app/key").unwrap();
        assert_eq!(host, "live.example.com");
        assert_eq!(port, 1935);
    }

    #[test]
    fn rtmps_defaults_to_port_443() {
        let (host, port) = parse_rtmp_url("rtmps://secure.example.com/app").unwrap();
        assert_eq!(host, "secure.example.com");
        assert_eq!(port, 443);
    }

    #[test]
    fn explicit_port_overrides_the_scheme_default() {
        let (host, port) = parse_rtmp_url("rtmp://host.example.com:1234/app/key").unwrap();
        assert_eq!(host, "host.example.com");
        assert_eq!(port, 1234);
    }

    #[test]
    fn host_without_path_is_accepted() {
        let (host, port) = parse_rtmp_url("rtmp://host.example.com").unwrap();
        assert_eq!(host, "host.example.com");
        assert_eq!(port, 1935);
    }

    #[test]
    fn surrounding_whitespace_is_trimmed() {
        let (host, port) = parse_rtmp_url("  rtmp://host.example.com/app  ").unwrap();
        assert_eq!(host, "host.example.com");
        assert_eq!(port, 1935);
    }

    #[test]
    fn non_rtmp_scheme_is_rejected() {
        let err = parse_rtmp_url("https://host.example.com/app").unwrap_err();
        assert_eq!(validation_codes(err), vec!["invalid_rtmp_url"]);
    }

    #[test]
    fn non_numeric_port_is_rejected() {
        let err = parse_rtmp_url("rtmp://host.example.com:notaport/app").unwrap_err();
        assert_eq!(validation_codes(err), vec!["invalid_rtmp_url"]);
    }

    #[test]
    fn empty_host_is_rejected() {
        let err = parse_rtmp_url("rtmp:///app/key").unwrap_err();
        assert_eq!(validation_codes(err), vec!["invalid_rtmp_url"]);
    }

    #[test]
    fn classify_connection_refused() {
        let msg = classify_rtmp_error("rtmp://x: Connection refused\n");
        assert_eq!(msg, "Connection refused - server not accepting connections");
    }

    #[test]
    fn classify_connection_timed_out() {
        let msg = classify_rtmp_error("Connection timed out");
        assert_eq!(msg, "Connection timed out - server not responding");
    }

    #[test]
    fn classify_bad_stream_key_from_404() {
        assert_eq!(
            classify_rtmp_error("Server returned 404 Not Found"),
            "Stream key rejected - check your stream key"
        );
    }

    #[test]
    fn classify_bad_stream_key_from_publish_badname() {
        assert_eq!(
            classify_rtmp_error("NetStream.Publish.BadName"),
            "Stream key rejected - check your stream key"
        );
    }

    #[test]
    fn classify_auth_failure() {
        assert_eq!(
            classify_rtmp_error("HTTP 401 Authorization required"),
            "Authentication failed - invalid stream key"
        );
    }

    #[test]
    fn classify_connection_rejected() {
        assert_eq!(
            classify_rtmp_error("NetConnection.Connect.Rejected by app"),
            "Connection rejected by server - may need authentication"
        );
    }

    #[test]
    fn classify_already_publishing_is_valid_key() {
        assert_eq!(
            classify_rtmp_error("Already publishing to this stream"),
            "Stream key is valid but already in use"
        );
    }

    #[test]
    fn classify_empty_stderr_is_unknown() {
        assert_eq!(classify_rtmp_error(""), "Connection failed - unknown error");
    }

    #[test]
    fn classify_unknown_error_is_truncated_to_200_chars() {
        let long = "x".repeat(300);
        let msg = classify_rtmp_error(&long);
        assert!(msg.starts_with("Connection failed: "));
        // 200-char cap on the stderr body (the prefix is separate).
        let body = msg.trim_start_matches("Connection failed: ");
        assert_eq!(body.chars().count(), 200);
    }

    #[test]
    fn classify_unknown_error_is_trimmed() {
        let msg = classify_rtmp_error("  weird ffmpeg failure  ");
        assert_eq!(msg, "Connection failed: weird ffmpeg failure");
    }

    #[test]
    fn classify_refused_takes_priority_over_generic() {
        // A stderr that contains "Connection refused" never falls through to
        // the generic truncation branch even if other text is present.
        let msg = classify_rtmp_error("noise noise Connection refused noise");
        assert_eq!(msg, "Connection refused - server not accepting connections");
    }
}

//! Structured error enum for SpiritStream core services.
//!
//! Every public service method returns `Result<T, CoreError>`. Transport
//! adapters (HTTP, CLI) are responsible for mapping variants to their
//! protocol-specific failure representations (HTTP status, exit code, etc.) —
//! that mapping never leaks into core. `From<std::io::Error>` and
//! `From<serde_json::Error>` impls let helpers use the `?` operator without
//! ad-hoc String adapters.

use serde::{Deserialize, Serialize};
use thiserror::Error;
use ts_rs::TS;

/// One validation issue surfaced by a core service.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../packages/types/src/generated/")]
pub struct ValidationIssue {
    /// Stable, machine-readable code (e.g. `"bitrate_out_of_range"`).
    pub code: String,
    /// Human-readable summary. Localization happens at the transport boundary.
    pub message: String,
    /// Optional pointer into the offending document (JSON-pointer-ish syntax).
    pub path: Option<String>,
}

/// Top-level error type returned by core services.
///
/// Variants are tagged for stable JSON serialization, so transports can
/// surface them directly without re-shaping the payload.
#[derive(Debug, Clone, Error, Serialize, Deserialize)]
#[serde(tag = "kind", content = "details", rename_all = "snake_case")]
pub enum CoreError {
    #[error("profile not found: {name}")]
    ProfileNotFound { name: String },

    #[error("password required for profile: {name}")]
    PasswordRequired { name: String },

    #[error("password incorrect")]
    PasswordIncorrect,

    /// Password supplied to encrypt a profile is below the minimum length
    /// (see `crate::services::encryption::PROFILE_PASSWORD_MIN_LENGTH`).
    /// Distinct from `PasswordIncorrect` so the audit log can flag a
    /// weak-password rejection separately from brute-force attempts
    /// against an existing profile.
    #[error("password too short: minimum {min_length} characters")]
    PasswordTooShort { min_length: u32 },

    #[error("invalid stream config")]
    InvalidStreamConfig { reasons: Vec<ValidationIssue> },

    #[error("validation failed")]
    ValidationFailed { reasons: Vec<ValidationIssue> },

    #[error("profile already exists: {name}")]
    ProfileAlreadyExists { name: String },

    #[error("encoder unavailable: {encoder}")]
    EncoderUnavailable { encoder: String },

    #[error("port conflict on {port} (held by {owner})")]
    PortConflict { port: u16, owner: String },

    #[error("path outside allowed root")]
    PathOutsideAllowedRoot { path: String },

    /// Generic 404 for non-profile resources (files, themes by path, etc.).
    /// Use `ProfileNotFound` for the profile-specific case so callers can
    /// branch on profile-vs-other.
    #[error("not found: {resource}")]
    NotFound { resource: String },

    #[error("ffmpeg not found")]
    FfmpegNotFound,

    #[error("network error")]
    NetworkError { detail: String },

    #[error("rate limited")]
    RateLimited { retry_after_secs: u32 },

    #[error("unauthorized")]
    Unauthorized,

    /// No profile has been activated in this session — the caller is asking
    /// for state that lives behind `ProfileService::activate`. Distinct from
    /// `Unauthorized` so clients can prompt "choose a profile" instead of
    /// re-authenticating.
    #[error("no active profile")]
    NoActiveProfile,

    /// Chat platform connector has not been opened (or has dropped) before
    /// the caller asked it to send. Plan-cited variant: "new variants are
    /// added as the migration surfaces them (e.g., `ChatPlatformNotConnected
    /// { platform }` may emerge from `ChatService`)".
    #[error("chat platform not connected: {platform}")]
    ChatPlatformNotConnected { platform: String },

    /// The caller asked to send on a platform whose `*_send_enabled` flag is
    /// off in the active profile's chat settings. Separate from
    /// `ChatPlatformNotConnected` so the UI can suggest "enable sending" vs.
    /// "reconnect".
    #[error("chat sending disabled for platform: {platform}")]
    ChatSendingDisabled { platform: String },

    /// Outbound chat message exceeded the per-platform character cap (`limit`
    /// from `ChatPlatform::max_message_chars`). Validated server-side BEFORE
    /// the PII filter so the wire never sees the over-length text.
    #[error("chat message exceeds {limit}-char limit for {platform} ({actual} chars)")]
    ChatMessageLengthExceeded {
        platform: String,
        limit: usize,
        actual: usize,
    },

    /// Outbound chat message matched a phrase in the active
    /// profile's PII blocklist. `phrase_id` is the stable audit-log
    /// identifier; the actual matched text is never surfaced to the
    /// caller (would defeat the filter's purpose).
    #[error("chat message blocked by PII filter (phrase {phrase_id})")]
    ChatBlockedByPii { phrase_id: String },

    #[error("not implemented")]
    NotImplemented { feature: String },

    /// Catch-all for unexpected failures. The transport layer MUST NOT
    /// serialize the `context` field to clients — log server-side only.
    #[error("internal error")]
    Internal { context: String },
}

impl CoreError {
    /// Stable, machine-readable kind string. Mirrors the serde tag so external
    /// consumers (HTTP clients, CLI scripts, telemetry) can branch on this
    /// without parsing the human-readable message.
    pub fn kind(&self) -> &'static str {
        match self {
            CoreError::ProfileNotFound { .. } => "profile_not_found",
            CoreError::PasswordRequired { .. } => "password_required",
            CoreError::PasswordIncorrect => "password_incorrect",
            CoreError::PasswordTooShort { .. } => "password_too_short",
            CoreError::InvalidStreamConfig { .. } => "invalid_stream_config",
            CoreError::ValidationFailed { .. } => "validation_failed",
            CoreError::ProfileAlreadyExists { .. } => "profile_already_exists",
            CoreError::EncoderUnavailable { .. } => "encoder_unavailable",
            CoreError::PortConflict { .. } => "port_conflict",
            CoreError::PathOutsideAllowedRoot { .. } => "path_outside_allowed_root",
            CoreError::NotFound { .. } => "not_found",
            CoreError::FfmpegNotFound => "ffmpeg_not_found",
            CoreError::NetworkError { .. } => "network_error",
            CoreError::RateLimited { .. } => "rate_limited",
            CoreError::Unauthorized => "unauthorized",
            CoreError::NoActiveProfile => "no_active_profile",
            CoreError::ChatPlatformNotConnected { .. } => "chat_platform_not_connected",
            CoreError::ChatSendingDisabled { .. } => "chat_sending_disabled",
            CoreError::ChatMessageLengthExceeded { .. } => "chat_message_length_exceeded",
            CoreError::ChatBlockedByPii { .. } => "chat_blocked_by_pii",
            CoreError::NotImplemented { .. } => "not_implemented",
            CoreError::Internal { .. } => "internal",
        }
    }
}

impl From<std::io::Error> for CoreError {
    fn from(err: std::io::Error) -> Self {
        CoreError::Internal {
            context: format!("io: {err}"),
        }
    }
}

impl From<serde_json::Error> for CoreError {
    /// JSON deserialization failures from client-supplied bodies are
    /// **client errors** (malformed payload), not server bugs. Surface as
    /// `ValidationFailed` so the HTTP transport maps to 400 instead of 500
    /// and the client can show a field-level error message.
    fn from(err: serde_json::Error) -> Self {
        CoreError::ValidationFailed {
            reasons: vec![ValidationIssue {
                code: "malformed_json_body".into(),
                message: format!("serde_json: {err}"),
                path: None,
            }],
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every variant's `kind()` must equal its serde tag, and the
    /// strings must be unique — external consumers branch on these.
    #[test]
    fn kind_strings_are_exhaustive_and_unique() {
        let variants = vec![
            CoreError::ProfileNotFound { name: "p".into() },
            CoreError::PasswordRequired { name: "p".into() },
            CoreError::PasswordIncorrect,
            CoreError::PasswordTooShort { min_length: 12 },
            CoreError::InvalidStreamConfig { reasons: vec![] },
            CoreError::ValidationFailed { reasons: vec![] },
            CoreError::ProfileAlreadyExists { name: "p".into() },
            CoreError::EncoderUnavailable { encoder: "x".into() },
            CoreError::PortConflict {
                port: 1935,
                owner: "p".into(),
            },
            CoreError::PathOutsideAllowedRoot { path: "/x".into() },
            CoreError::NotFound {
                resource: "r".into(),
            },
            CoreError::FfmpegNotFound,
            CoreError::NetworkError { detail: "d".into() },
            CoreError::RateLimited {
                retry_after_secs: 5,
            },
            CoreError::Unauthorized,
            CoreError::NoActiveProfile,
            CoreError::ChatPlatformNotConnected {
                platform: "twitch".into(),
            },
            CoreError::ChatSendingDisabled {
                platform: "twitch".into(),
            },
            CoreError::ChatMessageLengthExceeded {
                platform: "twitch".into(),
                limit: 500,
                actual: 600,
            },
            CoreError::ChatBlockedByPii {
                phrase_id: "ph".into(),
            },
            CoreError::NotImplemented {
                feature: "veilid".into(),
            },
            CoreError::Internal {
                context: "boom".into(),
            },
        ];

        let mut seen = std::collections::HashSet::new();
        for err in &variants {
            let kind = err.kind();
            assert!(!kind.is_empty(), "kind must be non-empty for {err:?}");
            assert!(seen.insert(kind), "duplicate kind string: {kind}");
        }
        assert_eq!(seen.len(), variants.len());
    }

    #[test]
    fn kind_matches_serde_tag() {
        let err = CoreError::PortConflict {
            port: 1935,
            owner: "live".into(),
        };
        let json = serde_json::to_value(&err).unwrap();
        assert_eq!(json["kind"], err.kind());
    }

    #[test]
    fn display_interpolates_fields() {
        let err = CoreError::PortConflict {
            port: 1935,
            owner: "live".into(),
        };
        assert_eq!(err.to_string(), "port conflict on 1935 (held by live)");
        assert_eq!(
            CoreError::ProfileNotFound { name: "alpha".into() }.to_string(),
            "profile not found: alpha"
        );
    }

    #[test]
    fn io_error_maps_to_internal() {
        let io = std::io::Error::new(std::io::ErrorKind::NotFound, "missing");
        let err: CoreError = io.into();
        match err {
            CoreError::Internal { context } => assert!(context.contains("io:")),
            other => panic!("expected Internal, got {other:?}"),
        }
    }

    #[test]
    fn serde_json_error_maps_to_validation_failed() {
        let bad: Result<i32, _> = serde_json::from_str("not json");
        let err: CoreError = bad.unwrap_err().into();
        match err {
            CoreError::ValidationFailed { reasons } => {
                assert_eq!(reasons[0].code, "malformed_json_body");
            }
            other => panic!("expected ValidationFailed, got {other:?}"),
        }
    }
}

//! # spiritstream-core
//!
//! Transport-agnostic business logic for SpiritStream. This crate must NOT
//! depend on `axum`, `tower`, `tauri`, or any other transport framework —
//! see `.claude/rules/architecture.md`.
//!
//! Transport adapters (HTTP, CLI, Tauri command bridge, future Veilid) live
//! in sibling crates and consume the services exported here.

pub mod commands;
pub mod errors;
pub mod models;
pub mod registry;
pub mod services;
pub mod traits;

// Re-export the structured error enum at the crate root for ergonomic use.
pub use errors::CoreError;
pub use registry::{NoopEventSink, ServiceRegistry, ServiceRegistryOptions};

//! Chat credential surface — `ChatConfig`, per-platform `ChatCredentials`,
//! and the provider-specific auth enums (`TwitchAuth`, `YouTubeAuth`).
//!
//! Pulled out of `models/chat.rs` (K2) to keep the chat module under the
//! 600 LOC ceiling. Pure data with hand-written `Debug` impls (F5) so
//! tokens never reach log lines.
//!
//! ts-rs `export_to` paths point four directories up from this file
//! (`crates/core/src/models/chat/`) to reach `packages/types/`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use super::ChatPlatform;

/// Configuration for connecting a chat platform.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub struct ChatConfig {
    /// Platform to connect to
    pub platform: ChatPlatform,
    /// Whether this platform is enabled
    pub enabled: bool,
    /// Platform-specific configuration
    pub credentials: ChatCredentials,
}

/// Platform-specific credentials.
///
/// `Debug` is hand-written (F5) so OAuth tokens, session cookies, and
/// API keys never reach a panic message, log line, or `dbg!()`
/// rendering. Serde is unaffected.
#[derive(Clone, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "lowercase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub enum ChatCredentials {
    #[serde(rename_all = "camelCase")]
    Twitch {
        /// Twitch channel name to join
        channel: String,
        /// Authentication method (optional - anonymous read-only if not provided)
        auth: Option<TwitchAuth>,
    },
    #[serde(rename_all = "camelCase")]
    TikTok {
        /// TikTok username to monitor
        username: String,
        /// Session cookies/token (may be needed for some unofficial APIs)
        session_token: Option<String>,
    },
    #[serde(rename_all = "camelCase")]
    YouTube {
        /// YouTube channel ID or handle (e.g., "UCxxxxxx" or "@channelname")
        /// The backend will automatically find the current live stream
        channel_id: String,
        /// Authentication method
        auth: YouTubeAuth,
    },
    #[serde(rename_all = "camelCase")]
    Trovo {
        /// Trovo channel ID (numeric user/channel ID)
        channel_id: String,
    },
    #[serde(rename_all = "camelCase")]
    Kick {
        /// Kick channel name (case-insensitive — Kick normalises internally).
        channel: String,
        /// OAuth bearer for the user account doing the chatting. `None`
        /// means read-only (anonymous Pusher subscription works without
        /// auth); `Some(token)` enables send via `api.kick.com/public/v1/chat`.
        #[serde(default)]
        oauth_token: Option<String>,
        /// Kick broadcaster user id (Kick's REST POST /chat expects the
        /// numeric broadcaster id, NOT the username). The chat lifecycle
        /// fetches this once when activating the profile.
        #[serde(default)]
        broadcaster_user_id: Option<u64>,
    },
    #[serde(rename_all = "camelCase")]
    Facebook {
        /// Facebook Live video ID
        video_id: String,
        /// Facebook access token
        access_token: String,
    },
}

/// Twitch authentication options.
///
/// `Debug` is hand-written (F5) so OAuth bearers and refresh tokens
/// never reach a log line via the default derive. Serde is unaffected.
#[derive(Clone, Serialize, Deserialize, TS)]
#[serde(tag = "method", rename_all = "camelCase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub enum TwitchAuth {
    /// User-provided OAuth token (from twitchtokengenerator.com or similar)
    #[serde(rename_all = "camelCase")]
    UserToken {
        /// OAuth token (with or without "oauth:" prefix)
        oauth_token: String,
    },
    /// App OAuth - user authenticated via "Login with Twitch" flow
    #[serde(rename_all = "camelCase")]
    AppOAuth {
        /// Access token from OAuth flow
        #[serde(default)]
        access_token: String,
        /// Refresh token for renewal
        refresh_token: Option<String>,
        /// Token expiration timestamp (Unix epoch seconds, JSON `number`).
        #[ts(type = "number | null")]
        expires_at: Option<i64>,
    },
}

/// YouTube authentication options.
///
/// `Debug` is hand-written (F5) so API keys and OAuth tokens never
/// reach a log line via the default derive. Serde is unaffected.
#[derive(Clone, Serialize, Deserialize, TS)]
#[serde(tag = "method", rename_all = "camelCase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub enum YouTubeAuth {
    /// User-provided API key (preferred - uses user's own quota)
    #[serde(rename_all = "camelCase")]
    ApiKey {
        /// Google API key with YouTube Data API enabled
        key: String,
    },
    /// App OAuth - user authenticated via "Login with Google" flow
    #[serde(rename_all = "camelCase")]
    AppOAuth {
        /// Access token from OAuth flow
        #[serde(default)]
        access_token: String,
        /// Refresh token for renewal
        refresh_token: Option<String>,
        /// Token expiration timestamp (Unix epoch seconds, JSON `number`).
        #[ts(type = "number | null")]
        expires_at: Option<i64>,
    },
}

// F5: hand-written Debug impls for secret-bearing credential enums.
// Default derives would print tokens; these emit `<redacted>` markers
// instead while leaving the non-secret discriminator + channel fields
// visible for diagnostics.

impl std::fmt::Debug for ChatCredentials {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ChatCredentials::Twitch { channel, auth } => f
                .debug_struct("ChatCredentials::Twitch")
                .field("channel", channel)
                .field("auth", auth)
                .finish(),
            ChatCredentials::TikTok {
                username,
                session_token,
            } => f
                .debug_struct("ChatCredentials::TikTok")
                .field("username", username)
                .field(
                    "session_token",
                    &session_token.as_ref().map(|_| "<redacted>"),
                )
                .finish(),
            ChatCredentials::YouTube { channel_id, auth } => f
                .debug_struct("ChatCredentials::YouTube")
                .field("channel_id", channel_id)
                .field("auth", auth)
                .finish(),
            ChatCredentials::Trovo { channel_id } => f
                .debug_struct("ChatCredentials::Trovo")
                .field("channel_id", channel_id)
                .finish(),
            ChatCredentials::Kick {
                channel,
                oauth_token,
                broadcaster_user_id,
            } => f
                .debug_struct("ChatCredentials::Kick")
                .field("channel", channel)
                .field("oauth_token", &oauth_token.as_ref().map(|_| "<redacted>"))
                .field("broadcaster_user_id", broadcaster_user_id)
                .finish(),
            ChatCredentials::Facebook {
                video_id,
                access_token: _,
            } => f
                .debug_struct("ChatCredentials::Facebook")
                .field("video_id", video_id)
                .field("access_token", &"<redacted>")
                .finish(),
        }
    }
}

impl std::fmt::Debug for TwitchAuth {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TwitchAuth::UserToken { oauth_token: _ } => f
                .debug_struct("TwitchAuth::UserToken")
                .field("oauth_token", &"<redacted>")
                .finish(),
            TwitchAuth::AppOAuth {
                access_token: _,
                refresh_token,
                expires_at,
            } => f
                .debug_struct("TwitchAuth::AppOAuth")
                .field("access_token", &"<redacted>")
                .field(
                    "refresh_token",
                    &refresh_token.as_ref().map(|_| "<redacted>"),
                )
                .field("expires_at", expires_at)
                .finish(),
        }
    }
}

impl std::fmt::Debug for YouTubeAuth {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            YouTubeAuth::ApiKey { key: _ } => f
                .debug_struct("YouTubeAuth::ApiKey")
                .field("key", &"<redacted>")
                .finish(),
            YouTubeAuth::AppOAuth {
                access_token: _,
                refresh_token,
                expires_at,
            } => f
                .debug_struct("YouTubeAuth::AppOAuth")
                .field("access_token", &"<redacted>")
                .field(
                    "refresh_token",
                    &refresh_token.as_ref().map(|_| "<redacted>"),
                )
                .field("expires_at", expires_at)
                .finish(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// F5 regression: `Debug` rendering of a credentials variant
    /// holding a token must NOT contain the raw token. Pre-F5, the
    /// derived Debug printed the bearer verbatim.
    #[test]
    fn debug_redacts_chat_credentials_facebook_access_token() {
        let creds = ChatCredentials::Facebook {
            video_id: "vid-1".into(),
            access_token: "SUPER-SECRET-FACEBOOK-BEARER".into(),
        };
        let rendered = format!("{creds:?}");
        assert!(
            !rendered.contains("SUPER-SECRET-FACEBOOK-BEARER"),
            "Facebook access_token leaked via Debug: {rendered}",
        );
        assert!(
            rendered.contains("vid-1"),
            "non-secret field dropped: {rendered}"
        );
        assert!(rendered.contains("<redacted>"));
    }

    #[test]
    fn debug_redacts_twitch_user_token() {
        let auth = TwitchAuth::UserToken {
            oauth_token: "SUPER-SECRET-TWITCH-OAUTH".into(),
        };
        let rendered = format!("{auth:?}");
        assert!(!rendered.contains("SUPER-SECRET-TWITCH-OAUTH"));
        assert!(rendered.contains("<redacted>"));
    }

    #[test]
    fn debug_redacts_youtube_apikey() {
        let auth = YouTubeAuth::ApiKey {
            key: "SUPER-SECRET-YOUTUBE-API-KEY".into(),
        };
        let rendered = format!("{auth:?}");
        assert!(!rendered.contains("SUPER-SECRET-YOUTUBE-API-KEY"));
        assert!(rendered.contains("<redacted>"));
    }

    #[test]
    fn debug_redacts_kick_oauth_token() {
        let creds = ChatCredentials::Kick {
            channel: "kingbob".into(),
            oauth_token: Some("SUPER-SECRET-KICK-OAUTH".into()),
            broadcaster_user_id: Some(123),
        };
        let rendered = format!("{creds:?}");
        assert!(!rendered.contains("SUPER-SECRET-KICK-OAUTH"));
        assert!(
            rendered.contains("kingbob"),
            "non-secret channel name dropped"
        );
    }

    /// F5: the `AppOAuth` Twitch arm holds BOTH an access token and a
    /// refresh token. Rendering `ChatCredentials::Twitch` must redact both
    /// while keeping the channel name and the non-secret expiry visible.
    /// Exercises the outer `ChatCredentials::Twitch` arm and the inner
    /// `TwitchAuth::AppOAuth` arm together.
    #[test]
    fn debug_redacts_twitch_appoauth_access_and_refresh() {
        let creds = ChatCredentials::Twitch {
            channel: "streamer42".into(),
            auth: Some(TwitchAuth::AppOAuth {
                access_token: "SECRET-TWITCH-ACCESS".into(),
                refresh_token: Some("SECRET-TWITCH-REFRESH".into()),
                expires_at: Some(1_700_000_000),
            }),
        };
        let rendered = format!("{creds:?}");
        assert!(!rendered.contains("SECRET-TWITCH-ACCESS"), "{rendered}");
        assert!(!rendered.contains("SECRET-TWITCH-REFRESH"), "{rendered}");
        assert!(rendered.contains("streamer42"), "channel dropped: {rendered}");
        assert!(rendered.contains("1700000000"), "expiry dropped: {rendered}");
    }

    /// F5: same dual-token guarantee for the YouTube `AppOAuth` arm, routed
    /// through the outer `ChatCredentials::YouTube` arm.
    #[test]
    fn debug_redacts_youtube_appoauth_access_and_refresh() {
        let creds = ChatCredentials::YouTube {
            channel_id: "UCabc123".into(),
            auth: YouTubeAuth::AppOAuth {
                access_token: "SECRET-YT-ACCESS".into(),
                refresh_token: Some("SECRET-YT-REFRESH".into()),
                expires_at: Some(1_700_000_000),
            },
        };
        let rendered = format!("{creds:?}");
        assert!(!rendered.contains("SECRET-YT-ACCESS"), "{rendered}");
        assert!(!rendered.contains("SECRET-YT-REFRESH"), "{rendered}");
        assert!(rendered.contains("UCabc123"), "channel_id dropped: {rendered}");
    }

    /// F5: TikTok's optional `session_token` is a credential — it must be
    /// redacted, while the public username stays visible.
    #[test]
    fn debug_redacts_tiktok_session_token() {
        let creds = ChatCredentials::TikTok {
            username: "tikuser".into(),
            session_token: Some("SECRET-TIKTOK-SESSION".into()),
        };
        let rendered = format!("{creds:?}");
        assert!(!rendered.contains("SECRET-TIKTOK-SESSION"), "{rendered}");
        assert!(rendered.contains("tikuser"), "username dropped: {rendered}");
        assert!(rendered.contains("<redacted>"));
    }

    /// Trovo carries no secret — its Debug arm just renders the channel id.
    /// Guards against a future field addition silently going unredacted.
    #[test]
    fn debug_trovo_renders_channel_id() {
        let creds = ChatCredentials::Trovo {
            channel_id: "1234567".into(),
        };
        let rendered = format!("{creds:?}");
        assert!(rendered.contains("1234567"), "channel_id dropped: {rendered}");
    }
}

use serde::{Deserialize, Serialize};
use ts_rs::TS;
use uuid::Uuid;

// K2: credential surface (`ChatConfig`, `ChatCredentials`, `TwitchAuth`,
// `YouTubeAuth`) and their hand-written `Debug` impls live in a
// submodule so this file stays under the 600 LOC ceiling. Re-exported
// at the public path so downstream `use spiritstream_core::models::*`
// remains source-compatible.
mod credentials;
pub use credentials::{ChatConfig, ChatCredentials, TwitchAuth, YouTubeAuth};

/// Chat-log session status returned by `GET /api/v1/chat/log`.
/// `started_at` is Unix-epoch milliseconds; `0` when no session has
/// started since the last process boot (`active == false`). Sentinel
/// rather than `Option<i64>` to keep the ts-rs-emitted wire shape a
/// plain `bigint` instead of `bigint | null`, matching the rest of
/// `@spiritstream/types`'s timestamp fields.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../packages/types/src/generated/")]
pub struct ChatLogStatus {
    pub active: bool,
    /// Unix epoch ms. Emitted as JSON number; ts-rs would default to
    /// `bigint` for i64 but `JSON.stringify(BigInt)` throws, so we
    /// pin the TS type to `number` (safe to year ~287,000 AD).
    #[serde(default)]
    #[ts(type = "number")]
    pub started_at: i64,
}

/// Represents a platform that supports chat
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "lowercase")]
#[ts(export, export_to = "../../../packages/types/src/generated/")]
pub enum ChatPlatform {
    Twitch,
    #[serde(rename = "tiktok")]
    TikTok,
    YouTube,
    Trovo,
    Kick,
    Facebook,
}

impl ChatPlatform {
    pub fn as_str(&self) -> &'static str {
        match self {
            ChatPlatform::Twitch => "twitch",
            ChatPlatform::TikTok => "tiktok",
            ChatPlatform::YouTube => "youtube",
            ChatPlatform::Trovo => "trovo",
            ChatPlatform::Kick => "kick",
            ChatPlatform::Facebook => "facebook",
        }
    }

    /// Maximum chat-message length the platform accepts. Enforced server-side
    /// in `ChatService::send_message`  before the PII filter
    /// runs, so over-length messages never touch the wire.
    pub fn max_message_chars(&self) -> usize {
        match self {
            ChatPlatform::Twitch => 500,
            ChatPlatform::YouTube => 200,
            ChatPlatform::Trovo => 500,
            ChatPlatform::Kick => 500,
            ChatPlatform::Facebook => 200,
            ChatPlatform::TikTok => 150,
        }
    }
}

/// A normalized chat message from any platform.
///
/// **Field stratification.** `username` / `message` / `timestamp` /
/// `color` / `badges` are the legacy surface that pre-Phase-B chat-log
/// JSONL files were written with — they're preserved so the log-replay
/// path keeps round-tripping. New code reads `author` (structured
/// identity), `fragments` (renderable list), `flags` (boolean
/// attributes), and `event` (non-text events). Connectors that haven't
/// migrated yet leave the new fields at their defaults; the renderer
/// falls back to legacy fields when `fragments` is empty.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../packages/types/src/generated/")]
pub struct ChatMessage {
    /// Unique message ID
    pub id: String,
    /// Platform this message came from
    pub platform: ChatPlatform,
    /// Phase J multi-account tuple key — the platform-side account
    /// identifier this message belongs to. `None` until that phase
    /// lands; connectors that already know the account ID may set it.
    #[serde(default)]
    pub account_id: Option<String>,
    /// Platform-specific room/chat ID (Twitch broadcaster_user_id,
    /// YouTube live_chat_id, …). `None` for the legacy log path.
    #[serde(default)]
    pub channel_id: Option<String>,
    /// Platforms this message was sent to (for cross-post / outbound)
    pub platforms: Option<Vec<ChatPlatform>>,
    /// Legacy: mirrors `author.display_name`. New code reads `author`.
    pub username: String,
    /// Legacy: raw message text. New code reads `fragments` / `raw_text`.
    pub message: String,
    /// Timestamp in milliseconds since Unix epoch (JSON `number`,
    /// safe through year ~287,000 AD).
    #[ts(type = "number")]
    pub timestamp: i64,
    /// Server-side receive time (separate from `timestamp` which is
    /// the message-author-set time on platforms that supply one).
    /// Connectors set both equal on platforms without a distinct
    /// server-received timestamp.
    #[serde(default)]
    #[ts(type = "number | null")]
    pub server_received_at_ms: Option<i64>,
    /// Structured author identity. `None` for legacy log entries.
    #[serde(default)]
    pub author: Option<ChatAuthor>,
    /// Backend-built renderable list. Empty for legacy log entries;
    /// the renderer then falls back to `message` text.
    #[serde(default)]
    pub fragments: Vec<MessageFragment>,
    /// Boolean attributes — emitted as a single integer on the wire
    /// (see [`MessageFlags`] serde impl).
    #[serde(default)]
    #[ts(type = "number")]
    pub flags: MessageFlags,
    /// Copy/search buffer; identical to `message` for inbound text.
    /// Optional so legacy entries don't carry a duplicate field.
    #[serde(default)]
    pub raw_text: Option<String>,
    /// Total bits in a Twitch cheer message. `None` if not a cheer.
    #[serde(default)]
    pub bits_total: Option<u32>,
    /// Optional row-tinting color (e.g. message highlighted by points
    /// reward, or platform-supplied background color).
    #[serde(default)]
    pub highlight_color: Option<FragmentColor>,
    /// Twitch Hype Chat pin-duration tier when this message is an
    /// elevated pin.
    #[serde(default)]
    pub elevated_tier: Option<ElevatedTier>,
    /// Reply-thread anchor when this message is a reply.
    #[serde(default)]
    pub reply: Option<ReplyContext>,
    /// Non-text event payload. Either set (a system event) or text
    /// (`fragments` non-empty); a single message never carries both.
    #[serde(default)]
    pub event: Option<ChatEvent>,
    /// Message direction (inbound/outbound)
    #[serde(default)]
    pub direction: ChatMessageDirection,
    /// Source message ID from the platform (if available)
    pub source_id: Option<String>,
    /// Legacy: user's display color (hex string). New code reads
    /// `author.color`.
    pub color: Option<String>,
    /// Legacy: raw badge codes. New code reads `author.badges_raw` (or
    /// the resolved `Badge` fragments in `fragments`).
    pub badges: Option<Vec<String>>,
}

impl ChatMessage {
    pub fn new(platform: ChatPlatform, username: String, message: String) -> Self {
        let now_ms = chrono::Utc::now().timestamp_millis();
        Self {
            id: Uuid::new_v4().to_string(),
            platform,
            account_id: None,
            channel_id: None,
            platforms: None,
            username,
            message,
            timestamp: now_ms,
            server_received_at_ms: Some(now_ms),
            author: None,
            fragments: Vec::new(),
            flags: MessageFlags::empty(),
            raw_text: None,
            bits_total: None,
            highlight_color: None,
            elevated_tier: None,
            reply: None,
            event: None,
            direction: ChatMessageDirection::Inbound,
            source_id: None,
            color: None,
            badges: None,
        }
    }

    pub fn new_outbound(platforms: Vec<ChatPlatform>, username: String, message: String) -> Self {
        let primary = platforms.first().copied().unwrap_or(ChatPlatform::Twitch);
        let now_ms = chrono::Utc::now().timestamp_millis();
        Self {
            id: Uuid::new_v4().to_string(),
            platform: primary,
            account_id: None,
            channel_id: None,
            platforms: Some(platforms),
            username,
            message,
            timestamp: now_ms,
            server_received_at_ms: Some(now_ms),
            author: None,
            fragments: Vec::new(),
            flags: MessageFlags::empty(),
            raw_text: None,
            bits_total: None,
            highlight_color: None,
            elevated_tier: None,
            reply: None,
            event: None,
            direction: ChatMessageDirection::Outbound,
            source_id: None,
            color: None,
            badges: None,
        }
    }

    pub fn with_color(mut self, color: String) -> Self {
        self.color = Some(color);
        self
    }

    pub fn with_source_id(mut self, source_id: String) -> Self {
        self.id = format!("{}:{}", self.platform.as_str(), source_id);
        self.source_id = Some(source_id);
        self
    }

    pub fn with_badges(mut self, badges: Vec<String>) -> Self {
        self.badges = Some(badges);
        self
    }
}

// ---------------------------------------------------------------------------
// Phase B: structured-fragment chat model
//
// The new pipeline pre-parses platform-specific payloads into a tagged-union
// `MessageFragment` list and a `MessageFlags` bitfield. Frontend renders the
// list verbatim and dispatches on `fragment.kind`; never parses raw text.
// Backend is the only place that knows IRC tags, Helix metadata, YouTube
// liveChatMessages shapes, 7TV/BTTV/FFZ token tables, etc.
// ---------------------------------------------------------------------------

/// Validated CSS-safe colour. `hex` is a 7-char `"#RRGGBB"` string;
/// constructed via [`FragmentColor::from_hex`] so user-supplied IRC
/// `color=` tags (which can be malformed) never reach the renderer
/// without validation.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../packages/types/src/generated/")]
pub struct FragmentColor {
    pub hex: String,
}

impl FragmentColor {
    /// Accept either `#RRGGBB` or `RRGGBB` (with optional leading `#`),
    /// case-insensitive. Returns `None` for anything else — the
    /// renderer falls back to the platform-default colour.
    pub fn from_hex(raw: &str) -> Option<Self> {
        let trimmed = raw.trim().trim_start_matches('#');
        if trimmed.len() != 6 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }
        Some(Self {
            hex: format!("#{}", trimmed.to_uppercase()),
        })
    }
}

