        // First two refreshes — under threshold (3).
        let r1 = svc.record_oauth_refresh("twitch", true).await.unwrap();
        let r2 = svc.record_oauth_refresh("twitch", true).await.unwrap();
        assert_eq!(r1, RefreshAnomaly::None);
        assert_eq!(r2, RefreshAnomaly::None);
        // Third refresh trips the threshold.
        let r3 = svc.record_oauth_refresh("twitch", true).await.unwrap();
        assert!(matches!(r3, RefreshAnomaly::RapidRefreshBurst { .. }));
        assert_eq!(sink.unusual.load(Ordering::SeqCst), 1);
        let entries = audit.entries().unwrap();
        // 3 OauthRefresh entries + 1 OauthRefreshUnusualLocation entry.
        assert_eq!(entries.len(), 4);
        let unusual_count = entries
            .iter()
            .filter(|e| matches!(e.action, AuditAction::OauthRefreshUnusualLocation { .. }))
            .count();
        assert_eq!(unusual_count, 1);
    }

    #[tokio::test]
    async fn separate_platforms_track_independently() {
        let dir = TempDir::new().unwrap();
        let (_audit, sink, svc) = build(&dir);
        // 3 twitch refreshes → twitch tripped.
        let _ = svc.record_oauth_refresh("twitch", true).await;
        let _ = svc.record_oauth_refresh("twitch", true).await;
        let r3 = svc.record_oauth_refresh("twitch", true).await.unwrap();
        assert!(matches!(r3, RefreshAnomaly::RapidRefreshBurst { .. }));
        // 1 youtube refresh — does NOT trip (independent history).
        let r4 = svc.record_oauth_refresh("youtube", true).await.unwrap();
        assert_eq!(r4, RefreshAnomaly::None);
        assert_eq!(sink.unusual.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn failed_refresh_is_audited_but_not_counted() {
        let dir = TempDir::new().unwrap();
        let (audit, sink, svc) = build(&dir);
        // 5 failures should NOT trip the anomaly (the heuristic targets
        // successful bursts, not failure storms).
        for _ in 0..5 {
            let r = svc.record_oauth_refresh("twitch", false).await.unwrap();
            assert_eq!(r, RefreshAnomaly::None);
        }
        assert_eq!(sink.unusual.load(Ordering::SeqCst), 0);
        let entries = audit.entries().unwrap();
        assert_eq!(entries.len(), 5);
    }

    /// Smoke test for the `NoopEventSink` integration — confirms a
    /// transport that doesn't care about events still works.
    #[tokio::test]
    async fn works_with_noop_event_sink() {
        let dir = TempDir::new().unwrap();
        let audit = Arc::new(AuditLogService::new(dir.path().to_path_buf()).unwrap());
        let events: Arc<dyn EventSink> = Arc::new(NoopEventSink);
        let svc = AuthSurveillanceService::new(audit, events);
        for _ in 0..3 {
            let _ = svc.record_oauth_refresh("twitch", true).await;
        }
    }
}

//! Network-free connector surface tests.
//!
//! Every connector's `connect()` validates credentials and required
//! fields synchronously BEFORE it touches the network. These tests pin
//! that pre-network surface — fresh-state getters, wrong-credential
//! rejection, empty-field rejection, read-only send behaviour, and the
//! not-connected guards on `disconnect`/`send` — without standing up a
//! mock server. The post-validation network bodies are exercised
//! separately.

use tokio::sync::mpsc;

use super::platform::{ChatPlatform, PlatformError};
use super::{
    FacebookConnector, KickConnector, TikTokConnector, TrovoConnector, TwitchConnector,
    YouTubeConnector,
};
use crate::models::{ChatConnectionStatus, ChatCredentials, ChatMessage};

fn assert_fresh(connector: &dyn ChatPlatform, name: &str) {
    assert_eq!(connector.status(), ChatConnectionStatus::Disconnected);
    assert!(!connector.is_connected());
    assert_eq!(connector.message_count(), 0);
    assert_eq!(connector.platform_name(), name);
    assert!(connector.last_error().is_none());
    assert!(!connector.can_send());
}

async fn connect_err(connector: &mut dyn ChatPlatform, cred: ChatCredentials) -> PlatformError {
    let (tx, _rx) = mpsc::channel::<ChatMessage>(8);
    connector
        .connect(cred, tx)
        .await
        .expect_err("connect should fail before any network call")
}

/// A credential of a platform the connector under test does not accept,
/// used to drive the "Expected X credentials" rejection branch.
fn foreign_cred() -> ChatCredentials {
    ChatCredentials::Trovo {
        channel_id: "someone-else".into(),
    }
}

#[test]
fn fresh_connectors_report_disconnected_zeroed_state() {
    assert_fresh(&TwitchConnector::new(), "twitch");
    assert_fresh(&YouTubeConnector::new(), "youtube");
    assert_fresh(&TrovoConnector::new(), "trovo");
    assert_fresh(&KickConnector::new(), "kick");
    assert_fresh(&FacebookConnector::new(), "facebook");
    assert_fresh(&TikTokConnector::new(), "tiktok");
}

