        }
    }
}

/// Auth info extracted from credentials for API calls
#[derive(Clone)]
enum AuthMode {
    /// OAuth Bearer token shared via watch channel (supports live refresh)
    OAuth {
        access_token_rx: watch::Receiver<String>,
    },
    /// API key query parameter
    ApiKey { key: String },
}

impl AuthMode {
    /// Apply auth to a reqwest RequestBuilder
    fn apply(&self, builder: reqwest::RequestBuilder) -> reqwest::RequestBuilder {
        match self {
            AuthMode::OAuth { access_token_rx } => {
                let token = access_token_rx.borrow().clone();
                builder.header("Authorization", format!("Bearer {}", token))
            }
            AuthMode::ApiKey { key } => builder.query(&[("key", key.as_str())]),
        }
    }
}

/// Find the live chat ID for the active broadcast
async fn find_live_chat_id(
    client: &reqwest::Client,
    auth: &AuthMode,
    channel_id: &str,
) -> Result<String, PlatformError> {
    match auth {
        AuthMode::OAuth { .. } => {
            // OAuth mode: use liveBroadcasts.list with mine=true (5 quota units)
            let url = format!("{}/liveBroadcasts", YOUTUBE_API_BASE);
            let resp = auth
                .apply(client.get(&url))
                .query(&[
                    ("part", "snippet"),
                    ("broadcastStatus", "active"),
                    ("broadcastType", "all"),
                ])
                .send()
                .await
                .map_err(|e| {
                    PlatformError::Network(format!("Failed to fetch broadcasts: {}", e))
                })?;

            if !resp.status().is_success() {
                let status = resp.status();
                let body = resp
                    .text()
                    .await
                    .unwrap_or_else(|e| format!("<failed to read response body: {e}>"));
                return Err(PlatformError::Platform(format!(
                    "YouTube API error ({}): {}",
                    status, body
                )));
            }

            let data: serde_json::Value = resp.json().await.map_err(|e| {
                PlatformError::Network(format!("Failed to parse broadcasts response: {}", e))
            })?;

            // Get the first active broadcast's liveChatId
            data["items"]
                .as_array()
                .and_then(|items| items.first())
                .and_then(|item| item["snippet"]["liveChatId"].as_str())
                .map(|s| s.to_string())
                .ok_or_else(|| {
                    PlatformError::Platform(
                        "No active live broadcast found. Make sure you are currently live streaming on YouTube.".to_string(),
                    )
                })
        }
        AuthMode::ApiKey { .. } => {
            // API key mode: search for live videos, then get liveStreamingDetails
            // Find live video for the channel (100 quota units)
            let search_url = format!("{}/search", YOUTUBE_API_BASE);
            let resp = auth
                .apply(client.get(&search_url))
                .query(&[
                    ("part", "id"),
                    ("channelId", channel_id),
                    ("type", "video"),
                    ("eventType", "live"),
                    ("maxResults", "1"),
                ])
                .send()
                .await
                .map_err(|e| {
                    PlatformError::Network(format!("Failed to search live videos: {}", e))
                })?;

            if !resp.status().is_success() {
                let status = resp.status();
                let body = resp
                    .text()
                    .await
                    .unwrap_or_else(|e| format!("<failed to read response body: {e}>"));
                return Err(PlatformError::Platform(format!(
                    "YouTube API error ({}): {}",
                    status, body
                )));
            }

            let search_data: serde_json::Value = resp.json().await.map_err(|e| {
                PlatformError::Network(format!("Failed to parse search response: {}", e))
            })?;

            let video_id = search_data["items"]
                .as_array()
                .and_then(|items| items.first())
                .and_then(|item| item["id"]["videoId"].as_str())
                .ok_or_else(|| {
                    PlatformError::Platform(
                        "No active live stream found for this channel. Make sure the channel is currently live streaming.".to_string(),
                    )
                })?
                .to_string();

            // Get liveStreamingDetails for the video (1 quota unit)
            let videos_url = format!("{}/videos", YOUTUBE_API_BASE);
            let resp = auth
                .apply(client.get(&videos_url))
                .query(&[("part", "liveStreamingDetails"), ("id", &video_id)])
                .send()
                .await
                .map_err(|e| {
                    PlatformError::Network(format!("Failed to fetch video details: {}", e))
                })?;

            if !resp.status().is_success() {
                let status = resp.status();
                let body = resp
                    .text()
                    .await
                    .unwrap_or_else(|e| format!("<failed to read response body: {e}>"));
                return Err(PlatformError::Platform(format!(
                    "YouTube API error ({}): {}",
                    status, body
                )));
            }

            let video_data: serde_json::Value = resp.json().await.map_err(|e| {
                PlatformError::Network(format!("Failed to parse video response: {}", e))
            })?;

            video_data["items"]
                .as_array()
                .and_then(|items| items.first())
                .and_then(|item| item["liveStreamingDetails"]["activeLiveChatId"].as_str())
                .map(|s| s.to_string())
                .ok_or_else(|| {
                    PlatformError::Platform(
                        "Live stream found but no active chat. Chat may be disabled for this stream.".to_string(),
                    )
                })
        }
    }
}

#[async_trait]
impl ChatPlatform for YouTubeConnector {
    async fn connect(
        &mut self,
        credentials: ChatCredentials,
        message_tx: mpsc::Sender<ChatMessage>,
    ) -> PlatformResult<()> {
        if self.is_connected() {
            return Err(PlatformError::AlreadyConnected);
        }

        self.status.store(
            status_to_u8(ChatConnectionStatus::Connecting),
            Ordering::Relaxed,
        );
        self.disconnecting.store(false, Ordering::Relaxed);
        self.can_send = false;
        self.message_count.store(0, Ordering::Relaxed);
        if let Ok(mut recent) = self.recent_outbound.lock() {
            recent.clear();
        }
        if let Ok(mut guard) = self.last_error.lock() {
            *guard = None;
        }

        // Extract YouTube credentials
        let (channel_id, auth_mode) = match credentials {
            ChatCredentials::YouTube { channel_id, auth } => {
                let mode = match auth {
                    YouTubeAuth::ApiKey { key } => {
                        self.oauth_token_tx = None;
                        AuthMode::ApiKey { key }
                    }
                    YouTubeAuth::AppOAuth { access_token, .. } => {
                        let (token_tx, token_rx) = watch::channel(access_token);
                        self.oauth_token_tx = Some(token_tx);
                        AuthMode::OAuth {
                            access_token_rx: token_rx,
                        }
                    }
                };
                (channel_id, mode)
            }
            _ => {
                return Err(PlatformError::InvalidConfig(
                    "Expected YouTube credentials".to_string(),
                ));
            }
        };

        info!(
            "Connecting to YouTube Live Chat for channel: {}",
            channel_id
        );
        self.status.store(
            status_to_u8(ChatConnectionStatus::Connecting),
            Ordering::Relaxed,
        );

        let http_client = reqwest::Client::builder()
            .timeout(Duration::from_secs(30))
            .build()
            .map_err(|e| PlatformError::Network(format!("Failed to create HTTP client: {}", e)))?;

        // Find the active live chat ID
        let live_chat_id = match find_live_chat_id(&http_client, &auth_mode, &channel_id).await {
            Ok(id) => {
                info!("Found YouTube live chat ID");
                id
            }
            Err(e) => {
                self.status
                    .store(status_to_u8(ChatConnectionStatus::Error), Ordering::Relaxed);
                if let Ok(mut guard) = self.last_error.lock() {
                    *guard = Some(format!("{}", e));
                }
                return Err(e);
            }
        };

        self.channel_id = Some(channel_id);
        self.live_chat_id = Some(live_chat_id.clone());
        self.auth_mode = Some(auth_mode.clone());
        self.can_send = matches!(auth_mode, AuthMode::OAuth { .. });
        self.self_channel_id = self.channel_id.clone();
        self.status.store(
            status_to_u8(ChatConnectionStatus::Connected),
            Ordering::Relaxed,
        );

        // Create disconnect channel
        let (disconnect_tx, mut disconnect_rx) = mpsc::channel::<()>(1);
        self.disconnect_tx = Some(disconnect_tx);

        info!("Connected to YouTube Live Chat, starting polling");

        // Spawn the polling task
        let status = self.status.clone();
        let last_error = self.last_error.clone();
        let message_count = self.message_count.clone();
        let disconnecting = self.disconnecting.clone();
        let recent_outbound = self.recent_outbound.clone();
        let self_channel_id = self.self_channel_id.clone();
        tokio::spawn(async move {
            let mut page_token: Option<String> = None;
            // Start with a reasonable default; updated from API response
            let mut poll_interval_ms: u64 = 6000;

            loop {
                // Check for disconnect signal
                if disconnect_rx.try_recv().is_ok() {
                    info!("YouTube chat disconnect signal received");
                    disconnecting.store(true, Ordering::Relaxed);
                    break;
                }

                // Build the request
                let mut url = format!(
                    "{}/liveChat/messages?liveChatId={}&part=snippet,authorDetails&maxResults=200",
                    YOUTUBE_API_BASE, live_chat_id
                );
                if let Some(ref token) = page_token {
                    url.push_str(&format!("&pageToken={}", token));
                }

                let request = auth_mode.apply(http_client.get(&url));
                match request.send().await {
                    Ok(resp) => {
                        if !resp.status().is_success() {
                            let http_status = resp.status();
                            // H6: surface the body-read failure instead
                            // of swallowing it with `unwrap_or_default()`.
                            // A failed `text()` previously hid disconnects
                            // mid-error-read as a generic empty body.
                            let body = match resp.text().await {
                                Ok(b) => b,
                                Err(e) => {
                                    warn!(
                                        "YouTube chat API error {}: body read failed: {}",
                                        http_status, e
                                    );
                                    format!("<body read failed: {e}>")
                                }
                            };
                            status.store(
                                status_to_u8(ChatConnectionStatus::Error),
                                Ordering::Relaxed,
                            );
                            // 403 often means quota exhausted; 401 means token expired
                            if http_status.as_u16() == 401 {
                                error!("YouTube API auth expired, waiting for token refresh");
                                poll_interval_ms = poll_interval_ms.max(30000);
                                if let Ok(mut guard) = last_error.lock() {
                                    *guard = Some("YouTube auth expired".to_string());
                                }
                            }
                            if http_status.as_u16() == 403 {
                                warn!("YouTube API quota may be exhausted (403). Backing off.");
                                poll_interval_ms = poll_interval_ms.max(30000);
                            } else {
                                warn!("YouTube chat API error ({}): {}", http_status, body);
                                if let Ok(mut guard) = last_error.lock() {
                                    *guard = Some(format!("YouTube API error {}", http_status));
                                }
                            }
                        } else {
                            match resp.json::<serde_json::Value>().await {
                                Ok(data) => {
                                    if let Ok(mut guard) = last_error.lock() {
                                        *guard = None;
                                    }
                                    status.store(
                                        status_to_u8(ChatConnectionStatus::Connected),
                                        Ordering::Relaxed,
                                    );

                                    // I4: reset the poll interval to base on every
                                    // successful poll BEFORE applying any API
                                    // recommendation. Pre-I4 the 401/403 paths
                                    // bumped `poll_interval_ms` to ≥30 s and the
                                    // reset only happened when the API explicitly
                                    // returned `pollingIntervalMillis`. If quota
                                    // recovered but the API omitted that field
                                    // (it's optional in the live-chat response),
                                    // the connector stayed stuck at 30 s polling
                                    // for the rest of the stream.
                                    poll_interval_ms = 6000;

                                    // Update polling interval from API recommendation
                                    if let Some(interval) = data["pollingIntervalMillis"].as_u64() {
                                        poll_interval_ms = interval;
                                    }

                                    // Update page token for next request
                                    page_token =
                                        data["nextPageToken"].as_str().map(|s| s.to_string());

                                    // Process messages
                                    if let Some(items) = data["items"].as_array() {
                                        for item in items {
                                            let Some(chat_msg) = parse_youtube_chat_item(item)
                                            else {
                                                continue;
                                            };

                                            // Skip our own outbound echoes inside the
                                            // dedup window. Needs the live
                                            // `recent_outbound` ring + own channel id,
                                            // so it stays in the loop.
                                            if let Some(self_id) = &self_channel_id {
                                                if item["authorDetails"]["channelId"].as_str()
                                                    == Some(self_id.as_str())
                                                {
                                                    let mut recent = recent_outbound
                                                        .lock()
                                                        .unwrap_or_else(|e| e.into_inner());
                                                    let now = Instant::now();
                                                    while let Some(front) = recent.front() {
                                                        if now
                                                            .duration_since(front.timestamp)
                                                            .as_secs()
                                                            > OUTBOUND_DEDUP_WINDOW_SECS
                                                        {
                                                            recent.pop_front();
                                                        } else {
                                                            break;
                                                        }
                                                    }
                                                    if recent
                                                        .iter()
                                                        .any(|entry| entry.text == chat_msg.message)
                                                    {
                                                        continue;
                                                    }
                                                }
                                            }

                                            if message_tx.send(chat_msg).await.is_err() {
                                                warn!("Failed to send YouTube message: receiver dropped");
                                                return;
                                            }
                                        }

                                        if !items.is_empty() {
                                            debug!(
                                                "Processed {} YouTube chat messages",
                                                items.len()
                                            );
                                            message_count
                                                .fetch_add(items.len() as u64, Ordering::Relaxed);
                                        }
                                    }
                                }
                                Err(e) => {
                                    warn!("Failed to parse YouTube chat response: {}", e);
                                    status.store(
                                        status_to_u8(ChatConnectionStatus::Error),
                                        Ordering::Relaxed,
                                    );
                                    if let Ok(mut guard) = last_error.lock() {
                                        *guard = Some(
                                            "Failed to parse YouTube chat response".to_string(),
                                        );
                                    }
                                }
                            }
                        }
                    }
                    Err(e) => {
                        warn!("YouTube chat request failed: {}", e);
                        status.store(status_to_u8(ChatConnectionStatus::Error), Ordering::Relaxed);
                        if let Ok(mut guard) = last_error.lock() {
                            *guard = Some("YouTube chat request failed".to_string());
                        }
                    }
                }

                // Wait before next poll with ±10% jitter so N streamers
                // recovering from the same network blip don't all poll
                // YouTube on the same tick (thundering herd). Floor of
                // 100ms keeps the jitter range meaningful at small
                // intervals.
                let jitter_range = (poll_interval_ms / 10).max(100);
                let jitter = rand::random::<u64>() % jitter_range;
                let sleep_ms = poll_interval_ms.saturating_sub(jitter_range / 2) + jitter;
                tokio::time::sleep(Duration::from_millis(sleep_ms)).await;
            }

            if !disconnecting.load(Ordering::Relaxed) {
                status.store(status_to_u8(ChatConnectionStatus::Error), Ordering::Relaxed);
                if let Ok(mut guard) = last_error.lock() {
                    *guard = Some("YouTube chat polling stopped".to_string());
                }
            }
            info!("YouTube chat polling stopped");
        });

        Ok(())
    }

    async fn disconnect(&mut self) -> PlatformResult<()> {
        if !self.is_connected() {
            return Err(PlatformError::NotConnected);
        }

        info!("Disconnecting from YouTube Live Chat");
        self.disconnecting.store(true, Ordering::Relaxed);

        // Send disconnect signal to polling task
        if let Some(tx) = self.disconnect_tx.take() {
            let _ = tx.send(()).await;
        }

        self.channel_id = None;
        self.self_channel_id = None;
        self.live_chat_id = None;
        self.auth_mode = None;
        self.can_send = false;
        self.status.store(
            status_to_u8(ChatConnectionStatus::Disconnected),
            Ordering::Relaxed,
        );
        self.oauth_token_tx = None;
        if let Ok(mut guard) = self.last_error.lock() {
            *guard = None;
        }

        info!("Disconnected from YouTube Live Chat");
        Ok(())
    }

    fn status(&self) -> ChatConnectionStatus {
        status_from_u8(self.status.load(Ordering::Relaxed))
    }

    fn message_count(&self) -> u64 {
        self.message_count.load(Ordering::Relaxed)
    }

    fn platform_name(&self) -> &'static str {
        "youtube"
    }

    fn update_token(&mut self, token: String) {
        if let Some(tx) = &self.oauth_token_tx {
            if tx.send(token).is_err() {
                debug!("YouTube chat token update failed: receiver dropped");
            }
        }
    }

    async fn send_message(&mut self, message: String) -> PlatformResult<()> {
        if !self.can_send {
            return Err(PlatformError::Authentication(
                "YouTube account is not authenticated for sending".to_string(),
            ));
        }

        let live_chat_id = self
            .live_chat_id
            .clone()
            .ok_or_else(|| PlatformError::Platform("No active live chat ID".to_string()))?;

        let auth_mode = self.auth_mode.clone().ok_or_else(|| {
            PlatformError::Authentication("Missing authentication mode".to_string())
        })?;

        if matches!(auth_mode, AuthMode::ApiKey { .. }) {
            return Err(PlatformError::Authentication(
                "YouTube API key cannot send messages".to_string(),
            ));
        }

        let http_client = reqwest::Client::builder()
            .timeout(Duration::from_secs(30))
            .build()
            .map_err(|e| PlatformError::Network(format!("Failed to create HTTP client: {}", e)))?;

        let url = format!("{}/liveChat/messages?part=snippet", YOUTUBE_API_BASE);
        let message_text = message.clone();
        let body = serde_json::json!({
            "snippet": {
                "liveChatId": live_chat_id,
                "type": "textMessageEvent",
                "textMessageDetails": { "messageText": message_text }
            }
        });

        let response = auth_mode
            .apply(http_client.post(&url))
            .json(&body)
            .send()
            .await
            .map_err(|e| PlatformError::Network(format!("Failed to send message: {}", e)))?;

        if !response.status().is_success() {
            let status = response.status();
            let body = response
                .text()
                .await
                .unwrap_or_else(|e| format!("<failed to read response body: {e}>"));
            return Err(PlatformError::Platform(format!(
                "YouTube send failed ({}): {}",
                status, body
            )));
        }

        if let Ok(mut recent) = self.recent_outbound.lock() {
            recent.push_back(OutboundMessage {
                text: message,
                timestamp: Instant::now(),
            });
            while recent.len() > 100 {
                recent.pop_front();
            }
        }

        Ok(())
    }

    fn can_send(&self) -> bool {
        self.can_send && self.is_connected()
    }

    fn last_error(&self) -> Option<String> {
        self.last_error.lock().ok().and_then(|e| e.clone())
    }
}

impl Default for YouTubeConnector {
    fn default() -> Self {
        Self::new()
    }
}

use log::info;

use crate::errors::CoreError;
use crate::models::{ChatConfig, ChatCredentials, ChatPlatform};
use crate::services::AuditAction;

use super::chat_validation;

/// Extract the platform-side identifier from credentials so we can
/// stamp it on the `ChatPlatformConnected` audit entry. Different
/// platforms key on different things:
/// - Twitch / Trovo / Kick: the channel slug the connector subscribed to.
/// - YouTube: the channel id (the watch broadcast id is only known once
///   the live discovery returns; not surfaced at this layer yet).
/// - TikTok: the username.
/// - Facebook: the live video id — load-bearing because it doubles as
///   the audit grep key when reconstructing "did I ever enable Facebook
///   for this stream" history.
fn account_id_from_credentials(creds: &ChatCredentials) -> Option<String> {
    match creds {
        ChatCredentials::Twitch { channel, .. } => Some(channel.clone()),
        ChatCredentials::YouTube { channel_id, .. } => Some(channel_id.clone()),
        ChatCredentials::Trovo { channel_id } => Some(channel_id.clone()),
        ChatCredentials::Kick { channel, .. } => Some(channel.clone()),
        ChatCredentials::TikTok { username, .. } => Some(username.clone()),
        ChatCredentials::Facebook { video_id, .. } => Some(video_id.clone()),
    }
}

impl super::ChatManager {
    /// Connect to a chat platform.
    pub async fn connect(&self, config: ChatConfig) -> Result<(), CoreError> {
        if !config.enabled {
            return Err(chat_validation(
                "chat_platform_not_enabled",
                "Platform is not enabled",
            ));
        }

        info!("Connecting to {} chat", config.platform.as_str());

        let mut platforms = self.platforms.lock().await;

        // Check if already connected.
        if let Some(connector) = platforms.get(&config.platform) {
            if connector.is_connected() {
                return Err(chat_validation(
                    "chat_platform_already_connected",
                    format!("{} is already connected", config.platform.as_str()),
                ));
            }
        }

        // Create or get platform connector. The factory is total over
        // every ChatPlatform variant; `None` is reserved for a future
        // "platform pending re-impl" branch.
        let mut connector = match platforms.remove(&config.platform) {
            Some(existing) => existing,
            None => Self::create_platform_connector(config.platform).ok_or_else(|| {
                chat_validation(
                    "chat_platform_unsupported",
                    format!(
                        "Chat for {} is not yet implemented",
                        config.platform.as_str()
                    ),
                )
            })?,
        };

        // Capture the account_id before the connector consumes
        // `config.credentials`. Powers the audit-log entry below.
        let account_id = account_id_from_credentials(&config.credentials);

        // Connect to the platform. The connector itself tracks its own
        // `last_error` (see `ChatPlatform::last_error` trait impls); re-
        // inserting the failed connector lets the UI surface that error
        // through `get_platform_status` without a separate stale cache.
        let message_tx = self.message_tx.clone();
        if let Err(e) = connector.connect(config.credentials, message_tx).await {
            let error = format!("Failed to connect to {}: {}", config.platform.as_str(), e);
            platforms.insert(config.platform, connector);
            return Err(CoreError::Internal { context: error });
        }

        platforms.insert(config.platform, connector);

        info!("Successfully connected to {}", config.platform.as_str());

        if let Some(audit) = self.audit() {
            let _ = audit.record(AuditAction::ChatPlatformConnected {
                platform: config.platform.as_str().to_string(),
                account_id,
            });
        }

        Ok(())
    }

    /// Disconnect from a chat platform.
    pub async fn disconnect(&self, platform: ChatPlatform) -> Result<(), CoreError> {
        info!("Disconnecting from {} chat", platform.as_str());

        let mut platforms = self.platforms.lock().await;

        if let Some(mut connector) = platforms.remove(&platform) {
            connector
                .disconnect()
                .await
                .map_err(|e| CoreError::Internal {
                    context: format!("Failed to disconnect from {}: {}", platform.as_str(), e),
                })?;

            // Re-insert the disconnected connector.
            platforms.insert(platform, connector);

            info!("Successfully disconnected from {}", platform.as_str());

            if let Some(audit) = self.audit() {
                let _ = audit.record(AuditAction::ChatPlatformDisconnected {
                    platform: platform.as_str().to_string(),
                    reason: "user_requested".to_string(),
                });
            }

            Ok(())
        } else {
            Err(CoreError::ChatPlatformNotConnected {
                platform: platform.as_str().to_string(),
            })
        }
    }

    /// Update the OAuth access token for a specific platform (if connected).
    pub async fn update_platform_token(
        &self,
        platform: ChatPlatform,
        token: String,
    ) -> Result<(), CoreError> {
        let mut platforms = self.platforms.lock().await;

        if let Some(connector) = platforms.get_mut(&platform) {
            connector.update_token(token);
            Ok(())
        } else {
            Err(CoreError::ChatPlatformNotConnected {
                platform: platform.as_str().to_string(),
            })
        }
    }

    /// Disconnect from every connected platform. `reason` is recorded
    /// against each per-platform `ChatPlatformDisconnected` audit entry
    /// so a forensic reader can distinguish a panic teardown from a
    /// user-requested mass-disconnect from a process shutdown. Use the
    /// stable short discriminators documented on the audit variant:
    /// `"panic_triggered"`, `"user_requested"`, `"shutdown"`.
    pub async fn disconnect_all(&self, reason: &str) -> Result<(), CoreError> {
        info!("Disconnecting from all chat platforms (reason={reason})");

        let mut platforms = self.platforms.lock().await;
        let mut errors = Vec::new();
        let mut disconnected: Vec<ChatPlatform> = Vec::new();

        for (platform, connector) in platforms.iter_mut() {
            if connector.is_connected() {
                match connector.disconnect().await {
                    Ok(()) => disconnected.push(*platform),
                    Err(e) => errors.push(format!("{}: {}", platform.as_str(), e)),
                }
            }
        }

        if let Some(audit) = self.audit() {
            for platform in &disconnected {
                let _ = audit.record(AuditAction::ChatPlatformDisconnected {
                    platform: platform.as_str().to_string(),
                    reason: reason.to_string(),
                });
            }
        }

        if errors.is_empty() {
            info!("Successfully disconnected from all platforms");
            Ok(())
        } else {
            Err(CoreError::Internal {
                context: format!("Some disconnections failed: {}", errors.join(", ")),
            })
        }
    }
}

use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::PathBuf;
use std::sync::atomic::Ordering;

use chrono::Local;
use log::warn;
use tokio::sync::{mpsc, oneshot};

use crate::errors::CoreError;
use crate::models::ChatMessage;

/// Internal command queue for the background chat-log writer task.
pub(crate) enum ChatLogCommand {
    StartSession,
    EndSession,
    Log(Box<ChatMessage>),
    Flush(oneshot::Sender<()>),
}

impl super::ChatManager {
    /// Start the chat log writer background task.
    pub(super) fn start_log_writer(
        &self,
        mut log_rx: mpsc::Receiver<ChatLogCommand>,
        log_dir: PathBuf,
    ) {
        let handle = tokio::spawn(async move {
            let _ = std::fs::create_dir_all(&log_dir);
            let mut state = ChatLogState::new(log_dir);

            while let Some(cmd) = log_rx.recv().await {
                match cmd {
                    ChatLogCommand::StartSession => {
                        state.start_session();
                    }
                    ChatLogCommand::EndSession => {
                        state.end_session();
                    }
                    ChatLogCommand::Log(message) => {
                        state.write_message(&message);
                    }
                    ChatLogCommand::Flush(tx) => {
                        state.flush();
                        let _ = tx.send(());
                    }
                }
            }
        });
        if let Ok(mut slot) = self.log_writer_handle.lock() {
            *slot = Some(handle);
        }
    }

    /// Start a new log session (stream start). Sync `pub fn` API so
    /// callers don't need to await; uses `try_send` to stay non-blocking.
    /// Drops on Full (5000-cmd capacity = ~166s of writes at 30 cmd/s,
    /// so Full means the writer is wedged and one more dropped command
    /// is the least of the problems).
    pub fn start_log_session(&self) {
        let now = Local::now().timestamp_millis();
        self.log_session_start_ms.store(now, Ordering::Relaxed);
        let _ = self.log_tx.try_send(ChatLogCommand::StartSession);
    }

    /// End the current log session (stream end).
    pub fn end_log_session(&self) {
        self.log_session_start_ms.store(0, Ordering::Relaxed);
        let _ = self.log_tx.try_send(ChatLogCommand::EndSession);
    }

    /// Log a message to disk (best effort). Applies the
    /// anonymous-mode pseudonymizer to the username field before
    /// queueing, so the log writer never sees plaintext usernames
    /// when anonymous mode is on.
    pub fn log_message(&self, message: ChatMessage) {
        let message = self.apply_anonymous_policy_to_message(message);
        let _ = self.log_tx.try_send(ChatLogCommand::Log(Box::new(message)));
    }

    /// Hot path helper: apply the cached anonymous-mode policy to a
    /// `ChatMessage` if active. Uses a blocking lock (`try_lock`)
    /// because `log_message` is non-async by contract — if the policy
    /// mutex is contended at this exact moment, we let the message
    /// through unchanged rather than blocking. Frequency: contention
    /// only at profile-activate-time, which is human-paced.
    fn apply_anonymous_policy_to_message(&self, mut message: ChatMessage) -> ChatMessage {
        if let Ok(guard) = self.anonymous_policy.try_lock() {
            if let Some((enabled, salt)) = guard.as_ref() {
                if *enabled && !salt.is_empty() {
                    message.username =
                        crate::services::pseudonymizer::pseudonymize(&message.username, salt);
                }
            }
        }
        message
    }

    /// Flush pending log writes to disk.
    pub async fn flush_chat_logs(&self) -> Result<(), CoreError> {
        let (tx, rx) = oneshot::channel();
        self.log_tx
            .send(ChatLogCommand::Flush(tx))
            .await
            .map_err(|_| CoreError::Internal {
                context: "Chat log writer is not available".into(),
            })?;
        rx.await.map_err(|_| CoreError::Internal {
            context: "Failed to flush chat logs".into(),
        })
    }

    /// Return the current log session start timestamp (ms), if active.
    pub fn log_session_start_ms(&self) -> Option<i64> {
        let value = self.log_session_start_ms.load(Ordering::Relaxed);
        if value > 0 {
            Some(value)
        } else {
            None
        }
    }
}

struct ChatLogState {
    log_dir: PathBuf,
    active: bool,
    current_hour_key: Option<String>,
    writer: Option<BufWriter<File>>,
}

impl ChatLogState {
    fn new(log_dir: PathBuf) -> Self {
        Self {
            log_dir,
            active: false,
            current_hour_key: None,
            writer: None,
        }
    }

    fn start_session(&mut self) {
        self.active = true;
        self.current_hour_key = None;
        self.writer = None;
    }

    fn end_session(&mut self) {
        self.active = false;
        self.flush();
        self.writer = None;
        self.current_hour_key = None;
    }

    fn write_message(&mut self, message: &ChatMessage) {
        if !self.active {
            return;
        }

        let hour_key = Local::now().format("%Y%m%d-%H").to_string();
        if self.current_hour_key.as_deref() != Some(&hour_key) {
            if let Err(e) = self.rotate_file(&hour_key) {
                warn!("Failed to rotate chat log file: {}", e);
                return;
            }
        }

        if let Some(writer) = self.writer.as_mut() {
            if let Ok(line) = serde_json::to_string(message) {
                if let Err(e) = writer.write_all(line.as_bytes()) {
                    warn!("Failed to write chat log line: {}", e);
                    return;
                }
                let _ = writer.write_all(b"\n");
            }
        }
    }

    fn rotate_file(&mut self, hour_key: &str) -> Result<(), CoreError> {
        let path = self.log_dir.join(format!("chatlog_{}.jsonl", hour_key));
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
            .map_err(|e| CoreError::Internal {
                context: format!("Failed to open chat log file: {e}"),
            })?;

        self.writer = Some(BufWriter::new(file));
        self.current_hour_key = Some(hour_key.to_string());
        Ok(())
    }

    fn flush(&mut self) {
        if let Some(writer) = self.writer.as_mut() {
            let _ = writer.flush();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::ChatLogState;
    use crate::models::{ChatMessage, ChatPlatform};
    use std::fs;
    use tempfile::TempDir;

    fn sample(text: &str) -> ChatMessage {
        ChatMessage::new(ChatPlatform::Twitch, "viewer".into(), text.into())
    }

    fn jsonl_files(dir: &std::path::Path) -> Vec<std::path::PathBuf> {
        fs::read_dir(dir)
            .unwrap()
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("jsonl"))
            .collect()
    }

    #[test]
    fn inactive_state_never_opens_a_file() {
        let dir = TempDir::new().unwrap();
        let mut state = ChatLogState::new(dir.path().to_path_buf());
        state.write_message(&sample("dropped while inactive"));
        assert!(jsonl_files(dir.path()).is_empty());
    }

    #[test]
    fn active_session_writes_one_jsonl_line_per_message() {
        let dir = TempDir::new().unwrap();
        let mut state = ChatLogState::new(dir.path().to_path_buf());
        state.start_session();
        state.write_message(&sample("hello"));
        state.write_message(&sample("world"));
        state.end_session();

        let files = jsonl_files(dir.path());
        assert_eq!(files.len(), 1, "one hour-keyed file");
        let body = fs::read_to_string(&files[0]).unwrap();
        let lines: Vec<&str> = body.lines().collect();
        assert_eq!(lines.len(), 2);
        assert!(body.contains("hello"));
        assert!(body.contains("world"));
    }

    #[test]
    fn messages_after_end_session_are_dropped() {
        let dir = TempDir::new().unwrap();
        let mut state = ChatLogState::new(dir.path().to_path_buf());
        state.start_session();
        state.write_message(&sample("kept"));
        state.end_session();
        state.write_message(&sample("after-end"));

        let files = jsonl_files(dir.path());
        let body = fs::read_to_string(&files[0]).unwrap();
        assert!(body.contains("kept"));
        assert!(!body.contains("after-end"));
    }
}

//! Central manager for all chat platform connections.
//!
//! Method impls live in focused submodules:
//! - `connection`: connect / disconnect / update_platform_token / disconnect_all.
//! - `send`: send_message (PII gate + per-platform char-limit + audit).
//! - `status`: get_status / is_any_connected + background message-handler
//!   and status-monitor tasks.
//! - `settings`: profile chat settings cache + per-platform send-enable
//!   flags + anonymous-mode policy.
//! - `log_writer`: chat log session lifecycle + per-hour rotation +
//!   ChatLogState + ChatLogCommand.

mod connection;
mod log_writer;
mod send;
mod settings;
mod status;

