pub use settings_manager::*;
pub use theme_manager::*;

use serde::{Deserialize, Serialize};

// Embedded OAuth Client IDs (PKCE flow — no secrets needed for Twitch's
// implicit / for YouTube's PKCE). Placeholders are replaced at release
// time; runtime overrides via OAuthConfig or env vars take precedence.
const TWITCH_CLIENT_ID: &str = "TWITCH_CLIENT_ID_PLACEHOLDER";
const YOUTUBE_CLIENT_ID: &str = "YOUTUBE_CLIENT_ID_PLACEHOLDER";
const KICK_CLIENT_ID: &str = "KICK_CLIENT_ID_PLACEHOLDER";
const FACEBOOK_CLIENT_ID: &str = "FACEBOOK_CLIENT_ID_PLACEHOLDER";

/// User-provided OAuth credentials. Each field falls back through:
/// (1) explicit override on this struct, (2) env var, (3) embedded
/// placeholder constant.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct OAuthConfig {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub twitch_client_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub twitch_client_secret: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub youtube_client_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub youtube_client_secret: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub kick_client_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub kick_client_secret: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub facebook_client_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub facebook_client_secret: Option<String>,
}

impl OAuthConfig {
    pub fn has_twitch(&self) -> bool {
        true
    }

    pub fn has_youtube(&self) -> bool {
        true
    }

    pub fn get_twitch_client_id(&self) -> String {
        if let Some(value) = self.twitch_client_id.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_TWITCH_CLIENT_ID") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        TWITCH_CLIENT_ID.to_string()
    }

    pub fn get_twitch_client_secret(&self) -> Option<String> {
        if let Some(value) = self.twitch_client_secret.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_TWITCH_CLIENT_SECRET") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        None
    }

    pub fn get_youtube_client_id(&self) -> String {
        if let Some(value) = self.youtube_client_id.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_YOUTUBE_CLIENT_ID") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        YOUTUBE_CLIENT_ID.to_string()
    }

    /// Required for Google Desktop apps even with PKCE (non-standard).
    pub fn get_youtube_client_secret(&self) -> Option<String> {
        if let Some(value) = self.youtube_client_secret.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_YOUTUBE_CLIENT_SECRET") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        None
    }

    pub fn has_kick(&self) -> bool {
        true
    }

    pub fn get_kick_client_id(&self) -> String {
        if let Some(value) = self.kick_client_id.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_KICK_CLIENT_ID") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        KICK_CLIENT_ID.to_string()
    }

    /// Kick OAuth requires the client secret for confidential clients;
    /// public PKCE clients can omit it. Same fall-through chain as the
    /// other providers.
    pub fn get_kick_client_secret(&self) -> Option<String> {
        if let Some(value) = self.kick_client_secret.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_KICK_CLIENT_SECRET") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        None
    }

    pub fn has_facebook(&self) -> bool {
        true
    }

    pub fn get_facebook_client_id(&self) -> String {
        if let Some(value) = self.facebook_client_id.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_FACEBOOK_CLIENT_ID") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return trimmed.to_string();
            }
        }
        FACEBOOK_CLIENT_ID.to_string()
    }

    /// Facebook OAuth requires the App Secret for the token exchange —
    /// Meta does not support PKCE for web apps. Same fall-through chain
    /// as the other providers.
    pub fn get_facebook_client_secret(&self) -> Option<String> {
        if let Some(value) = self.facebook_client_secret.as_deref() {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        if let Ok(value) = std::env::var("SPIRITSTREAM_FACEBOOK_CLIENT_SECRET") {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env_unset(key: &str) -> bool {
        std::env::var(key).is_err()
    }

    #[test]
    fn has_provider_flags_are_always_true() {
        let c = OAuthConfig::default();
        assert!(c.has_twitch());
        assert!(c.has_youtube());
        assert!(c.has_kick());
        assert!(c.has_facebook());
    }

    #[test]
    fn explicit_client_id_override_is_trimmed_and_returned() {
        let c = OAuthConfig {
            twitch_client_id: Some("  tw-id  ".into()),
            youtube_client_id: Some("yt-id".into()),
            kick_client_id: Some("kick-id".into()),
            facebook_client_id: Some("fb-id".into()),
            ..OAuthConfig::default()
        };
        assert_eq!(c.get_twitch_client_id(), "tw-id");
        assert_eq!(c.get_youtube_client_id(), "yt-id");
        assert_eq!(c.get_kick_client_id(), "kick-id");
        assert_eq!(c.get_facebook_client_id(), "fb-id");
    }

    #[test]
    fn explicit_client_secret_override_is_trimmed_and_returned() {
        let c = OAuthConfig {
            twitch_client_secret: Some("  tw-secret  ".into()),
            youtube_client_secret: Some("yt-secret".into()),
            kick_client_secret: Some("kick-secret".into()),
            facebook_client_secret: Some("fb-secret".into()),
            ..OAuthConfig::default()
        };
        assert_eq!(c.get_twitch_client_secret().as_deref(), Some("tw-secret"));
        assert_eq!(c.get_youtube_client_secret().as_deref(), Some("yt-secret"));
        assert_eq!(c.get_kick_client_secret().as_deref(), Some("kick-secret"));
        assert_eq!(c.get_facebook_client_secret().as_deref(), Some("fb-secret"));
    }

    #[test]
    fn whitespace_only_override_falls_through_to_non_empty_value() {
        let c = OAuthConfig {
            twitch_client_id: Some("   ".into()),
            ..OAuthConfig::default()
        };
        let resolved = c.get_twitch_client_id();
        // Whitespace-only override is ignored; resolution continues to env
        // or the embedded placeholder — never the blank string itself.
        assert!(!resolved.is_empty());
        assert_ne!(resolved, "   ");
    }

    #[test]
    fn client_id_falls_back_to_placeholder_when_unset() {
        // Only meaningful when the CI/dev shell hasn't injected real IDs.
        let c = OAuthConfig::default();
        if env_unset("SPIRITSTREAM_TWITCH_CLIENT_ID") {
            assert_eq!(c.get_twitch_client_id(), "TWITCH_CLIENT_ID_PLACEHOLDER");
        }
        if env_unset("SPIRITSTREAM_YOUTUBE_CLIENT_ID") {
            assert_eq!(c.get_youtube_client_id(), "YOUTUBE_CLIENT_ID_PLACEHOLDER");
        }
        if env_unset("SPIRITSTREAM_KICK_CLIENT_ID") {
            assert_eq!(c.get_kick_client_id(), "KICK_CLIENT_ID_PLACEHOLDER");
        }
        if env_unset("SPIRITSTREAM_FACEBOOK_CLIENT_ID") {
            assert_eq!(c.get_facebook_client_id(), "FACEBOOK_CLIENT_ID_PLACEHOLDER");
        }
    }

    #[test]
    fn client_secret_defaults_to_none_when_unset() {
        let c = OAuthConfig::default();
        if env_unset("SPIRITSTREAM_TWITCH_CLIENT_SECRET") {
            assert!(c.get_twitch_client_secret().is_none());
        }
        if env_unset("SPIRITSTREAM_YOUTUBE_CLIENT_SECRET") {
            assert!(c.get_youtube_client_secret().is_none());
        }
        if env_unset("SPIRITSTREAM_KICK_CLIENT_SECRET") {
            assert!(c.get_kick_client_secret().is_none());
        }
        if env_unset("SPIRITSTREAM_FACEBOOK_CLIENT_SECRET") {
            assert!(c.get_facebook_client_secret().is_none());
        }
    }
}

use crate::errors::CoreError;
use log::{error, info};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::net::TcpListener;
use std::time::{Duration, Instant};

use super::pkce::generate_pkce_pair;
use super::provider::OAuthProvider;
use super::tokens::{OAuthCompleteResult, OAuthTokens, OAuthUserInfo};
use super::{network, unknown_provider};

/// Result of initiating an OAuth flow. ts-rs-exported so the
/// `@spiritstream/types` package is the single source of truth on
/// the wire shape — no parallel hand-written TS file.
#[derive(Debug, Clone, Serialize, Deserialize, ts_rs::TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../../../packages/types/src/generated/")]
pub struct OAuthFlowResult {
    /// The URL to open in the browser
    pub auth_url: String,
    /// The port the callback server is listening on
    pub callback_port: u16,
    /// The state parameter for CSRF verification
    pub state: String,
}

/// Pending OAuth flow with PKCE state.
///
/// `state` is also the `HashMap` key the flow is filed under, but we
/// keep a copy inside the value so the callback handler can assert
/// equality between the inbound state param and the stored nonce. Any
/// mismatch indicates an in-memory desync (or tampering) and is
/// refused, even though under normal flow the two are tautologically
/// equal — defense in depth.
#[derive(Debug, Clone)]
pub(super) struct PendingOAuthFlow {
    pub(super) provider: String,
    pub(super) state: String,
    pub(super) code_verifier: String,
    pub(super) redirect_uri: String,
    pub(super) created_at: Instant,
}

impl super::OAuthService {
    /// Find an available port for the callback server.
    /// Uses a small set of fixed ports so that redirect URIs can be pre-registered
    /// with OAuth providers (Twitch requires exact match including port).
    fn find_available_port() -> Result<u16, CoreError> {
        const PREFERRED_PORTS: &[u16] = &[8891, 8892, 8893, 8894, 8895];

        for &port in PREFERRED_PORTS {
            if TcpListener::bind(format!("127.0.0.1:{}", port)).is_ok() {
                return Ok(port);
            }
        }

        for port in 49152..49162 {
            if TcpListener::bind(format!("127.0.0.1:{}", port)).is_ok() {
                return Ok(port);
            }
        }
        Err(CoreError::Internal {
            context: "No available port found for OAuth callback".into(),
        })
    }

    async fn cleanup_expired_flows(&self) {
        let mut flows = self.pending_flows.lock().await;
        let now = Instant::now();
        flows.retain(|_, flow| now.duration_since(flow.created_at) < Duration::from_secs(600));
    }

    /// Build the authorization URL (PKCE optional for code flow).
    fn build_auth_url(
        provider: &OAuthProvider,
        client_id: &str,
        redirect_uri: &str,
        state: &str,
        response_type: &str,
        code_challenge: Option<&str>,
    ) -> String {
        let scopes = provider.scopes.join(" ");

        let mut params = vec![
            ("client_id", client_id),
            ("redirect_uri", redirect_uri),
            ("response_type", response_type),
            ("scope", &scopes),
            ("state", state),
        ];

        if let Some(challenge) = code_challenge {
            params.push(("code_challenge", challenge));
            params.push(("code_challenge_method", "S256"));
        }

        if provider.name == "youtube" {
            params.push(("access_type", "offline"));
            params.push(("prompt", "consent"));
        }

        if provider.name == "twitch" {
            params.push(("force_verify", "true"));
        }

        let query = params
            .iter()
            .map(|(k, v)| format!("{}={}", k, urlencoding::encode(v)))
            .collect::<Vec<_>>()
            .join("&");

        format!("{}?{}", provider.auth_url, query)
    }

    /// Start the OAuth flow for a provider.
    /// Twitch uses implicit flow when no client secret is configured.
    /// YouTube always uses authorization code + PKCE.
    pub async fn start_flow(&self, provider_name: &str) -> Result<OAuthFlowResult, CoreError> {
        self.cleanup_expired_flows().await;

        let config = self.config.lock().await;

        let (provider, client_id, client_secret) = match provider_name {
            "twitch" => (
                OAuthProvider::twitch(),
                config.get_twitch_client_id(),
                config.get_twitch_client_secret(),
            ),
            "youtube" => (
                OAuthProvider::youtube(),
                config.get_youtube_client_id(),
                config.get_youtube_client_secret(),
            ),
            "kick" => (
                OAuthProvider::kick(),
                config.get_kick_client_id(),
                config.get_kick_client_secret(),
            ),
            "facebook" => (
                OAuthProvider::facebook(),
                config.get_facebook_client_id(),
                config.get_facebook_client_secret(),
            ),
            _ => return Err(unknown_provider(provider_name)),
        };

        drop(config);

        let port = Self::find_available_port()?;
        let redirect_uri = format!("http://localhost:{}/oauth/callback", port);

        let (use_implicit, use_pkce) = match provider_name {
            // Twitch requires client secret for auth-code token exchange.
            // Fall back to implicit flow when no secret is configured.
            "twitch" => (client_secret.is_none(), false),
            // Kick mandates auth code + PKCE (OAuth 2.1 — no implicit flow).
            "kick" => (false, true),
            // Facebook's web OAuth uses auth code + App Secret (no PKCE).
            // The token exchange requires both client_id + client_secret.
            "facebook" => (false, false),
            // YouTube uses auth code + PKCE.
            _ => (false, true),
        };

        let (code_verifier, code_challenge) = if use_pkce {
            let (v, c) = generate_pkce_pair();
            (v, Some(c))
        } else {
            (String::new(), None)
        };

        let state = uuid::Uuid::new_v4().to_string();
        let response_type = if use_implicit { "token" } else { "code" };
        let auth_url = Self::build_auth_url(
            &provider,
            &client_id,
            &redirect_uri,
            &state,
            response_type,
            code_challenge.as_deref(),
        );

        let id_len = client_id.len();
        let (id_prefix, id_suffix) = if id_len > 12 {
            (&client_id[..6], &client_id[id_len - 6..])
        } else {
            (client_id.as_str(), client_id.as_str())
        };
        info!(
            "OAuth start: provider={}, client_id_hint={}...{}, len={}",
            provider_name, id_prefix, id_suffix, id_len
        );

        let pending_flow = PendingOAuthFlow {
            provider: provider_name.to_string(),
            state: state.clone(),
            code_verifier,
            redirect_uri: redirect_uri.clone(),
            created_at: Instant::now(),
        };

        {
            let mut flows = self.pending_flows.lock().await;
            flows.insert(state.clone(), pending_flow);
        }

        let flow_label = if use_implicit {
            "implicit"
        } else if use_pkce {
            "PKCE"
        } else {
            "auth code"
        };
        info!(
            "Starting {} OAuth flow with {} on port {}",
            provider_name, flow_label, port
        );

        Ok(OAuthFlowResult {
            auth_url,
            callback_port: port,
            state,
        })
    }

    /// Exchange an authorization code for tokens (PKCE flow).
    pub async fn exchange_code(
        &self,
        provider_name: &str,
        code: &str,
        state: &str,
    ) -> Result<OAuthTokens, CoreError> {
        let pending_flow = {
            let mut flows = self.pending_flows.lock().await;
            flows.remove(state).ok_or(CoreError::Unauthorized)?
        };

        // CSRF defense in depth: the HashMap key MUST equal the stored
        // state nonce. Under normal flow this is tautological — we
        // inserted with `state.clone()` as both key and value. A
        // divergence here indicates in-memory tampering or a logic bug,
        // and we refuse the callback rather than continuing.
        if pending_flow.state != state {
            error!(
                "OAuth state desync for provider={}: refusing callback",
                provider_name
            );
            return Err(CoreError::Unauthorized);
        }

        if pending_flow.provider != provider_name {
            return Err(CoreError::Internal {
                context: "Provider mismatch in OAuth flow".into(),
            });
        }

        let config = self.config.lock().await;

        let (provider, client_id, client_secret) = match provider_name {
            "twitch" => (
                OAuthProvider::twitch(),
                config.get_twitch_client_id(),
                config.get_twitch_client_secret(),
            ),
            "youtube" => (
                OAuthProvider::youtube(),
                config.get_youtube_client_id(),
                config.get_youtube_client_secret(),
            ),
            "kick" => (
                OAuthProvider::kick(),
                config.get_kick_client_id(),
                config.get_kick_client_secret(),
            ),
            "facebook" => (
                OAuthProvider::facebook(),
                config.get_facebook_client_id(),
                config.get_facebook_client_secret(),
            ),
            _ => return Err(unknown_provider(provider_name)),
        };

        drop(config);

        let mut params = HashMap::new();
        params.insert("client_id", client_id.as_str());
        params.insert("code", code);
        if !pending_flow.code_verifier.is_empty() {
            params.insert("code_verifier", pending_flow.code_verifier.as_str());
        }
        params.insert("grant_type", "authorization_code");
        params.insert("redirect_uri", pending_flow.redirect_uri.as_str());

        let client_secret_owned = client_secret.clone();
        if let Some(ref secret) = client_secret_owned {
            params.insert("client_secret", secret.as_str());
        }

        info!(
            "Exchanging {} authorization code for tokens (PKCE{})",
            provider_name,
            if client_secret.is_some() {
                " + secret"
            } else {
                ""
            }
        );

        let response = self
            .http_client
            .post(provider.token_url)
            .form(&params)
            .send()
            .await
            .map_err(|e| network(format!("Token exchange request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            // Deliberately NOT logging the response body. OAuth providers
            // routinely echo the submitted form fields (including
            // `refresh_token`, `client_secret`, `code`) inside error JSON
            // — masking is brittle, omission is correct.
            let _ = response.text().await;
            error!("Token exchange failed: {}", status);
            return Err(network(format!(
                "Token exchange failed: {status}. Please try again."
            )));
        }

        let tokens: OAuthTokens = response.json().await.map_err(|e| CoreError::Internal {
            context: format!("Failed to parse token response: {e}"),
        })?;

        info!("Successfully obtained {} tokens via PKCE", provider_name);
        Ok(tokens)
    }

    /// Complete the OAuth flow: exchange code, fetch user info.
    pub async fn complete_flow(
        &self,
        provider_name: &str,
        code: &str,
        state: &str,
    ) -> Result<OAuthCompleteResult, CoreError> {
        let tokens = self.exchange_code(provider_name, code, state).await?;

        let user_info = match provider_name {
            "twitch" => {
                let user = self.fetch_twitch_user(&tokens.access_token).await?;
                OAuthUserInfo {
                    provider: "twitch".to_string(),
                    user_id: user.id,
                    username: user.login,
                    display_name: user.display_name,
                }
            }
            "youtube" => {
                let channel = self.fetch_youtube_channel(&tokens.access_token).await?;
                OAuthUserInfo {
                    provider: "youtube".to_string(),
                    user_id: channel.id.clone(),
                    username: channel.id,
                    display_name: channel.title,
                }
            }
            "facebook" => {
                let user = self.fetch_facebook_user(&tokens.access_token).await?;
                OAuthUserInfo {
                    provider: "facebook".to_string(),
                    user_id: user.id,
                    username: user.name.clone(),
                    display_name: user.name,
                }
            }
            "kick" => {
                let user = self.fetch_kick_user(&tokens.access_token).await?;
                OAuthUserInfo {
                    provider: "kick".to_string(),
                    user_id: user.user_id.to_string(),
                    username: user.name.clone(),
                    display_name: user.name,
                }
            }
            _ => return Err(unknown_provider(provider_name)),
        };

        info!(
            "OAuth flow complete for {} user: {}",
            provider_name, user_info.display_name
        );

        Ok(OAuthCompleteResult { tokens, user_info })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::errors::CoreError;
    use crate::services::oauth::{OAuthConfig, OAuthService};

    #[test]
    fn build_auth_url_includes_core_params_and_encodes() {
        let p = OAuthProvider::twitch();
        let url = OAuthService::build_auth_url(
            &p,
            "cid",
            "http://localhost:8891/oauth/callback",
            "st8",
            "code",
            None,
        );
        assert!(url.starts_with("https://id.twitch.tv/oauth2/authorize?"));
        assert!(url.contains("client_id=cid"));
        assert!(url.contains("redirect_uri=http%3A%2F%2Flocalhost%3A8891%2Foauth%2Fcallback"));
        assert!(url.contains("state=st8"));
        assert!(url.contains("response_type=code"));
        assert!(url.contains("force_verify=true"));
        assert!(!url.contains("code_challenge"));
    }

    #[test]
    fn build_auth_url_adds_pkce_challenge_when_present() {
        let p = OAuthProvider::kick();
        let url = OAuthService::build_auth_url(&p, "cid", "http://x/cb", "s", "code", Some("CHAL"));
        assert!(url.contains("code_challenge=CHAL"));
        assert!(url.contains("code_challenge_method=S256"));
    }

    #[test]
    fn build_auth_url_youtube_adds_offline_consent_and_encodes_scope() {
        let p = OAuthProvider::youtube();
        let url = OAuthService::build_auth_url(&p, "cid", "http://x/cb", "s", "code", Some("C"));
        assert!(url.contains("access_type=offline"));
        assert!(url.contains("prompt=consent"));
        assert!(url.contains("scope=https%3A%2F%2Fwww.googleapis.com"));
