impl super::OAuthService {
    /// Pre-flight check: does this token expire within `leeway_secs` of now?
    /// Callers about to use an access token should call this and request a
    /// refresh when it returns `true` to avoid an in-flight 401. Expiry
    /// handling lives in core (this method), not in every consumer.
    ///
    /// `expires_at` is Unix epoch seconds; `0` means "no expiry recorded"
    /// (treated as not-expiring so we don't churn refresh on freshly-set
    /// profiles that haven't been issued a real expiry yet).
    pub fn token_needs_refresh(&self, expires_at: i64, leeway_secs: i64) -> bool {
        if expires_at == 0 {
            return false;
        }
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
            .unwrap_or(0);
        expires_at <= now.saturating_add(leeway_secs)
    }

    /// Refresh `access_token` only when it's about to expire. Idempotent —
    /// returns `Ok(None)` if no refresh was needed, `Ok(Some(new_tokens))`
    /// when the access token was actually rotated, or `Err(CoreError)` on
    /// failure. Callers persist the new tokens themselves so the storage
    /// boundary (encrypted-at-rest) stays in one place.
    pub async fn refresh_if_expiring(
        &self,
        provider_name: &str,
        refresh_token: &str,
        expires_at: i64,
        leeway_secs: i64,
    ) -> Result<Option<OAuthTokens>, CoreError> {
        if !self.token_needs_refresh(expires_at, leeway_secs) {
            return Ok(None);
        }
        if refresh_token.is_empty() {
            // No refresh token to spend — surface as Unauthorized so the
            // transport can prompt the user to log in again.
            return Err(CoreError::Unauthorized);
        }
        let tokens = self.refresh_token(provider_name, refresh_token).await?;
        Ok(Some(tokens))
    }

    /// Iterate every supported provider on the given profile, refresh any
    /// access token that's inside the leeway window, and mutate the profile
    /// in place with the rotated credentials. The caller is responsible for
    /// persisting the profile when `outcome.refreshed` is non-empty.
    ///
    /// Per-provider refresh failures are logged + surveilled but never abort
    /// the loop: a Twitch network blip must not block YouTube refresh. The
    /// `failed` list carries the providers the transport should surface as
    /// "needs re-auth" — the orchestration owner decides how (bus event,
    /// CLI exit code, etc).
    pub async fn refresh_profile_tokens(
        &self,
        profile: &mut crate::models::Profile,
        leeway_secs: i64,
        surveillance: Option<&Arc<crate::services::AuthSurveillanceService>>,
    ) -> Result<OAuthRefreshOutcome, CoreError> {
        let mut outcome = OAuthRefreshOutcome::default();

        for provider in ["twitch", "youtube", "kick", "facebook"] {
            let (access, refresh, expires_at) = match provider {
                "twitch" => (
                    profile.settings.oauth.twitch.access_token.clone(),
                    profile.settings.oauth.twitch.refresh_token.clone(),
                    profile.settings.oauth.twitch.expires_at,
                ),
                "youtube" => (
                    profile.settings.oauth.youtube.access_token.clone(),
                    profile.settings.oauth.youtube.refresh_token.clone(),
                    profile.settings.oauth.youtube.expires_at,
                ),
                "kick" => (
                    profile.settings.oauth.kick.access_token.clone(),
                    profile.settings.oauth.kick.refresh_token.clone(),
                    profile.settings.oauth.kick.expires_at,
                ),
                "facebook" => (
                    profile.settings.oauth.facebook.access_token.clone(),
                    profile.settings.oauth.facebook.refresh_token.clone(),
                    profile.settings.oauth.facebook.expires_at,
                ),
                _ => continue,
            };
            if access.is_empty() || refresh.is_empty() {
                continue;
            }
            match self
                .refresh_if_expiring(provider, &refresh, expires_at, leeway_secs)
                .await
            {
                Ok(None) => {}
                Ok(Some(tokens)) => {
                    if let Some(s) = surveillance {
                        let _ = s.record_oauth_refresh(provider, true).await;
                    }
                    let now_secs = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
                        .unwrap_or(0);
                    let expires_in =
                        i64::try_from(tokens.expires_in.unwrap_or(0)).unwrap_or(i64::MAX);
                    let new_expires = now_secs.saturating_add(expires_in);
                    match provider {
                        "twitch" => {
                            profile.settings.oauth.twitch.access_token = tokens.access_token;
                            if let Some(rt) = tokens.refresh_token {
                                profile.settings.oauth.twitch.refresh_token = rt;
                            }
                            profile.settings.oauth.twitch.expires_at = new_expires;
                        }
                        "youtube" => {
                            profile.settings.oauth.youtube.access_token = tokens.access_token;
                            if let Some(rt) = tokens.refresh_token {
                                profile.settings.oauth.youtube.refresh_token = rt;
                            }
                            profile.settings.oauth.youtube.expires_at = new_expires;
                        }
                        "kick" => {
                            profile.settings.oauth.kick.access_token = tokens.access_token;
                            if let Some(rt) = tokens.refresh_token {
                                profile.settings.oauth.kick.refresh_token = rt;
                            }
                            profile.settings.oauth.kick.expires_at = new_expires;
                        }
                        "facebook" => {
                            profile.settings.oauth.facebook.access_token = tokens.access_token;
                            if let Some(rt) = tokens.refresh_token {
                                profile.settings.oauth.facebook.refresh_token = rt;
                            }
                            profile.settings.oauth.facebook.expires_at = new_expires;
                        }
                        _ => {}
                    }
                    outcome.refreshed.push(provider.to_string());
                }
                Err(e) => {
                    if let Some(s) = surveillance {
                        let _ = s.record_oauth_refresh(provider, false).await;
                    }
                    log::warn!("OAuth refresh for {provider} failed during activate: {e}");
                    outcome.failed.push(provider.to_string());
                }
            }
        }

        Ok(outcome)
    }

    /// Refresh an access token using a refresh token.
    pub async fn refresh_token(
        &self,
        provider_name: &str,
        refresh_token: &str,
    ) -> Result<OAuthTokens, CoreError> {
        let config = self.config.lock().await;

        let (provider, client_id, client_secret) = match provider_name {
            "twitch" => (
                OAuthProvider::twitch(),
                config.get_twitch_client_id(),
                config.get_twitch_client_secret(),
            ),
            "youtube" => (
                OAuthProvider::youtube(),
                config.get_youtube_client_id(),
                config.get_youtube_client_secret(),
            ),
            "kick" => (
                OAuthProvider::kick(),
                config.get_kick_client_id(),
                config.get_kick_client_secret(),
            ),
            "facebook" => (
                OAuthProvider::facebook(),
                config.get_facebook_client_id(),
                config.get_facebook_client_secret(),
            ),
            _ => return Err(unknown_provider(provider_name)),
        };

        drop(config);

        let mut params = HashMap::new();
        params.insert("client_id", client_id.as_str());
        params.insert("refresh_token", refresh_token);
        params.insert("grant_type", "refresh_token");

        // Google Desktop apps require client_secret even for refresh (non-standard).
        let client_secret_owned = client_secret;
        if let Some(ref secret) = client_secret_owned {
            params.insert("client_secret", secret.as_str());
        }

        info!("Refreshing {} access token", provider_name);

        let response = self
            .http_client
            .post(provider.token_url)
            .form(&params)
            .send()
            .await
            .map_err(|e| network(format!("Token refresh request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            // Drop the body without logging — providers echo submitted form
            // fields (refresh_token, client_secret) in error JSON.
            let _ = response.text().await;
            error!("Token refresh failed: {}", status);
            // Differentiate so callers know whether to prompt re-login
            // (4xx — refresh token revoked / bad_grant) or retry after
            // backoff (5xx — provider transient outage).
            return if status.is_client_error() {
                Err(CoreError::Unauthorized)
            } else {
                Err(CoreError::NetworkError {
                    detail: format!("Token refresh failed: {status}"),
                })
            };
        }

        let tokens: OAuthTokens = response.json().await.map_err(|e| CoreError::Internal {
            context: format!("Failed to parse token response: {e}"),
        })?;

        info!("Successfully refreshed {} tokens", provider_name);
        Ok(tokens)
    }

    /// Fetch Twitch user info using an access token.
    pub async fn fetch_twitch_user(&self, access_token: &str) -> Result<TwitchUser, CoreError> {
        let config = self.config.lock().await;
        let client_id = config.get_twitch_client_id();
        drop(config);

        let response = self
            .http_client
            .get("https://api.twitch.tv/helix/users")
            .header("Authorization", format!("Bearer {}", access_token))
            .header("Client-Id", client_id)
            .send()
            .await
            .map_err(|e| network(format!("Twitch user request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            let _ = response.text().await;
            error!("Twitch user fetch failed: {}", status);
            return Err(CoreError::Unauthorized);
        }

        #[derive(Deserialize)]
        struct TwitchResponse {
            data: Vec<TwitchUser>,
        }

        let data: TwitchResponse = response.json().await.map_err(|e| CoreError::Internal {
            context: format!("Failed to parse Twitch response: {e}"),
        })?;

        data.data
            .into_iter()
            .next()
            .ok_or_else(|| CoreError::Internal {
                context: "No user data in Twitch response".into(),
            })
    }

    /// Fetch YouTube channel info using an access token.
    pub async fn fetch_youtube_channel(
        &self,
        access_token: &str,
    ) -> Result<YouTubeChannel, CoreError> {
        let response = self
            .http_client
            .get("https://www.googleapis.com/youtube/v3/channels")
            .query(&[("part", "snippet"), ("mine", "true")])
            .header("Authorization", format!("Bearer {}", access_token))
            .send()
            .await
            .map_err(|e| network(format!("YouTube channel request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            let _ = response.text().await;
            error!("YouTube channel fetch failed: {}", status);
            return Err(CoreError::Unauthorized);
        }

        #[derive(Deserialize)]
        struct YouTubeResponse {
            items: Option<Vec<YouTubeItem>>,
        }

        #[derive(Deserialize)]
        struct YouTubeItem {
            id: String,
            snippet: YouTubeSnippet,
        }

        #[derive(Deserialize)]
        struct YouTubeSnippet {
            title: String,
        }

        let data: YouTubeResponse = response.json().await.map_err(|e| CoreError::Internal {
            context: format!("Failed to parse YouTube response: {e}"),
        })?;

        let item = data
            .items
            .and_then(|items| items.into_iter().next())
            .ok_or_else(|| CoreError::Internal {
                context: "No channel data in YouTube response".into(),
            })?;

        Ok(YouTubeChannel {
            id: item.id,
            title: item.snippet.title,
        })
    }

    /// Validate a Twitch token and get user info (alias for fetch_twitch_user).
    pub async fn validate_twitch_token(&self, access_token: &str) -> Result<TwitchUser, CoreError> {
        self.fetch_twitch_user(access_token).await
    }

    /// Fetch the bearer-identified Facebook user. Meta's `/me` endpoint
    /// returns the user id + display name; the same id is the seed for
    /// looking up Pages the user manages (`/me/accounts`) — which is
    /// what the Live Video connector needs the Page Access Token of.
    pub async fn fetch_facebook_user(&self, access_token: &str) -> Result<FacebookUser, CoreError> {
        let response = self
            .http_client
            .get("https://graph.facebook.com/v18.0/me")
            .query(&[("fields", "id,name"), ("access_token", access_token)])
            .send()
            .await
            .map_err(|e| network(format!("Facebook user request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            let _ = response.text().await;
            error!("Facebook user fetch failed: {}", status);
            return Err(CoreError::Unauthorized);
        }

        response
            .json::<FacebookUser>()
            .await
            .map_err(|e| CoreError::Internal {
                context: format!("Failed to parse Facebook user response: {e}"),
            })
    }

    /// Fetch the bearer-identified Kick user. Kick exposes a `users` REST
    /// endpoint that returns the broadcaster id needed to address
    /// `POST /public/v1/chat`.
    pub async fn fetch_kick_user(&self, access_token: &str) -> Result<KickUser, CoreError> {
        let response = self
            .http_client
            .get("https://api.kick.com/public/v1/users")
            .header("Authorization", format!("Bearer {access_token}"))
            .header("Accept", "application/json")
            .send()
            .await
            .map_err(|e| network(format!("Kick user request failed: {e}")))?;

        if !response.status().is_success() {
            let status = response.status();
            let _ = response.text().await;
            error!("Kick user fetch failed: {}", status);
            return Err(CoreError::Unauthorized);
        }

        #[derive(Deserialize)]
        struct KickEnvelope {
            data: Vec<KickUser>,
        }

        let envelope: KickEnvelope = response.json().await.map_err(|e| CoreError::Internal {
            context: format!("Failed to parse Kick user response: {e}"),
        })?;

        envelope
            .data
            .into_iter()
            .next()
            .ok_or_else(|| CoreError::Internal {
                context: "No user data in Kick response".into(),
            })
    }

    /// Revoke a token (best effort — not all providers support this).
    pub async fn revoke_token(&self, provider_name: &str, token: &str) -> Result<(), CoreError> {
        match provider_name {
            "twitch" => {
                let config = self.config.lock().await;
                let client_id = config.get_twitch_client_id();
                drop(config);

                let response = self
                    .http_client
                    .post("https://id.twitch.tv/oauth2/revoke")
                    .form(&[("client_id", client_id.as_str()), ("token", token)])
                    .send()
                    .await
                    .map_err(|e| network(format!("Token revoke request failed: {e}")))?;

                if !response.status().is_success() {
                    warn!("Twitch token revocation returned non-success status");
                }
                Ok(())
            }
            "youtube" => {
                let response = self
                    .http_client
                    .post("https://oauth2.googleapis.com/revoke")
                    .form(&[("token", token)])
                    .send()
                    .await
                    .map_err(|e| network(format!("Token revoke request failed: {e}")))?;

                if !response.status().is_success() {
                    warn!("YouTube token revocation returned non-success status");
                }
                Ok(())
            }
            "facebook" => {
                // Meta's revocation endpoint: DELETE /me/permissions.
                // This revokes *all* the app's permissions for the
                // bearer-identified user, which is what "forget" should
                // do — partial revocation isn't something the UI exposes.
                let response = self
                    .http_client
                    .delete("https://graph.facebook.com/v18.0/me/permissions")
                    .query(&[("access_token", token)])
                    .send()
                    .await
                    .map_err(|e| network(format!("Token revoke request failed: {e}")))?;

                if !response.status().is_success() {
                    warn!("Facebook token revocation returned non-success status");
                }
                Ok(())
            }
            "kick" => {
                let config = self.config.lock().await;
                let client_id = config.get_kick_client_id();
                drop(config);

                // Kick's id.kick.com supports token revocation per RFC 7009.
                let response = self
                    .http_client
                    .post("https://id.kick.com/oauth/revoke")
                    .form(&[("client_id", client_id.as_str()), ("token", token)])
                    .send()
                    .await
                    .map_err(|e| network(format!("Token revoke request failed: {e}")))?;

                if !response.status().is_success() {
                    warn!("Kick token revocation returned non-success status");
                }
                Ok(())
            }
            _ => Err(unknown_provider(provider_name)),
        }
    }
}

#[cfg(test)]
mod debug_redaction_tests {
    use super::*;

    /// F5 regression: `OAuthTokens` must not surface its bearer or
    /// refresh values through `{:?}` rendering. Pre-F5 the default
    /// derive printed the literal token any time a log line, panic
    /// message, or `dbg!()` touched the struct.
    #[test]
    fn debug_redacts_oauth_tokens() {
        let tokens = OAuthTokens {
            access_token: "SUPER-SECRET-OAUTH-BEARER".into(),
            refresh_token: Some("SUPER-SECRET-OAUTH-REFRESH".into()),
            expires_in: Some(3600),
            token_type: Some("Bearer".into()),
            scope: Some("chat:read chat:edit".into()),
        };
        let rendered = format!("{tokens:?}");
        assert!(
            !rendered.contains("SUPER-SECRET-OAUTH-BEARER"),
            "access_token leaked via Debug: {rendered}",
        );
        assert!(
            !rendered.contains("SUPER-SECRET-OAUTH-REFRESH"),
            "refresh_token leaked via Debug: {rendered}",
        );
        assert!(rendered.contains("<redacted>"));
        // Non-secret fields survive so logs remain useful.
        assert!(rendered.contains("Bearer"));
        assert!(rendered.contains("chat:read"));
    }

    use super::super::{OAuthConfig, OAuthService};

    fn svc() -> OAuthService {
        OAuthService::new(OAuthConfig::default())
    }

    #[test]
    fn token_needs_refresh_treats_zero_expiry_as_never() {
        // `0` means "no expiry recorded" — a freshly-set profile must not
        // churn refresh just because its expiry hasn't been issued yet.
        assert!(!svc().token_needs_refresh(0, 60));
        assert!(!svc().token_needs_refresh(0, 0));
    }

    #[test]
    fn token_needs_refresh_true_when_already_past_expiry() {
        // An expiry one hour in the past is unambiguously stale.
        let one_hour_ago = now_secs() - 3600;
        assert!(svc().token_needs_refresh(one_hour_ago, 0));
    }

    #[test]
    fn token_needs_refresh_false_when_outside_leeway_window() {
        // Expiry an hour out with a 60s leeway: plenty of runway, no refresh.
        let one_hour_ahead = now_secs() + 3600;
        assert!(!svc().token_needs_refresh(one_hour_ahead, 60));
    }

    #[test]
    fn token_needs_refresh_true_when_inside_leeway_window() {
        // Expiry 30s out with a 120s leeway: inside the pre-emptive window,
        // refresh now to avoid an in-flight 401.
        let thirty_seconds_ahead = now_secs() + 30;
        assert!(svc().token_needs_refresh(thirty_seconds_ahead, 120));
    }

    fn now_secs() -> i64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0)
    }
}

use std::sync::Arc;

use crate::services::{EventSink, FFmpegHandler, ProfileManager, SettingsManager};

use super::types::ObsStreamStatus;

/// OBS→SpiritStream cascade delay before starting the relay. Mirrors
/// the 2-second stabilization window the frontend used to apply
/// client-side; centralising it here so any client (Tauri / Docker /
/// CLI) gets the same behaviour without re-implementing the delay.
const OBS_TRIGGER_DELAY_MS: u64 = 2000;

/// Server-side cascade dependencies. Set once at startup by
/// `ServiceRegistry::build` after every service is constructed. When
/// present, `start_event_listener` runs the OBS→SpiritStream trigger
/// cascade in core (read active profile → check direction → call
/// `FFmpegHandler::start_all`) instead of relying on a frontend
/// observer to do it. Frontend keeps only display state.
#[derive(Clone)]
pub struct ObsCascadeDeps {
    pub profiles: Arc<ProfileManager>,
    pub settings: Arc<SettingsManager>,
    pub ffmpeg: Arc<FFmpegHandler>,
}

/// Wrap any `EventSink + Clone` into an `Arc<dyn EventSink>` so it can
/// flow into `FFmpegHandler::start_all`, which takes a trait-object
/// sink. The wrapper itself implements `EventSink` by delegating to
/// the inner clone.
struct EventSinkClone<E: EventSink + Send + Sync + 'static>(E);

impl<E: EventSink + Send + Sync + 'static> EventSink for EventSinkClone<E> {
    fn emit(&self, event: &str, payload: serde_json::Value) {
        self.0.emit(event, payload);
    }
}

impl super::ObsWebSocketHandler {
    /// Start listening for OBS events via polling.
    ///
    /// When `cascade_deps` is set, the listener runs the
    /// OBS→SpiritStream trigger cascade in core on every active↔inactive
    /// transition (read direction from active profile → optionally
    /// call `FFmpegHandler::start_all` / `stop_all`). The frontend
    /// only sees informational `obs://stream_state` events and an
    /// optional `stream_started_by_obs` / `stream_stopped_by_obs` —
    /// it never decides whether to start streaming.
    pub(super) async fn start_event_listener<E: EventSink + Send + Sync + Clone + 'static>(
        &self,
        event_sink: E,
    ) {
        let state = self.state.clone();
        let client = self.client.clone();
        let triggered_by_us = self.triggered_by_us.clone();
        let cascade_deps = self.cascade_deps.clone();
        let cascade_start_handle = self.cascade_start_handle.clone();
        let mut shutdown_rx = self.shutdown_tx.subscribe();

        // I1: if a previous poll task is already running (reconnect
        // flow), abort it before spawning the replacement. The aborted
        // task observes a CancelError immediately so the old poll loop
        // doesn't continue racing the fresh client.
        if let Some(prev) = self.listener_handle.lock().await.take() {
            prev.abort();
        }

        let handle = tokio::spawn(async move {
            loop {
                if shutdown_rx.try_recv().is_ok() {
                    log::debug!("OBS event listener shutting down");
                    break;
                }

                let client_guard = client.read().await;
                if let Some(ref obs_client) = *client_guard {
                    let sink = event_sink.clone();

                    match obs_client.streaming().status().await {
                        Ok(stream_status) => {
                            let new_status = if stream_status.active {
                                ObsStreamStatus::Active
                            } else {
                                ObsStreamStatus::Inactive
                            };

                            let mut state_guard = state.write().await;
                            if state_guard.stream_status != new_status {
                                state_guard.stream_status = new_status;
                                drop(state_guard);

                                let was_self_triggered = triggered_by_us
                                    .swap(false, std::sync::atomic::Ordering::SeqCst);

                                sink.emit(
                                    "obs://stream_state",
                                    serde_json::json!({
                                        "status": new_status,
                                        "active": stream_status.active,
                                        "triggeredByUs": was_self_triggered,
                                    }),
                                );

                                // Cascade: when not self-triggered, ask
                                // the active profile's `obs.direction`
                                // whether to drive SpiritStream and run
                                // the action server-side.
                                if !was_self_triggered {
                                    let deps_snapshot = match cascade_deps.read() {
                                        Ok(g) => g.clone(),
                                        Err(e) => {
                                            log::error!(
                                                "obs cascade_deps read lock poisoned — OBS→SS cascade dropped: {e}"
                                            );
                                            None
                                        }
                                    };
                                    if let Some(deps) = deps_snapshot {
                                        Self::run_obs_to_ss_cascade(
                                            stream_status.active,
                                            deps,
                                            event_sink.clone(),
                                            cascade_start_handle.clone(),
                                        )
                                        .await;
                                    }
                                }
                            }
                        }
                        Err(e) => {
                            log::debug!("Failed to poll OBS stream status: {e}");
                        }
                    }
                } else {
                    break;
                }
                drop(client_guard);

                tokio::time::sleep(std::time::Duration::from_secs(2)).await;
            }
        });
        *self.listener_handle.lock().await = Some(handle);
    }

    /// Run the OBS→SpiritStream trigger cascade. Decides whether to
    /// start/stop SpiritStream based on the active profile's
    /// `obs.direction` and current FFmpeg state. Spawns a delayed task
    /// for the actual start so OBS has time to settle. The delayed-start
    /// task handle is captured in `cascade_start_handle` (I1) so OBS
    /// oscillation inside the delay window cancels the stale start
    /// instead of queueing a duplicate.
    async fn run_obs_to_ss_cascade<E: EventSink + Send + Sync + 'static>(
        obs_now_active: bool,
        deps: ObsCascadeDeps,
        event_sink: E,
        cascade_start_handle: Arc<tokio::sync::Mutex<Option<tokio::task::JoinHandle<()>>>>,
    ) {
        let Ok(settings) = deps.settings.load() else {
            return;
        };
        let Some(active_name) = settings.last_profile.clone() else {
            return;
        };
        let profile = match deps
            .profiles
            .load_with_key_decryption(&active_name, None)
            .await
        {
            Ok(p) => p,
            Err(err) => {
                log::warn!("OBS cascade: failed to load active profile '{active_name}': {err}");
                return;
            }
        };
        let direction = profile.settings.obs.direction;
        let allowed = matches!(
            direction,
            crate::models::ObsIntegrationDirection::ObsToSpiritstream
                | crate::models::ObsIntegrationDirection::Bidirectional
        );
        if !allowed {
            return;
        }

        if obs_now_active {
            // OBS started → start SpiritStream if not already.
            let already = deps.ffmpeg.active_count() > 0;
            if already {
                log::debug!("OBS cascade: SpiritStream already streaming, skipping start trigger");
                return;
            }
            let eligible: Vec<_> = profile
                .output_groups
                .iter()
                .filter(|g| !g.stream_targets.is_empty())
                .cloned()
                .collect();
            if eligible.is_empty() {
                log::warn!("OBS cascade: no eligible output groups, skipping start trigger");
                return;
            }
            let incoming_url = format!(
                "rtmp://{}:{}/{}",
                profile.input.bind_address, profile.input.port, profile.input.application
            );
            let count = eligible.len();
            let delay = std::time::Duration::from_millis(OBS_TRIGGER_DELAY_MS);
            let ffmpeg = deps.ffmpeg.clone();
            let sink_arc: Arc<dyn EventSink> = Arc::new(EventSinkClone(event_sink));
            let handle = tokio::spawn(async move {
                tokio::time::sleep(delay).await;
                match ffmpeg.start_all(&eligible, &incoming_url, sink_arc.clone()) {
                    Ok(_) => {
                        log::info!("OBS cascade: started SpiritStream ({count} groups)");
                        sink_arc.emit(
                            "stream_started_by_obs",
                            serde_json::json!({ "groupCount": count }),
                        );
                    }
                    Err(err) => {
                        log::error!("OBS cascade: failed to start SpiritStream: {err}");
                    }
                }
            });
            // Single-flight: cancel any prior delayed-start before
            // recording the new one. Lock contention here is fine —
            // we only reach this branch on an active-transition.
            let mut guard = cascade_start_handle.lock().await;
            if let Some(prev) = guard.take() {
                prev.abort();
            }
            *guard = Some(handle);
        } else {
            // OBS stopped → stop SpiritStream if streaming.
            if deps.ffmpeg.active_count() == 0 {
                return;
            }
            match deps.ffmpeg.stop_all() {
                Ok(_) => {
                    log::info!("OBS cascade: stopped SpiritStream");
                    event_sink.emit("stream_stopped_by_obs", serde_json::json!({}));
                }
                Err(err) => {
                    log::error!("OBS cascade: failed to stop SpiritStream: {err}");
                }
            }
        }
    }
}

use crate::errors::CoreError;

use super::obs_not_connected;

impl super::ObsWebSocketHandler {
    /// Start streaming in OBS
    pub async fn start_stream(&self) -> Result<(), CoreError> {
        let client = self.client.read().await;
        if let Some(ref client) = *client {
            // Flip the loop-prevention flag before driving OBS so the inbound
            // state event that follows doesn't trigger SpiritStream→OBS back.
            self.mark_triggered_by_us();
            client
                .streaming()
                .start()
                .await
                .map_err(|e| CoreError::Internal {
                    context: format!("Failed to start OBS stream: {e}"),
                })?;
            log::info!("Started OBS stream");
            Ok(())
        } else {
            Err(obs_not_connected())
        }
    }

    /// Stop streaming in OBS
    pub async fn stop_stream(&self) -> Result<(), CoreError> {
        let client = self.client.read().await;
        if let Some(ref client) = *client {
            self.mark_triggered_by_us();
            client
                .streaming()
                .stop()
                .await
                .map_err(|e| CoreError::Internal {
                    context: format!("Failed to stop OBS stream: {e}"),
                })?;
            log::info!("Stopped OBS stream");
            Ok(())
        } else {
            Err(obs_not_connected())
        }
    }

    /// Helper called by the `ObsTrigger` impl: drive OBS to start its
    /// stream when the active profile's direction allows SpiritStream
    /// → OBS triggering. Sets `triggered_by_us` first so the inbound
    /// state event doesn't bounce back through the OBS→SS cascade.
    pub(super) async fn ss_trigger_obs(&self, start: bool) {
        let cascade = match self.cascade_deps.read() {
            Ok(g) => g.clone(),
            Err(e) => {
                log::error!("obs cascade_deps read lock poisoned — SS→OBS trigger dropped: {e}");
                return;
            }
        };
        let Some(deps) = cascade else { return };
        let Ok(settings) = deps.settings.load() else {
            return;
        };
        let Some(active_name) = settings.last_profile.clone() else {
            return;
        };
        let profile = match deps
            .profiles
            .load_with_key_decryption(&active_name, None)
            .await
        {
            Ok(p) => p,
            Err(err) => {
                log::warn!("SS→OBS cascade: failed to load profile '{active_name}': {err}");
                return;
            }
        };
        let direction = profile.settings.obs.direction;
        let allowed = matches!(
            direction,
            crate::models::ObsIntegrationDirection::SpiritstreamToObs
                | crate::models::ObsIntegrationDirection::Bidirectional
        );
        if !allowed {
            return;
        }
        let connected = matches!(
            self.state.read().await.connection_status,
            super::types::ObsConnectionStatus::Connected
        );
        if !connected {
            log::debug!("SS→OBS cascade: OBS not connected, skipping trigger");
            return;
        }
        let client_guard = self.client.read().await;
        let Some(ref client) = *client_guard else {
            return;
        };
        self.mark_triggered_by_us();
        let result = if start {
            client.streaming().start().await
        } else {
            client.streaming().stop().await
        };
        if let Err(err) = result {
            log::warn!(
                "SS→OBS cascade: OBS {} failed: {err}",
                if start { "start" } else { "stop" }
            );
        } else {
            log::info!(
                "SS→OBS cascade: OBS {} succeeded",
                if start { "started" } else { "stopped" }
            );
        }
    }
}

// Forward the workspace-level trait so `FFmpegHandler` can hold
// `Arc<dyn ObsTrigger>` without depending on the concrete handler.
#[async_trait::async_trait]
impl crate::services::ObsTrigger for super::ObsWebSocketHandler {
    async fn trigger_start(&self) {
        self.ss_trigger_obs(true).await;
    }
    async fn trigger_stop(&self) {
        self.ss_trigger_obs(false).await;
    }
}

use obws::Client;
use std::sync::Arc;

use crate::errors::CoreError;
use crate::services::{Encryption, EventSink};

use super::types::{ObsConfig, ObsConnectionStatus, ObsStreamStatus};

impl super::ObsWebSocketHandler {
    /// Connect with exponential-backoff auto-retry. Used by the
    /// startup auto-connect flow when the active profile's
    /// `obs.auto_connect` flag is on. Honors `shutdown_tx` so a manual
    /// `disconnect()` (or app shutdown) interrupts the retry loop
    /// immediately. Backend-side replacement for the frontend's
    /// previous `useObsEvents.ts` retry state machine — same backoff
    /// curve (200ms → 30s, multiplier 1.5).
    pub fn spawn_auto_connect<E: EventSink + Send + Sync + Clone + 'static>(
        self: Arc<Self>,
        event_sink: E,
    ) {
        const INITIAL_DELAY_MS: u64 = 2000;
        const MAX_DELAY_MS: u64 = 30000;
        const BACKOFF_MULT: f64 = 1.5;
        let mut shutdown_rx = self.shutdown_tx.subscribe();
        let handler = self.clone();
        tokio::spawn(async move {
            let mut delay_ms = INITIAL_DELAY_MS;
            loop {
                if shutdown_rx.try_recv().is_ok() {
                    log::debug!("OBS auto-connect loop interrupted by shutdown");
                    break;
                }
                let already = matches!(
                    handler.state.read().await.connection_status,
                    ObsConnectionStatus::Connected | ObsConnectionStatus::Connecting
                );
                if already {
                    break;
                }
                match handler.connect(event_sink.clone()).await {
                    Ok(()) => {
                        log::info!("OBS auto-connect: connected");
                        break;
                    }
                    Err(err) => {
                        log::info!(
                            "OBS auto-connect: attempt failed ({err}); retrying in {delay_ms}ms"
                        );
                        tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
                        delay_ms =
                            ((delay_ms as f64) * BACKOFF_MULT).min(MAX_DELAY_MS as f64) as u64;
                    }
                }
            }
        });
    }

    pub async fn connect<E: EventSink + Send + Sync + Clone + 'static>(
        &self,
        event_sink: E,
    ) -> Result<(), CoreError> {
        let config = self.config.read().await.clone();

        // Guard against double-connect: if a previous `connect()` is still
        // mid-handshake (state == Connecting) or already finished (Connected),
        // bail out without re-emitting "connecting" or starting a second
        // handshake. The second call would otherwise emit a duplicate event
        // AND race the first call's `client_guard` write — fixing the latter
        // properly needs a cancellation token; for now we just prevent the
        // duplicate state transition.
        {
            let state_read = self.state.read().await;
            if matches!(
                state_read.connection_status,
                ObsConnectionStatus::Connecting | ObsConnectionStatus::Connected
            ) {
                return Ok(());
            }
        }

        {
            let mut state = self.state.write().await;
            state.connection_status = ObsConnectionStatus::Connecting;
            state.error_message = None;
        }

        event_sink.emit(
            "obs://status",
            serde_json::json!({
                "status": "connecting",
                "host": config.host,
                "port": config.port
            }),
        );

        let password = if config.use_auth && !config.password.is_empty() {
            if Encryption::is_stream_key_encrypted(&config.password) {
                Some(Encryption::decrypt_stream_key(
                    &config.password,
                    &self.app_data_dir,
                )?)
            } else {
                Some(config.password.clone())
            }
        } else {
            None
        };

        let connect_result = Client::connect(&config.host, config.port, password).await;

        match connect_result {
            Ok(client) => {
                log::info!(
                    "Connected to OBS WebSocket at {}:{}",
                    config.host,
                    config.port
                );

                let version_info = client.general().version().await.ok();

                {
                    let mut state = self.state.write().await;
                    state.connection_status = ObsConnectionStatus::Connected;
                    state.error_message = None;
                    if let Some(ref info) = version_info {
                        state.obs_version = Some(info.obs_version.to_string());
                        state.websocket_version = Some(info.obs_web_socket_version.to_string());
                    }
                }

                if let Ok(stream_status) = client.streaming().status().await {
                    let mut state = self.state.write().await;
                    state.stream_status = if stream_status.active {
                        ObsStreamStatus::Active
                    } else {
                        ObsStreamStatus::Inactive
                    };
                }

                {
                    let mut client_guard = self.client.write().await;
                    *client_guard = Some(client);
                }

                let state = self.state.read().await.clone();
                event_sink.emit(
                    "obs://status",
                    serde_json::json!({
                        "status": "connected",
                        "obsVersion": state.obs_version,
                        "websocketVersion": state.websocket_version,
                        "streamStatus": state.stream_status
                    }),
                );

                self.start_event_listener(event_sink).await;

                Ok(())
            }
            Err(e) => {
                let error_msg = format!("Failed to connect to OBS: {e}");
                log::error!("{error_msg}");

                {
                    let mut state = self.state.write().await;
                    state.connection_status = ObsConnectionStatus::Error;
                    state.error_message = Some(error_msg.clone());
                }

                event_sink.emit(
                    "obs://status",
                    serde_json::json!({
                        "status": "error",
                        "error": error_msg.clone(),
                    }),
                );

                Err(CoreError::Internal { context: error_msg })
            }
        }
    }

    pub async fn disconnect<E: EventSink>(&self, event_sink: E) -> Result<(), CoreError> {
        let _ = self.shutdown_tx.send(());

        {
            let mut client = self.client.write().await;
            *client = None;
        }

        {
            let mut state = self.state.write().await;
            state.connection_status = ObsConnectionStatus::Disconnected;
            state.stream_status = ObsStreamStatus::Unknown;
            state.error_message = None;
            state.obs_version = None;
            state.websocket_version = None;
        }

        log::info!("Disconnected from OBS WebSocket");

        event_sink.emit(
            "obs://status",
            serde_json::json!({
                "status": "disconnected"
            }),
        );

        Ok(())
    }

    /// Encrypt and save OBS password
    pub fn encrypt_password(&self, password: &str) -> Result<String, CoreError> {
        if password.is_empty() {
            return Ok(String::new());
        }
        Encryption::encrypt_stream_key(password, &self.app_data_dir)
    }

    /// Return the current OBS config with the stored password decrypted for the
    /// caller. Used by the typed REST handler so transports never touch
    /// `Encryption::*` directly — every CoreError flows through the single
    /// `ApiError(CoreError)` mapping on the HTTP side.
    pub async fn get_decrypted_config(&self) -> Result<ObsConfig, CoreError> {
        let mut config = self.config.read().await.clone();
        if !config.password.is_empty() && Encryption::is_stream_key_encrypted(&config.password) {
            config.password = Encryption::decrypt_stream_key(&config.password, &self.app_data_dir)?;
        }
        Ok(config)
    }
}

use obws::Client;
use std::sync::Arc;
use tokio::sync::{broadcast, Mutex as TokioMutex, RwLock};
use tokio::task::JoinHandle;

use super::cascade::ObsCascadeDeps;
use super::types::{IntegrationDirection, ObsConfig, ObsState};

/// Manages OBS WebSocket connection and stream synchronization. The
/// type lives here; method impls are spread across `connection`,
/// `commands`, and `cascade` submodules so each concern is in its own
/// file but all hang off `impl super::ObsWebSocketHandler`.
pub struct ObsWebSocketHandler {
    pub(super) state: Arc<RwLock<ObsState>>,
    pub(super) client: Arc<RwLock<Option<Client>>>,
    pub(super) config: Arc<RwLock<ObsConfig>>,
    pub(super) shutdown_tx: broadcast::Sender<()>,
    pub(super) app_data_dir: std::path::PathBuf,
    /// Loop-prevention flag for SpiritStream → OBS triggers. When this side
    /// initiates an OBS state change (`start_stream` / `stop_stream`), the
    /// subsequent inbound state event would normally bounce back through the
    /// "OBS → SpiritStream" trigger path and cause a feedback loop. We set
    /// this flag before driving OBS, then the OBS event listener atomically
    /// clears it; the orchestration layer reads it via
    /// `consume_triggered_by_us` to know to skip the trigger.
    pub(super) triggered_by_us: Arc<std::sync::atomic::AtomicBool>,
    /// Cascade dependencies (`ProfileManager` / `SettingsManager` /
    /// `FFmpegHandler`). Set once at startup by
    /// `ServiceRegistry::build`. When present, the OBS event listener
    /// runs the OBS→SpiritStream trigger cascade in core — the
    /// frontend never decides "should we start streaming?", it just
    /// renders state changes.
    ///
    /// `std::sync::RwLock` (not `tokio::sync::RwLock`) so the setter
    /// can be called from synchronous code (`ServiceRegistry::build`)
    /// without an executor. Reads on the OBS poll loop are sparse
    /// enough that the lockless cost is irrelevant.
    pub(super) cascade_deps: Arc<std::sync::RwLock<Option<ObsCascadeDeps>>>,
    /// I1: handle to the background poll task spawned in
    /// `start_event_listener`. Pre-I1 we spawned and dropped the join
    /// handle, so the task outlived the handler in unit tests + on
    /// reconnect cycles where the same handler started a fresh poll
    /// loop without cancelling the old one. `Drop` aborts the handle
    /// so the runtime reclaims the task immediately.
    pub(super) listener_handle: Arc<TokioMutex<Option<JoinHandle<()>>>>,
    /// I1: handle to the in-flight OBS→SpiritStream delayed-start task
    /// spawned in `run_obs_to_ss_cascade`. Single-flight — a fresh
    /// trigger aborts the previous delayed task, so OBS oscillating
    /// active↔inactive inside the 2 s OBS_TRIGGER_DELAY_MS window
    /// cancels the stale start instead of queueing duplicates. Drop
    /// also aborts so the task can't outlive the handler.
    pub(super) cascade_start_handle: Arc<TokioMutex<Option<JoinHandle<()>>>>,
}

impl Drop for ObsWebSocketHandler {
    fn drop(&mut self) {
        // Best-effort cancellation. `try_lock` because Drop isn't
        // async and we don't want to block on lock contention from a
        // dying handler. Send shutdown FIRST so a non-locked poll
        // task can observe the broadcast.
        let _ = self.shutdown_tx.send(());
        if let Ok(mut guard) = self.listener_handle.try_lock() {
            if let Some(handle) = guard.take() {
                handle.abort();
            }
        }
        if let Ok(mut guard) = self.cascade_start_handle.try_lock() {
            if let Some(handle) = guard.take() {
                handle.abort();
            }
        }
    }
}

impl ObsWebSocketHandler {
    pub fn new(app_data_dir: std::path::PathBuf) -> Self {
        let (shutdown_tx, _) = broadcast::channel(1);
        Self {
            state: Arc::new(RwLock::new(ObsState::default())),
            client: Arc::new(RwLock::new(None)),
            config: Arc::new(RwLock::new(ObsConfig::default_config())),
            shutdown_tx,
            app_data_dir,
            triggered_by_us: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            cascade_deps: Arc::new(std::sync::RwLock::new(None)),
            listener_handle: Arc::new(TokioMutex::new(None)),
            cascade_start_handle: Arc::new(TokioMutex::new(None)),
        }
    }

    /// Install the cascade deps so the OBS event listener can run the
    /// OBS→SpiritStream trigger in core. Called once by
    /// `ServiceRegistry::build` after all services exist.
    pub fn set_cascade_deps(&self, deps: ObsCascadeDeps) {
        match self.cascade_deps.write() {
            Ok(mut guard) => *guard = Some(deps),
            Err(e) => {
                log::error!("obs cascade_deps write lock poisoned during set_cascade_deps: {e}")
            }
        }
    }

    /// Mark the next OBS state change as one we initiated, so the orchestration
    /// layer can skip its OBS→SpiritStream trigger path for that event.
    pub fn mark_triggered_by_us(&self) {
        self.triggered_by_us
            .store(true, std::sync::atomic::Ordering::SeqCst);
    }

    /// Atomically read-and-clear the triggered-by-us flag. The first observer
    /// of a triggered state event consumes the flag; subsequent observers see
    /// `false` and proceed with normal trigger evaluation.
    pub fn consume_triggered_by_us(&self) -> bool {
        self.triggered_by_us
            .swap(false, std::sync::atomic::Ordering::SeqCst)
    }

    pub async fn set_config(&self, config: ObsConfig) {
        let mut cfg = self.config.write().await;
        *cfg = config;
    }

    pub async fn get_config(&self) -> ObsConfig {
        self.config.read().await.clone()
    }

    pub async fn get_state(&self) -> ObsState {
        self.state.read().await.clone()
    }

    pub async fn is_connected(&self) -> bool {
        let state = self.state.read().await;
        state.connection_status == super::types::ObsConnectionStatus::Connected
    }

    pub async fn get_direction(&self) -> IntegrationDirection {
        self.config.read().await.direction
    }

    pub async fn should_obs_trigger_spiritstream(&self) -> bool {
        let direction = self.get_direction().await;
        matches!(
            direction,
            IntegrationDirection::ObsToSpiritstream | IntegrationDirection::Bidirectional
        )
    }

    pub async fn should_spiritstream_trigger_obs(&self) -> bool {
        let direction = self.get_direction().await;
        matches!(
            direction,
            IntegrationDirection::SpiritstreamToObs | IntegrationDirection::Bidirectional
        )
    }
}

