// SpiritStream Path Validation Service
// Security utility to prevent path traversal attacks

use std::path::{Path, PathBuf};

use crate::errors::{CoreError, ValidationIssue};

fn outside_allowed(path: &Path) -> CoreError {
    CoreError::PathOutsideAllowedRoot {
        path: path.to_string_lossy().to_string(),
    }
}

/// Validate that a path is within an allowed directory (prevents path traversal attacks).
///
/// On success returns the canonicalized path. On failure returns
/// `CoreError::PathOutsideAllowedRoot { path }`; the transport layer maps
/// this to HTTP 403 / CLI exit code per `crates/transport-http/src/error.rs`.
pub fn validate_path_within(path: &Path, allowed_dir: &Path) -> Result<PathBuf, CoreError> {
    // First check for obvious traversal attempts
    let path_str = path.to_string_lossy();
    if path_str.contains("..") {
        return Err(outside_allowed(path));
    }

    // For paths that don't exist yet (like export targets), check the parent directory
    if !path.exists() {
        if let Some(parent) = path.parent() {
            let parent_canonical = parent.canonicalize().map_err(|_| outside_allowed(path))?;
            let allowed_canonical = allowed_dir
                .canonicalize()
                .map_err(|_| outside_allowed(allowed_dir))?;

            if !parent_canonical.starts_with(&allowed_canonical) {
                return Err(outside_allowed(path));
            }

            // Return the intended path (parent + filename)
            if let Some(filename) = path.file_name() {
                return Ok(parent_canonical.join(filename));
            }
        }
        return Err(outside_allowed(path));
    }

    // For existing paths, canonicalize and check
    let canonical = path.canonicalize().map_err(|_| outside_allowed(path))?;
    let allowed_canonical = allowed_dir
        .canonicalize()
        .map_err(|_| outside_allowed(allowed_dir))?;

    if !canonical.starts_with(&allowed_canonical) {
        return Err(outside_allowed(path));
    }

    Ok(canonical)
}

/// Validate that a path is within any of the allowed directories.
///
/// Returns the canonicalized path on the first match. Fails with
/// `CoreError::PathOutsideAllowedRoot` if none of the supplied roots contain
/// the path.
pub fn validate_path_within_any(path: &Path, allowed_dirs: &[&Path]) -> Result<PathBuf, CoreError> {
    for allowed_dir in allowed_dirs {
        if let Ok(validated) = validate_path_within(path, allowed_dir) {
            return Ok(validated);
        }
    }

    Err(outside_allowed(path))
}

/// Validate file extension is allowed.
///
/// Fails with `CoreError::ValidationFailed` carrying `code =
/// "invalid_file_extension"` plus the list of accepted extensions.
pub fn validate_extension(path: &Path, allowed_extensions: &[&str]) -> Result<(), CoreError> {
    let extension =
        path.extension()
            .and_then(|e| e.to_str())
            .ok_or_else(|| CoreError::ValidationFailed {
                reasons: vec![ValidationIssue {
                    code: "missing_file_extension".into(),
                    message: "File must have an extension".into(),
                    path: None,
                }],
            })?;

    if !allowed_extensions.contains(&extension) {
        return Err(CoreError::ValidationFailed {
            reasons: vec![ValidationIssue {
                code: "invalid_file_extension".into(),
                message: format!(
                    "Invalid file extension '{}'. Allowed: {}",
                    extension,
                    allowed_extensions.join(", ")
                ),
                path: None,
            }],
        });
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::tempdir;

    #[test]
    fn test_rejects_path_traversal() {
        let temp = tempdir().unwrap();
        let allowed = temp.path();
        let bad_path = allowed.join("../../../etc/passwd");

        let result = validate_path_within(&bad_path, allowed);
        assert!(matches!(
            result,
            Err(CoreError::PathOutsideAllowedRoot { .. })
        ));
    }

    #[test]
    fn test_accepts_valid_path() {
        let temp = tempdir().unwrap();
        let allowed = temp.path();
        let valid_file = allowed.join("test.txt");
        fs::write(&valid_file, "test").unwrap();

        let result = validate_path_within(&valid_file, allowed);
        assert!(result.is_ok());
    }

    #[test]
    fn test_validates_extension() {
        let path = Path::new("/some/file.json");
        assert!(validate_extension(path, &["json", "jsonc"]).is_ok());

        let bad_path = Path::new("/some/file.exe");
        let err = validate_extension(bad_path, &["json", "jsonc"]).unwrap_err();
        assert!(matches!(err, CoreError::ValidationFailed { .. }));
    }
}

//! PII chat filter.
//!
//! Matches a per-profile blocklist against chat message text. Two
//! matchers are available:
//!
//! * **Strict** (default) — Unicode NFD normalization + ASCII
//!   case-folding + literal substring match. Catches `Kälí` ↔ `kali`,
//!   but doesn't try to defeat `k@li` / leet-speak.
//! * **Fuzzy** (opt-in via per-profile toggle) — additionally applies
//!   a small curated leet-speak substitution table and strips
//!   zero-width characters before matching. Users opt in knowing it
//!   trades some false-positive risk for catching obvious obfuscation.
//!
//! The blocklist content is never logged. Audit-log entries reference
//! a stable `phrase_id` (SHA-256 prefix of the phrase) so a forensic
//! trail of "the filter fired" exists without the matched text on
//! disk.
//!
//! # Residual risks
//!
//! Homoglyph attacks (Cyrillic `а` vs Latin `a`), distributed-doxxing
//! across multiple messages, leet-speak combinations beyond the curated
//! table, and attackers who hash the user's name and send only the
//! hash. The filter is a safety net, not a firewall.

use sha2::{Digest, Sha256};

/// Matching strictness chosen per profile. Strict is the default;
/// users explicitly opt into Fuzzy in the safety settings panel.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum PiiMatchMode {
    #[default]
    Strict,
    Fuzzy,
}

/// Result of running a message through the filter.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PiiCheck {
    /// No phrase matched — message can be displayed / sent / logged.
    Clear,
    /// A phrase matched. The matched text is NOT returned; only the
    /// stable phrase id (suitable for audit logging).
    Match { phrase_id: String },
}

/// Compute the stable audit-log identifier for a blocklist phrase.
/// Truncated SHA-256 prefix — keeps the audit line short while
/// staying collision-resistant across reasonable blocklist sizes.
pub fn phrase_id(phrase: &str) -> String {
    let normalised = normalise_strict(phrase);
    let mut hasher = Sha256::new();
    hasher.update(normalised.as_bytes());
    let digest = hasher.finalize();
    hex::encode(&digest[..8])
}

/// Run `message` through `blocklist` under the given match mode.
/// Returns the first matching phrase's id (we don't need to enumerate
/// every match — one hit is enough to drop the message).
pub fn check(message: &str, blocklist: &[String], mode: PiiMatchMode) -> PiiCheck {
    let haystack = match mode {
        PiiMatchMode::Strict => normalise_strict(message),
        PiiMatchMode::Fuzzy => normalise_fuzzy(message),
    };
    for phrase in blocklist {
        if phrase.is_empty() {
            continue;
        }
        let needle = match mode {
            PiiMatchMode::Strict => normalise_strict(phrase),
            PiiMatchMode::Fuzzy => normalise_fuzzy(phrase),
        };
        if needle.is_empty() {
            continue;
        }
        if haystack.contains(&needle) {
            return PiiCheck::Match {
                phrase_id: phrase_id(phrase),
            };
        }
    }
    PiiCheck::Clear
}

/// Strict normalisation: NFKC + lowercase. NFKC collapses lookalike
/// code points (mathematical-italic `𝕊𝕒𝕞` → `Sam`, fullwidth `Ｓａｍ` →
/// `Sam`, ligatures `ﬃ` → `ffi`) into their canonical ASCII / Latin
/// equivalents BEFORE case-folding, so a blocklist entry of "sam"
/// catches every visual variant an attacker might use to bypass it.
/// Per the SpiritStream threat model (sex workers, harassment-prone
/// streamers, journalists), this matters: a leaked deadname or real
/// name typed in mathematical italic must still trigger the filter.
fn normalise_strict(s: &str) -> String {
    use unicode_normalization::UnicodeNormalization;
    s.nfkc().collect::<String>().to_lowercase()
}

/// Fuzzy normalisation: NFKC + strict + leet-speak substitution +
/// zero-width character stripping. The substitution table is
/// intentionally small and curated — users CANNOT register their own
/// patterns (no regex from user input, no ReDoS risk, no logic
/// injection). NFKC runs first so subsequent steps see canonical
/// code points.
fn normalise_fuzzy(s: &str) -> String {
    use unicode_normalization::UnicodeNormalization;
    let normalised: String = s.nfkc().collect();
    let mut out = String::with_capacity(normalised.len());
    for c in normalised.chars() {
        // Strip zero-width joiners / non-joiners / spaces.
        if matches!(c, '\u{200B}' | '\u{200C}' | '\u{200D}' | '\u{FEFF}') {
            continue;
        }
        out.push(c);
    }
    let lowered = out.to_lowercase();
    let mut result = String::with_capacity(lowered.len());
    for c in lowered.chars() {
        let replacement = match c {
            '@' => 'a',
            '0' => 'o',
            // `1` is ambiguous (l vs i). Pick `l` — by far the more
            // common leet substitution. `!` maps to `i` to keep the
            // exclamation variant covered.
            '1' => 'l',
            '!' => 'i',
            '3' => 'e',
            '4' => 'a',
            '5' | '$' => 's',
            '7' => 't',
            '8' => 'b',
            _ => c,
        };
        result.push(replacement);
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn block(items: &[&str]) -> Vec<String> {
        items.iter().map(|s| (*s).to_string()).collect()
    }

    // --- Strict matcher --------------------------------------------------

    #[test]
    fn strict_substring_match_case_insensitive() {
        let bl = block(&["alex"]);
        assert!(matches!(
            check("Hi ALEX!", &bl, PiiMatchMode::Strict),
            PiiCheck::Match { .. }
        ));
        assert!(matches!(
            check("hi alex", &bl, PiiMatchMode::Strict),
            PiiCheck::Match { .. }
        ));
        assert_eq!(
            check("nothing here", &bl, PiiMatchMode::Strict),
            PiiCheck::Clear
        );
    }

    #[test]
    fn strict_unicode_aware_lowercase() {
        // German ß lowercase / uppercase round-trip via to_lowercase.
        let bl = block(&["straße"]);
        assert!(matches!(
            check("STRAẞE in München", &bl, PiiMatchMode::Strict),
            PiiCheck::Match { .. }
        ));
    }

    #[test]
    fn strict_does_not_match_leet_substitution() {
        // Without fuzzy mode, `a` and `@` are distinct.
        let bl = block(&["alex"]);
        assert_eq!(check("hi @lex", &bl, PiiMatchMode::Strict), PiiCheck::Clear);
    }

    #[test]
    fn strict_catches_nfkc_lookalike_bypass() {
        // Pre-NFKC bug: an attacker could bypass a blocklist entry of
        // "sam" by typing mathematical-italic "𝕊𝕒𝕞", fullwidth "Ｓａｍ",
        // or the "ﬃ" ligature. NFKC folds them to canonical ASCII
        // before lowercase, so the strict matcher catches all variants.
        let bl = block(&["sam", "office"]);
        // Mathematical-italic capital S, lowercase a, lowercase m.
        assert!(
            matches!(
                check("𝕊𝕒𝕞 was here", &bl, PiiMatchMode::Strict),
                PiiCheck::Match { .. }
            ),
            "mathematical-italic lookalike bypassed strict matcher"
        );
        // Fullwidth Latin.
        assert!(
            matches!(
                check("Ｓａｍ was here", &bl, PiiMatchMode::Strict),
                PiiCheck::Match { .. }
            ),
            "fullwidth lookalike bypassed strict matcher"
        );
        // Ligature `ﬃ` (U+FB03) → "ffi"; blocklist "office" should catch.
        assert!(
            matches!(
                check("oﬃce hours", &bl, PiiMatchMode::Strict),
                PiiCheck::Match { .. }
            ),
            "ﬃ ligature bypassed strict matcher"
        );
    }

    // --- Fuzzy matcher ---------------------------------------------------

    #[test]
    fn fuzzy_matches_leet_substitutions() {
        let bl = block(&["alex"]);
        assert!(matches!(
            check("@l3x", &bl, PiiMatchMode::Fuzzy),
            PiiCheck::Match { .. }
        ));
        assert!(matches!(
            check("4lex", &bl, PiiMatchMode::Fuzzy),
            PiiCheck::Match { .. }
        ));
        assert!(matches!(
            check("a1ex", &bl, PiiMatchMode::Fuzzy),
            PiiCheck::Match { .. }
        ));
    }

    #[test]
    fn fuzzy_strips_zero_width_characters() {
        // Insert a zero-width joiner mid-name.
        let bl = block(&["alex"]);
        let msg = "a\u{200B}lex";
        assert!(matches!(
            check(msg, &bl, PiiMatchMode::Fuzzy),
            PiiCheck::Match { .. }
        ));
    }

    #[test]
    fn fuzzy_still_clears_clean_input() {
        let bl = block(&["alex"]);
        assert_eq!(
            check("hello world", &bl, PiiMatchMode::Fuzzy),
            PiiCheck::Clear
        );
    }

    // --- phrase_id --------------------------------------------------------

    #[test]
    fn phrase_id_is_stable_under_case_changes() {
        // The audit-log id must collapse case differences so adding
        // "ALEX" then "alex" doesn't produce two distinct ids.
        assert_eq!(phrase_id("Alex"), phrase_id("ALEX"));
        assert_eq!(phrase_id("alex"), phrase_id("Alex"));
    }

    #[test]
    fn phrase_id_distinguishes_distinct_phrases() {
        assert_ne!(phrase_id("alex"), phrase_id("hometown"));
    }

    #[test]
    fn phrase_id_is_short_for_log_lines() {
        // 8 bytes hex-encoded = 16 chars. Keeps audit log readable.
        assert_eq!(phrase_id("anything").len(), 16);
    }

    // --- Empty blocklist / empty phrase ----------------------------------

    #[test]
    fn empty_blocklist_always_clear() {
        assert_eq!(
            check("anything", &[], PiiMatchMode::Strict),
            PiiCheck::Clear
        );
        assert_eq!(check("anything", &[], PiiMatchMode::Fuzzy), PiiCheck::Clear);
    }

    #[test]
    fn empty_phrases_are_ignored() {
        // An empty string in the blocklist must NOT match every message.
        let bl = block(&[""]);
        assert_eq!(
            check("anything", &bl, PiiMatchMode::Strict),
            PiiCheck::Clear
        );
        assert_eq!(check("anything", &bl, PiiMatchMode::Fuzzy), PiiCheck::Clear);
    }
}

// Platform Registry
// Centralized configuration for streaming platforms

use crate::errors::CoreError;
use crate::models::Platform;
use serde::Deserialize;
use std::collections::HashMap;

/// Stream key placement strategy
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum StreamKeyPlacement {
    /// Append stream key to URL (e.g., rtmp://server/app/{key})
    Append,
    /// Replace {stream_key} template in URL (e.g., rtmp://server/app/{stream_key})
    InUrlTemplate,
}

/// Platform-specific configuration
#[derive(Debug, Clone)]
pub struct PlatformConfig {
    /// Display name (human-readable, e.g. "YouTube", "Twitch")
    pub name: &'static str,

    /// Default RTMP server URL (may contain {stream_key} template)
    pub default_server: &'static str, // Used in InUrlTemplate redaction

    /// Stream key placement strategy
    pub placement: StreamKeyPlacement,

    /// Default app path (e.g., "app", "live2", "rtmp")
    /// Used for URL normalization
    pub default_app_path: Option<&'static str>,

    /// Stream key position in URL path (0 = no masking, 1 = /KEY, 2 = /app/KEY, etc.)
    pub stream_key_position: usize, // Used in Append redaction
}

impl PlatformConfig {
    /// Human-readable platform name (e.g., "YouTube", "Twitch"). Used
    /// by `redact_url_labeled` so operator logs show *which* target
    /// they're looking at when multiple stream destinations are
    /// running in parallel.
    pub fn display_name(&self) -> &'static str {
        self.name
    }

    /// Normalize a platform URL (e.g., ensure Kick has /app path)
    pub fn normalize_url(&self, url: &str) -> String {
        // If no default app path, no normalization needed
        let Some(app_path) = self.default_app_path else {
            return url.to_string();
        };

        // Parse the URL
        let (scheme, rest) = match url.split_once("://") {
            Some(parts) => parts,
            None => return format!("{url}/{app_path}"),
        };

        let (host, path) = match rest.split_once('/') {
            Some(parts) => parts,
            None => return format!("{scheme}://{rest}/{app_path}"),
        };

        // If path is empty or doesn't contain the app path, add it
        if path.is_empty() {
            format!("{scheme}://{host}/{app_path}")
        } else if !path.starts_with(app_path) {
            format!(
                "{scheme}://{host}/{app_path}/{}",
                path.trim_start_matches('/')
            )
        } else {
            url.to_string()
        }
    }

    /// Redact stream key from URL for logging
    pub fn redact_url(&self, url: &str) -> String {
        // Only redact RTMP(S) URLs
        if !(url.starts_with("rtmp://") || url.starts_with("rtmps://")) {
            return url.to_string();
        }

        match self.placement {
            StreamKeyPlacement::InUrlTemplate => {
                // For template mode, find where the template was and redact that portion
                // Template contains {stream_key}, so we need to find what replaced it
                let template = self.default_server;

                // Find the {stream_key} placeholder position
                if let Some(template_start) = template.find("{stream_key}") {
                    let before_key = &template[..template_start];
                    let after_key = &template[template_start + "{stream_key}".len()..];

                    // Check if URL matches the template pattern
                    if url.starts_with(before_key) && url.contains(after_key) {
                        // Find where the key ends (where after_key starts in the URL)
                        if let Some(key_end) = url.find(after_key) {
                            return format!("{}***{}", before_key, &url[key_end..]);
                        }
                    }
                }

                // Fallback: couldn't parse template, return generic redaction
                Self::generic_segment_redact(url)
            }
            StreamKeyPlacement::Append => {
                // For append mode, use path-based redaction
                if self.stream_key_position == 0 {
                    return url.to_string();
                }

                // Parse URL
                let (scheme, rest) = match url.split_once("://") {
                    Some(parts) => parts,
                    None => return url.to_string(),
                };

                let (host, path) = match rest.split_once('/') {
                    Some(parts) => parts,
                    None => return url.to_string(),
                };

                // Split path into segments
                let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();

                // Check if we have enough segments to redact
                if segments.len() < self.stream_key_position {
                    return url.to_string();
                }

                // Build redacted URL
                let safe_segments = &segments[0..self.stream_key_position - 1];
                let safe_path = safe_segments.join("/");

                format!("{scheme}://{host}/{safe_path}/***")
            }
        }
    }

    /// Generic segment-based redaction (fallback)
    fn generic_segment_redact(url: &str) -> String {
        let (scheme, rest) = match url.split_once("://") {
            Some(parts) => parts,
            None => return url.to_string(),
        };

        let (host, path) = match rest.split_once('/') {
            Some(parts) => parts,
            None => return url.to_string(),
        };

        let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
        if segments.len() < 2 {
            return url.to_string();
        }

        let safe_segments = &segments[0..segments.len() - 1];
        let safe_path = safe_segments.join("/");

        format!("{scheme}://{host}/{safe_path}/***")
    }
}

/// Global platform registry
pub struct PlatformRegistry {
    configs: HashMap<Platform, PlatformConfig>,
}

/// Wire-shape mirror of `data/streaming-platforms.json`. Typed-serde
/// parse so a malformed embedded data file fails as one structured
/// `CoreError::Internal` at startup rather than seven separate panics
/// scattered across `serde_json::Value`-tree navigation. The matching
/// `build.rs` deserializes the same file (different consumer — generates
/// the `Platform` enum) so any structural drift is caught at compile time
/// AND the runtime read-back still validates the contract.
#[derive(Deserialize)]
struct PlatformsJson {
    services: Vec<PlatformJsonEntry>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct PlatformJsonEntry {
    name: String,
    #[serde(default)]
    display_name: Option<String>,
    default_url: String,
    stream_key_placement: String,
}

impl PlatformRegistry {
    /// Create a new registry by loading platform configurations from JSON.
    /// Returns `CoreError::Internal` on malformed embedded data (compile-time
    /// bug — `build.rs` validates the same schema, so a reaching this branch
    /// at runtime means the build pipeline regressed).
    pub fn new() -> Result<Self, CoreError> {
        let json_content = include_str!("../../../../data/streaming-platforms.json");
        let data: PlatformsJson =
            serde_json::from_str(json_content).map_err(|e| CoreError::Internal {
                context: format!(
                    "platform registry: embedded streaming-platforms.json is malformed: {e}"
                ),
            })?;

        let mut configs = HashMap::new();
        for service in data.services {
            // Filter: only include RTMP/RTMPS with "append" or "in_url_template" placement.
            if !service.default_url.starts_with("rtmp://")
                && !service.default_url.starts_with("rtmps://")
            {
                continue;
            }
            let placement = match service.stream_key_placement.as_str() {
                "append" => StreamKeyPlacement::Append,
                "in_url_template" => StreamKeyPlacement::InUrlTemplate,
                // Unknown placement variant — skip the entry so a new field
                // value added to the data file doesn't refuse startup.
                _ => continue,
            };

            // Skip entries whose `name` isn't a known `Platform` enum variant.
            // The `Platform` enum is generated by `build.rs` from the same JSON
            // — a mismatch here is impossible during a clean build, but
            // skipping (vs panicking) keeps `Platform::Custom` and any future
            // out-of-band variants from breaking startup.
            let Ok(platform) = serde_json::from_str::<Platform>(&format!("\"{}\"", service.name))
            else {
                continue;
            };

            let (app_path, stream_key_position) = Self::extract_app_path(&service.default_url);

            // Box::leak to create 'static strings. The registry is constructed
            // exactly once per process via ServiceRegistry::build, so this is
            // a one-time leak bounded by the data file size (~3KB).
            let display_name = service.display_name.as_deref().unwrap_or(&service.name);
            let static_display_name = Box::leak(display_name.to_string().into_boxed_str());
            let static_default_url = Box::leak(service.default_url.into_boxed_str());
            let static_app_path = app_path.map(|s| Box::leak(s.into_boxed_str()) as &'static str);

            configs.insert(
                platform,
                PlatformConfig {
                    name: static_display_name,
                    default_server: static_default_url,
                    placement,
                    default_app_path: static_app_path,
                    stream_key_position,
                },
            );
        }

        Ok(Self { configs })
    }

    /// Extract app path from RTMP URL
    /// Returns (Option<String>, stream_key_position)
    fn extract_app_path(url: &str) -> (Option<String>, usize) {
        // Parse URL to extract path
        let (_scheme, rest) = match url.split_once("://") {
            Some(parts) => parts,
            None => return (None, 2), // Default
        };

        let (_host, path) = match rest.split_once('/') {
            Some(parts) => parts,
            None => return (None, 2), // No path, default
        };

        // Extract first segment of path as app path
        let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();

        if segments.is_empty() {
            (None, 2)
        } else {
            (Some(segments[0].to_string()), 2) // Stream key is at position 2 (/app/KEY)
        }
    }

    /// Get configuration for a platform
    pub fn get(&self, platform: &Platform) -> Option<&PlatformConfig> {
        self.configs.get(platform)
    }

    /// Normalize URL for a platform
    pub fn normalize_url(&self, platform: &Platform, url: &str) -> String {
        self.get(platform)
            .map(|config| config.normalize_url(url))
            .unwrap_or_else(|| url.to_string())
    }

    /// Build complete URL with stream key based on platform's placement strategy
    pub fn build_url_with_key(
        &self,
        platform: &Platform,
        base_url: &str,
        stream_key: &str,
    ) -> String {
        if let Some(config) = self.get(platform) {
            match config.placement {
                StreamKeyPlacement::Append => {
                    // Append stream key to URL: rtmp://server/app + /key
                    format!("{}/{}", base_url.trim_end_matches('/'), stream_key)
                }
                StreamKeyPlacement::InUrlTemplate => {
                    // Replace {stream_key} template in URL
                    base_url.replace("{stream_key}", stream_key)
                }
            }
        } else {
            // Fallback: assume append mode
            format!("{}/{}", base_url.trim_end_matches('/'), stream_key)
        }
    }

    /// Generic redaction for unknown platforms (fallback)
    /// This is a public static method that can be used when platform context is not available
    pub fn generic_redact(url: &str) -> String {
        if !(url.starts_with("rtmp://") || url.starts_with("rtmps://")) {
            return url.to_string();
        }

        let (scheme, rest) = match url.split_once("://") {
            Some(parts) => parts,
            None => return url.to_string(),
        };

        let (host, path) = match rest.split_once('/') {
            Some(parts) => parts,
            None => return url.to_string(),
        };

        let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
        if segments.len() < 2 {
            return url.to_string();
        }

        format!("{scheme}://{host}/{}/***", segments[0])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generic_redaction() {
        let url = "rtmp://custom-server.com/stream/my_key";
        let redacted = PlatformRegistry::generic_redact(url);
        assert_eq!(redacted, "rtmp://custom-server.com/stream/***");
    }

    #[test]
    fn test_registry_loads_from_json() {
        let registry = PlatformRegistry::new().expect("test fixture");
        // Verify registry is not empty
        assert!(
            !registry.configs.is_empty(),
            "Registry should load platforms from JSON"
        );
    }

    /// URL normalization must run on `ProfileService::save` so the
    /// persisted profile contains a usable RTMP URL regardless of what the
    /// user typed. This test pins the contract — a user typing just the
    /// hostname for a known platform must get the default app path appended.
    #[test]
    fn normalize_url_appends_default_app_path_for_twitch() {
        let registry = PlatformRegistry::new().expect("test fixture");
        let normalized = registry.normalize_url(
            &crate::models::Platform::Twitch,
            "rtmp://ingest.global-contribute.live-video.net",
        );
        assert_eq!(
            normalized, "rtmp://ingest.global-contribute.live-video.net/app",
            "twitch default_app_path must be appended when missing"
        );
    }

    /// Already-normalized URLs must pass through untouched (idempotent).
    #[test]
    fn normalize_url_is_idempotent_when_app_path_present() {
        let registry = PlatformRegistry::new().expect("test fixture");
        let already = "rtmp://ingest.global-contribute.live-video.net/app";
        assert_eq!(
            registry.normalize_url(&crate::models::Platform::Twitch, already),
            already
        );
    }

    /// Unknown / custom platforms have no normalization rules — URL is
    /// returned unchanged so the user can stream to arbitrary destinations.
    #[test]
    fn normalize_url_passes_through_for_custom_platform() {
        let registry = PlatformRegistry::new().expect("test fixture");
        let url = "rtmp://my-private-rtmp.example.com:1935/live";
        assert_eq!(
            registry.normalize_url(&crate::models::Platform::Custom, url),
            url
        );
    }

    fn append_config(position: usize) -> PlatformConfig {
        PlatformConfig {
            name: "Test",
            default_server: "rtmp://host/app",
            placement: StreamKeyPlacement::Append,
            default_app_path: Some("app"),
            stream_key_position: position,
        }
    }

    #[test]
    fn display_name_returns_human_label() {
        assert_eq!(append_config(2).display_name(), "Test");
    }

    /// The safety-critical path: the trailing stream-key segment must be
    /// replaced with `***` so operator logs never carry the live key.
    #[test]
    fn redact_url_append_masks_trailing_key_segment() {
        let cfg = append_config(2);
        let redacted = cfg.redact_url("rtmp://host/app/SUPERSECRETKEY");
        assert_eq!(redacted, "rtmp://host/app/***");
        assert!(!redacted.contains("SUPERSECRETKEY"));
    }

    #[test]
    fn redact_url_append_position_zero_is_noop() {
        let cfg = append_config(0);
        let url = "rtmp://host/app/key";
        assert_eq!(cfg.redact_url(url), url);
    }

    #[test]
    fn redact_url_leaves_non_rtmp_urls_untouched() {
        let cfg = append_config(2);
        let url = "https://example.com/app/key";
        assert_eq!(cfg.redact_url(url), url);
    }

    #[test]
    fn redact_url_append_too_few_segments_is_noop() {
        let cfg = append_config(2);
        // Only one segment before the key position → nothing to redact.
        let url = "rtmp://host/onlyone";
        assert_eq!(cfg.redact_url(url), url);
    }

    /// Template placement with a suffix after `{stream_key}` redacts the
