                host: s.obs.host.clone(),
                port: s.obs.port,
                use_auth: s.obs.use_auth,
                direction: s.obs.direction,
                auto_connect: s.obs.auto_connect,
            },
            chat: s.chat.clone(),
        }
    }
}

//! Profile file I/O: list, load (with encryption-aware decode), delete,
//! is-encrypted probe, RTMP input-conflict scan.

use super::validation::validate_profile_name;
use crate::errors::CoreError;
use crate::models::{Profile, ProfileSummary, RtmpInput};
use crate::services::Encryption;

// Magic bytes that identify encrypted profile files. Legacy installs
// produced `MGLA` blobs (AES-256-GCM body); current writers produce `MGL2`
// blobs (AES-256-GCM-SIV body). `load()` reads either; `save()` writes V2.
// `pub(crate)` because `services::encryption` consumes them in its test
// fixtures alongside `Encryption::decrypt_v1` / `decrypt_v2`.
pub(crate) const ENCRYPTED_MAGIC_V1: &[u8] = b"MGLA";
pub(crate) const ENCRYPTED_MAGIC_V2: &[u8] = b"MGL2";
pub(crate) const ENCRYPTED_MAGIC_LEN: usize = 4;

impl super::ProfileManager {
    /// Get all profile names from the profiles directory.
    pub async fn get_all_names(&self) -> Result<Vec<String>, CoreError> {
        let mut names = Vec::new();

        let entries = std::fs::read_dir(&self.profiles_dir)?;

        for entry in entries.flatten() {
            let path = entry.path();
            if let Some(name) = path.file_stem() {
                // Accept both .json (unencrypted) and .mgs (encrypted) files
                let ext = path.extension().and_then(|e| e.to_str());
                if ext == Some("json") || ext == Some("mgs") {
                    names.push(name.to_string_lossy().to_string());
                }
            }
        }

        Ok(names)
    }

    /// Get summaries of all profiles (for list display). Includes services
    /// list for each profile.
    pub async fn get_all_summaries(&self) -> Result<Vec<ProfileSummary>, CoreError> {
        let names = self.get_all_names().await?;
        let order_map = self.ensure_order_indexes().await?;

        let mut summaries = Vec::new();

        for name in names {
            let is_encrypted = self.is_encrypted(&name);

            // Try to load the profile (unencrypted profiles only). Encrypted
            // profiles show minimal info since we can't read them without
            // the password.
            if let Ok(profile) = self.load(&name, None).await {
                summaries.push(profile.to_summary(is_encrypted));
            } else if is_encrypted {
                // For encrypted profiles we can't read, show minimal summary
                summaries.push(ProfileSummary {
                    id: String::new(),
                    name: name.clone(),
                    resolution: "?".to_string(),
                    bitrate: 0,
                    target_count: 0,
                    services: Vec::new(),
                    is_encrypted: true,
                });
            }
        }
        summaries.sort_by_key(|s| order_map.get(&s.name).copied().unwrap_or(i32::MAX));
        Ok(summaries)
    }

    /// Load a profile by name. If password is provided, will attempt to
    /// decrypt. If no password, will try unencrypted first, and return
    /// `CoreError::PasswordRequired` if the profile is encrypted.
    pub async fn load(&self, name: &str, password: Option<&str>) -> Result<Profile, CoreError> {
        validate_profile_name(name)?;

        let encrypted_path = self.profiles_dir.join(format!("{name}.mgs"));
        let json_path = self.profiles_dir.join(format!("{name}.json"));

        if encrypted_path.exists() {
            let data = std::fs::read(&encrypted_path)?;

            if data.len() < ENCRYPTED_MAGIC_LEN {
                return Err(CoreError::Internal {
                    context: format!("invalid encrypted profile format: {name}"),
                });
            }
            let magic = &data[..ENCRYPTED_MAGIC_LEN];
            let body = &data[ENCRYPTED_MAGIC_LEN..];

            // Treat empty-string password the same as no password — clients
            // sending `{"password": ""}` for an encrypted profile should get
            // `PasswordRequired` (so the UI prompts), not `PasswordIncorrect`
            // (which suggests they typed the wrong key).
            let password = match password {
                Some(p) if !p.is_empty() => p,
                _ => {
                    return Err(CoreError::PasswordRequired {
                        name: name.to_string(),
                    })
                }
            };

            let decrypted = if magic == ENCRYPTED_MAGIC_V2 {
                Encryption::decrypt_v2(body, password)?
            } else if magic == ENCRYPTED_MAGIC_V1 {
                Encryption::decrypt_v1(body, password)?
            } else {
                return Err(CoreError::Internal {
                    context: format!("invalid encrypted profile format: {name}"),
                });
            };

            let content = String::from_utf8(decrypted).map_err(|e| CoreError::Internal {
                context: format!("invalid utf-8 in decrypted profile: {e}"),
            })?;

            // The file extension is the authoritative encryption flag —
            // overwrite whatever was stored inside the blob so the loaded
            // Profile can't lie about its own encryption state.
            let mut profile: Profile = serde_json::from_str(&content)?;
            profile.encrypted = true;
            // Same safety-critical PII unwrap as the plaintext branch.
            // Even for password-encrypted profiles, the blocklist
            // entries inside the blob are individually `ENC2::` wrapped
            // (machine-key, not the profile password), so unwrap here
            // unconditionally.
            self.decrypt_pii_blocklist(&mut profile)?;
            return Ok(profile);
        }

        if json_path.exists() {
            let content = std::fs::read_to_string(&json_path)?;
            let mut profile: Profile = serde_json::from_str(&content)?;
            profile.encrypted = false;
            // Safety-critical: pii_blocklist entries are written `ENC2::`
            // wrapped (`encrypt_pii_blocklist`) so the on-disk JSON
            // never holds real names / deadnames as plaintext.
            // `decrypt_pii_blocklist` must run on every load path so
            // callers see cleartext phrases — otherwise the PII filter
            // compares messages against ciphertext blobs and silently
            // lets blocked phrases through (regression caught by the
            // `chat-send-pii-blocks-message` integration case).
            // Keyed off the machine key (NOT the profile password),
            // so it's safe to run here in the no-password branch too.
            self.decrypt_pii_blocklist(&mut profile)?;
            return Ok(profile);
        }

        Err(CoreError::ProfileNotFound {
            name: name.to_string(),
        })
    }

    /// Delete a profile by name (both encrypted and unencrypted versions).
    pub async fn delete(&self, name: &str) -> Result<(), CoreError> {
        log::info!("Deleting profile: {name}");

        validate_profile_name(name)?;

        let json_path = self.profiles_dir.join(format!("{name}.json"));
        let mgs_path = self.profiles_dir.join(format!("{name}.mgs"));

        let mut deleted = false;

        if json_path.exists() {
            std::fs::remove_file(&json_path)?;
            deleted = true;
        }

        if mgs_path.exists() {
            std::fs::remove_file(&mgs_path)?;
            deleted = true;
        }

        if deleted {
            log::info!("Profile deleted successfully: {name}");
            if let Some(audit) = self.audit() {
                if let Err(e) = audit.record(crate::services::AuditAction::ProfileDeleted {
                    name: name.to_string(),
                }) {
                    log::error!("profile_manager failed to append ProfileDeleted audit entry: {e}");
                }
            }
            Ok(())
        } else {
            log::warn!("Profile not found for deletion: {name}");
            Err(CoreError::ProfileNotFound {
                name: name.to_string(),
            })
        }
    }

    /// Check if a profile is encrypted. Returns false for invalid profile
    /// names (fails safely).
    ///
    /// Considers a profile encrypted if EITHER a `.mgs` file exists (the
    /// expected case) OR a `.json` file starts with the `MGLA`/`MGL2`
    /// magic. The magic-byte fallback covers the corruption case where
    /// a `.mgs` file is renamed to `.json` (user mistake, backup tool
    /// that strips unknown extensions, attacker with write access). Pre-
    /// fix that file would be misclassified as plaintext, then the load
    /// path would attempt to JSON-deserialize the binary ciphertext and
    /// surface an opaque parse error instead of correctly prompting for
    /// the password.
    pub fn is_encrypted(&self, name: &str) -> bool {
        // Validate profile name to prevent path traversal attacks. For this
        // method, we return false for invalid names (fail safely).
        if validate_profile_name(name).is_err() {
            return false;
        }

        let mgs_path = self.profiles_dir.join(format!("{name}.mgs"));
        if mgs_path.exists() {
            return true;
        }
        let json_path = self.profiles_dir.join(format!("{name}.json"));
        // Read the first 4 bytes only — magic check is cheap and we
        // don't want to slurp big files just to classify them.
        if let Ok(mut f) = std::fs::File::open(&json_path) {
            use std::io::Read;
            let mut header = [0u8; ENCRYPTED_MAGIC_LEN];
            if f.read_exact(&mut header).is_ok()
                && (header == *ENCRYPTED_MAGIC_V1 || header == *ENCRYPTED_MAGIC_V2)
            {
                return true;
            }
        }
        false
    }

    /// Validate that no *other* profile claims the same RTMP
    /// `(bindAddress, port)` pair. Returns `CoreError::PortConflict` when
    /// another profile owns the same input. The current profile (matched
    /// by `profile_id`) is excluded from the scan so saving the same
    /// profile with unchanged input is a no-op.
    ///
    /// Only unencrypted profiles can be scanned without a password;
    /// encrypted profiles are skipped (we cannot determine their input
    /// config without the user's password, and the rest of the rewrite
    /// assumes the user remembers their own conflicts).
    pub async fn validate_input_conflict(
        &self,
        profile_id: &str,
        input: &RtmpInput,
    ) -> Result<(), CoreError> {
        let names = self.get_all_names().await?;
        for name in names {
            if self.is_encrypted(&name) {
                continue;
            }
            let other = match self.load(&name, None).await {
                Ok(p) => p,
                Err(_) => continue,
            };
            if other.id == profile_id {
                continue;
            }
            if other.input.port == input.port && other.input.bind_address == input.bind_address {
                return Err(CoreError::PortConflict {
                    port: input.port,
                    owner: other.name,
                });
            }
        }
        Ok(())
    }
}

//! Profile persistence service.
//!
//! Owns CRUD, encryption boundary, order-index file, validation, and the
//! `ProfileActivated` event payload. Split across focused sub-modules so
//! each concern lives in a file under 300 LOC:
//!
//! - `events.rs`       — `ProfileActivatedEvent` + `ActivatedObs` (DTOs)
//! - `validation.rs`   — name + settings-bounds validation, public constants
//! - `order_index.rs`  — order-index file I/O (drag-reorder support)
//! - `io.rs`           — file I/O: list, load, delete, is-encrypted, port-conflict
//! - `security.rs`     — encryption boundary (per-field + whole-file envelope)
//!
//! The public symbols re-export through `services/profile_manager.rs` so the
//! historical import path `crate::services::profile_manager::ProfileManager`
//! keeps working unchanged.

mod events;
pub(super) mod io;
mod order_index;
mod security;
mod validation;

use std::path::PathBuf;
use std::sync::{Arc, RwLock};

pub use events::{ActivatedObs, ProfileActivatedEvent};
pub use validation::{BACKEND_PORT_MIN, DISCORD_COOLDOWN_SECONDS_MAX};

use super::AuditLogService;

/// Manages profile storage and retrieval.
pub struct ProfileManager {
    pub(super) profiles_dir: PathBuf,
    pub(super) app_data_dir: PathBuf,
    pub(super) order_index_dir: PathBuf,
    /// Audit-log handle, wired post-construction by `ServiceRegistry`
    /// (same pattern as `ChatManager::set_audit_log` / `ThemeManager`).
    /// G2: `ProfileSaved` + `ProfileDeleted` enum variants existed but
    /// were never emitted because the manager had no handle to record
    /// them. Wiring it here keeps emission single-source (every save/
    /// delete path goes through these methods).
    pub(super) audit_log: Arc<RwLock<Option<Arc<AuditLogService>>>>,
}

impl ProfileManager {
    /// Create a new ProfileManager with the given app data directory.
    pub fn new(app_data_dir: PathBuf) -> Self {
        let profiles_dir = app_data_dir.join("profiles");
        let order_index_dir = app_data_dir.join("indexes");
        std::fs::create_dir_all(&profiles_dir).ok();
        std::fs::create_dir_all(&order_index_dir).ok();
        Self {
            profiles_dir,
            app_data_dir,
            order_index_dir,
            audit_log: Arc::new(RwLock::new(None)),
        }
    }

    /// Wire the audit log after construction. Until this is called,
    /// `ProfileSaved` and `ProfileDeleted` are best-effort no-ops —
    /// matches the `ThemeManager` / `ChatManager` degraded-mode shape.
    pub fn set_audit_log(&self, audit: Arc<AuditLogService>) {
        match self.audit_log.write() {
            Ok(mut guard) => *guard = Some(audit),
            Err(e) => log::error!(
                "profile_manager audit_log write lock poisoned during set_audit_log: {e}"
            ),
        }
    }

    /// Read the wired audit-log handle. Returns `None` before
    /// `set_audit_log` runs (legitimate construction-order state) but
    /// logs and returns `None` on poisoned lock so audit gaps caused
    /// by an upstream panic surface in operator logs.
    pub(super) fn audit(&self) -> Option<Arc<AuditLogService>> {
        match self.audit_log.read() {
            Ok(g) => g.clone(),
            Err(e) => {
                log::error!(
                    "profile_manager audit_log read lock poisoned — audit entry dropped: {e}"
                );
                None
            }
        }
    }
}

#[cfg(test)]
mod permission_tests {
    use super::ProfileManager;
    use crate::models::{Profile, ProfileSettings, RtmpInput};

    fn fresh_dir() -> std::path::PathBuf {
        let p = std::env::temp_dir().join(format!(
            "spiritstream-profile-perm-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(p.join("profiles")).unwrap();
        p
    }

    /// Saved profile files (`.json` plaintext and `.mgs` encrypted) must
    /// land at mode 0600 on Unix. Profile files contain stream keys, OAuth
    /// tokens, OBS passwords, and webhook URLs — even the encrypted variant
    /// is sensitive metadata.
    #[cfg(unix)]
    #[tokio::test]
    async fn save_writes_profile_at_0600() {
        use std::os::unix::fs::PermissionsExt;
        let data_dir = fresh_dir();
        let mgr = ProfileManager::new(data_dir.clone());
        let profile = Profile {
            id: "phase69-test".into(),
            name: "phase69-test".into(),
            encrypted: false,
            input: RtmpInput {
                input_type: "rtmp".into(),
                bind_address: "127.0.0.1".into(),
                port: 1935,
                application: "live".into(),
            },
            output_groups: vec![],
            settings: ProfileSettings::default(),
            pii_blocklist: vec![],
            pii_fuzzy: false,
            anonymous_logging: true,
            anonymous_salt: String::new(),
        };
        mgr.save_with_key_encryption(&profile, None)
            .await
            .expect("save plaintext profile");
        let json_path = mgr.profiles_dir.join("phase69-test.json");
        let perms = std::fs::metadata(&json_path).unwrap().permissions();
        assert_eq!(
            perms.mode() & 0o777,
            0o600,
            "plaintext profile .json must be owner-only",
        );
        // Password must be ≥ PROFILE_PASSWORD_MIN_LENGTH (12 chars) — that's
        // the threat-model floor for the profile-encryption key.
        mgr.save_with_key_encryption(&profile, Some("test-pw-twelve"))
            .await
            .expect("save encrypted profile");
        let mgs_path = mgr.profiles_dir.join("phase69-test.mgs");
        let perms = std::fs::metadata(&mgs_path).unwrap().permissions();
        assert_eq!(
            perms.mode() & 0o777,
            0o600,
            "encrypted profile .mgs must be owner-only",
        );
        let _ = std::fs::remove_dir_all(data_dir);
    }
}

//! Order-index file I/O for the profile picker drag-and-drop reorder.
//! Persists to `<app_data_dir>/indexes/order_indexes.json`.

use crate::errors::CoreError;
use crate::services::write_owner_only_atomic;
use std::collections::hash_map::Entry;
use std::collections::{HashMap, HashSet};

impl super::ProfileManager {
    /// Read the order-index map for drag-and-drop on the profile picker.
    pub fn read_order_index_map(&self) -> Result<HashMap<String, i32>, CoreError> {
        let indexes_path = self.order_index_dir.join("order_indexes.json");

        if !indexes_path.exists() {
            let empty: HashMap<String, i32> = HashMap::new();
            let content = serde_json::to_string_pretty(&empty)?;
            // I5: even the initial-write path is owner-only atomic so a
            // crash here can never leave a world-readable partial file.
            write_owner_only_atomic(&indexes_path, content.as_bytes())?;
            return Ok(empty);
        }

        let content = std::fs::read_to_string(&indexes_path)?;
        let map: HashMap<String, i32> = serde_json::from_str(&content)?;
        Ok(map)
    }

    /// I5: route through `write_owner_only_atomic` so a partial write
    /// can't leave a 0644 `order_indexes.json.tmp` on disk, and the
    /// final file always lands at 0600 on Unix.
    pub fn write_order_index_map(&self, map: &HashMap<String, i32>) -> Result<(), CoreError> {
        let path = self.order_index_dir.join("order_indexes.json");
        let content = serde_json::to_string_pretty(map)?;
        write_owner_only_atomic(&path, content.as_bytes())
    }

    /// This method can eventually be removed; its purpose is to add
    /// `order_index` to profiles that were created before order_index was
    /// introduced.
    pub async fn ensure_order_indexes(&self) -> Result<HashMap<String, i32>, CoreError> {
        let names = self.get_all_names().await?;
        let mut map = self.read_order_index_map()?;

        let mut max = map.values().copied().max().unwrap_or(0);
        max = ((max + 9) / 10) * 10;

        let mut changed = false;

        // I7: pre-build a set so the `names.contains(k)` lookup below
        // is O(1) and the loop is O(n) instead of O(n²). Also iterate
        // by reference rather than `names.clone()`-ing the entire
        // vector on every call.
        let name_set: HashSet<&str> = names.iter().map(String::as_str).collect();

        for name in &names {
            match map.entry(name.clone()) {
                Entry::Vacant(e) => {
                    max += 10;
                    e.insert(max);
                    changed = true;
                }
                Entry::Occupied(_) => {}
            }
        }
        map.retain(|k, _| name_set.contains(k.as_str()));
        if changed {
            self.write_order_index_map(&map)?;
        }

        Ok(map)
    }
}

#[cfg(test)]
mod tests {
    use super::super::ProfileManager;
    use std::collections::HashMap;
    use tempfile::TempDir;

    fn manager() -> (ProfileManager, TempDir) {
        let dir = TempDir::new().unwrap();
        (ProfileManager::new(dir.path().to_path_buf()), dir)
    }

    #[test]
    fn read_on_missing_file_creates_an_empty_owner_only_map() {
        let (mgr, dir) = manager();
        let map = mgr.read_order_index_map().unwrap();
        assert!(map.is_empty());

        let path = dir.path().join("indexes").join("order_indexes.json");
        assert!(path.exists(), "first read must materialise the file");

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&path).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode, 0o600, "order index file must be owner-only");
        }
    }

    #[test]
    fn write_then_read_round_trips_the_map() {
        let (mgr, _dir) = manager();
        let mut map = HashMap::new();
        map.insert("alpha".to_string(), 10);
        map.insert("beta".to_string(), 20);
        mgr.write_order_index_map(&map).unwrap();

        let read_back = mgr.read_order_index_map().unwrap();
        assert_eq!(read_back, map);
    }

    #[tokio::test]
    async fn ensure_assigns_increasing_multiples_of_ten_to_unindexed_profiles() {
        let (mgr, _dir) = manager();
        for (i, name) in ["one", "two", "three"].iter().enumerate() {
            save_named(&mgr, name, 1935 + i as u16).await;
        }

        let map = mgr.ensure_order_indexes().await.unwrap();
        assert_eq!(map.len(), 3);
        let mut values: Vec<i32> = map.values().copied().collect();
        values.sort_unstable();
        assert_eq!(values, vec![10, 20, 30]);
    }

    #[tokio::test]
    async fn ensure_preserves_existing_indexes_and_only_fills_gaps() {
        let (mgr, _dir) = manager();
        save_named(&mgr, "kept", 1935).await;
        save_named(&mgr, "added", 1936).await;

        let mut seed = HashMap::new();
        seed.insert("kept".to_string(), 100);
        mgr.write_order_index_map(&seed).unwrap();

        let map = mgr.ensure_order_indexes().await.unwrap();
        assert_eq!(map.get("kept"), Some(&100), "existing index untouched");
        // New profile is placed above the current max, rounded to the next ten.
        assert_eq!(map.get("added"), Some(&110));
    }

    #[tokio::test]
    async fn ensure_drops_indexes_for_profiles_that_no_longer_exist() {
        let (mgr, _dir) = manager();
        save_named(&mgr, "survivor", 1935).await;

        let mut seed = HashMap::new();
        seed.insert("survivor".to_string(), 10);
        seed.insert("ghost".to_string(), 20);
        mgr.write_order_index_map(&seed).unwrap();

        let map = mgr.ensure_order_indexes().await.unwrap();
        assert!(map.contains_key("survivor"));
        assert!(!map.contains_key("ghost"), "stale entry must be pruned");
    }

    async fn save_named(mgr: &ProfileManager, name: &str, port: u16) {
        use crate::models::{Profile, ProfileSettings, RtmpInput};
        let profile = Profile {
            id: name.into(),
            name: name.into(),
            encrypted: false,
            input: RtmpInput {
                input_type: "rtmp".into(),
                bind_address: "127.0.0.1".into(),
                port,
                application: "live".into(),
            },
            output_groups: vec![],
            settings: ProfileSettings::default(),
            pii_blocklist: vec![],
            pii_fuzzy: false,
            anonymous_logging: true,
            anonymous_salt: String::new(),
        };
        mgr.save_with_key_encryption(&profile, None)
            .await
            .expect("save profile");
    }
}

//! Encryption boundary for profile persistence.
//!
//! Owns the per-field encryption of stream keys, OBS password, Discord
//! webhook, backend token, YouTube API key, and OAuth tokens; plus the
//! whole-file Argon2id + AES-GCM-SIV envelope used when a password is
//! supplied. Save / load operations live here because their orchestration
//! and the encryption helpers are tightly coupled — splitting them would
//! risk an encryption-boundary mismatch.

use super::io::{ENCRYPTED_MAGIC_LEN, ENCRYPTED_MAGIC_V2};
use super::validation::validate_profile_name;
use crate::errors::{CoreError, ValidationIssue};
use crate::models::{OAuthAccount, Profile};
use crate::services::Encryption;
use std::path::Path;

/// Encrypt the bearer + refresh fields of an `OAuthAccount` in place.
/// Skips already-encrypted values so re-encrypting a saved profile is
/// idempotent (the same property `encrypt_stream_keys` already relies on).
fn encrypt_oauth_account(account: &mut OAuthAccount, app_data_dir: &Path) -> Result<(), CoreError> {
    if !account.access_token.is_empty()
        && !Encryption::is_stream_key_encrypted(&account.access_token)
    {
        account.access_token = Encryption::encrypt_stream_key(&account.access_token, app_data_dir)?;
    }
    if !account.refresh_token.is_empty()
        && !Encryption::is_stream_key_encrypted(&account.refresh_token)
    {
        account.refresh_token =
            Encryption::encrypt_stream_key(&account.refresh_token, app_data_dir)?;
    }
    Ok(())
}

/// Inverse of [`encrypt_oauth_account`]. Idempotent — leaves plaintext
/// values untouched.
fn decrypt_oauth_account(account: &mut OAuthAccount, app_data_dir: &Path) -> Result<(), CoreError> {
    if Encryption::is_stream_key_encrypted(&account.access_token) {
        account.access_token = Encryption::decrypt_stream_key(&account.access_token, app_data_dir)?;
    }
    if Encryption::is_stream_key_encrypted(&account.refresh_token) {
        account.refresh_token =
            Encryption::decrypt_stream_key(&account.refresh_token, app_data_dir)?;
    }
    Ok(())
}

impl super::ProfileManager {
    /// Encrypt all stream keys in a profile.
    pub(super) fn encrypt_stream_keys(&self, profile: &mut Profile) -> Result<(), CoreError> {
        for group in &mut profile.output_groups {
            for target in &mut group.stream_targets {
                // Skip if already encrypted or empty
                if !target.stream_key.is_empty()
                    && !Encryption::is_stream_key_encrypted(&target.stream_key)
                {
                    target.stream_key =
                        Encryption::encrypt_stream_key(&target.stream_key, &self.app_data_dir)?;
                }
            }
        }
        Ok(())
    }

    /// Decrypt all stream keys in a profile.
    pub(super) fn decrypt_stream_keys(&self, profile: &mut Profile) -> Result<(), CoreError> {
        for group in &mut profile.output_groups {
            for target in &mut group.stream_targets {
                // Only decrypt if encrypted
                if Encryption::is_stream_key_encrypted(&target.stream_key) {
                    target.stream_key =
                        Encryption::decrypt_stream_key(&target.stream_key, &self.app_data_dir)?;
                }
            }
        }
        Ok(())
    }

    /// Wrap each PII blocklist entry with the `ENC2::` machine-key
    /// envelope so plaintext profiles don't store real names / deadnames
    /// / hometowns as plain JSON on disk. `encrypt_stream_key` is
    /// idempotent — already-wrapped entries pass through unchanged. The
    /// docstring on `Profile.pii_blocklist` has promised this since
    /// inception; the wrapping itself was missing until O.11b.
    pub(super) fn encrypt_pii_blocklist(&self, profile: &mut Profile) -> Result<(), CoreError> {
        for entry in &mut profile.pii_blocklist {
            if !entry.is_empty() && !Encryption::is_stream_key_encrypted(entry) {
                *entry = Encryption::encrypt_stream_key(entry, &self.app_data_dir)?;
            }
        }
        Ok(())
    }

    /// Unwrap each PII blocklist entry written by `encrypt_pii_blocklist`.
    /// Plaintext entries (legacy profiles saved before O.11b) pass
    /// through unchanged so they get wrapped on the next save.
    pub(super) fn decrypt_pii_blocklist(&self, profile: &mut Profile) -> Result<(), CoreError> {
        for entry in &mut profile.pii_blocklist {
            if Encryption::is_stream_key_encrypted(entry) {
                *entry = Encryption::decrypt_stream_key(entry, &self.app_data_dir)?;
            }
        }
        Ok(())
    }

    /// Encrypt sensitive fields in profile settings (OBS password, Discord
    /// webhook, backend token, YouTube API key, OAuth tokens).
    pub(super) fn encrypt_profile_settings(&self, profile: &mut Profile) -> Result<(), CoreError> {
        if !profile.settings.obs.password.is_empty()
            && !Encryption::is_stream_key_encrypted(&profile.settings.obs.password)
        {
            profile.settings.obs.password =
                Encryption::encrypt_stream_key(&profile.settings.obs.password, &self.app_data_dir)?;
        }

        if !profile.settings.discord.webhook_url.is_empty()
            && !Encryption::is_stream_key_encrypted(&profile.settings.discord.webhook_url)
        {
            profile.settings.discord.webhook_url = Encryption::encrypt_stream_key(
                &profile.settings.discord.webhook_url,
                &self.app_data_dir,
            )?;
        }

        if !profile.settings.backend.token.is_empty()
            && !Encryption::is_stream_key_encrypted(&profile.settings.backend.token)
        {
            profile.settings.backend.token = Encryption::encrypt_stream_key(
                &profile.settings.backend.token,
                &self.app_data_dir,
            )?;
        }

        if !profile.settings.chat.youtube_api_key.is_empty()
            && !Encryption::is_stream_key_encrypted(&profile.settings.chat.youtube_api_key)
        {
            profile.settings.chat.youtube_api_key = Encryption::encrypt_stream_key(
                &profile.settings.chat.youtube_api_key,
                &self.app_data_dir,
            )?;
        }

        // G1: encrypt every OAuth provider account, not just twitch +
        // youtube. Pre-G1 the kick + facebook tokens were persisted in
        // plaintext even when `encrypt_stream_keys` was on, because the
        // original sweep was written before those providers landed.
        encrypt_oauth_account(&mut profile.settings.oauth.twitch, &self.app_data_dir)?;
        encrypt_oauth_account(&mut profile.settings.oauth.youtube, &self.app_data_dir)?;
        encrypt_oauth_account(&mut profile.settings.oauth.kick, &self.app_data_dir)?;
        encrypt_oauth_account(&mut profile.settings.oauth.facebook, &self.app_data_dir)?;

        Ok(())
    }

    /// Decrypt sensitive fields in profile settings (OBS password, Discord
    /// webhook, backend token, YouTube API key, OAuth tokens).
    pub(super) fn decrypt_profile_settings(&self, profile: &mut Profile) -> Result<(), CoreError> {
        if Encryption::is_stream_key_encrypted(&profile.settings.obs.password) {
            profile.settings.obs.password =
                Encryption::decrypt_stream_key(&profile.settings.obs.password, &self.app_data_dir)?;
        }

        if Encryption::is_stream_key_encrypted(&profile.settings.discord.webhook_url) {
            profile.settings.discord.webhook_url = Encryption::decrypt_stream_key(
                &profile.settings.discord.webhook_url,
                &self.app_data_dir,
            )?;
        }

        if Encryption::is_stream_key_encrypted(&profile.settings.backend.token) {
            profile.settings.backend.token = Encryption::decrypt_stream_key(
                &profile.settings.backend.token,
                &self.app_data_dir,
            )?;
        }

        if Encryption::is_stream_key_encrypted(&profile.settings.chat.youtube_api_key) {
            profile.settings.chat.youtube_api_key = Encryption::decrypt_stream_key(
                &profile.settings.chat.youtube_api_key,
                &self.app_data_dir,
            )?;
        }

        decrypt_oauth_account(&mut profile.settings.oauth.twitch, &self.app_data_dir)?;
        decrypt_oauth_account(&mut profile.settings.oauth.youtube, &self.app_data_dir)?;
        decrypt_oauth_account(&mut profile.settings.oauth.kick, &self.app_data_dir)?;
        decrypt_oauth_account(&mut profile.settings.oauth.facebook, &self.app_data_dir)?;
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn test_encrypt_profile_settings(
        &self,
        profile: &mut Profile,
    ) -> Result<(), CoreError> {
        self.encrypt_profile_settings(profile)
    }

    #[cfg(test)]
    pub(crate) fn test_decrypt_profile_settings(
        &self,
        profile: &mut Profile,
    ) -> Result<(), CoreError> {
        self.decrypt_profile_settings(profile)
    }

    /// Save a profile with optional password-based encryption.
    ///
    /// Two normalizations happen on the way in:
    /// 1. `PlatformRegistry::normalize_url()` runs on every stream-target URL
    ///    so platform-specific path prefixes are consistent regardless of
    ///    what the user typed.
    /// 2. `validate_input_conflict()` verifies no other profile claims the
    ///    same RTMP `(bindAddress, port)`.
    ///
    /// Encryption uses the profile's own `settings.encrypt_stream_keys`
    /// (stream keys + sensitive settings fields) and the optional `password`
    /// (whole-file Argon2id + AES-GCM-SIV envelope).
    pub async fn save_with_key_encryption(
        &self,
        profile: &Profile,
        password: Option<&str>,
    ) -> Result<(), CoreError> {
        let encrypt_keys = profile.settings.encrypt_stream_keys;

        log::info!(
            "Saving profile: {} (encrypted: {}, stream keys encrypted: {})",
            profile.name,
            password.is_some(),
            encrypt_keys
        );

        validate_profile_name(&profile.name)?;
        Self::validate_profile_settings_bounds(&profile.settings)?;
        if profile.id.trim().is_empty() {
            return Err(CoreError::ValidationFailed {
                reasons: vec![ValidationIssue {
                    code: "profile_id_empty".into(),
                    message: "Profile id cannot be empty.".into(),
                    path: Some("/id".into()),
                }],
            });
        }

        // High-value-secret length floor for profile encryption. See
        // `crate::services::PROFILE_PASSWORD_MIN_LENGTH` for the threat-
        // model rationale (NIST SP 800-63B-3 + OWASP 2024 for memorized
        // secrets protecting credentials, PII blocklists, and anonymous-
        // mode salts).
        if let Some(pw) = password {
            if pw.len() < crate::services::PROFILE_PASSWORD_MIN_LENGTH {
                return Err(CoreError::PasswordTooShort {
                    min_length: crate::services::PROFILE_PASSWORD_MIN_LENGTH as u32,
                });
            }
        }

        self.validate_input_conflict(&profile.id, &profile.input)
            .await?;

        // Clone so we can normalize + encrypt without mutating the caller's
        // profile.
        let mut profile_to_save = profile.clone();

        // Keep `Profile.encrypted` in sync with the actual file shape we're
        // about to write. Without this, a client sending `encrypted: false`
        // + a password would persist a misleading flag inside the encrypted
        // blob — `is-encrypted` would then lie on the next load.
        profile_to_save.encrypted = password.is_some();

        // Generate the per-profile pseudonymizer salt on first save if the
        // caller didn't supply one. Existing profiles loaded from disk
        // before this field existed also get a salt the next time they're
        // saved.
        profile_to_save.ensure_anonymous_salt();

        // `PlatformRegistry::normalize_url()` exists in core but was never
        // called on save. Pull it in. Server is now the authoritative place
        // URL normalization happens.
        let registry = crate::services::PlatformRegistry::new()?;
        for group in &mut profile_to_save.output_groups {
            for target in &mut group.stream_targets {
                let normalized = registry.normalize_url(&target.service, &target.url);
                target.url = normalized;
            }
        }

        if encrypt_keys {
            self.encrypt_stream_keys(&mut profile_to_save)?;
        }
        self.encrypt_profile_settings(&mut profile_to_save)?;

        // PII blocklist: for password-encrypted profiles the whole body
        // is enveloped below, so plain JSON for the entries is fine. For
        // PLAINTEXT profiles we must wrap each entry under the machine
        // key — otherwise real names / deadnames / hometowns hit disk
        // as raw JSON, which is the threat model's worst case. Wrap
        // unconditionally (encrypt_pii_blocklist is idempotent), so even
        // if a profile flips between password+no-password the blocklist
        // is always at-rest-protected on disk.
        self.encrypt_pii_blocklist(&mut profile_to_save)?;

        let content = serde_json::to_string_pretty(&profile_to_save)?;

        if let Some(pwd) = password {
            let encrypted = Encryption::encrypt(content.as_bytes(), pwd)?;

            let mut data = Vec::with_capacity(ENCRYPTED_MAGIC_LEN + encrypted.len());
            data.extend_from_slice(ENCRYPTED_MAGIC_V2);
            data.extend_from_slice(&encrypted);

            // Profile files always written owner-only.
            let path = self.profiles_dir.join(format!("{}.mgs", profile.name));
            crate::services::write_owner_only_atomic(&path, &data)?;

            let json_path = self.profiles_dir.join(format!("{}.json", profile.name));
            if json_path.exists() {
                std::fs::remove_file(&json_path).ok();
            }
        } else {
            let path = self.profiles_dir.join(format!("{}.json", profile.name));
            crate::services::write_owner_only_atomic(&path, content.as_bytes())?;

            let mgs_path = self.profiles_dir.join(format!("{}.mgs", profile.name));
            if mgs_path.exists() {
                std::fs::remove_file(&mgs_path).ok();
            }
        }

        log::info!("Profile saved successfully: {}", profile.name);
        if let Some(audit) = self.audit() {
            if let Err(e) = audit.record(crate::services::AuditAction::ProfileSaved {
                name: profile.name.clone(),
            }) {
                log::error!("profile_manager failed to append ProfileSaved audit entry: {e}");
            }
        }
        Ok(())
    }

    /// Load a profile and always decrypt stream keys and sensitive settings.
    pub async fn load_with_key_decryption(
        &self,
        name: &str,
        password: Option<&str>,
    ) -> Result<Profile, CoreError> {
        log::info!("Loading profile: {name}");
        let mut profile = self.load(name, password).await?;

        self.decrypt_stream_keys(&mut profile)?;
        self.decrypt_profile_settings(&mut profile)?;
        // PII blocklist: wrapped on save (encrypt_pii_blocklist),
        // unwrap on load so callers see the plain phrases. Legacy
        // profiles saved before O.11b have plaintext entries; the
        // decrypt helper passes those through unchanged so they get
        // wrapped on the next save.
        self.decrypt_pii_blocklist(&mut profile)?;

        log::info!(
            "Profile loaded successfully: {} ({} output groups, {} total targets)",
            name,
            profile.output_groups.len(),
            profile
                .output_groups
                .iter()
                .map(|g| g.stream_targets.len())
                .sum::<usize>()
        );
        Ok(profile)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::ProfileSettings;
    use crate::services::Encryption;
    use crate::services::ProfileManager;
    use tempfile::TempDir;

    fn profile_with_oauth_tokens() -> Profile {
        let mut settings = ProfileSettings::default();
        settings.oauth.twitch.access_token = "tw-access".into();
        settings.oauth.twitch.refresh_token = "tw-refresh".into();
        settings.oauth.youtube.access_token = "yt-access".into();
        settings.oauth.youtube.refresh_token = "yt-refresh".into();
        settings.oauth.kick.access_token = "kk-access".into();
        settings.oauth.kick.refresh_token = "kk-refresh".into();
        settings.oauth.facebook.access_token = "fb-access".into();
        settings.oauth.facebook.refresh_token = "fb-refresh".into();
        Profile {
            id: "g1-test".into(),
            name: "g1-test".into(),
            encrypted: false,
            input: crate::models::RtmpInput::default(),
            output_groups: Vec::new(),
            settings,
            pii_blocklist: Vec::new(),
            pii_fuzzy: false,
            anonymous_logging: true,
            anonymous_salt: String::new(),
        }
    }

    /// G1 regression: pre-fix, only twitch + youtube OAuth tokens were
    /// encrypted. Kick + Facebook ended up on disk in plaintext even
    /// when `encrypt_stream_keys` was on. This test pins that all four
    /// providers round-trip through the encrypt path.
    #[tokio::test]
    async fn encrypts_oauth_tokens_for_all_four_providers() {
        let dir = TempDir::new().unwrap();
        let mgr = ProfileManager::new(dir.path().to_path_buf());

        let mut p = profile_with_oauth_tokens();
        mgr.test_encrypt_profile_settings(&mut p).unwrap();

        for (provider, account) in [
            ("twitch", &p.settings.oauth.twitch),
            ("youtube", &p.settings.oauth.youtube),
            ("kick", &p.settings.oauth.kick),
            ("facebook", &p.settings.oauth.facebook),
        ] {
            assert!(
                Encryption::is_stream_key_encrypted(&account.access_token),
                "{provider} access_token not encrypted: {}",
                account.access_token,
            );
            assert!(
                Encryption::is_stream_key_encrypted(&account.refresh_token),
                "{provider} refresh_token not encrypted: {}",
                account.refresh_token,
            );
        }

        // Round trip back to plaintext.
        mgr.test_decrypt_profile_settings(&mut p).unwrap();
        assert_eq!(p.settings.oauth.kick.access_token, "kk-access");
        assert_eq!(p.settings.oauth.facebook.refresh_token, "fb-refresh");
    }

    /// O.11b regression: a plaintext profile's `pii_blocklist` used to
    /// hit disk as raw JSON strings — the threat model's worst case
    /// (real name / deadname / hometown plain-text on disk). Wrap each
    /// entry with the `ENC2::` envelope so an attacker who reads the
    /// `.json` file sees ciphertext, not phrases.
    #[tokio::test]
    async fn pii_blocklist_is_wrapped_on_save_for_plaintext_profile() {
        let dir = TempDir::new().unwrap();
        let mgr = ProfileManager::new(dir.path().to_path_buf());

        let mut p = profile_with_oauth_tokens();
        p.name = "pii-test".into();
        p.id = "pii-test".into();
        p.pii_blocklist = vec![
            "Alice Smith".into(),
            "alice@example.com".into(),
            "123 Main St".into(),
        ];

        // Save plaintext (no password) — the on-disk JSON must not
        // contain any of the raw phrases.
        mgr.save_with_key_encryption(&p, None).await.unwrap();
        let on_disk =
            std::fs::read_to_string(dir.path().join("profiles").join("pii-test.json")).unwrap();
        for phrase in ["Alice Smith", "alice@example.com", "123 Main St"] {
            assert!(
                !on_disk.contains(phrase),
                "PII phrase {phrase:?} leaked into plaintext profile JSON",
            );
        }
        assert!(
            on_disk.contains("ENC2::"),
            "Expected ENC2:: wrapping on PII entries in plaintext profile",
        );

        // Load roundtrip: callers must see the original plaintext phrases.
        let loaded = mgr
            .load_with_key_decryption("pii-test", None)
            .await
            .unwrap();
        assert_eq!(
            loaded.pii_blocklist,
            vec![
                "Alice Smith".to_string(),
                "alice@example.com".to_string(),
                "123 Main St".to_string(),
            ],
        );
    }

    /// G2 regression: `ProfileSaved` was a defined-not-emitted variant.
    /// Wiring `set_audit_log` + emission inside `save_with_key_encryption`
    /// makes every save observable in the HMAC chain.
    #[tokio::test]
    async fn save_emits_profile_saved_audit_entry() {
        use crate::services::{AuditAction, AuditLogService};
        use std::sync::Arc;
        let dir = TempDir::new().unwrap();
        let mgr = ProfileManager::new(dir.path().to_path_buf());
        let audit = Arc::new(AuditLogService::new(dir.path().to_path_buf()).unwrap());
        mgr.set_audit_log(audit.clone());

        let mut p = profile_with_oauth_tokens();
        p.input.port = 19350; // avoid collision with any concurrent test
        mgr.save_with_key_encryption(&p, None).await.unwrap();

        let entries = audit.entries().unwrap();
        let saved = entries
            .iter()
            .filter(|e| matches!(e.action, AuditAction::ProfileSaved { .. }))
            .count();
        assert!(saved >= 1, "expected at least one ProfileSaved entry");
    }

    /// G2 regression: `ProfileDeleted` was also defined-not-emitted.
    #[tokio::test]
    async fn delete_emits_profile_deleted_audit_entry() {
        use crate::services::{AuditAction, AuditLogService};
        use std::sync::Arc;
        let dir = TempDir::new().unwrap();
        let mgr = ProfileManager::new(dir.path().to_path_buf());
        let audit = Arc::new(AuditLogService::new(dir.path().to_path_buf()).unwrap());
        mgr.set_audit_log(audit.clone());

        let mut p = profile_with_oauth_tokens();
        p.input.port = 19351;
        mgr.save_with_key_encryption(&p, None).await.unwrap();
        mgr.delete("g1-test").await.unwrap();

        let entries = audit.entries().unwrap();
        let deleted = entries
            .iter()
            .filter(|e| matches!(e.action, AuditAction::ProfileDeleted { .. }))
            .count();
        assert_eq!(deleted, 1, "expected exactly one ProfileDeleted entry");
    }
}

//! Profile validation helpers — name shape, settings bounds, constants.

use crate::errors::{CoreError, ValidationIssue};

/// Discord webhook cooldown upper bound, in seconds. Zero is allowed
/// ("no rate limiting between notifications"); beyond 24 hours the
/// user has effectively disabled the notification and a typed setting
/// would be misleading.
pub const DISCORD_COOLDOWN_SECONDS_MAX: u32 = 86_400;

/// Backend bind port lower bound. Port 0 is reserved and never valid
/// for binding.
pub const BACKEND_PORT_MIN: u16 = 1;

/// Validate profile name to prevent path traversal attacks.
///
/// Returns `CoreError::ValidationFailed` with stable issue codes so callers
/// (CLI, frontend) can localize the message or branch programmatically.
pub(super) fn validate_profile_name(name: &str) -> Result<(), CoreError> {
    let mut reasons: Vec<ValidationIssue> = Vec::new();
    if name.is_empty() {
        reasons.push(ValidationIssue {
            code: "profile_name_empty".into(),
            message: "Profile name cannot be empty.".into(),
            path: Some("/name".into()),
        });
    }
    if name.contains('/') || name.contains('\\') {
        reasons.push(ValidationIssue {
            code: "profile_name_path_separator".into(),
            message: "Profile name cannot contain path separators.".into(),
            path: Some("/name".into()),
        });
    }
    if name.contains("..") {
        reasons.push(ValidationIssue {
            code: "profile_name_path_traversal".into(),
            message: "Profile name cannot contain '..'.".into(),
            path: Some("/name".into()),
        });
    }
    if !name
        .chars()
        .all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == ' ')
    {
        reasons.push(ValidationIssue {
            code: "profile_name_charset".into(),
            message:
                "Profile name can only contain letters, numbers, spaces, underscores, and hyphens."
                    .into(),
            path: Some("/name".into()),
        });
    }
    if name.len() > 100 {
        reasons.push(ValidationIssue {
            code: "profile_name_too_long".into(),
            message: "Profile name is too long (max 100 characters).".into(),
            path: Some("/name".into()),
        });
    }
    if reasons.is_empty() {
        Ok(())
    } else {
        Err(CoreError::ValidationFailed { reasons })
    }
}

impl super::ProfileManager {
    /// Enforce bounds on profile-scoped settings that now live in
    /// `ProfileSettings`. Out-of-range values produce a single
    /// `CoreError::ValidationFailed` carrying every offending field —
    /// callers get a complete list.
    pub(super) fn validate_profile_settings_bounds(
        settings: &crate::models::ProfileSettings,
    ) -> Result<(), CoreError> {
        let mut issues = Vec::new();
        if settings.backend.port < BACKEND_PORT_MIN {
            issues.push(ValidationIssue {
                code: "backend_port_out_of_range".into(),
                message: format!(
                    "backend.port must be in [{BACKEND_PORT_MIN}, 65535], got {}",
                    settings.backend.port
                ),
                path: Some("/settings/backend/port".into()),
            });
        }
        if settings.discord.cooldown_seconds > DISCORD_COOLDOWN_SECONDS_MAX {
            issues.push(ValidationIssue {
                code: "discord_cooldown_seconds_out_of_range".into(),
                message: format!(
                    "discord.cooldown_seconds must be in [0, {DISCORD_COOLDOWN_SECONDS_MAX}], got {}",
                    settings.discord.cooldown_seconds
                ),
                path: Some("/settings/discord/cooldownSeconds".into()),
            });
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(CoreError::ValidationFailed { reasons: issues })
        }
    }
}

