//! `ProfileActivationService` — orchestrates a single profile activation by
//! composing the participating services. Owning the orchestration in its own
//! service keeps `ProfileManager` focused on persistence + CRUD and keeps
//! `OAuthService` focused on token policy; the transport layer becomes a
//! one-liner that asks for an activation and reacts to the structured
//! `ActivationOutcome` it gets back.
//!
//! Previously this orchestration lived inside `ProfileManager::activate`,
//! which coupled persistence concerns to OAuth refresh + chat propagation +
//! OBS lifecycle. Extracting it eliminates that coupling, matches the
//! rewrite's "thin transport, modular core" rule, and gives both the HTTP
//! and CLI transports a single entry point with identical semantics.

use std::sync::Arc;

use tokio::sync::Mutex;

use crate::errors::CoreError;
use crate::models::{ObsIntegrationDirection, Profile};
use crate::services::profile_manager::ProfileActivatedEvent;
use crate::services::{
    AuthSurveillanceService, ChatManager, EventSink, IntegrationDirection, OAuthService, ObsConfig,
    ObsConnectionStatus, ObsWebSocketHandler, ProfileManager, SettingsManager,
};

/// Refresh leeway for OAuth tokens evaluated during activation. Matches the
/// constant previously used by the HTTP transport's standalone helper — far
/// enough ahead of expiry that the first chat-connect or stream-start after
/// activate doesn't 401.
const OAUTH_REFRESH_LEEWAY_SECS: i64 = 300;

/// Structured result of `ProfileActivationService::activate`. Transports
/// emit `profile.event` on their event bus and translate
/// `oauth_refresh_failed` into transport-shaped follow-up events
/// (HTTP: `oauth_token_expired` over the WebSocket).
#[derive(Debug)]
pub struct ActivationOutcome {
    pub profile: Profile,
    pub event: ProfileActivatedEvent,
    pub oauth_refresh_failed: Vec<String>,
}

/// Composes profile load + OAuth refresh + chat propagation + OBS
/// reconfigure + event payload assembly. Constructed once in
/// `ServiceRegistry` and shared as `Arc<...>` across transports.
#[derive(Clone)]
pub struct ProfileActivationService {
    profiles: Arc<ProfileManager>,
    settings: Arc<SettingsManager>,
    oauth: Arc<OAuthService>,
    chat: Arc<ChatManager>,
    obs: Arc<ObsWebSocketHandler>,
    events: Arc<dyn EventSink>,
    surveillance: Arc<AuthSurveillanceService>,
    /// Serialises concurrent `activate()` calls. Two activations of
    /// different profiles racing would let their persisted state
    /// (last_profile, chat config, OBS config) interleave by scheduling
    /// — whoever finished last would win, ignoring which the user
    /// actually requested first. Frontend double-clicks + retry-on-fail
    /// paths can trigger this without an attacker. Held across the
    /// whole cascade (load → OAuth refresh → save → chat → OBS → event).
    activation_lock: Arc<Mutex<()>>,
}

impl ProfileActivationService {
    pub fn new(
        profiles: Arc<ProfileManager>,
        settings: Arc<SettingsManager>,
        oauth: Arc<OAuthService>,
        chat: Arc<ChatManager>,
        obs: Arc<ObsWebSocketHandler>,
        events: Arc<dyn EventSink>,
        surveillance: Arc<AuthSurveillanceService>,
    ) -> Self {
        Self {
            profiles,
            settings,
            oauth,
            chat,
            obs,
            events,
            surveillance,
            activation_lock: Arc::new(Mutex::new(())),
        }
    }

    /// Run the full activation cascade. Single load, single OAuth-refresh
    /// pass, single chat/OBS propagation, single event-payload assembly.
    /// Encrypted profiles run Argon2id exactly once (m=64 MiB, t=3, p=4) —
    /// previously the transport-side post-load refresh path doubled this.
    pub async fn activate(
        &self,
        name: &str,
        password: Option<&str>,
    ) -> Result<ActivationOutcome, CoreError> {
        // Serialise: see `activation_lock` field comment for why.
        let _activation_guard = self.activation_lock.lock().await;
        let mut profile = self
            .profiles
            .load_with_key_decryption(name, password)
            .await?;

        let refresh = self
            .oauth
            .refresh_profile_tokens(
                &mut profile,
                OAUTH_REFRESH_LEEWAY_SECS,
                Some(&self.surveillance),
            )
            .await?;
        if !refresh.refreshed.is_empty() {
            self.profiles
                .save_with_key_encryption(&profile, None)
                .await?;
        }

        // Persist the active profile name to `Settings::last_profile`.
        // Subsequent CLI invocations (which start with empty in-memory
        // state) and HTTP startup's profile auto-load (`lib.rs:2486`)
        // both rely on this to identify the active profile. Prior to
        // this, only obs_websocket + the HTTP startup probe read the
        // field, and nothing wrote it — leaving CLI chat send and other
        // active-profile-aware commands without an active profile.
        match self.settings.load() {
            Ok(mut current) => {
                if current.last_profile.as_deref() != Some(name) {
                    current.last_profile = Some(name.to_string());
                    if let Err(e) = self.settings.save(&current) {
                        log::warn!("Failed to persist last_profile={name}: {e}");
                    }
                }
            }
            Err(e) => log::warn!("Could not load settings to persist last_profile: {e}"),
        }

        self.chat
            .update_profile_chat_settings(profile.settings.chat.clone())
            .await;

        // Tear down any existing OBS session before reconfigure — otherwise
        // we'd hold a connection authenticated with the prior profile's
        // password while the new config replaces it.
        let prior_status = self.obs.get_state().await.connection_status;
        if matches!(
            prior_status,
            ObsConnectionStatus::Connected | ObsConnectionStatus::Connecting
        ) {
            if let Err(e) = self.obs.disconnect(self.events.clone()).await {
                log::warn!("OBS disconnect during profile activate failed: {e}");
            }
        }

        let obs_settings = &profile.settings.obs;
        let direction = match obs_settings.direction {
            ObsIntegrationDirection::ObsToSpiritstream => IntegrationDirection::ObsToSpiritstream,
            ObsIntegrationDirection::SpiritstreamToObs => IntegrationDirection::SpiritstreamToObs,
            ObsIntegrationDirection::Bidirectional => IntegrationDirection::Bidirectional,
            ObsIntegrationDirection::Disabled => IntegrationDirection::Disabled,
        };
        self.obs
            .set_config(ObsConfig {
                host: obs_settings.host.clone(),
                port: obs_settings.port,
                password: obs_settings.password.clone(),
                use_auth: obs_settings.use_auth,
                direction,
                auto_connect: obs_settings.auto_connect,
            })
            .await;

        if obs_settings.auto_connect {
            if let Err(e) = self.obs.connect(self.events.clone()).await {
                log::warn!("OBS auto-connect during profile activate failed: {e}");
            }
        }

        let event = ProfileActivatedEvent::from_profile_public(&profile);
        // Emit the consolidated event from the orchestrator itself so HTTP
        // and CLI see identical bus traffic without re-implementing the
        // emission. Transports may still inspect `outcome.event` for
        // response bodies / CLI JSON output.
        match serde_json::to_value(&event) {
            Ok(value) => self.events.emit("profile_activated", value),
            Err(e) => log::warn!("profile_activated event serialization failed: {e}"),
        }

        Ok(ActivationOutcome {
            profile,
            event,
            oauth_refresh_failed: refresh.failed,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::{OAuthAccount, OAuthSettings, ProfileSettings, RtmpInput};
    use crate::services::{AuditLogService, OAuthConfig};
    use crate::NoopEventSink;

    fn fresh_dir() -> std::path::PathBuf {
        let p = std::env::temp_dir().join(format!(
            "spiritstream-activation-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(p.join("profiles")).unwrap();
        p
    }

    fn now_secs() -> i64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as i64
    }

    async fn save_profile_with_oauth(
        mgr: &ProfileManager,
        name: &str,
        twitch_expires_at: i64,
        twitch_refresh: &str,
    ) {
        let settings = ProfileSettings {
            oauth: OAuthSettings {
                twitch: OAuthAccount {
                    access_token: "access-token-xyz".into(),
                    refresh_token: twitch_refresh.into(),
                    expires_at: twitch_expires_at,
                    user_id: "twitch-user".into(),
                    username: "twitchhandle".into(),
                    display_name: "Twitch Display".into(),
                },
                ..OAuthSettings::default()
            },
            ..ProfileSettings::default()
        };
        let profile = Profile {
            id: format!("test-{name}"),
            name: name.into(),
            encrypted: false,
            input: RtmpInput {
                input_type: "rtmp".into(),
                bind_address: "127.0.0.1".into(),
                port: 1935,
                application: "live".into(),
            },
            output_groups: vec![],
            settings,
            pii_blocklist: vec![],
            pii_fuzzy: false,
            anonymous_logging: true,
            anonymous_salt: String::new(),
        };
        mgr.save_with_key_encryption(&profile, None)
            .await
            .expect("save plaintext fixture");
    }

    /// A token NOT inside the leeway window must not be touched — refresh is
    /// a no-op for healthy tokens. The expiry field stays intact through the
    /// load/refresh/return loop, and the outcome lists neither refresh nor
    /// failure for the provider.
    #[tokio::test]
    async fn refresh_skips_tokens_outside_leeway() {
        let data_dir = fresh_dir();
        let mgr = ProfileManager::new(data_dir.clone());
        let oauth = Arc::new(OAuthService::new(OAuthConfig::default()));

        let far_future = now_secs() + 3600;
        save_profile_with_oauth(&mgr, "still-fresh", far_future, "refresh-token-abc").await;

        let mut profile = mgr
            .load_with_key_decryption("still-fresh", None)
            .await
            .expect("load profile");
        let outcome = oauth
            .refresh_profile_tokens(&mut profile, 300, None)
            .await
            .expect("refresh must not error on healthy tokens");

        assert!(outcome.refreshed.is_empty());
        assert!(outcome.failed.is_empty());
        assert_eq!(profile.settings.oauth.twitch.expires_at, far_future);
        assert_eq!(
            profile.settings.oauth.twitch.access_token,
            "access-token-xyz"
        );
        let _ = std::fs::remove_dir_all(data_dir);
    }

    /// A profile with NO refresh token + an expiring access token: refresh
    /// helper skips the provider entirely (no `failed` entry — we can't even
    /// attempt without a refresh token). expires_at stays unchanged so the
    /// caller can act on the in-memory profile without re-loading.
    #[tokio::test]
    async fn refresh_skips_provider_without_refresh_token() {
        let data_dir = fresh_dir();
        let mgr = ProfileManager::new(data_dir.clone());
        let oauth = Arc::new(OAuthService::new(OAuthConfig::default()));

        let almost_expired = now_secs() + 60;
        save_profile_with_oauth(&mgr, "no-refresh", almost_expired, "").await;

        let mut profile = mgr
            .load_with_key_decryption("no-refresh", None)
            .await
            .expect("load profile");
        let outcome = oauth
            .refresh_profile_tokens(&mut profile, 300, None)
            .await
            .expect("missing refresh_token must not abort the loop");

        assert!(outcome.refreshed.is_empty());
        assert!(outcome.failed.is_empty());
        assert_eq!(profile.settings.oauth.twitch.expires_at, almost_expired);
        let _ = std::fs::remove_dir_all(data_dir);
    }

    /// Build the seven participants directly against a temp dir. Every one is
    /// constructed from local file paths — no keyring, no network, no
    /// subprocess — so the full `activate()` cascade runs in-process.
    fn build_service(data_dir: &std::path::Path) -> ProfileActivationService {
        let profiles = Arc::new(ProfileManager::new(data_dir.to_path_buf()));
        let settings = Arc::new(SettingsManager::new(data_dir.to_path_buf()));
        let oauth = Arc::new(OAuthService::new(OAuthConfig::default()));
        let events: Arc<dyn EventSink> = Arc::new(NoopEventSink);
        let chat = Arc::new(ChatManager::new(events.clone(), data_dir.join("logs")));
        let obs = Arc::new(ObsWebSocketHandler::new(data_dir.to_path_buf()));
        let audit = Arc::new(AuditLogService::new(data_dir.to_path_buf()).expect("audit log"));
        let surveillance = Arc::new(AuthSurveillanceService::new(audit, events.clone()));
        ProfileActivationService::new(
            profiles,
            settings,
            oauth,
            chat,
            obs,
            events,
            surveillance,
        )
    }

    /// Happy-path cascade: a healthy (far-future) token and the default OBS
    /// settings (auto_connect=false, no prior session) keep every step on the
    /// in-process path — load, no-op refresh, last_profile persistence, chat
    /// propagation, OBS reconfigure, and consolidated event assembly. Asserts
    /// the structured outcome and the persisted `last_profile`.
    #[tokio::test]
    async fn activate_runs_full_cascade_and_persists_last_profile() {
        let data_dir = fresh_dir();
        std::fs::create_dir_all(data_dir.join("logs")).unwrap();
        let service = build_service(&data_dir);

        let far_future = now_secs() + 3600;
        save_profile_with_oauth(&service.profiles, "go-live", far_future, "refresh-token-abc").await;

        let outcome = service.activate("go-live", None).await.expect("activate");

        assert_eq!(outcome.profile.name, "go-live");
        assert_eq!(outcome.event.name, "go-live");
        assert!(outcome.oauth_refresh_failed.is_empty());

        let persisted = service.settings.load().expect("settings load");
        assert_eq!(persisted.last_profile.as_deref(), Some("go-live"));
        let _ = std::fs::remove_dir_all(data_dir);
    }

    /// A second activation of the SAME profile is a no-op for `last_profile`
    /// (the `!=` guard skips the redundant save) and still returns a complete
    /// outcome — proving the cascade is idempotent under the frontend
    /// double-click / retry path the `activation_lock` exists to serialise.
    #[tokio::test]
    async fn activate_is_idempotent_for_repeat_activation() {
        let data_dir = fresh_dir();
        std::fs::create_dir_all(data_dir.join("logs")).unwrap();
        let service = build_service(&data_dir);

        let far_future = now_secs() + 3600;
        save_profile_with_oauth(&service.profiles, "again", far_future, "refresh-token-abc").await;

        service.activate("again", None).await.expect("first activate");
        let outcome = service.activate("again", None).await.expect("second activate");

        assert_eq!(outcome.profile.name, "again");
        assert_eq!(
            service.settings.load().unwrap().last_profile.as_deref(),
            Some("again")
        );
        let _ = std::fs::remove_dir_all(data_dir);
    }

    /// Activating a profile that was never saved surfaces the load error from
    /// the very first `?` in the cascade — the orchestrator must not swallow
    /// it into a partial activation.
    #[tokio::test]
    async fn activate_missing_profile_errors() {
        let data_dir = fresh_dir();
        std::fs::create_dir_all(data_dir.join("logs")).unwrap();
        let service = build_service(&data_dir);

        let err = service.activate("does-not-exist", None).await.unwrap_err();
        // Whatever the precise variant, last_profile must not have been touched.
        assert!(service.settings.load().unwrap().last_profile.is_none());
        let _ = err;
        let _ = std::fs::remove_dir_all(data_dir);
    }
}

//! Facade — preserves the historical import path
//! `crate::services::profile_manager::ProfileManager` while the real impl
//! lives in `services::profile::*`. External callers (e.g.
//! `services::profile_activation`) do not need updating.
//!
//! Internal sub-modules:
//! - `services/profile/mod.rs`         — `ProfileManager` struct + `new()` + tests
//! - `services/profile/events.rs`      — `ProfileActivatedEvent`, `ActivatedObs`
//! - `services/profile/validation.rs`  — name + settings bounds + public constants
//! - `services/profile/order_index.rs` — order-index file I/O
//! - `services/profile/io.rs`          — file I/O: list, load, delete, etc.
//! - `services/profile/security.rs`    — encryption boundary

pub use super::profile::{
    ActivatedObs, ProfileActivatedEvent, ProfileManager, BACKEND_PORT_MIN,
    DISCORD_COOLDOWN_SECONDS_MAX,
};

// Re-export the encrypted-profile magic constants for sibling modules
// (e.g. `services::encryption` tests) that still reference the historical
// `profile_manager::ENCRYPTED_MAGIC_*` path. New code should reach for
// `profile::io::ENCRYPTED_MAGIC_*` instead.
pub(crate) use super::profile::io::{ENCRYPTED_MAGIC_LEN, ENCRYPTED_MAGIC_V1, ENCRYPTED_MAGIC_V2};

//! Anonymous-mode pseudonymization.
//!
//! Replaces identifying strings — chat usernames, OAuth account labels
//! — with stable HMAC-SHA256 outputs derived from a per-profile salt.
//! The same plaintext under the same salt always produces the same
//! pseudonym, so a chat session reads coherently. A salt-leaked log
//! reverses back to plaintext only for plaintexts the attacker already
//! has on hand to test against; the salt-protected hash is one-way.
//!
//! # Format
//!
//! `pseudonymize("alice", salt) → "hash:abcd1234ef567890"`
//!
//! 16-char prefix of hex-encoded HMAC-SHA256. The `hash:` literal
//! marks the value as pseudonymised so a future migration / log
//! reader can recognise it without ambiguity (a real chat username
//! never starts with `hash:` followed by 16 hex chars).
//!
//! # Decode
//!
//! There is intentionally no `decode()` function — the construction is
//! one-way. The UI's "show me real usernames" affordance works by
//! re-pseudonymising candidate plaintexts the user already has stored
//! locally (their connected accounts) and comparing against logged
//! hashes via [`matches()`].

use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

const HASH_PREFIX: &str = "hash:";
const HASH_PREFIX_LEN: usize = 16; // hex chars of HMAC prefix surfaced

/// Generate a fresh 32-byte salt suitable for [`pseudonymize`]. Returns
/// the salt hex-encoded so it can live on the `Profile` struct as a
/// plain string (and survive a JSON round-trip without bigint dance).
pub fn generate_salt() -> String {
    use rand::RngCore;
    let mut bytes = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut bytes);
    hex::encode(bytes)
}

/// Pseudonymise `value` under the hex-encoded `salt`. Returns the
/// salted hash in the documented `hash:<16hex>` format. Returns the
/// input unchanged if `salt` is empty or malformed — callers that
/// have already decided to apply anonymous mode are responsible for
/// passing a valid salt.
pub fn pseudonymize(value: &str, salt_hex: &str) -> String {
    let Some(salt) = decode_salt(salt_hex) else {
        return value.to_string();
    };
    let mut mac = HmacSha256::new_from_slice(&salt).expect("HMAC accepts any key length");
    mac.update(value.as_bytes());
    let digest = mac.finalize().into_bytes();
    let encoded = hex::encode(&digest[..(HASH_PREFIX_LEN / 2)]);
    format!("{HASH_PREFIX}{encoded}")
}

/// Test whether `candidate` plaintext would produce `pseudonym` under
/// `salt`. The UI uses this to decode hashes back to plaintexts the
/// user already knows about (their connected account usernames). The
/// comparison is constant-time on the byte representation so the time
/// taken doesn't leak how many bytes of the pseudonym a candidate
/// matched — `String == String` short-circuits at the first differing
/// byte, which over many candidate calls is a character-by-character
/// timing oracle for an attacker who can measure the response.
pub fn matches(candidate: &str, salt_hex: &str, pseudonym: &str) -> bool {
    use subtle::ConstantTimeEq;
    let derived = pseudonymize(candidate, salt_hex);
    // `pseudonymize` always returns a fixed-shape string (HASH_PREFIX +
    // HASH_PREFIX_LEN hex chars), so a length mismatch means the
    // candidate input couldn't have produced this pseudonym at all —
    // bail before ct_eq to avoid mixing different lengths.
    if derived.len() != pseudonym.len() {
        return false;
    }
    derived.as_bytes().ct_eq(pseudonym.as_bytes()).into()
}

/// Check whether a value is in the pseudonymised format. Lets the UI
/// branch between "show as-is" and "show with decode affordance"
/// without needing the salt.
pub fn looks_pseudonymized(value: &str) -> bool {
    let Some(rest) = value.strip_prefix(HASH_PREFIX) else {
        return false;
    };
    rest.len() == HASH_PREFIX_LEN && rest.chars().all(|c| c.is_ascii_hexdigit())
}

fn decode_salt(salt_hex: &str) -> Option<Vec<u8>> {
    if salt_hex.is_empty() {
        return None;
    }
    hex::decode(salt_hex).ok().filter(|b| !b.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pseudonymize_is_deterministic_under_same_salt() {
        let salt = generate_salt();
        let a = pseudonymize("alice", &salt);
        let b = pseudonymize("alice", &salt);
        assert_eq!(a, b, "same input + same salt must yield same pseudonym");
    }

    #[test]
    fn pseudonymize_differs_across_salts() {
        let s1 = generate_salt();
        let s2 = generate_salt();
        assert_ne!(s1, s2, "salts must be unique per call");
        let a = pseudonymize("alice", &s1);
        let b = pseudonymize("alice", &s2);
        assert_ne!(
            a, b,
            "same name + different salt must yield different pseudonyms"
        );
    }

    #[test]
    fn pseudonymize_differs_across_inputs_under_same_salt() {
        let salt = generate_salt();
        let alice = pseudonymize("alice", &salt);
        let bob = pseudonymize("bob", &salt);
        assert_ne!(
            alice, bob,
            "different inputs must yield different pseudonyms"
        );
    }

    #[test]
    fn pseudonymize_format_is_hash_prefix_plus_16_hex() {
        let salt = generate_salt();
        let out = pseudonymize("user", &salt);
        assert!(out.starts_with("hash:"));
        assert_eq!(out.len(), "hash:".len() + 16);
        assert!(out[5..].chars().all(|c| c.is_ascii_hexdigit()));
    }

    #[test]
    fn empty_salt_returns_input_unchanged() {
        assert_eq!(pseudonymize("alice", ""), "alice");
    }

    #[test]
    fn malformed_salt_returns_input_unchanged() {
        // hex::decode("xyz") fails — not hex.
        assert_eq!(pseudonymize("alice", "xyz"), "alice");
    }

    #[test]
    fn matches_returns_true_for_correct_candidate() {
        let salt = generate_salt();
        let pseudonym = pseudonymize("alice", &salt);
        assert!(matches("alice", &salt, &pseudonym));
    }

    #[test]
    fn matches_returns_false_for_wrong_candidate() {
        let salt = generate_salt();
        let pseudonym = pseudonymize("alice", &salt);
        assert!(!matches("bob", &salt, &pseudonym));
    }

    #[test]
    fn looks_pseudonymized_recognises_real_pseudonyms() {
        let salt = generate_salt();
        let p = pseudonymize("alice", &salt);
        assert!(looks_pseudonymized(&p));
    }

    #[test]
    fn looks_pseudonymized_rejects_plain_usernames() {
        assert!(!looks_pseudonymized("alice"));
        assert!(!looks_pseudonymized("hash:abc")); // too short
        assert!(!looks_pseudonymized("hash:1234567890abcdefXX")); // not hex
    }

    #[test]
    fn generate_salt_is_64_hex_chars() {
        // 32 bytes hex-encoded = 64 chars.
        assert_eq!(generate_salt().len(), 64);
    }
}

//! Safety coordination service.
//!
//! Owns the panic-disconnect flow. Reachable from every transport
//! identically:
//!
//! * HTTP — `POST /api/v1/safety/panic`
//! * CLI  — `spiritstream-cli safety panic`
//! * Tauri 2 mobile — panic gesture binds to this same call
//!
//! Hotkey registration on desktop is the Tauri shell's responsibility
//! (Tauri 2 global-shortcut plugin); this service handles the actions
//! invoked once a panic fires.
//!
//! # Contract (atomicity)
//!
//! `panic()` is **synchronous-with-timeout client side, fire-and-forget
//! for remote services**. The flow:
//!
//! 1. Stop every active FFmpeg stream (process kill).
//! 2. Disconnect every chat platform (immediate, no graceful close).
//! 3. Disconnect OBS WebSocket.
//! 4. Wipe in-memory secret caches via [`SecretStore::purge_caches`].
//! 5. Record an audit-log entry — audit entries themselves are NOT
//!    wiped; the user needs a forensic trail of when panic fired.
//! 6. Emit `panic_triggered` event so subscribed UIs render the banner.
//!
//! Remote services (Discord webhook for "user panicked" notifications
//! etc.) are intentionally skipped — blocking on platform RTTs would
//! add 5-15s of latency to a panic where every second matters. The
//! audit entry is the durable record.

use std::sync::Arc;
use std::time::Instant;

use crate::errors::CoreError;
use crate::models::ChatPlatform;
use crate::services::{
    pii_filter, AuditAction, AuditLogService, ChatManager, FFmpegHandler, ObsWebSocketHandler,
    PiiCheck, PiiMatchMode,
};
use crate::traits::{EventSink, SecretStore};

/// Result returned by a successful panic — surfaced through the event
/// bus and the audit log so the user can see what happened.
#[derive(Debug, Clone)]
pub struct PanicResult {
    pub streams_stopped: usize,
    pub elapsed_ms: u64,
    /// Q8: errors that occurred while running the disconnect sequence
    /// (FFmpeg stop_all, chat disconnect_all, OBS disconnect). Each
    /// entry is a human-readable string prefixed with the failing
    /// subsystem. Pre-Q8 these were `log::error!`-and-forgotten — the
    /// operator had no programmatic way to detect that chat didn't
    /// actually disconnect, only that panic "ran."
    pub connector_errors: Vec<String>,
}

/// Coordinates the panic-disconnect flow across services.
pub struct SafetyService {
    ffmpeg: Arc<FFmpegHandler>,
    chat: Arc<ChatManager>,
    obs: Arc<ObsWebSocketHandler>,
    audit: Arc<AuditLogService>,
    events: Arc<dyn EventSink>,
    secrets: Arc<dyn SecretStore>,
}

impl SafetyService {
    pub fn new(
        ffmpeg: Arc<FFmpegHandler>,
        chat: Arc<ChatManager>,
        obs: Arc<ObsWebSocketHandler>,
        audit: Arc<AuditLogService>,
        events: Arc<dyn EventSink>,
        secrets: Arc<dyn SecretStore>,
    ) -> Self {
        Self {
            ffmpeg,
            chat,
            obs,
            audit,
            events,
            secrets,
        }
    }

    /// Check an outbound chat message against a PII blocklist snapshot.
    /// Returns `Ok(())` if the message is clear, or
    /// `Err(CoreError::ChatBlockedByPii)` if a phrase matched. On match,
    /// an audit entry is recorded with the stable `phrase_id` (never
    /// the matched text) so a forensic trail exists.
    ///
    /// Takes the blocklist + fuzzy flag directly so callers can pass a
    /// cached snapshot (HTTP holds the active-profile pii cache on
    /// `AppState`; CLI loads the profile per-command) without re-loading
    /// the full `Profile` on every send.
    ///
    /// `platforms` is only used for the audit entry — the filter
    /// decision itself is platform-agnostic.
    pub fn check_outbound_pii(
        &self,
        blocklist: &[String],
        fuzzy: bool,
        platforms: &[ChatPlatform],
        message: &str,
    ) -> Result<(), CoreError> {
        if blocklist.is_empty() {
            return Ok(());
        }
        let mode = if fuzzy {
            PiiMatchMode::Fuzzy
        } else {
            PiiMatchMode::Strict
        };
        if let PiiCheck::Match { phrase_id } = pii_filter::check(message, blocklist, mode) {
            // One aggregate audit entry per send call. The decision is
            // platform-agnostic (same phrase, multiple destinations);
            // per-platform records would inflate the chain without
            // adding forensic signal. `platforms` captures the full
            // target set the send attempted.
            let target_strs: Vec<String> =
                platforms.iter().map(|p| p.as_str().to_string()).collect();
            let _ = self.audit.record(AuditAction::ChatMessagePiiBlocked {
                platforms: target_strs,
                phrase_id: phrase_id.clone(),
            });
            self.events.emit(
                "pii_filter_fired",
                serde_json::json!({
                    "phraseId": phrase_id,
                    "platformCount": platforms.len(),
                }),
            );
            return Err(CoreError::ChatBlockedByPii { phrase_id });
        }
        Ok(())
    }

    /// Trigger a panic disconnect. Returns a [`PanicResult`] summarising
    /// the action; the result is also emitted as a `panic_triggered`
    /// event and recorded in the audit log.
    ///
    /// Errors from individual steps are logged but never propagated —
    /// a panic call must always finish, even if one of the upstream
    /// services failed. The only failure modes from this method are
    /// audit-log write errors, which we surface so the caller can
    /// decide whether to retry (the upstream actions are already done).
    pub async fn panic(&self) -> Result<PanicResult, CoreError> {
        let started = Instant::now();
        let mut connector_errors: Vec<String> = Vec::new();

        // 1. Stop every active FFmpeg stream. Capture the count before
        //    stop_all clears it so the audit/event can report it.
        let streams_stopped = self.ffmpeg.active_count();
        if let Err(e) = self.ffmpeg.stop_all() {
            let msg = format!("ffmpeg.stop_all: {e}");
            log::error!("panic: {msg}");
            connector_errors.push(msg);
        }

        // 2. Disconnect every connected chat platform.
        if let Err(e) = self.chat.disconnect_all("panic_triggered").await {
            let msg = format!("chat.disconnect_all: {e}");
            log::error!("panic: {msg}");
            connector_errors.push(msg);
        }

        // 3. Disconnect OBS. The handler takes an EventSink generic, so
        //    pass the same one we'll emit through. Errors are logged.
        let obs_event_sink = OneShotEventSink {
            inner: self.events.clone(),
        };
        if let Err(e) = self.obs.disconnect(obs_event_sink).await {
            let msg = format!("obs.disconnect: {e}");
            log::error!("panic: {msg}");
            connector_errors.push(msg);
        }

        // 4. Wipe in-memory secret caches. The trait default is a no-op
        //    so an impl that holds no in-memory secrets (file store)
        //    just returns immediately.
        self.secrets.purge_caches().await;

        let elapsed_ms = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);

        // 5. Audit. We propagate this error: if the audit write fails
        //    the user has no durable record of the panic, which is
        //    worth surfacing. Connector errors collected above land in
        //    the chain so the operator can see "panic ran, but Twitch
        //    didn't actually disconnect."
        self.audit.record(AuditAction::PanicTriggered {
            streams_stopped,
            elapsed_ms,
            connector_errors: connector_errors.clone(),
        })?;

        // 6. Event. Frontends listen for `panic_triggered` and render
        //    the post-panic banner. Connector errors travel with the
        //    event so the UI can show a "panic completed with N
        //    warnings" toast.
        self.events.emit(
            "panic_triggered",
            serde_json::json!({
                "streamsStopped": streams_stopped,
                "elapsedMs": elapsed_ms,
                "connectorErrors": connector_errors.clone(),
            }),
        );

        Ok(PanicResult {
            streams_stopped,
            elapsed_ms,
            connector_errors,
        })
    }
}

/// One-shot adapter that lets [`ObsWebSocketHandler::disconnect`] —
/// which expects an `impl EventSink` by value — accept our `Arc<dyn>`.
struct OneShotEventSink {
    inner: Arc<dyn EventSink>,
}

impl EventSink for OneShotEventSink {
    fn emit(&self, event: &str, payload: serde_json::Value) {
        self.inner.emit(event, payload);
    }
}

