            perms.mode() & 0o777,
            0o600,
            "secret file must be owner-read/write only",
        );
    }

    #[tokio::test]
    async fn ciphertext_is_not_plaintext_on_disk() {
        // Cross-check: the bytes on disk must NOT contain the plaintext.
        let (_dir, store) = store();
        let secret = b"plaintext-marker-DO-NOT-LEAK";
        store.put("ns", "k", secret).await.unwrap();
        let on_disk = std::fs::read(store.entry_path("ns", "k")).unwrap();
        assert!(
            !on_disk.windows(secret.len()).any(|w| w == secret),
            "plaintext leaked into ciphertext file",
        );
    }
}

//! OS-keyring backed `SecretStore`.
//!
//! Uses `keyring = "3"` to reach macOS Keychain, Windows Credential
//! Manager, and Linux Secret Service. The keyring API stores strings,
//! so binary values are base64-encoded on the way in and decoded on the
//! way out.
//!
//! There is no fallback to another backend — if the keyring is
//! unavailable in this environment, the factory at startup already
//! chose the file impl instead.

use async_trait::async_trait;
use base64::{engine::general_purpose::STANDARD as BASE64, Engine as _};

use crate::errors::CoreError;
use crate::traits::SecretStore;

const SERVICE: &str = "spiritstream";

pub struct KeyringSecretStore;

impl KeyringSecretStore {
    pub fn new() -> Self {
        Self
    }

    fn account(namespace: &str, key: &str) -> String {
        // The keyring "account" field is presented to the user inside
        // their OS keyring UI, so keep it human-readable. We've already
        // validated namespace/key elsewhere — no separator escaping
        // needed beyond joining with "::".
        format!("{namespace}::{key}")
    }

    fn map_err(prefix: &str, e: keyring::Error) -> CoreError {
        CoreError::Internal {
            context: format!("{prefix}: {e}"),
        }
    }
}

impl Default for KeyringSecretStore {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl SecretStore for KeyringSecretStore {
    async fn get(&self, namespace: &str, key: &str) -> Result<Option<Vec<u8>>, CoreError> {
        let account = Self::account(namespace, key);
        let entry = keyring::Entry::new(SERVICE, &account)
            .map_err(|e| Self::map_err("keyring entry", e))?;
        match entry.get_password() {
            Ok(encoded) => {
                let bytes = BASE64
                    .decode(encoded.as_bytes())
                    .map_err(|e| CoreError::Internal {
                        context: format!("keyring base64 decode: {e}"),
                    })?;
                Ok(Some(bytes))
            }
            Err(keyring::Error::NoEntry) => Ok(None),
            Err(e) => Err(Self::map_err("keyring get", e)),
        }
    }

    async fn put(&self, namespace: &str, key: &str, value: &[u8]) -> Result<(), CoreError> {
        let account = Self::account(namespace, key);
        let entry = keyring::Entry::new(SERVICE, &account)
            .map_err(|e| Self::map_err("keyring entry", e))?;
        let encoded = BASE64.encode(value);
        entry
            .set_password(&encoded)
            .map_err(|e| Self::map_err("keyring put", e))
    }

    async fn delete(&self, namespace: &str, key: &str) -> Result<(), CoreError> {
        let account = Self::account(namespace, key);
        let entry = keyring::Entry::new(SERVICE, &account)
            .map_err(|e| Self::map_err("keyring entry", e))?;
        match entry.delete_credential() {
            Ok(()) => Ok(()),
            // Idempotent delete — absent entry is success.
            Err(keyring::Error::NoEntry) => Ok(()),
            Err(e) => Err(Self::map_err("keyring delete", e)),
        }
    }
}

//! Secret-storage selection.
//!
//! Two impls live side-by-side as independent modules:
//!
//! * [`KeyringSecretStore`] — wraps the OS keyring (macOS Keychain,
//!   Windows Credential Manager, Linux Secret Service).
//! * [`EncryptedFileSecretStore`] — AES-256-GCM-SIV under the
//!   per-machine key, for Docker / headless / any environment that
//!   can't host an OS keyring.
//!
//! **Exactly one is selected at startup** by [`build_secret_store`] and
//! held as `Arc<dyn SecretStore>` for the process lifetime. There is no
//! runtime fallback chain between them — the binary picks once and runs
//! that impl exclusively (per the "no fallback" rule in
//! `feedback_no_legacy.md`).
//!
//! Operators can force a choice with `SPIRITSTREAM_SECRET_STORE=keyring|file`.
//! With no override, a one-shot canary round-trip on the OS keyring
//! decides: success → keyring, any error → file.

use std::path::Path;
use std::sync::Arc;

use crate::traits::SecretStore;

mod encrypted_file_store;
mod keyring_store;

pub use encrypted_file_store::EncryptedFileSecretStore;
pub use keyring_store::KeyringSecretStore;

/// Which `SecretStore` impl the factory picked. Logged at startup; never
/// changes for the rest of the process lifetime.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SecretStoreKind {
    Keyring,
    File,
}

/// Build the single `SecretStore` impl this process will use.
///
/// * `app_data_dir` — where the file-backed impl writes its blobs if
///   chosen.
/// * `override_kind` — value of `SPIRITSTREAM_SECRET_STORE`. Recognised:
///   `"keyring"`, `"file"`. Anything else (including `None`) falls
///   through to the auto-detect probe.
pub fn build_secret_store(
    app_data_dir: &Path,
    override_kind: Option<&str>,
) -> Arc<dyn SecretStore> {
    let chosen = resolve_kind(override_kind);
    log::info!("Secret store: {chosen:?}");
    match chosen {
        SecretStoreKind::Keyring => Arc::new(KeyringSecretStore::new()),
        SecretStoreKind::File => {
            Arc::new(EncryptedFileSecretStore::new(app_data_dir.to_path_buf()))
        }
    }
}

/// Pure decision function — returns the kind without constructing it.
/// Exposed for tests so they can verify the override + probe logic
/// without touching the OS keyring or filesystem.
pub fn resolve_kind(override_kind: Option<&str>) -> SecretStoreKind {
    match override_kind.map(|s| s.to_ascii_lowercase()).as_deref() {
        Some("keyring") => SecretStoreKind::Keyring,
        Some("file") => SecretStoreKind::File,
        _ => probe_keyring(),
    }
}

/// One-shot probe: try a full keyring round-trip (write → read → delete)
/// of a sentinel canary entry. Any error indicates the keyring is not
/// available in this environment (no D-Bus, sandboxed container, etc.)
/// and the factory falls through to the file impl.
fn probe_keyring() -> SecretStoreKind {
    const SERVICE: &str = "spiritstream";
    const ACCOUNT: &str = "__probe__";
    const CANARY: &str = "probe";

    let attempt = || -> Result<bool, keyring::Error> {
        let entry = keyring::Entry::new(SERVICE, ACCOUNT)?;
        entry.set_password(CANARY)?;
        let read = entry.get_password()?;
        // Best-effort cleanup. If delete fails (e.g. permissions on a
        // platform that requires explicit confirmation), the probe still
        // counted as success because read worked.
        let _ = entry.delete_credential();
        Ok(read == CANARY)
    };

    match attempt() {
        Ok(true) => SecretStoreKind::Keyring,
        Ok(false) => {
            log::warn!(
                "Secret store: keyring round-trip read mismatched written value, using file impl"
            );
            SecretStoreKind::File
        }
        Err(e) => {
            log::info!("Secret store: keyring unavailable ({e}); using file impl");
            SecretStoreKind::File
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn explicit_override_keyring_wins() {
        // Test the override branch directly. The probe is not invoked.
        assert_eq!(resolve_kind(Some("keyring")), SecretStoreKind::Keyring);
        assert_eq!(resolve_kind(Some("KEYRING")), SecretStoreKind::Keyring);
    }

    #[test]
    fn explicit_override_file_wins() {
        assert_eq!(resolve_kind(Some("file")), SecretStoreKind::File);
        assert_eq!(resolve_kind(Some("FILE")), SecretStoreKind::File);
    }

    #[test]
    fn unrecognised_override_falls_through_to_probe() {
        // We can't assert which kind the probe returns in CI (depends on
        // host capabilities) — just that the function returns SOMETHING
        // and doesn't panic. The override path is what we control.
        let _ = resolve_kind(Some("nonsense"));
        let _ = resolve_kind(None);
    }
}

//! Owner-only file write helper.
//!
//! Every persisted artifact that may contain secrets — profile files,
//! settings, machine key, audit-log entries, secret-store blobs — flows
//! through [`write_owner_only_atomic`]. The helper:
//!
//! 1. Writes to a sibling `<path>.tmp` first.
//! 2. On Unix, chmod 0600 (owner read+write only) the tmp file.
//! 3. On Windows, sets `FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM`
//!    on the tmp file. Windows file ACLs are inherited from the parent
//!    directory at creation time; user data directories on a standard
//!    install already restrict access to the owning user, so the
//!    additional hidden/system marker is the meaningful hardening we
//!    can do without taking a dependency on the heavier Win32 ACL APIs.
//! 4. Atomically renames the tmp file to the final path.
//!
//! Tests under `phase_69_perms` assert mode 0600 across every sensitive
//! write path (profile save, settings save, machine-key write, secret
//! store put).

use std::io;
use std::path::Path;

use crate::errors::CoreError;

/// Atomically write `bytes` to `path` with owner-only permissions.
///
/// The temp file lives next to the destination, gets its permissions
/// hardened before the rename so a partially-written file is never
/// world-readable for any window, and is renamed into place last.
pub fn write_owner_only_atomic(path: &Path, bytes: &[u8]) -> Result<(), CoreError> {
    let tmp = tmp_path(path);
    std::fs::write(&tmp, bytes).map_err(|e| CoreError::Internal {
        context: format!("write {:?}: {e}", path.display()),
    })?;
    if let Err(e) = harden_perms(&tmp) {
        // Clean up the partial tmp file so a later run doesn't keep
        // colliding on it.
        let _ = std::fs::remove_file(&tmp);
        return Err(e);
    }
    std::fs::rename(&tmp, path).map_err(|e| CoreError::Internal {
        context: format!("rename {:?}: {e}", path.display()),
    })
}

fn tmp_path(path: &Path) -> std::path::PathBuf {
    // Match the destination filename + `.tmp`. We don't use OsString
    // gymnastics because the file name is always under our control.
    let mut name = path
        .file_name()
        .map(|n| n.to_os_string())
        .unwrap_or_default();
    name.push(".tmp");
    path.with_file_name(name)
}

#[cfg(unix)]
fn harden_perms(path: &Path) -> Result<(), CoreError> {
    use std::os::unix::fs::PermissionsExt;
    let perms = std::fs::Permissions::from_mode(0o600);
    std::fs::set_permissions(path, perms).map_err(|e: io::Error| CoreError::Internal {
        context: format!("chmod 0600 {:?}: {e}", path.display()),
    })
}

#[cfg(windows)]
fn harden_perms(path: &Path) -> Result<(), CoreError> {
    use std::os::windows::ffi::OsStrExt;
    let metadata = std::fs::metadata(path).map_err(|e: io::Error| CoreError::Internal {
        context: format!("metadata {:?}: {e}", path.display()),
    })?;
    use std::os::windows::fs::MetadataExt;
    let mut attributes = metadata.file_attributes();
    const FILE_ATTRIBUTE_HIDDEN: u32 = 0x2;
    const FILE_ATTRIBUTE_SYSTEM: u32 = 0x4;
    attributes |= FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM;

    let wide_path: Vec<u16> = path.as_os_str().encode_wide().chain(Some(0)).collect();
    unsafe {
        if winapi::um::fileapi::SetFileAttributesW(wide_path.as_ptr(), attributes) == 0 {
            return Err(CoreError::Internal {
                context: format!("SetFileAttributesW {:?} failed", path.display()),
            });
        }
    }
    Ok(())
}

#[cfg(not(any(unix, windows)))]
fn harden_perms(_path: &Path) -> Result<(), CoreError> {
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[cfg(unix)]
    #[test]
    fn write_owner_only_creates_file_with_0600() {
        use std::os::unix::fs::PermissionsExt;
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("secret.bin");
        write_owner_only_atomic(&path, b"contents").unwrap();
        let perms = std::fs::metadata(&path).unwrap().permissions();
        assert_eq!(perms.mode() & 0o777, 0o600);
    }

    #[cfg(unix)]
    #[test]
    fn write_owner_only_overwrites_existing_file_keeping_0600() {
        use std::os::unix::fs::PermissionsExt;
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        // First write
        write_owner_only_atomic(&path, b"first").unwrap();
        // Pretend something widened the perms (simulating a backup tool
        // or restored-from-archive scenario) — our write must re-tighten.
        let widened = std::fs::Permissions::from_mode(0o644);
        std::fs::set_permissions(&path, widened).unwrap();
        write_owner_only_atomic(&path, b"second").unwrap();
        let perms = std::fs::metadata(&path).unwrap().permissions();
        assert_eq!(perms.mode() & 0o777, 0o600);
        assert_eq!(std::fs::read(&path).unwrap(), b"second");
    }

    #[test]
    fn write_owner_only_does_not_leave_tmp_files_on_success() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("entry");
        write_owner_only_atomic(&path, b"data").unwrap();
        let tmp = tmp_path(&path);
        assert!(!tmp.exists(), "tmp must be removed by rename");
        assert!(path.exists());
    }
}

//! SettingsManager — load/save the global `settings.json`.
//!
//! Forward-only architecture (post-rewrite): there is **no migration
//! path** from pre-rewrite settings files. Per-profile data (theme,
//! OBS, Discord, chat, OAuth, backend bind) lives in `ProfileSettings`,
//! not here, and is validated by `ProfileManager`. The global Settings
//! document only carries app-level knobs:
//!
//! * `start_minimized`
//! * `ffmpeg_path` — operator override consumed by `FFmpegLocator`
//! * `log_retention_days` — bounded `[1, 365]`
//! * `last_profile`
//! * `error_reporting_enabled` / `error_reporting_endpoint`
//!
//! Bound checks for fields that moved to `ProfileSettings`
//! (`backend.port`, `discord.cooldown_seconds`) run inside
//! `ProfileManager::save`, not here, because the fields travel with
//! the profile they belong to.

use std::path::PathBuf;
use std::sync::RwLock;

use crate::errors::{CoreError, ValidationIssue};
use crate::models::Settings;

/// Inclusive lower / upper bounds for `log_retention_days`. Below 1
/// disables rotation entirely (a safety footgun for audit-trail use
/// cases); above 365 invites disk-pressure incidents on
/// long-running installs.
pub const LOG_RETENTION_DAYS_MIN: u32 = 1;
pub const LOG_RETENTION_DAYS_MAX: u32 = 365;

/// Manages global settings persistence.
pub struct SettingsManager {
    settings_path: PathBuf,
    cache: RwLock<Option<Settings>>,
}

impl SettingsManager {
    pub fn new(app_data_dir: PathBuf) -> Self {
        let settings_path = app_data_dir.join("settings.json");
        Self {
            settings_path,
            cache: RwLock::new(None),
        }
    }

    /// Load settings from disk, returning `Settings::default()` if the
    /// file is missing. Out-of-range values on load are clamped to
    /// defaults (a startup hang would be worse than a reset).
    pub fn load(&self) -> Result<Settings, CoreError> {
        // Cache fast-path. Poison recovery: a previous writer panicked
        // mid-update — fall through to the disk read rather than trust
        // either the stale value or `Err`.
        match self.cache.read() {
            Ok(cache) => {
                if let Some(ref settings) = *cache {
                    return Ok(settings.clone());
                }
            }
            Err(_) => log::warn!("Settings cache RwLock poisoned on read; falling through to disk"),
        }

        let mut settings: Settings = if self.settings_path.exists() {
            let content =
                std::fs::read_to_string(&self.settings_path).map_err(|e| CoreError::Internal {
                    context: format!("Failed to read settings: {e}"),
                })?;
            // `#[serde(default)]` on every Settings field means a missing
            // key in the user's file gets the default value automatically.
            // No manual merge-missing pass needed.
            serde_json::from_str(&content).map_err(|e| CoreError::Internal {
                context: format!("Failed to parse settings: {e}"),
            })?
        } else {
            let defaults = Settings::default();
            self.save_internal(&defaults)?;
            defaults
        };

        if Self::validate_bounds(&settings).is_err() {
            log::warn!(
                "Persisted settings failed bounds check on load; clamping offending fields to defaults"
            );
            let defaults = Settings::default();
            if settings.log_retention_days < LOG_RETENTION_DAYS_MIN
                || settings.log_retention_days > LOG_RETENTION_DAYS_MAX
            {
                settings.log_retention_days = defaults.log_retention_days;
            }
            let _ = self.save_internal(&settings);
        }

        let mut cache = self.cache.write().unwrap_or_else(|e| e.into_inner());
        *cache = Some(settings.clone());

        Ok(settings)
    }

    /// Save settings to disk after enforcing bound checks. Out-of-range
    /// values produce a single `CoreError::ValidationFailed` carrying
    /// every offending field — callers get a complete list rather than
    /// peeling errors off one at a time.
    pub fn save(&self, settings: &Settings) -> Result<(), CoreError> {
        Self::validate_bounds(settings)?;
        self.save_internal(settings)?;
        let mut cache = self.cache.write().unwrap_or_else(|e| e.into_inner());
        *cache = Some(settings.clone());
        Ok(())
    }

    fn validate_bounds(settings: &Settings) -> Result<(), CoreError> {
        let mut issues = Vec::new();
        if settings.log_retention_days < LOG_RETENTION_DAYS_MIN
            || settings.log_retention_days > LOG_RETENTION_DAYS_MAX
        {
            issues.push(ValidationIssue {
                code: "log_retention_days_out_of_range".into(),
                message: format!(
                    "log_retention_days must be in [{LOG_RETENTION_DAYS_MIN}, {LOG_RETENTION_DAYS_MAX}], got {}",
                    settings.log_retention_days
                ),
                path: Some("/logRetentionDays".into()),
            });
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(CoreError::ValidationFailed { reasons: issues })
        }
    }

    fn save_internal(&self, settings: &Settings) -> Result<(), CoreError> {
        if let Some(parent) = self.settings_path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| CoreError::Internal {
                context: format!("Failed to create settings directory: {e}"),
            })?;
        }
        let content = serde_json::to_string_pretty(settings).map_err(|e| CoreError::Internal {
            context: format!("Failed to serialize settings: {e}"),
        })?;
        // settings.json may carry the operator API token in
        // some deployments, so always write owner-only.
        crate::services::write_owner_only_atomic(&self.settings_path, content.as_bytes())
    }

    pub fn get_profiles_path(&self) -> PathBuf {
        self.settings_path
            .parent()
            .map(|p| p.join("profiles"))
            .unwrap_or_else(|| PathBuf::from("profiles"))
    }

    /// Export settings + profiles to a directory, capped at 100 MiB.
    /// Refuses upfront if the source already exceeds the
    /// cap, and re-checks after each copy so a profiles dir with
    /// millions of files cannot drain the host disk via a runaway
    /// export.
    pub fn export_data(&self, export_path: &PathBuf) -> Result<(), CoreError> {
        const MAX_EXPORT_BYTES: u64 = 100 * 1024 * 1024;
        let mut total_bytes: u64 = 0;
        let too_large = |total: u64, more: u64| total.saturating_add(more) > MAX_EXPORT_BYTES;
        let oversize = || CoreError::Internal {
            context: format!("export exceeds {MAX_EXPORT_BYTES}-byte cap"),
        };

        std::fs::create_dir_all(export_path).map_err(|e| CoreError::Internal {
            context: format!("Failed to create export directory: {e}"),
        })?;

        if self.settings_path.exists() {
            let size = std::fs::metadata(&self.settings_path)
                .map_err(|e| CoreError::Internal {
                    context: e.to_string(),
                })?
                .len();
            if too_large(total_bytes, size) {
                return Err(oversize());
            }
            total_bytes += size;
            let dest = export_path.join("settings.json");
            std::fs::copy(&self.settings_path, &dest).map_err(|e| CoreError::Internal {
                context: format!("Failed to export settings: {e}"),
            })?;
        }

        let profiles_dir = self.get_profiles_path();
        if profiles_dir.exists() {
            let export_profiles_dir = export_path.join("profiles");
            std::fs::create_dir_all(&export_profiles_dir).map_err(|e| CoreError::Internal {
                context: format!("Failed to create profiles export directory: {e}"),
            })?;

            for entry in std::fs::read_dir(&profiles_dir)
                .map_err(|e| CoreError::Internal {
                    context: e.to_string(),
                })?
                .flatten()
            {
                let size = entry
                    .metadata()
                    .map_err(|e| CoreError::Internal {
                        context: e.to_string(),
                    })?
                    .len();
                if too_large(total_bytes, size) {
                    return Err(oversize());
                }
                total_bytes += size;
                let dest = export_profiles_dir.join(entry.file_name());
                std::fs::copy(entry.path(), dest).map_err(|e| CoreError::Internal {
                    context: format!("Failed to export profile: {e}"),
                })?;
            }
        }

        Ok(())
    }

    /// Clear settings + every profile from disk. Used by
    /// the destructive "reset app" flow gated behind a one-shot
    /// confirm token.
    pub fn clear_data(&self) -> Result<(), CoreError> {
        if self.settings_path.exists() {
            std::fs::remove_file(&self.settings_path).map_err(|e| CoreError::Internal {
                context: format!("Failed to remove settings: {e}"),
            })?;
        }
        let profiles_dir = self.get_profiles_path();
        if profiles_dir.exists() {
            std::fs::remove_dir_all(&profiles_dir).map_err(|e| CoreError::Internal {
                context: format!("Failed to remove profiles: {e}"),
            })?;
        }
        // Drop the cache so subsequent loads reread from a (now empty)
        // disk and write fresh defaults. A poisoned cache lock means a
        // stale entry could survive the wipe — surface it loudly rather
        // than silently leaking pre-clear settings into a `load()` call.
        match self.cache.write() {
            Ok(mut cache) => *cache = None,
            Err(e) => log::error!(
                "settings_manager cache write lock poisoned during clear_all_data — stale cache may survive: {e}"
            ),
        }
        Ok(())
    }
}

