    #[cfg(unix)]
    #[test]
    fn save_writes_settings_json_at_0600() {
        use std::os::unix::fs::PermissionsExt;
        let (mgr, _tmp) = manager();
        let s = mgr.load().expect("load defaults");
        mgr.save(&s).expect("save defaults");
        let perms = std::fs::metadata(&mgr.settings_path).unwrap().permissions();
        assert_eq!(
            perms.mode() & 0o777,
            0o600,
            "settings.json must be owner-only after save",
        );
    }

    #[test]
    fn load_clamps_out_of_range_persisted_value_to_default() {
        let tmp = TempDir::new().expect("tempdir");
        let mut bad = Settings::default();
        bad.log_retention_days = 9999;
        let json = serde_json::to_string(&bad).expect("serialize");
        std::fs::write(tmp.path().join("settings.json"), json).expect("seed file");

        let mgr = SettingsManager::new(tmp.path().to_path_buf());
        let loaded = mgr.load().expect("load with clamp");
        assert_eq!(
            loaded.log_retention_days,
            Settings::default().log_retention_days
        );
    }

    #[test]
    fn export_data_copies_settings_and_profiles_under_cap() {
        let (mgr, tmp) = manager();
        let s = mgr.load().expect("load defaults");
        mgr.save(&s).expect("save defaults");

        let profiles_dir = mgr.get_profiles_path();
        std::fs::create_dir_all(&profiles_dir).expect("profiles dir");
        std::fs::write(profiles_dir.join("p1.json"), b"{}").expect("seed profile");

        let export_dir = tmp.path().join("export");
        mgr.export_data(&export_dir).expect("export");

        assert!(export_dir.join("settings.json").exists());
        assert!(export_dir.join("profiles").join("p1.json").exists());
    }

    #[test]
    fn clear_data_removes_settings_and_profiles_and_drops_cache() {
        let (mgr, _tmp) = manager();
        let s = mgr.load().expect("load defaults");
        mgr.save(&s).expect("save defaults");
        let profiles_dir = mgr.get_profiles_path();
        std::fs::create_dir_all(&profiles_dir).expect("profiles dir");
        std::fs::write(profiles_dir.join("p1.json"), b"{}").expect("seed profile");

        mgr.clear_data().expect("clear");

        assert!(!mgr.settings_path.exists());
        assert!(!profiles_dir.exists());

        // A subsequent load rereads from the wiped disk and rewrites defaults.
        let reloaded = mgr.load().expect("reload after clear");
        assert_eq!(
            reloaded.log_retention_days,
            Settings::default().log_retention_days
        );
        assert!(mgr.settings_path.exists());
    }
}

//! Theme catalog — list themes and resolve token maps.
//!
//! Reads from bundled themes (`project_themes_dir`), the embedded fallback,
//! and the user's themes dir. No silent fallback chain in `get_theme_tokens`
//! — a broken user override is reported, not swallowed.

use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

use crate::errors::CoreError;
use crate::models::{ThemeFile, ThemeSummary};

use super::validation::load_theme_file;
use super::{
    theme_invalid, theme_not_found, ThemeManager, THEME_FILE_EXTENSIONS, THEME_TEMPLATE_NAME,
};

impl ThemeManager {
    pub fn list_themes(&self) -> Vec<ThemeSummary> {
        // Sync is now only done on app startup and when refresh_themes() is
        // called. Calling sync from here would deadlock with the file watcher.
        let mut themes = Vec::new();
        let mut seen_ids = HashSet::new();

        self.append_themes_from_dir(
            &self.project_themes_dir,
            "builtin",
            &mut themes,
            &mut seen_ids,
        );

        if themes.is_empty() {
            log::info!(
                "No themes found in project_themes_dir, using embedded theme list as fallback"
            );
            for summary in crate::services::embedded_themes::get_embedded_theme_list() {
                if !seen_ids.contains(&summary.id) {
                    seen_ids.insert(summary.id.clone());
                    themes.push(summary);
                }
            }
        }

        self.append_themes_from_dir(&self.themes_dir, "custom", &mut themes, &mut seen_ids);

        themes
    }

    pub fn get_theme_tokens(&self, theme_id: &str) -> Result<HashMap<String, String>, CoreError> {
        // Resolution order — no silent fallback chain.
        //
        // 1. **User override**: a file at `{themes_dir}/{theme_id}.jsonc`
        //    is the operator's claim about `theme_id`. If it loads
        //    cleanly, use it. If it loads broken, fail loud — silently
        //    reverting to the bundled copy would lie to the operator
        //    about whether their edits applied.
        // 2. **Bundled-embedded**: if the theme id matches a built-in,
        //    return the embedded tokens. This is the canonical source
        //    for bundled themes, not a fallback.
        // 3. **Filesystem bundled** (dev tree's `themes/` dir): only
        //    relevant in dev where embedded tokens may be stale; same
        //    fail-loud rule as the user dir.
        // 4. None of the above → `theme_not_found`.
        if let Some(theme) = self.find_theme_in_dir(theme_id, &self.themes_dir)? {
            log::info!(
                "get_theme_tokens('{theme_id}'): user override ({} tokens)",
                theme.tokens.len()
            );
            return Ok(theme.tokens);
        }
        if let Some(tokens) = crate::services::embedded_themes::get_embedded_theme_tokens(theme_id)
        {
            log::info!(
                "get_theme_tokens('{theme_id}'): bundled embedded ({} tokens)",
                tokens.len()
            );
            return Ok(tokens);
        }
        if let Some(theme) = self.find_theme_in_dir(theme_id, &self.project_themes_dir)? {
            log::info!(
                "get_theme_tokens('{theme_id}'): dev project_themes_dir ({} tokens)",
                theme.tokens.len()
            );
            return Ok(theme.tokens);
        }
        Err(theme_not_found(theme_id))
    }

    pub(super) fn append_themes_from_dir(
        &self,
        dir: &Path,
        source: &str,
        themes: &mut Vec<ThemeSummary>,
        seen_ids: &mut HashSet<String>,
    ) {
        if !dir.exists() {
            return;
        }

        for path in theme_paths_from_dir(dir) {
            if should_skip_theme_file(&path) {
                continue;
            }

            match load_theme_file(&path) {
                Ok(theme) => {
                    if seen_ids.contains(&theme.id) {
                        continue;
                    }
                    seen_ids.insert(theme.id.clone());
                    let built_in = crate::services::is_embedded_theme(&theme.id);
                    themes.push(ThemeSummary {
                        id: theme.id,
                        name: theme.name,
                        mode: theme.mode,
                        source: source.to_string(),
                        built_in,
                        valid: true,
                        error: None,
                    });
                }
                Err(error) => {
                    // Broken theme — surface it in the list with
                    // `valid: false` so the operator sees their file
                    // is malformed instead of it silently vanishing.
                    // ID is recovered from the filename stem (the
                    // installer's naming convention).
                    let stem = path
                        .file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or("unknown")
                        .to_string();
                    if seen_ids.contains(&stem) {
                        continue;
                    }
                    seen_ids.insert(stem.clone());
                    let err_msg = error.to_string();
                    let file_name = path
                        .file_name()
                        .and_then(|s| s.to_str())
                        .unwrap_or("unknown")
                        .to_string();
                    log::warn!("Invalid theme file {file_name:?}: {err_msg}");

                    // Audit-log entry so operators get a structured,
                    // queryable signal beyond the transient WARN line.
                    // Especially relevant for accessibility regressions
                    // (e.g. high-contrast theme missing tokens — silent
                    // fallback to default for low-vision users).
                    match self.audit_log.read() {
                        Ok(slot) => {
                            if let Some(audit) = slot.as_ref() {
                                if let Err(e) = audit.record(
                                    crate::services::AuditAction::ThemeValidationFailed {
                                        file_name: file_name.clone(),
                                        reason: err_msg.clone(),
                                    },
                                ) {
                                    log::error!(
                                        "theme_manager failed to append ThemeValidationFailed audit entry: {e}"
                                    );
                                }
                            }
                        }
                        Err(e) => log::error!(
                            "theme_manager audit_log read lock poisoned — ThemeValidationFailed audit entry dropped: {e}"
                        ),
                    }
                    themes.push(ThemeSummary {
                        id: stem.clone(),
                        name: stem,
                        mode: crate::models::ThemeMode::Dark,
                        source: source.to_string(),
                        built_in: false,
                        valid: false,
                        error: Some(err_msg),
                    });
                }
            }
        }
    }

    /// Find a theme in a directory.
    /// - `Ok(Some(theme))` — file found and parsed successfully.
    /// - `Ok(None)` — directory exists but no file claims `theme_id`.
    /// - `Err(CoreError)` — a file at the conventional path
    ///   `{dir}/{theme_id}.jsonc` (the install layout) exists but
    ///   failed to parse. Caller propagates rather than silently
    ///   falling through to the bundled copy, so the operator sees
    ///   their broken theme instead of a phantom revert.
    pub(super) fn find_theme_in_dir(
        &self,
        theme_id: &str,
        dir: &Path,
    ) -> Result<Option<ThemeFile>, CoreError> {
        if !dir.exists() {
            log::debug!("find_theme_in_dir: directory does not exist: {dir:?}");
            return Ok(None);
        }

        // Conventional path first: installed themes always land at
        // `{themes_dir}/{theme.id}.jsonc` (see `install_theme`). If a
        // file matches that path, it is the user's claim about
        // `theme_id` — load failures here are reported, not swallowed.
        for ext in ["jsonc", "json"] {
            let direct = dir.join(format!("{theme_id}.{ext}"));
            if direct.exists() && !should_skip_theme_file(&direct) {
                return match load_theme_file(&direct) {
                    Ok(theme) if theme.id == theme_id => {
                        log::info!("find_theme_in_dir: FOUND theme '{theme_id}' at {direct:?}");
                        Ok(Some(theme))
                    }
                    Ok(theme) => Err(theme_invalid(format!(
                        "Theme file {direct:?} declares id '{}', not '{theme_id}'",
                        theme.id
                    ))),
                    Err(e) => Err(theme_invalid(format!(
                        "Theme file {direct:?} failed to load: {e}"
                    ))),
                };
            }
        }

        // Fallback scan for non-conventionally-named files (older
        // installs, manually-placed themes). A parse error during the
        // scan stays a debug log — the file isn't claiming `theme_id`
        // by convention, so we can't know it was meant to match.
        let paths = theme_paths_from_dir(dir);
        for path in paths {
            if should_skip_theme_file(&path) {
                continue;
            }
            match load_theme_file(&path) {
                Ok(theme) if theme.id == theme_id => {
                    log::info!("find_theme_in_dir: FOUND theme '{theme_id}' at {path:?}");
                    return Ok(Some(theme));
                }
                Ok(_) => {}
                Err(e) => log::debug!("find_theme_in_dir: failed to load {path:?}: {e}"),
            }
        }

        log::debug!("find_theme_in_dir: theme '{theme_id}' NOT found in {dir:?}");
        Ok(None)
    }
}

pub(super) fn theme_paths_from_dir(dir: &Path) -> Vec<PathBuf> {
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(_) => return Vec::new(),
    };

    let mut paths: Vec<PathBuf> = entries.flatten().map(|entry| entry.path()).collect();
    paths.sort_by_key(|path| match path.extension().and_then(|s| s.to_str()) {
        Some("jsonc") => 0,
        Some("json") => 1,
        _ => 2,
    });

    paths
}

pub(super) fn should_skip_theme_file(path: &Path) -> bool {
    if !is_theme_file(path) {
        return true;
    }
    let fname = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
    fname == THEME_TEMPLATE_NAME || fname.contains(".deprecated")
}

fn is_theme_file(path: &Path) -> bool {
    match path.extension().and_then(|s| s.to_str()) {
        Some(ext) => THEME_FILE_EXTENSIONS.contains(&ext),
        None => false,
    }
}

#[cfg(test)]
mod tests {
    use super::super::validation::required_tokens;
    use super::*;
    use tempfile::TempDir;

    fn complete_theme_jsonc(id: &str, name: &str, mode: &str) -> String {
        let mut entries = String::new();
        for (i, key) in required_tokens().iter().enumerate() {
            if i > 0 {
                entries.push_str(",\n");
            }
            entries.push_str(&format!("    \"{key}\": \"#101010\""));
        }
        format!(
            "{{\n  \"id\": \"{id}\",\n  \"name\": \"{name}\",\n  \"mode\": \"{mode}\",\n  \"tokens\": {{\n{entries}\n  }}\n}}"
        )
    }

    fn manager(app: &TempDir, proj: &TempDir) -> ThemeManager {
        ThemeManager::new(app.path().to_path_buf(), proj.path().to_path_buf())
    }

    fn write_user_theme(app: &TempDir, id: &str, body: &str) {
        let path = app.path().join("themes").join(format!("{id}.jsonc"));
        fs::write(path, body).unwrap();
    }

    #[test]
    fn list_themes_falls_back_to_embedded_when_dirs_empty() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        let listed = mgr.list_themes();
        let embedded = crate::services::embedded_themes::get_embedded_theme_list();
        assert!(!listed.is_empty(), "embedded fallback populates the list");
        assert_eq!(listed.len(), embedded.len());
    }

    #[test]
    fn list_themes_includes_valid_user_theme_as_custom() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        write_user_theme(&app, "neon-rose", &complete_theme_jsonc("neon-rose", "Neon Rose", "dark"));

        let listed = mgr.list_themes();
        let entry = listed
            .iter()
            .find(|t| t.id == "neon-rose")
            .expect("user theme present");
        assert_eq!(entry.source, "custom");
        assert!(entry.valid);
        assert!(entry.error.is_none());
    }

    #[test]
    fn list_themes_surfaces_broken_user_theme_as_invalid() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        // Malformed: not even valid JSON.
        write_user_theme(&app, "broken", "{ this is not json ");

        let listed = mgr.list_themes();
        let entry = listed
            .iter()
            .find(|t| t.id == "broken")
            .expect("broken theme still listed");
        assert!(!entry.valid, "broken theme flagged invalid");
        assert!(entry.error.is_some(), "broken theme carries an error message");
    }

    #[test]
    fn get_theme_tokens_user_override_returns_its_tokens() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        write_user_theme(&app, "custom-x", &complete_theme_jsonc("custom-x", "Custom X", "light"));

        let tokens = mgr.get_theme_tokens("custom-x").expect("override resolves");
        assert!(!tokens.is_empty());
        assert!(tokens.keys().any(|k| k.starts_with("--")));
    }

    #[test]
    fn get_theme_tokens_resolves_embedded_builtin() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        let first = crate::services::embedded_themes::get_embedded_theme_list()
            .into_iter()
            .next()
            .expect("at least one embedded theme");
        let tokens = mgr
            .get_theme_tokens(&first.id)
            .expect("embedded builtin resolves");
        assert!(!tokens.is_empty(), "embedded theme yields tokens");
    }

    #[test]
    fn get_theme_tokens_unknown_id_errors() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        let err = mgr.get_theme_tokens("no-such-theme-xyz").unwrap_err();
        match err {
            CoreError::ValidationFailed { reasons } => {
                assert!(reasons.iter().any(|r| r.code == "theme_not_found"));
            }
            other => panic!("expected ValidationFailed/theme_not_found, got {other:?}"),
        }
    }

    #[test]
    fn get_theme_tokens_broken_user_override_fails_loud() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        // A file at the conventional path that fails to parse must error,
        // not silently fall through to the embedded copy.
        write_user_theme(&app, "darkpurple", "{ broken json ");
        let err = mgr.get_theme_tokens("darkpurple").unwrap_err();
        assert!(
            matches!(err, CoreError::ValidationFailed { .. }),
            "broken override should fail loud, got {err:?}"
        );
    }

    #[test]
    fn find_theme_in_dir_missing_directory_is_none() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        let missing = app.path().join("does-not-exist");
        let found = mgr.find_theme_in_dir("anything", &missing).unwrap();
        assert!(found.is_none());
    }

    #[test]
    fn find_theme_in_dir_id_mismatch_errors() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);
        // File named claimed-id.jsonc but declaring a different inner id.
        write_user_theme(
            &app,
            "claimed-id",
            &complete_theme_jsonc("actual-id", "Mismatch", "dark"),
        );
        let dir = app.path().join("themes");
        let err = mgr.find_theme_in_dir("claimed-id", &dir).unwrap_err();
        assert!(matches!(err, CoreError::ValidationFailed { .. }), "got {err:?}");
    }

    #[test]
    fn should_skip_theme_file_filters_template_and_non_themes() {
        let base = Path::new("/themes");
        assert!(should_skip_theme_file(&base.join(THEME_TEMPLATE_NAME)));
        assert!(should_skip_theme_file(&base.join("old.deprecated.jsonc")));
        assert!(should_skip_theme_file(&base.join("notes.txt")));
        assert!(should_skip_theme_file(&base.join("README")));
        assert!(!should_skip_theme_file(&base.join("good.jsonc")));
        assert!(!should_skip_theme_file(&base.join("good.json")));
    }

    #[test]
    fn theme_paths_from_dir_orders_jsonc_before_json() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join("b.json"), "{}").unwrap();
        fs::write(dir.path().join("a.jsonc"), "{}").unwrap();
        fs::write(dir.path().join("c.txt"), "x").unwrap();
        let paths = theme_paths_from_dir(dir.path());
        let exts: Vec<&str> = paths
            .iter()
            .filter_map(|p| p.extension().and_then(|s| s.to_str()))
            .collect();
        // jsonc sorts first, then json, then everything else.
        assert_eq!(exts.first(), Some(&"jsonc"));
        let json_pos = exts.iter().position(|e| *e == "json");
        let txt_pos = exts.iter().position(|e| *e == "txt");
        assert!(json_pos < txt_pos, "json must precede non-theme extensions");
    }

    #[test]
    fn theme_paths_from_dir_missing_directory_is_empty() {
        let paths = theme_paths_from_dir(Path::new("/no/such/dir/spiritstream-test"));
        assert!(paths.is_empty());
    }

    /// Regression guard for the trailing-comma bug: every shipped theme
    /// file (authored as JSONC with trailing commas) must load through the
    /// real filesystem path. Before the `jsonc::sanitize_jsonc` fix, all of
    /// these failed `serde_json` parsing and the embedded fallback was empty.
    #[test]
    fn every_shipped_theme_file_parses() {
        let manifest = env!("CARGO_MANIFEST_DIR");
        let themes_dir = std::path::Path::new(manifest).join("../../themes");
        let mut loaded = 0;
        for entry in std::fs::read_dir(&themes_dir).expect("themes dir exists") {
            let path = entry.unwrap().path();
            if path.extension().and_then(|e| e.to_str()) != Some("jsonc") {
                continue;
            }
            if should_skip_theme_file(&path) {
                continue;
            }
            load_theme_file(&path)
                .unwrap_or_else(|e| panic!("shipped theme {path:?} must load: {e:?}"));
            loaded += 1;
        }
        assert!(loaded > 0, "expected at least one shipped theme to load");
    }

    /// The embedded accessibility fallback must be non-empty — this is the
    /// defense-in-depth path the threat model relies on for low-vision users
    /// when the filesystem theme copies are unreachable.
    #[test]
    fn embedded_theme_fallback_is_populated() {
        let list = crate::services::embedded_themes::get_embedded_theme_list();
        assert!(
            !list.is_empty(),
            "embedded theme fallback must not be empty"
        );
        assert!(
            list.iter().any(|t| t.id == "high-contrast-dark"),
            "WCAG-AAA high-contrast theme must be embedded"
        );
    }
}

//! Theme install + sync helpers.
//!
//! `install_theme` lands a single user-supplied JSONC at the
//! conventional `{themes_dir}/{theme.id}.jsonc` path and emits a
//! `ThemeSummary` for the UI. `sync_project_themes` copies the
//! bundled themes from `project_themes_dir` into the user dir on
//! startup; both paths recorded in `recently_synced` so the
//! watcher loop knows to ignore its own writes.

use std::fs;
use std::path::Path;

use crate::errors::CoreError;
use crate::models::ThemeSummary;

use super::catalog::should_skip_theme_file;
use super::validation::{apply_token_fallbacks, parse_theme, validate_theme};
use super::{ThemeManager, THEME_INSTALL_EXTENSION};

impl ThemeManager {
    /// Syncs built-in/project themes to the appdata themes directory,
    /// skipping `theme-template.jsonc`.
    ///
    /// In production: Uses Tauri's resource_dir to access bundled themes.
    /// In development: Falls back to `../themes` relative path.
    pub fn sync_project_themes(&self) {
        log::info!(
            "Syncing themes from {:?} to {:?}",
            self.project_themes_dir,
            self.themes_dir
        );

        match fs::read_dir(&self.project_themes_dir) {
            Ok(entries) => {
                let mut copied = 0;
                for entry in entries.flatten() {
                    let path = entry.path();
                    if should_skip_theme_file(&path) {
                        continue;
                    }
                    let fname = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                    let dest_path = self.themes_dir.join(fname);
                    match fs::copy(&path, &dest_path) {
                        Ok(_) => {
                            log::info!("Synced theme {fname:?} to appdata");
                            copied += 1;
                            // Tell the watcher loop to ignore the inotify /
                            // FSEvent the OS will deliver for this just-written
                            // file. Without this, the watcher fires a spurious
                            // `themes_updated` event on every boot.
                            if let Ok(mut map) = self.recently_synced.lock() {
                                map.insert(dest_path.clone(), std::time::Instant::now());
                            }
                        }
                        Err(e) => {
                            log::error!("Failed to sync theme {fname:?} to appdata: {e}");
                        }
                    }
                }
                log::info!("Theme sync complete: {copied} theme(s) copied");
            }
            Err(e) => {
                log::error!(
                    "Failed to read project themes directory {:?}: {e}",
                    self.project_themes_dir
                );
            }
        }
    }

    pub fn install_theme(&self, source_path: &Path) -> Result<ThemeSummary, CoreError> {
        let content = fs::read_to_string(source_path).map_err(|e| CoreError::Internal {
            context: format!("Failed to read theme file: {e}"),
        })?;
        let mut theme = parse_theme(&content)?;
        apply_token_fallbacks(&mut theme.tokens);

        validate_theme(&theme)?;

        fs::create_dir_all(&self.themes_dir).map_err(|e| CoreError::Internal {
            context: format!("Failed to create themes directory: {e}"),
        })?;

        let dest_path = self
            .themes_dir
            .join(format!("{}.{}", theme.id, THEME_INSTALL_EXTENSION));
        // I6: route theme install through the atomic writer so the
        // file lands at 0600 (Unix) and a crash mid-install never
        // leaves a partial theme file behind. The themes directory is
        // user-owned but the file is a JSON document the user wrote
        // — same secret-handling pedigree as profile/settings writes.
        crate::services::write_owner_only_atomic(&dest_path, content.as_bytes())?;

        let built_in = crate::services::is_embedded_theme(&theme.id);
        Ok(ThemeSummary {
            id: theme.id,
            name: theme.name,
            mode: theme.mode,
            source: "custom".to_string(),
            built_in,
            valid: true,
            error: None,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::super::validation::required_tokens;
    use super::super::THEME_TEMPLATE_NAME;
    use super::*;
    use tempfile::TempDir;

    /// Build a theme JSONC that satisfies every required token so the
    /// validator accepts it. Each token gets a placeholder colour; the
    /// install path only cares the set is complete and non-empty.
    fn valid_theme_jsonc(id: &str, name: &str, mode: &str) -> String {
        let mut entries = String::new();
        for (i, key) in required_tokens().iter().enumerate() {
            if i > 0 {
                entries.push_str(",\n");
            }
            entries.push_str(&format!("    \"{key}\": \"#101010\""));
        }
        format!(
            "{{\n  \"id\": \"{id}\",\n  \"name\": \"{name}\",\n  \"mode\": \"{mode}\",\n  \"tokens\": {{\n{entries}\n  }}\n}}"
        )
    }

    fn manager(app: &TempDir, proj: &TempDir) -> ThemeManager {
        ThemeManager::new(app.path().to_path_buf(), proj.path().to_path_buf())
    }

    #[test]
    fn install_theme_lands_file_and_returns_summary() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        let src = app.path().join("incoming.jsonc");
        fs::write(&src, valid_theme_jsonc("my-theme", "My Theme", "dark")).unwrap();

        let summary = mgr.install_theme(&src).expect("a complete theme installs");
        assert_eq!(summary.id, "my-theme");
        assert_eq!(summary.name, "My Theme");
        assert_eq!(summary.source, "custom");
        assert!(!summary.built_in, "a user theme id is not embedded");

        let dest = app.path().join("themes").join("my-theme.jsonc");
        assert!(dest.exists(), "installed file missing at {dest:?}");
    }

    /// I6: install routes through the atomic owner-only writer, so the
    /// theme file must land at 0600 on Unix.
    #[cfg(unix)]
    #[test]
    fn install_theme_writes_owner_only_permissions() {
        use std::os::unix::fs::PermissionsExt;
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        let src = app.path().join("incoming.jsonc");
        fs::write(&src, valid_theme_jsonc("perm-theme", "Perm", "light")).unwrap();
        mgr.install_theme(&src).unwrap();

        let dest = app.path().join("themes").join("perm-theme.jsonc");
        let mode = fs::metadata(&dest).unwrap().permissions().mode();
        assert_eq!(mode & 0o777, 0o600, "theme file must be owner-only");
    }

    #[test]
    fn install_theme_rejects_incomplete_token_set() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        // Only one token — the validator requires the full set.
        let src = app.path().join("incoming.jsonc");
        fs::write(
            &src,
            r##"{ "id": "bad", "name": "Bad", "mode": "dark", "tokens": { "--bg-base": "#000" } }"##,
        )
        .unwrap();

        let err = mgr.install_theme(&src).unwrap_err();
        assert!(
            matches!(err, CoreError::ValidationFailed { .. }),
            "expected ValidationFailed, got {err:?}",
        );
        assert!(
            !app.path().join("themes").join("bad.jsonc").exists(),
            "a rejected theme must not be written to disk",
        );
    }

    #[test]
    fn install_theme_surfaces_unreadable_source() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();
        let mgr = manager(&app, &proj);

        let missing = app.path().join("does-not-exist.jsonc");
        let err = mgr.install_theme(&missing).unwrap_err();
        assert!(
            matches!(err, CoreError::Internal { .. }),
            "expected Internal read error, got {err:?}",
        );
    }

    #[test]
    fn sync_copies_real_files_skips_template_and_records_paths() {
        let app = TempDir::new().unwrap();
        let proj = TempDir::new().unwrap();

        fs::write(
            proj.path().join("spirit-dark.jsonc"),
            valid_theme_jsonc("spirit-dark", "Spirit Dark", "dark"),
        )
        .unwrap();
        // The template is a placeholder and must never reach the user dir.
        fs::write(proj.path().join(THEME_TEMPLATE_NAME), "{}").unwrap();

        let mgr = manager(&app, &proj);
        mgr.sync_project_themes();

        let themes_dir = app.path().join("themes");
        let dest = themes_dir.join("spirit-dark.jsonc");
        assert!(
            dest.exists(),
            "bundled theme should be copied to the user dir"
        );
        assert!(
            !themes_dir.join(THEME_TEMPLATE_NAME).exists(),
            "theme-template.jsonc must be skipped",
        );

        // The copied path is recorded so the watcher ignores its own write.
        let synced = mgr.recently_synced.lock().unwrap();
        assert!(
            synced.contains_key(&dest),
            "sync must record the dest path for watcher self-fire suppression",
        );
    }
}

//! Theme manager — list, install, hot-reload, and validate themes.
//!
//! Submodules (each is one or more `impl ThemeManager` blocks):
//! - [`catalog`] — list themes from bundled + user dirs, token resolution.
//! - [`install`] — install user theme files; sync bundled themes to user dir.
//! - [`watch`] — filesystem watcher that emits `themes_updated` events.
//! - [`validation`] — theme-file parse, token-set requirements, JSONC depth cap.

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use std::sync::{Arc, OnceLock};
use std::time::Duration;

use regex::Regex;

use crate::errors::{CoreError, ValidationIssue};

mod catalog;
mod install;
mod validation;
mod watch;

// ---------------------------------------------------------------------------
// Constants shared across submodules.
// ---------------------------------------------------------------------------

pub(super) const THEME_FILE_EXTENSIONS: [&str; 2] = ["json", "jsonc"];
pub(super) const THEME_INSTALL_EXTENSION: &str = "jsonc";
/// JSONC nesting depth cap. `serde_json` itself enforces 128, so this is
/// defense-in-depth tuned to the actual shape of theme files (flat token
/// maps, depth ≤ 3 in practice).
pub(super) const MAX_THEME_JSONC_DEPTH: u32 = 32;
pub(super) const THEME_ID_PATTERN: &str = r"^[a-z0-9][a-z0-9-_]{0,63}$";
pub(super) const THEME_TEMPLATE_NAME: &str = "theme-template.jsonc";
pub(super) const TOKENS_CSS: &str = include_str!("../../../styles/tokens.css");

pub(super) static REQUIRED_TOKENS: OnceLock<Vec<String>> = OnceLock::new();
pub(super) static THEME_ID_REGEX: OnceLock<Regex> = OnceLock::new();

/// How long after a `sync_project_themes` write we ignore matching
/// watcher events. Tuned for the OS file-event latency floor on macOS
/// FSEvents (~250ms) and Linux inotify (~immediate); 2s is a comfortable
/// upper bound that doesn't masquerade as a real user edit.
pub(super) const WATCHER_SELF_FIRE_GRACE: Duration = Duration::from_secs(2);

// ---------------------------------------------------------------------------
// Shared error constructors.
// ---------------------------------------------------------------------------

pub(super) fn theme_invalid(message: impl Into<String>) -> CoreError {
    CoreError::ValidationFailed {
        reasons: vec![ValidationIssue {
            code: "invalid_theme".into(),
            message: message.into(),
            path: None,
        }],
    }
}

pub(super) fn theme_not_found(theme_id: &str) -> CoreError {
    CoreError::ValidationFailed {
        reasons: vec![ValidationIssue {
            code: "theme_not_found".into(),
            message: format!("Theme '{theme_id}' not found"),
            path: Some("/themeId".into()),
        }],
    }
}

// ---------------------------------------------------------------------------
// ThemeManager — public surface.
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct ThemeManager {
    pub(super) themes_dir: PathBuf,
    pub(super) project_themes_dir: PathBuf,
    /// Audit-log handle for `ThemeValidationFailed` entries. Wired by
    /// `crates/core/src/registry.rs` post-construction via
    /// `set_audit_log`; before that wiring runs (e.g. early-startup
    /// scans during initialization) validation failures still log
    /// WARN but do not audit. Optional rather than required to avoid
    /// a cyclic Arc dependency between AuditLogService and ThemeManager
    /// at construction time.
    pub(super) audit_log: Arc<std::sync::RwLock<Option<Arc<crate::services::AuditLogService>>>>,
    /// Paths the manager just wrote via `sync_project_themes`. The
    /// `notify` watcher fires on its own writes too, which used to
    /// trigger a re-scan + spurious `themes_updated` event on every
    /// boot. This map suppresses watcher events whose path is present
    /// within a short grace window after the write.
    pub(super) recently_synced: Arc<std::sync::Mutex<HashMap<PathBuf, std::time::Instant>>>,
}

impl ThemeManager {
    pub fn new(app_data_dir: PathBuf, project_themes_dir: PathBuf) -> Self {
        let themes_dir = app_data_dir.join("themes");
        if let Err(e) = fs::create_dir_all(&themes_dir) {
            log::warn!("Failed to create themes directory: {e}");
        }
        let absolute_project_themes = if project_themes_dir.is_absolute() {
            project_themes_dir
        } else {
            std::env::current_dir()
                .ok()
                .map(|dir| dir.join(&project_themes_dir))
                .unwrap_or(project_themes_dir)
        };

        log::info!(
            "ThemeManager: project_themes_dir={:?} (exists={})",
            absolute_project_themes,
            absolute_project_themes.exists()
        );
        log::info!("ThemeManager: user themes_dir={themes_dir:?}");

        Self {
            themes_dir,
            project_themes_dir: absolute_project_themes,
            audit_log: Arc::new(std::sync::RwLock::new(None)),
            recently_synced: Arc::new(std::sync::Mutex::new(HashMap::new())),
        }
    }

    /// Wire the audit-log handle post-construction. Called by
    /// `crates/core/src/registry.rs` after both services exist;
    /// `set_audit_log` is idempotent (a second call replaces the
    /// stored handle). Before this runs, validation failures still
    /// WARN but do not audit.
    pub fn set_audit_log(&self, audit: Arc<crate::services::AuditLogService>) {
        match self.audit_log.write() {
            Ok(mut slot) => *slot = Some(audit),
            Err(e) => {
                log::error!("theme_manager audit_log write lock poisoned during set_audit_log: {e}")
            }
        }
    }
}

//! Theme parsing, token-set requirements, and the JSONC depth cap.
//!
//! Parse + validate are split from the catalog/install entry points
//! so they can be unit-tested in isolation and audited as a unit. The
//! brace-depth scanner and JSONC comment stripper are also exposed
//! here as free functions; both are stateless and CPU-only.

use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::Path;

use regex::Regex;

use crate::errors::CoreError;
use crate::models::ThemeFile;

use super::{
    theme_invalid, MAX_THEME_JSONC_DEPTH, REQUIRED_TOKENS, THEME_ID_PATTERN, THEME_ID_REGEX,
    TOKENS_CSS,
};

impl super::ThemeManager {}

pub(super) fn load_theme_file(path: &Path) -> Result<ThemeFile, CoreError> {
    let content = fs::read_to_string(path).map_err(|e| CoreError::Internal {
        context: format!("Failed to read theme: {e}"),
    })?;
    let mut theme = parse_theme(&content)?;
    apply_token_fallbacks(&mut theme.tokens);
    validate_theme(&theme)?;
    Ok(theme)
}

pub(super) fn parse_theme(content: &str) -> Result<ThemeFile, CoreError> {
    let no_comments = crate::services::jsonc::strip_jsonc_comments(content);
    // Reject inputs whose nesting depth exceeds the policy cap before
    // handing them to `serde_json`. Themes are flat token maps (depth
    // 1-3 in practice). `serde_json` itself bounds recursion at 128, so
    // this is defense-in-depth that catches stack-blow attempts well
    // before the parser does. Depth-check on the comment-stripped form so
    // braces inside comments never inflate the count.
    if let Some(depth) = max_brace_depth_or_overflow(&no_comments, MAX_THEME_JSONC_DEPTH) {
        return Err(theme_invalid(format!(
            "Theme JSONC nesting depth {depth} exceeds limit {MAX_THEME_JSONC_DEPTH}"
        )));
    }
    // Themes are authored as JSONC with trailing commas; serde_json rejects
    // them, so strip before parsing. Without this every shipped theme fails
    // to load — including the WCAG-AAA high-contrast variants.
    let sanitized = crate::services::jsonc::strip_trailing_commas(&no_comments);
    serde_json::from_str(&sanitized).map_err(|e| theme_invalid(format!("Invalid theme JSON: {e}")))
}

pub(super) fn apply_token_fallbacks(tokens: &mut HashMap<String, String>) {
    if !tokens.contains_key("--border-subtle") {
        if let Some(border_muted) = tokens.get("--border-muted").cloned() {
            tokens.insert("--border-subtle".to_string(), border_muted);
        }
    }
}

pub(super) fn validate_theme(theme: &ThemeFile) -> Result<(), CoreError> {
    if theme.id.trim().is_empty() {
        return Err(theme_invalid("Theme id is required"));
    }
    if theme.name.trim().is_empty() {
        return Err(theme_invalid("Theme name is required"));
    }

    let id_regex = THEME_ID_REGEX.get_or_init(|| Regex::new(THEME_ID_PATTERN).unwrap());
    if !id_regex.is_match(&theme.id) {
        return Err(theme_invalid(
            "Theme id must be lowercase alphanumeric with dashes or underscores",
        ));
    }

    if theme.tokens.is_empty() {
        return Err(theme_invalid("Theme tokens cannot be empty"));
    }

    let required = required_tokens();
    let mode_label = theme.mode.as_str();
    validate_token_set(mode_label, &theme.tokens, required)?;

    Ok(())
}

fn validate_token_set(
    label: &str,
    tokens: &HashMap<String, String>,
    required: &[String],
) -> Result<(), CoreError> {
    let missing: Vec<&String> = required
        .iter()
        .filter(|key| !tokens.contains_key(*key))
        .collect();
    if !missing.is_empty() {
        let preview = missing
            .iter()
            .take(5)
            .map(|k| (*k).as_str())
            .collect::<Vec<_>>();
        let remaining = missing.len().saturating_sub(preview.len());
        let suffix = if remaining > 0 {
            format!(" (and {remaining} more)")
        } else {
            "".to_string()
        };

        return Err(theme_invalid(format!(
            "Missing {label} tokens: {}{suffix}",
            preview.join(", ")
        )));
    }

    for (key, value) in tokens {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            return Err(theme_invalid(format!(
                "Invalid {label} token '{key}': value cannot be empty"
            )));
        }
        if trimmed.contains("REPLACE_ME") {
            return Err(theme_invalid(format!(
                "Invalid {label} token '{key}': replace REPLACE_ME placeholders"
            )));
        }
        if trimmed.contains("</style>") || trimmed.contains("<script") {
            return Err(theme_invalid(format!(
                "Invalid {label} token '{key}': value contains dangerous content"
            )));
        }
    }

    Ok(())
}

pub(super) fn required_tokens() -> &'static Vec<String> {
    REQUIRED_TOKENS.get_or_init(|| {
        let token_regex = Regex::new(r"--[A-Za-z0-9_-]+").unwrap();
        let mut tokens = HashSet::new();

        for cap in token_regex.captures_iter(TOKENS_CSS) {
            if let Some(matched) = cap.get(0) {
                let token = matched.as_str();

                // Skip optional tokens that themes can customize or omit:
                // color scales (violet-*, fuchsia-*, etc.) and typography
                // variants (font-*, letter-spacing-*, line-height-*).
                let is_optional = token.starts_with("--violet-")
                    || token.starts_with("--fuchsia-")
                    || token.starts_with("--pink-")
                    || token.starts_with("--neutral-")
                    || token.starts_with("--purple-")
                    || token.starts_with("--cyan-")
                    || token.starts_with("--green-")
                    || token.starts_with("--orange-")
                    || token.starts_with("--red-")
                    || token.starts_with("--yellow-")
                    || token.starts_with("--font-")
                    || token.starts_with("--letter-spacing-")
                    || token.starts_with("--line-height-");

                if !is_optional {
                    tokens.insert(token.to_string());
                }
            }
        }

        let mut tokens: Vec<String> = tokens.into_iter().collect();
        tokens.sort();
        tokens
    })
}

/// Scan `input` and return the maximum brace/bracket nesting depth, or
/// `None` if depth never exceeds `limit`. String literals are skipped so
/// `{` inside a string doesn't count. Used to reject stack-blow attempts
/// before they reach `serde_json`.
pub(super) fn max_brace_depth_or_overflow(input: &str, limit: u32) -> Option<u32> {
    let mut depth: u32 = 0;
    let mut max_seen: u32 = 0;
    let mut in_string = false;
    let mut escape = false;
    for byte in input.bytes() {
        if in_string {
            if escape {
                escape = false;
            } else if byte == b'\\' {
                escape = true;
            } else if byte == b'"' {
                in_string = false;
            }
            continue;
        }
        match byte {
            b'"' => in_string = true,
            b'{' | b'[' => {
                depth = depth.saturating_add(1);
                if depth > max_seen {
                    max_seen = depth;
                }
                if depth > limit {
                    return Some(depth);
                }
            }
            b'}' | b']' => {
                depth = depth.saturating_sub(1);
            }
            _ => {}
        }
    }
    None
}

#[cfg(test)]
mod phase_6_10_tests {
