//! Pluggable secret storage contract.
//!
//! Two concrete impls ship. Exactly one is selected at
//! startup by `build_secret_store(...)` and held as `Arc<dyn SecretStore>`
//! for the process lifetime — there is no runtime fallback chain:
//! - `KeyringSecretStore` via `keyring-rs` (macOS Keychain, Windows
//!   Credential Manager, Linux Secret Service).
//! - `EncryptedFileSecretStore` wrapping the AES-256-GCM-SIV +
//!   Argon2id machine-key approach (Docker, headless Linux without
//!   D-Bus, other environments that cannot host an OS keyring).
//!
//! The trait lives in core so service code can be written against the
//! abstraction; the selection logic lives in the secret_store module.

use async_trait::async_trait;

use crate::CoreError;

#[async_trait]
pub trait SecretStore: Send + Sync {
    /// Returns the stored secret bytes, or `Ok(None)` if absent.
    async fn get(&self, namespace: &str, key: &str) -> Result<Option<Vec<u8>>, CoreError>;

    /// Stores `value`, overwriting any prior entry.
    async fn put(&self, namespace: &str, key: &str, value: &[u8]) -> Result<(), CoreError>;

    /// Removes the entry. No-op if absent.
    async fn delete(&self, namespace: &str, key: &str) -> Result<(), CoreError>;

    /// Zeroizes in-memory caches without touching persistent storage.
    /// Invoked by `SafetyService::panic`.
    async fn purge_caches(&self) {}
}

//! Transport adapter contract.
//!
//! `HttpTransport`, `CliTransport`, and the future
//! `VeilidTransport` all implement this trait. Each takes
//! the same `ServiceRegistry`-shaped object built from core services and
//! exposes the same operations via its own protocol.
//!
//! Concrete `ServiceRegistry` lands when service constructors are unified.
//! Until then, transports continue to wire services
//! the way `server/src/main.rs` does today.

use std::sync::Arc;

use async_trait::async_trait;

use crate::CoreError;

#[async_trait]
pub trait Transport: Send + Sync + 'static {
    /// Run the transport until it terminates or is shut down. Implementations
    /// are responsible for binding ports / opening pipes / etc.
    async fn serve(self: Arc<Self>) -> Result<(), CoreError>;

    /// Signal the transport to begin a graceful shutdown. Should return
    /// immediately; `serve` should observe the signal and exit.
    async fn shutdown(&self);
}

//! `spiritstream-cli audit …` — read the local HMAC-chained audit log.

use clap::Subcommand;

use crate::error::CliError;
use crate::output::Output;
use spiritstream_core::ServiceRegistry;

#[derive(Debug, Subcommand)]
pub enum AuditCmd {
    /// Print recent audit entries as NDJSON.
    Log {
        /// Earliest entry to include (ISO 8601 timestamp). Entries
        /// with a `timestamp` strictly older are dropped from the output.
        #[arg(long)]
        since: Option<String>,
        /// Only emit entries whose `action.kind` matches this string.
        #[arg(long)]
        filter: Option<String>,
        /// Only emit entries whose `action.platform` matches this string.
        /// Combine with `--filter ChatPlatformConnected` to reconstruct
        /// connect history for a specific platform — e.g. operators
        /// auditing whether Facebook was ever enabled run
        /// `audit log --filter ChatPlatformConnected --platform facebook`.
        #[arg(long)]
        platform: Option<String>,
        /// Maximum entries to print (most-recent first). Default 200.
        #[arg(long, default_value_t = 200)]
        limit: usize,
    },
}

pub async fn run(
    cmd: AuditCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        AuditCmd::Log {
            since,
            filter,
            platform,
            limit,
        } => {
            let entries = registry.audit.entries()?;
            let since_ts = since
                .as_deref()
                .map(chrono::DateTime::parse_from_rfc3339)
                .transpose()
                .map_err(|e| CliError::Io(format!("invalid --since timestamp: {e}")))?
                .map(|dt| dt.with_timezone(&chrono::Utc));
            let filtered: Vec<_> = entries
                .into_iter()
                .rev()
                .filter(|e| {
                    if let Some(ts) = since_ts {
                        if e.timestamp < ts {
                            return false;
                        }
                    }
                    let action_json = serde_json::to_value(&e.action).ok();
                    if let Some(ref f) = filter {
                        let kind = action_json
                            .as_ref()
                            .and_then(|v| v.get("kind").and_then(|k| k.as_str()).map(String::from))
                            .unwrap_or_default();
                        if kind != *f {
                            return false;
                        }
                    }
                    if let Some(ref p) = platform {
                        let entry_platform = action_json
                            .as_ref()
                            .and_then(|v| {
                                v.get("platform").and_then(|x| x.as_str()).map(String::from)
                            })
                            .unwrap_or_default();
                        if entry_platform != *p {
                            return false;
                        }
                    }
                    true
                })
                .take(limit)
                .collect();
            out.emit(&filtered)?;
            Ok(())
        }
    }
}

//! `spiritstream-cli chat …` — chat platform connections.

use clap::Subcommand;
use spiritstream_core::models::{
    ChatConfig, ChatCredentials, ChatPlatform, ChatSendResult, TwitchAuth, YouTubeAuth,
};
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

fn parse_platform(raw: &str) -> Result<ChatPlatform, CliError> {
    // The model derives `Deserialize` with `rename_all = "lowercase"` (plus a
    // dedicated `tiktok` rename) — round-trip through serde so the CLI accepts
    // exactly the same wire values the HTTP surface does.
    serde_json::from_value(serde_json::json!(raw))
        .map_err(|e| CliError::Argument(format!("unknown chat platform '{raw}': {e}")))
}

/// Translate per-platform CLI flags into a `ChatConfig`. The HTTP equivalent
/// (`v1_chat_connect_proxy`) also performs OAuth-refresh enrichment from the
/// active profile; the CLI path keeps credentials explicit — the user
/// supplies `--oauth` themselves or runs `oauth refresh` separately. This
/// keeps each transport's path narrow and uniformly typed.
fn build_connect_config(
    platform: ChatPlatform,
    channel: Option<String>,
    channel_id: Option<String>,
    oauth: Option<String>,
    api_key: Option<String>,
    session_token: Option<String>,
    use_api_key: bool,
) -> Result<ChatConfig, CliError> {
    let credentials = match platform {
        ChatPlatform::Twitch => {
            let channel = channel.ok_or_else(|| {
                CliError::Argument("twitch connect requires --channel".into())
            })?;
            let auth = oauth.map(|access_token| TwitchAuth::AppOAuth {
                access_token,
                refresh_token: None,
                expires_at: None,
            });
            ChatCredentials::Twitch { channel, auth }
        }
        ChatPlatform::YouTube => {
            let channel_id = channel_id.ok_or_else(|| {
                CliError::Argument("youtube connect requires --channel-id".into())
            })?;
            let auth = if use_api_key {
                let key = api_key.ok_or_else(|| {
                    CliError::Argument("--use-api-key requires --api-key".into())
                })?;
                YouTubeAuth::ApiKey { key }
            } else {
                let access_token = oauth.ok_or_else(|| {
                    CliError::Argument(
                        "youtube connect requires --oauth (or pass --use-api-key with --api-key)"
                            .into(),
                    )
                })?;
                YouTubeAuth::AppOAuth {
                    access_token,
                    refresh_token: None,
                    expires_at: None,
                }
            };
            ChatCredentials::YouTube { channel_id, auth }
        }
        ChatPlatform::Trovo => {
            let channel_id = channel_id.or(channel).ok_or_else(|| {
                CliError::Argument("trovo connect requires --channel-id".into())
            })?;
            ChatCredentials::Trovo { channel_id }
        }
        ChatPlatform::TikTok => {
            let username = channel.ok_or_else(|| {
                CliError::Argument("tiktok connect requires --channel (username)".into())
            })?;
            ChatCredentials::TikTok {
                username,
                session_token,
            }
        }
        ChatPlatform::Kick | ChatPlatform::Facebook => {
            return Err(CliError::Argument(format!(
                "{} chat is not yet implemented",
                platform.as_str()
            )));
        }
    };
    Ok(ChatConfig {
        platform,
        enabled: true,
        credentials,
    })
}

#[derive(Debug, Subcommand)]
pub enum ChatCmd {
    /// Per-platform chat connection status.
    Status,
    /// Send a chat message to every enabled platform (the same set
    /// `ChatService::profile_chat_settings` exposes — `*_send_enabled`
    /// flags decide where it goes). The per-platform char limit lives
    /// in core (`ChatPlatform::max_message_chars`) and applies here too.
    Send { message: String },
    /// Connect to a chat platform. Credentials are sourced from explicit
    /// flags rather than the active profile so the CLI works without
    /// loading a profile first; for OAuth-bearing platforms, supply the
    /// access token via `--oauth`.
    Connect {
        /// Platform (twitch / youtube / trovo / tiktok).
        platform: String,
        /// Twitch channel name, Trovo channel ID, etc.
        #[arg(long)]
        channel: Option<String>,
        /// YouTube channel ID (`UC…` or `@handle`).
        #[arg(long)]
        channel_id: Option<String>,
        /// OAuth access token for Twitch / YouTube AppOAuth.
        #[arg(long)]
        oauth: Option<String>,
        /// YouTube API key (for `--use-api-key` mode).
        #[arg(long)]
        api_key: Option<String>,
        /// TikTok session cookie / token.
        #[arg(long)]
        session_token: Option<String>,
        /// Use the YouTube API-key auth path instead of OAuth.
        #[arg(long)]
        use_api_key: bool,
    },
    /// Reconnect a chat platform. Same credential shape as `connect` —
    /// `retry` first disconnects (silently if not connected) and then
    /// connects. Matches the HTTP `POST /chat/connections/:platform/retry`
    /// endpoint's effective behaviour.
    Retry {
        platform: String,
        #[arg(long)]
        channel: Option<String>,
        #[arg(long)]
        channel_id: Option<String>,
        #[arg(long)]
        oauth: Option<String>,
        #[arg(long)]
        api_key: Option<String>,
        #[arg(long)]
        session_token: Option<String>,
        #[arg(long)]
        use_api_key: bool,
    },
    /// Disconnect a specific platform (twitch / youtube / trovo / kick /
    /// facebook / tiktok).
    Disconnect { platform: String },
    /// Disconnect every connected chat platform.
    DisconnectAll,
    /// Print whether any chat platform is connected (boolean).
    Connected,
    /// Print the current chat log session start timestamp (or `null`).
    LogStatus,
    /// Print the status for a single platform. (`PlatformStatus`
    /// avoids the clap-derived `status1` slug the auto-numbered name
    /// produced — the original `Status1` came from the second `Status`
    /// variant being silently renumbered, surfaced as a confusing CLI
    /// command name to operators.)
    PlatformStatus { platform: String },
    /// Export the current chat log session to a file.
    ExportLog { path: std::path::PathBuf },
    /// Search the current chat log session.
    Search {
        query: String,
        #[arg(long)]
        limit: Option<usize>,
    },
}

pub async fn run(
    cmd: ChatCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        ChatCmd::Status => {
            let status = registry.chat.get_status().await;
            out.emit(&status)?;
            Ok(())
        }
        ChatCmd::Send { message } => {
            let trimmed = message.trim().to_string();
            if trimmed.is_empty() {
                return Err(CliError::Argument("message cannot be empty".into()));
            }

            // CLI is stateless per-invocation — registry.chat's cached
            // chat_settings + pii cache are empty on cold start. Load
            // the active profile from disk and derive both targets and
            // PII policy from one read.
            let global = registry.settings.load().ok();
            let active_name = global.as_ref().and_then(|s| s.last_profile.clone());
            let active_profile = match active_name.as_ref() {
                Some(name) => registry.profiles.load(name, None).await.ok(),
                None => None,
            };

            let chat_cfg = active_profile
                .as_ref()
                .map(|p| p.settings.chat.clone())
                .unwrap_or_default();
            let mut targets = Vec::new();
            if chat_cfg.twitch_send_enabled {
                targets.push(ChatPlatform::Twitch);
            }
            if chat_cfg.youtube_send_enabled && !chat_cfg.youtube_use_api_key {
                targets.push(ChatPlatform::YouTube);
            }
            if chat_cfg.trovo_send_enabled {
                targets.push(ChatPlatform::Trovo);
            }

            if targets.is_empty() {
                return Err(CliError::Argument(
                    "no chat platforms are enabled for sending in the active profile".into(),
                ));
            }

            let pii_policy = active_profile
                .as_ref()
                .map(|p| (p.pii_blocklist.clone(), p.pii_fuzzy));

            let results = registry
                .chat
                .send_message(trimmed, &targets, pii_policy, &registry.safety)
                .await;
            let out_results: Vec<ChatSendResult> = results
                .into_iter()
                .map(|(platform, result)| match result {
                    Ok(()) => ChatSendResult {
                        platform,
                        success: true,
                        error: None,
                        error_code: None,
                    },
                    Err(err) => ChatSendResult {
                        platform,
                        success: false,
                        error: Some(err.to_string()),
                        error_code: Some(err.kind().to_string()),
                    },
                })
                .collect();
            out.emit(&out_results)?;
            Ok(())
        }
        ChatCmd::Connect {
            platform,
            channel,
            channel_id,
            oauth,
            api_key,
            session_token,
            use_api_key,
        } => {
            let p = parse_platform(&platform)?;
            let config = build_connect_config(
                p,
                channel,
                channel_id,
                oauth,
                api_key,
                session_token,
                use_api_key,
            )?;
            registry.chat.connect(config).await?;
            out.emit(&serde_json::json!({ "platform": p, "connected": true }))?;
            Ok(())
        }
        ChatCmd::Retry {
            platform,
            channel,
            channel_id,
            oauth,
            api_key,
            session_token,
            use_api_key,
        } => {
            let p = parse_platform(&platform)?;
            // Disconnect first; "not connected" is acceptable for retry.
            if let Err(err) = registry.chat.disconnect(p).await {
                if err.kind() != "chat_platform_not_connected" {
                    return Err(err.into());
                }
            }
            let config = build_connect_config(
                p,
                channel,
                channel_id,
                oauth,
                api_key,
                session_token,
                use_api_key,
            )?;
            registry.chat.connect(config).await?;
            out.emit(&serde_json::json!({ "platform": p, "reconnected": true }))?;
            Ok(())
        }
        ChatCmd::Disconnect { platform } => {
            let p = parse_platform(&platform)?;
            registry.chat.disconnect(p).await?;
            out.emit(&serde_json::json!({ "platform": p, "disconnected": true }))?;
            Ok(())
        }
        ChatCmd::DisconnectAll => {
            registry.chat.disconnect_all("user_requested").await?;
            out.emit(&serde_json::json!({ "disconnectedAll": true }))?;
            Ok(())
        }
        ChatCmd::Connected => {
            let connected = registry.chat.is_any_connected().await;
            out.emit(&serde_json::json!({ "connected": connected }))?;
            Ok(())
        }
        ChatCmd::LogStatus => {
            let start_ms = registry.chat.log_session_start_ms();
            out.emit(&serde_json::json!({
                "active": start_ms.is_some(),
                "startedAt": start_ms,
            }))?;
            Ok(())
        }
        ChatCmd::PlatformStatus { platform } => {
            let p = parse_platform(&platform)?;
            let status = registry.chat.get_platform_status(p).await;
            out.emit(&status)?;
            Ok(())
        }
        ChatCmd::ExportLog { path } => {
            // Replicates `POST /api/v1/chat/log/export`: flush, then read every
            // chatlog_<hour>.jsonl line whose timestamp lies in the active
            // session window, write to `<path>`.
            use chrono::{Local, TimeZone};
            use spiritstream_core::models::ChatMessage;
            use std::fs::File;
            use std::io::{BufRead, BufReader, BufWriter, Write};

            let start_ms = registry
                .chat
                .log_session_start_ms()
                .ok_or_else(|| CliError::Argument("no active chat session to export".into()))?;
            registry.chat.flush_chat_logs().await?;
            let end_ms = Local::now().timestamp_millis();
            let start_dt = Local
                .timestamp_millis_opt(start_ms)
                .single()
                .unwrap_or_else(Local::now);
            let end_dt = Local
                .timestamp_millis_opt(end_ms)
                .single()
                .unwrap_or_else(Local::now);

            // Reuse the same hour-key builder the HTTP path uses.
            let mut keys: Vec<String> = Vec::new();
            let mut cursor = start_dt;
            while cursor <= end_dt {
                keys.push(cursor.format("%Y-%m-%d_%H").to_string());
                cursor += chrono::Duration::hours(1);
            }

            let mut writer = BufWriter::new(
                File::create(&path)
                    .map_err(|e| CliError::Io(format!("create {}: {e}", path.display())))?,
            );
            for key in keys {
                let src = registry.log_dir.join(format!("chatlog_{}.jsonl", key));
                if !src.exists() {
                    continue;
                }
                let f = File::open(&src)
                    .map_err(|e| CliError::Io(format!("read {}: {e}", src.display())))?;
                for line in BufReader::new(f).lines() {
                    let line = line.map_err(|e| CliError::Io(format!("read chat log: {e}")))?;
                    if line.trim().is_empty() {
                        continue;
                    }
                    if let Ok(m) = serde_json::from_str::<ChatMessage>(&line) {
                        if m.timestamp >= start_ms && m.timestamp <= end_ms {
                            writer
                                .write_all(line.as_bytes())
                                .map_err(|e| CliError::Io(format!("write export: {e}")))?;
                            writer
                                .write_all(b"\n")
                                .map_err(|e| CliError::Io(format!("write export: {e}")))?;
                        }
                    }
                }
            }
            writer
                .flush()
                .map_err(|e| CliError::Io(format!("flush export: {e}")))?;
            out.emit(&serde_json::json!({ "exported": true, "path": path }))?;
            Ok(())
        }
        ChatCmd::Search { query, limit } => {
            use chrono::{Local, TimeZone};
            use spiritstream_core::models::ChatMessage;
            use std::fs::File;
            use std::io::{BufRead, BufReader};

            let limit = limit.unwrap_or(500);
            let start_ms = registry
                .chat
                .log_session_start_ms()
                .ok_or_else(|| CliError::Argument("no active chat session to search".into()))?;
            let q = query.trim().to_lowercase();
            if q.is_empty() {
                out.emit(&Vec::<ChatMessage>::new())?;
                return Ok(());
            }
            let end_ms = Local::now().timestamp_millis();
            let start_dt = Local
                .timestamp_millis_opt(start_ms)
                .single()
                .unwrap_or_else(Local::now);
            let end_dt = Local
                .timestamp_millis_opt(end_ms)
                .single()
                .unwrap_or_else(Local::now);
            let mut keys: Vec<String> = Vec::new();
            let mut cursor = start_dt;
            while cursor <= end_dt {
                keys.push(cursor.format("%Y-%m-%d_%H").to_string());
                cursor += chrono::Duration::hours(1);
            }
            let mut matches: Vec<ChatMessage> = Vec::new();
            for key in keys {
                if matches.len() >= limit {
                    break;
                }
                let src = registry.log_dir.join(format!("chatlog_{}.jsonl", key));
                if !src.exists() {
                    continue;
                }
                let f = File::open(&src)
                    .map_err(|e| CliError::Io(format!("read {}: {e}", src.display())))?;
                for line in BufReader::new(f).lines() {
                    if matches.len() >= limit {
                        break;
                    }
                    let line = line.map_err(|e| CliError::Io(format!("read chat log: {e}")))?;
                    if line.trim().is_empty() {
                        continue;
                    }
                    let m = match serde_json::from_str::<ChatMessage>(&line) {
                        Ok(m) => m,
                        Err(_) => continue,
                    };
                    if m.timestamp < start_ms || m.timestamp > end_ms {
                        continue;
                    }
                    if m.username.to_lowercase().contains(&q)
                        || m.message.to_lowercase().contains(&q)
                    {
                        matches.push(m);
                    }
                }
            }
            out.emit(&matches)?;
            Ok(())
        }
    }
}

//! `spiritstream-cli confirm-token …` — one-shot confirmation tokens
//! for destructive operations.
//!
//! Three intents currently gate destructive endpoints / CLI flows:
//! `clear_data`, `rotate_machine_key`, `revoke_all_sessions`. Issuing
//! a token via the CLI lets scripted/automation flows perform the
//! destructive action without an interactive UI step — same token is
//! consumed by the HTTP transport (Q6: registry-shared service so the
//! CLI and HTTP see the same ConfirmTokenService instance).

use clap::Subcommand;
use serde::Serialize;

use crate::error::CliError;
use crate::output::Output;
use spiritstream_core::ServiceRegistry;

#[derive(Debug, Subcommand)]
pub enum ConfirmTokenCmd {
    /// Issue a fresh one-shot token scoped to `--intent`. Token TTL is
    /// 30 seconds — re-issue if your script takes longer than that.
    Issue {
        /// Intent the token authorises. Must match the destructive op
        /// (e.g. `rotate_machine_key`, `clear_data`,
        /// `revoke_all_sessions`, `enable_facebook_chat`). Tokens
        /// issued for one intent are rejected when presented for
        /// another.
        #[arg(long)]
        intent: String,
    },
}

#[derive(Serialize)]
struct IssueResponse {
    intent: String,
    token: String,
    ttl_secs: u64,
}

pub async fn run(
    cmd: ConfirmTokenCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        ConfirmTokenCmd::Issue { intent } => {
            let token = registry.confirm_tokens.issue(&intent);
            out.emit(&IssueResponse {
                intent,
                token,
                ttl_secs: registry.confirm_tokens.ttl().as_secs(),
            })?;
            Ok(())
        }
    }
}

//! `spiritstream-cli data …` — data lifecycle commands.

use clap::Subcommand;
use serde::Serialize;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum DataCmd {
    /// Export profiles, settings, and logs to a directory at `<path>`.
    Export {
        /// Destination directory. Must live inside the user's home or data dir.
        path: std::path::PathBuf,
    },
    /// **Destructive.** Delete every profile and reset settings to defaults.
    Clear {
        /// Confirm the wipe. Refused without `--yes`.
        #[arg(long)]
        yes: bool,
    },
    /// Rotate the machine encryption key. Re-encrypts every encrypted profile.
    RotateMachineKey {
        /// Confirm the rotation. Refused without `--yes` — recovery requires
        /// the old key file if anything goes wrong mid-rotation.
        #[arg(long)]
        yes: bool,
        /// Password for an encrypted (`.mgs`) profile, repeatable as
        /// `--password NAME=PASSWORD`. Required once per encrypted profile;
        /// rotation refuses to start if any are missing.
        #[arg(long, value_name = "NAME=PASSWORD")]
        password: Vec<String>,
    },
}

#[derive(Serialize)]
struct ExportResponse {
    path: std::path::PathBuf,
    exported: bool,
}

#[derive(Serialize)]
struct ClearResponse {
    cleared: bool,
}

pub async fn run(
    cmd: DataCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        DataCmd::Export { path } => {
            registry.settings.export_data(&path)?;
            out.emit(&ExportResponse {
                path,
                exported: true,
            })?;
            Ok(())
        }
        DataCmd::Clear { yes } => {
            if !yes {
                return Err(CliError::Argument(
                    "data clear is destructive — pass --yes to confirm".into(),
                ));
            }
            registry.settings.clear_data()?;
            out.emit(&ClearResponse { cleared: true })?;
            Ok(())
        }
        DataCmd::RotateMachineKey { yes, password } => {
            if !yes {
                return Err(CliError::Argument(
                    "rotate-machine-key changes encryption — pass --yes to confirm".into(),
                ));
            }
            let mut passwords: std::collections::HashMap<String, String> =
                std::collections::HashMap::new();
            for entry in password {
                let (name, pw) = entry.split_once('=').ok_or_else(|| {
                    CliError::Argument(
                        "--password expects NAME=PASSWORD per encrypted profile".into(),
                    )
                })?;
                passwords.insert(name.to_string(), pw.to_string());
            }
            let data_dir = registry.data_dir.clone();
            let profiles_dir = data_dir.join("profiles");
            let report = spiritstream_core::services::Encryption::rotate_machine_key(
                &data_dir,
                &profiles_dir,
                &passwords,
            )?;
            // G2: record the rotation in the HMAC chain so the audit
            // log can answer "when did this machine key change?" later.
            let _ = registry
                .audit
                .record(spiritstream_core::services::AuditAction::MachineKeyRotated {
                    profiles_updated: report.profiles_updated,
                    keys_reencrypted: report.keys_reencrypted,
                });
            out.emit(&report)?;
            Ok(())
        }
    }
}

//! `spiritstream-cli discord …` — Discord webhook integration.

use clap::Subcommand;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum DiscordCmd {
    /// Send a test message to a Discord webhook URL.
    TestWebhook { url: String },
    /// Send the go-live notification using `--profile <name>`'s saved
    /// Discord settings. Loads the named profile (decrypting with
    /// `--password` if encrypted), reads `settings.discord`, and calls
    /// the same `send_go_live_notification` the HTTP route invokes.
    Send {
        #[arg(long)]
        profile: String,
        #[arg(long)]
        password: Option<String>,
    },
    /// Reset the cooldown timer so the next send fires immediately.
    ResetCooldown,
}

pub async fn run(
    cmd: DiscordCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        DiscordCmd::TestWebhook { url } => {
            let result = registry.discord.test_webhook(&url).await;
            out.emit(&result)?;
            Ok(())
        }
        DiscordCmd::Send { profile, password } => {
            let profile_obj = registry
                .profiles
                .load_with_key_decryption(&profile, password.as_deref())
                .await?;
            let discord = &profile_obj.settings.discord;
            if !discord.webhook_enabled {
                out.emit(&serde_json::json!({
                    "success": false,
                    "message": "Discord webhook is not enabled",
                    "skippedCooldown": false,
                }))?;
                return Ok(());
            }
            let image_path = if discord.image_path.is_empty() {
                None
            } else {
                Some(discord.image_path.as_str())
            };
            let result = registry
                .discord
                .send_go_live_notification(
                    &discord.webhook_url,
                    &discord.go_live_message,
                    image_path,
                    discord.cooldown_enabled,
                    discord.cooldown_seconds,
                )
                .await;
            out.emit(&result)?;
            Ok(())
        }
        DiscordCmd::ResetCooldown => {
            registry.discord.reset_cooldown().await;
            out.emit(&serde_json::json!({ "reset": true }))?;
            Ok(())
        }
    }
}

//! `spiritstream-cli events watch` — stream service events to stdout as JSON
//! Lines (NDJSON), one JSON object per line.
//!
//! Subscribes via a stdout `EventSink` that the registry already holds. The
//! command blocks until the user interrupts (Ctrl+C). For tests, `--for-ms`
//! exits after a fixed duration so the suite stays deterministic.
//!
//! Only events whose `event` field starts with one of the `--filter`
//! prefixes are emitted; the default is no filter (every event).

use std::sync::Arc;
use std::time::Duration;

use clap::Subcommand;
use serde_json::Value;
use spiritstream_core::traits::EventSink;
use spiritstream_core::{ServiceRegistry, ServiceRegistryOptions};

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum EventsCmd {
    /// Block and print events as NDJSON until interrupted (or `--for-ms`
    /// elapses).
    Watch {
        /// Prefix filter. Comma-separated or repeated:
        ///   `--filter stream_stats,chat_message`
        ///   `--filter stream_stats --filter chat_message`
        #[arg(long = "filter", value_delimiter = ',')]
        filter: Vec<String>,
        /// Exit after this many milliseconds (test plumbing). Defaults to
        /// blocking forever.
        #[arg(long = "for-ms")]
        for_ms: Option<u64>,
    },
}

pub async fn run(
    cmd: EventsCmd,
    _registry: &ServiceRegistry,
    _out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        EventsCmd::Watch { filter, for_ms } => watch(filter, for_ms).await,
    }
}

async fn watch(filters: Vec<String>, for_ms: Option<u64>) -> Result<(), CliError> {
    // Build a *new* registry that wires a `StdoutEventSink` instead of
    // `NoopEventSink`. The outer `cli.data_dir` resolution already happened
    // (the registry passed in here uses Noop) — we just rebuild against the
    // same paths.
    let data_dir = dirs_next::data_local_dir()
        .map(|d| d.join("spiritstream"))
        .ok_or_else(|| CliError::Io("could not resolve data directory".into()))?;
    let log_dir = data_dir.join("logs");
    let themes_dir = data_dir.join("themes");
    let events: Arc<dyn EventSink> = Arc::new(StdoutEventSink::new(filters));
    let override_kind = std::env::var("SPIRITSTREAM_SECRET_STORE").ok();
    let secret_store =
        spiritstream_core::services::build_secret_store(&data_dir, override_kind.as_deref());
    let _registry = spiritstream_core::ServiceRegistry::build(ServiceRegistryOptions {
        data_dir,
        themes_dir,
        log_dir,
        custom_ffmpeg_path: None,
        events,
        secret_store,
    })
    .map_err(CliError::from)?;

    // Sit and let background tasks (theme watcher, etc.) emit. The
    // StdoutEventSink does its own stdout writes; we don't loop here on a
    // channel because the EventSink trait doesn't expose subscription.
    match for_ms {
        Some(ms) => tokio::time::sleep(Duration::from_millis(ms)).await,
        None => {
            let _ = tokio::signal::ctrl_c().await;
        }
    }
    // Suppress the standard one-document stdout emit — every event is a
    // separate line.
    Ok(())
}

/// `EventSink` that writes each event as a single NDJSON line to stdout.
struct StdoutEventSink {
    filters: Vec<String>,
}

impl StdoutEventSink {
    fn new(filters: Vec<String>) -> Self {
        Self { filters }
    }

    fn passes_filter(&self, event: &str) -> bool {
        self.filters.is_empty() || self.filters.iter().any(|f| event.starts_with(f))
    }
}

impl EventSink for StdoutEventSink {
    fn emit(&self, event: &str, payload: Value) {
        if !self.passes_filter(event) {
            return;
        }
        let line = serde_json::json!({ "event": event, "payload": payload });
        if let Ok(s) = serde_json::to_string(&line) {
            println!("{s}");
        }
    }
}

//! `spiritstream-cli files …` — file-browser primitives.
//!
//! Mirrors the HTTP `/api/v1/files/*` surface used by the frontend file
//! picker. The path-validation rules live in core
//! (`spiritstream_core::services::validate_path_within_any`); both CLI and
//! HTTP enforce the same allow-list (app data dir + user home).

use clap::Subcommand;
use serde::Serialize;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum FilesCmd {
    /// Browse a directory. Omitting `--path` returns the home directory.
    Browse {
        #[arg(long)]
        path: Option<std::path::PathBuf>,
    },
    /// Print the user's home directory path.
    Home,
}

#[derive(Serialize)]
struct FileEntry {
    name: String,
    #[serde(rename = "type")]
    kind: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    size: Option<u64>,
}

#[derive(Serialize)]
struct BrowseResponse {
    path: std::path::PathBuf,
    entries: Vec<FileEntry>,
    #[serde(skip_serializing_if = "Option::is_none")]
    parent: Option<std::path::PathBuf>,
}

pub async fn run(
    cmd: FilesCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    let home = dirs::home_dir();

    match cmd {
        FilesCmd::Home => {
            let path =
                home.ok_or_else(|| CliError::Argument("home directory not resolvable".into()))?;
            out.emit(&serde_json::json!({ "path": path }))?;
            Ok(())
        }
        FilesCmd::Browse { path } => {
            let target = match path {
                Some(p) => p,
                None => home.clone().ok_or_else(|| {
                    CliError::Argument("no --path and home dir not resolvable".into())
                })?,
            };

            // Enforce the same allow-list the HTTP layer uses: data dir + home.
            let mut allowed: Vec<&std::path::Path> = vec![registry.data_dir.as_path()];
            if let Some(ref h) = home {
                allowed.push(h.as_path());
            }
            spiritstream_core::services::validate_path_within_any(&target, &allowed)?;

            let read = std::fs::read_dir(&target)
                .map_err(|e| CliError::Io(format!("read_dir {}: {e}", target.display())))?;

            let mut entries = Vec::new();
            for r in read {
                let entry = r.map_err(|e| CliError::Io(format!("dir entry: {e}")))?;
                let meta = entry
                    .metadata()
                    .map_err(|e| CliError::Io(format!("metadata: {e}")))?;
                let kind = if meta.is_dir() { "directory" } else { "file" };
                let size = if meta.is_file() {
                    Some(meta.len())
                } else {
                    None
                };
                entries.push(FileEntry {
                    name: entry.file_name().to_string_lossy().to_string(),
                    kind,
                    size,
                });
            }
            entries.sort_by(|a, b| a.kind.cmp(b.kind).then_with(|| a.name.cmp(&b.name)));

            let parent = target.parent().map(|p| p.to_path_buf());
            out.emit(&BrowseResponse {
                path: target,
                entries,
                parent,
            })?;
            Ok(())
        }
    }
}

