//! `spiritstream-cli oauth …` — OAuth 2.0 flows for chat platforms.

use clap::Subcommand;
use serde::Serialize;

use crate::error::CliError;
use crate::output::Output;
use spiritstream_core::ServiceRegistry;

#[derive(Debug, Subcommand)]
pub enum OAuthCmd {
    /// Begin an OAuth flow for `<provider>` (e.g. `twitch`, `youtube`).
    /// Returns the auth URL the user must open in their browser, plus the
    /// callback port the server is listening on. The CLI is a thin wrapper
    /// around `OAuthService::start_flow` — it does NOT launch a browser
    /// itself (CLI users handle that side however they like).
    Start { provider: String },
    /// Complete the OAuth flow by exchanging the redirect `<code>` + state
    /// for tokens.
    Complete {
        provider: String,
        code: String,
        #[arg(long)]
        state: String,
    },
    /// Revoke and forget a stored OAuth token for `<provider>`.
    Disconnect { provider: String },
    /// Report whether `<provider>` is configured (always true with embedded client IDs).
    IsConfigured { provider: String },
    /// Refresh an access token using the supplied refresh token.
    Refresh {
        provider: String,
        refresh_token: String,
    },
    /// Revoke the token AND forget the account locally. The CLI doesn't
    /// have an active-profile session to read the stored token from, so
    /// the caller supplies it via `--token`.
    Forget {
        provider: String,
        #[arg(long)]
        token: String,
    },
    /// Read or write the user-provided OAuth client credentials. The
    /// embedded client IDs always work; this command is for operators
    /// who want to point SpiritStream at their own Twitch / YouTube
    /// OAuth applications instead of the bundled ones.
    Config {
        #[command(subcommand)]
        action: ConfigCmd,
    },
    /// Show the stored OAuth account info (logged_in, user_id, username,
    /// display_name) for `<provider>` on `--profile <name>`. Mirrors
    /// `GET /api/v1/oauth/{provider}/account`; the CLI takes `--profile`
    /// explicitly because there is no cross-invocation active-profile
    /// concept.
    Account {
        provider: String,
        #[arg(long)]
        profile: String,
        #[arg(long)]
        password: Option<String>,
    },
}

#[derive(Debug, Subcommand)]
pub enum ConfigCmd {
    /// Print the current OAuth config as JSON. Secrets are included
    /// when set (CLI users handle their own redaction).
    Get,
    /// Replace the OAuth config. Pass the full JSON via `--json` or
    /// individual fields via `--twitch-client-id`, etc. Fields not
    /// provided clear (set to `None`) — mirrors the HTTP PUT semantics.
    Set(Box<ConfigSetArgs>),
}

#[derive(Debug, clap::Args)]
pub struct ConfigSetArgs {
    /// Full JSON payload (overrides individual flags if both given).
    #[arg(long)]
    pub json: Option<String>,
    #[arg(long)]
    pub twitch_client_id: Option<String>,
    #[arg(long)]
    pub twitch_client_secret: Option<String>,
    #[arg(long)]
    pub youtube_client_id: Option<String>,
    #[arg(long)]
    pub youtube_client_secret: Option<String>,
    #[arg(long)]
    pub kick_client_id: Option<String>,
    #[arg(long)]
    pub kick_client_secret: Option<String>,
    #[arg(long)]
    pub facebook_client_id: Option<String>,
    #[arg(long)]
    pub facebook_client_secret: Option<String>,
}

#[derive(Serialize)]
struct StartResponse {
    auth_url: String,
    callback_port: u16,
    state: String,
}

#[derive(Serialize)]
struct CompleteResponse {
    provider: String,
    user_id: String,
    username: String,
    display_name: String,
}

pub async fn run(
    cmd: OAuthCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        OAuthCmd::Start { provider } => {
            let result = registry.oauth.start_flow(&provider).await?;
            out.emit(&StartResponse {
                auth_url: result.auth_url,
                callback_port: result.callback_port,
                state: result.state,
            })?;
            Ok(())
        }
        OAuthCmd::Complete {
            provider,
            code,
            state,
        } => {
            let result = registry
                .oauth
                .complete_flow(&provider, &code, &state)
                .await?;
            out.emit(&CompleteResponse {
                provider: result.user_info.provider,
                user_id: result.user_info.user_id,
                username: result.user_info.username,
                display_name: result.user_info.display_name,
            })?;
            Ok(())
        }
        OAuthCmd::Disconnect { provider } => {
            // Without an active-profile session the CLI can't reach the
            // stored token; this is a no-op acknowledgement matching the
            // HTTP layer's "session disconnect" path (which just clears the
            // session-side tokens — the profile-saved token survives).
            let _ = registry;
            #[derive(Serialize)]
            struct Resp {
                provider: String,
                disconnected: bool,
            }
            out.emit(&Resp {
                provider,
                disconnected: true,
            })?;
            Ok(())
        }
        OAuthCmd::IsConfigured { provider } => {
            let configured = registry.oauth.is_configured(&provider).await;
            out.emit(&serde_json::json!({ "provider": provider, "configured": configured }))?;
            Ok(())
        }
        OAuthCmd::Refresh {
            provider,
            refresh_token,
        } => {
            let tokens = registry
                .oauth
                .refresh_token(&provider, &refresh_token)
                .await?;
            out.emit(&tokens)?;
            Ok(())
        }
        OAuthCmd::Forget { provider, token } => {
            // Revoke the supplied token (best effort) then report success.
            // No stored-token clear from CLI — the CLI has no session state.
            if let Err(e) = registry.oauth.revoke_token(&provider, &token).await {
                log::warn!("revoke {provider} token failed: {e}");
            }
            out.emit(&serde_json::json!({ "provider": provider, "forgotten": true }))?;
            Ok(())
        }
        OAuthCmd::Account {
            provider,
            profile,
            password,
        } => {
            let profile_obj = registry
                .profiles
                .load_with_key_decryption(&profile, password.as_deref())
                .await?;
            let account = match provider.as_str() {
                "twitch" => &profile_obj.settings.oauth.twitch,
                "youtube" => &profile_obj.settings.oauth.youtube,
                other => {
                    return Err(CliError::Argument(format!(
                        "unknown oauth provider: {other} (expected twitch|youtube)"
                    )));
                }
            };
            let logged_in = !account.user_id.is_empty();
            out.emit(&spiritstream_core::models::OAuthAccountStatus {
                logged_in,
                user_id: account.user_id.clone(),
                username: account.username.clone(),
                display_name: account.display_name.clone(),
            })?;
            Ok(())
        }
        OAuthCmd::Config { action } => match action {
            ConfigCmd::Get => {
                let config = registry.oauth.get_config().await;
                out.emit(&config)?;
                Ok(())
            }
            ConfigCmd::Set(args) => {
                let ConfigSetArgs {
                    json,
                    twitch_client_id,
                    twitch_client_secret,
                    youtube_client_id,
                    youtube_client_secret,
                    kick_client_id,
                    kick_client_secret,
                    facebook_client_id,
                    facebook_client_secret,
                } = *args;
                let config: spiritstream_core::services::OAuthConfig = if let Some(raw) = json {
                    serde_json::from_str(&raw)
                        .map_err(|e| CliError::Argument(format!("invalid --json: {e}")))?
                } else {
                    spiritstream_core::services::OAuthConfig {
                        twitch_client_id,
                        twitch_client_secret,
                        youtube_client_id,
                        youtube_client_secret,
                        kick_client_id,
                        kick_client_secret,
                        facebook_client_id,
                        facebook_client_secret,
                    }
                };
                registry.oauth.update_config(config).await;
                out.emit(&serde_json::json!({ "updated": true }))?;
                Ok(())
            }
        },
    }
}

//! `spiritstream-cli obs …` — OBS Studio WebSocket integration.

use clap::Subcommand;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum ObsCmd {
    /// Snapshot of OBS connection + streaming state.
    State,
    /// Show the current OBS WebSocket config (password masked).
    Config,
    /// Connect to the configured OBS WebSocket.
    Connect,
    /// Disconnect from OBS.
    Disconnect,
    /// Start streaming in OBS (requires an active connection).
    StreamStart,
    /// Stop streaming in OBS.
    StreamStop,
    /// Replace the OBS WebSocket configuration. `--password` is encrypted
    /// before persisting; omit to keep the existing password.
    SetConfig {
        #[arg(long)]
        host: String,
        #[arg(long)]
        port: u16,
        #[arg(long)]
        password: Option<String>,
        #[arg(long, default_value_t = false)]
        use_auth: bool,
        /// One of `obs-to-spiritstream`, `spiritstream-to-obs`, `bidirectional`, `disabled`.
        #[arg(long, default_value = "disabled")]
        direction: String,
        #[arg(long, default_value_t = false)]
        auto_connect: bool,
    },
}

pub async fn run(
    cmd: ObsCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        ObsCmd::State => {
            let state = registry.obs.get_state().await;
            out.emit(&state)?;
            Ok(())
        }
        ObsCmd::Config => {
            let config = registry.obs.get_config().await;
            // Password is masked at the model layer — `ObsConfig` ts-rs export
            // already strips it for the wire shape.
            out.emit(&config)?;
            Ok(())
        }
        ObsCmd::Connect => {
            registry.obs.connect(registry.events.clone()).await?;
            out.emit(&serde_json::json!({ "connected": true }))?;
            Ok(())
        }
        ObsCmd::Disconnect => {
            registry.obs.disconnect(registry.events.clone()).await?;
            out.emit(&serde_json::json!({ "disconnected": true }))?;
            Ok(())
        }
        ObsCmd::StreamStart => {
            registry.obs.start_stream().await?;
            out.emit(&serde_json::json!({ "started": true }))?;
            Ok(())
        }
        ObsCmd::StreamStop => {
            registry.obs.stop_stream().await?;
            out.emit(&serde_json::json!({ "stopped": true }))?;
            Ok(())
        }
        ObsCmd::SetConfig {
            host,
            port,
            password,
            use_auth,
            direction,
            auto_connect,
        } => {
            use spiritstream_core::services::IntegrationDirection;
            let current = registry.obs.get_config().await;
            let encrypted = if let Some(p) = password.as_deref() {
                if p.is_empty() {
                    String::new()
                } else {
                    registry.obs.encrypt_password(p)?
                }
            } else {
                current.password
            };
            let dir = match direction.as_str() {
                "obs-to-spiritstream" => IntegrationDirection::ObsToSpiritstream,
                "spiritstream-to-obs" => IntegrationDirection::SpiritstreamToObs,
                "bidirectional" => IntegrationDirection::Bidirectional,
                _ => IntegrationDirection::Disabled,
            };
            let config = spiritstream_core::services::ObsConfig {
                host,
                port,
                password: encrypted,
                use_auth,
                direction: dir,
                auto_connect,
            };
            registry.obs.set_config(config).await;
            out.emit(&serde_json::json!({ "saved": true }))?;
            Ok(())
        }
    }
}

//! `spiritstream-cli profile …` — manage stream profiles.

use clap::Subcommand;
use serde::Serialize;
use spiritstream_core::models::Profile;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum ProfileCmd {
    /// List every profile by name in user-defined order.
    List,
    /// Report whether a profile exists locally.
    Exists {
        /// Profile name to query.
        name: String,
    },
    /// Print the resolved profile as JSON. `--password` is required for
    /// encrypted profiles and silently ignored for plaintext ones.
    Show {
        name: String,
        #[arg(long)]
        password: Option<String>,
    },
    /// Persist a profile from a JSON document on disk. `--password`
    /// re-encrypts the profile under that password (omit to leave plaintext).
    Save {
        /// Path to a JSON file containing the profile body.
        file: std::path::PathBuf,
        #[arg(long)]
        password: Option<String>,
    },
    /// Delete a profile.
    Delete { name: String },
    /// Report whether the named profile is stored encrypted on disk.
    IsEncrypted { name: String },
    /// Print the resolved summary list — parsed numeric bitrate/resolution
    /// and unique services, sourced from `Profile::to_summary()`.
    Summaries,
    /// Validate an RTMP input shape (bind address + port + application) for
    /// port-conflict against other profiles. Reads input JSON from `<file>`.
    ValidateInput {
        profile_id: String,
        file: std::path::PathBuf,
    },
    /// Replace the saved profile-order map (priority order shown in the UI).
    Reorder { ordered_names: Vec<String> },
    /// Print the saved profile-order map.
    Order,
    /// Backfill order indexes for any profile missing one. Idempotent —
    /// no-op when every profile already appears in the map. Mirrors
    /// `POST /api/v1/profiles/order/ensure`.
    EnsureOrder,
    /// Activate a profile — runs `ProfileService::activate()` so chat settings
    /// propagate, OBS reconfigures and (when the profile asks for it) auto-
    /// connects. Prints the resolved profile + the `ProfileActivatedEvent`
    /// payload the HTTP transport would emit on `/api/v1/events`.
    Activate {
        name: String,
        #[arg(long)]
        password: Option<String>,
    },
    /// Atomically remove encryption from a profile: load with `--password`,
    /// re-save unencrypted. Mirrors `POST /api/v1/profiles/{name}/decrypt`.
    Decrypt {
        name: String,
        #[arg(long)]
        password: String,
    },
    /// Verify a profile password against the encrypted blob. Mirrors
    /// `POST /api/v1/profiles/{name}/unlock`. The HTTP transport's session
    /// unlock set lives on `AppState`; in the CLI each invocation is its own
    /// session, so this command only validates the password.
    Unlock {
        name: String,
        #[arg(long)]
        password: String,
    },
    /// Mirrors `POST /api/v1/profiles/{name}/lock`. CLI is single-shot so
    /// this is a confirmation echo — no cross-invocation session state.
    Lock { name: String },
    /// Mirrors `GET /api/v1/profiles/locked`. CLI is single-shot so the
    /// unlocked set is always empty.
    LockedList,
}

#[derive(Serialize)]
struct ListResponse<'a> {
    names: &'a [String],
}

#[derive(Serialize)]
struct ExistsResponse {
    name: String,
    exists: bool,
}

#[derive(Serialize)]
struct DeleteResponse {
    name: String,
    deleted: bool,
}

#[derive(Serialize)]
struct SaveResponse {
    name: String,
    saved: bool,
}

#[derive(Serialize)]
struct IsEncryptedResponse {
    name: String,
    encrypted: bool,
}

pub async fn run(
    cmd: ProfileCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        ProfileCmd::List => {
            let names = registry.profiles.get_all_names().await?;
            out.emit(&ListResponse { names: &names })?;
            Ok(())
        }
        ProfileCmd::Exists { name } => {
            let names = registry.profiles.get_all_names().await?;
            let exists = names.iter().any(|n| n == &name);
            out.emit(&ExistsResponse { name, exists })?;
            Ok(())
        }
        ProfileCmd::Show { name, password } => {
            let profile = registry
                .profiles
                .load_with_key_decryption(&name, password.as_deref())
                .await?;
            out.emit(&profile)?;
            Ok(())
        }
        ProfileCmd::Save { file, password } => {
            let body = std::fs::read_to_string(&file)
                .map_err(|e| CliError::Io(format!("read {}: {}", file.display(), e)))?;
            let profile: Profile = serde_json::from_str(&body)
                .map_err(|e| CliError::Serialization(format!("parse {}: {}", file.display(), e)))?;
            let name = profile.name.clone();
            registry
                .profiles
                .save_with_key_encryption(&profile, password.as_deref())
                .await?;
            out.emit(&SaveResponse { name, saved: true })?;
            Ok(())
        }
        ProfileCmd::Delete { name } => {
            registry.profiles.delete(&name).await?;
            out.emit(&DeleteResponse {
                name,
                deleted: true,
            })?;
            Ok(())
        }
        ProfileCmd::IsEncrypted { name } => {
            let encrypted = registry.profiles.is_encrypted(&name);
            out.emit(&IsEncryptedResponse { name, encrypted })?;
            Ok(())
        }
        ProfileCmd::Summaries => {
            let summaries = registry.profiles.get_all_summaries().await?;
            out.emit(&summaries)?;
            Ok(())
        }
        ProfileCmd::ValidateInput { profile_id, file } => {
            let body = std::fs::read_to_string(&file)
                .map_err(|e| CliError::Io(format!("read {}: {}", file.display(), e)))?;
            let input: spiritstream_core::models::RtmpInput = serde_json::from_str(&body)
                .map_err(|e| CliError::Serialization(format!("parse {}: {}", file.display(), e)))?;
            registry
                .profiles
                .validate_input_conflict(&profile_id, &input)
                .await?;
            out.emit(&serde_json::json!({ "valid": true }))?;
            Ok(())
        }
        ProfileCmd::Reorder { ordered_names } => {
            // Mirror the HTTP `PATCH /api/v1/profiles/order` behaviour: every
            // submitted name must already exist; missing ones are rejected
            // before any writes.
            let existing = registry.profiles.get_all_names().await?;
            let mut map = registry.profiles.read_order_index_map()?;
            let mut idx: i32 = 0;
            for name in &ordered_names {
                if !existing.contains(name) {
                    return Err(spiritstream_core::CoreError::ProfileNotFound {
                        name: name.clone(),
                    }
                    .into());
                }
                idx += 10;
                map.insert(name.clone(), idx);
            }
            registry.profiles.write_order_index_map(&map)?;
            out.emit(&serde_json::json!({ "reordered": ordered_names }))?;
            Ok(())
        }
        ProfileCmd::Order => {
            let map = registry.profiles.read_order_index_map()?;
            out.emit(&map)?;
            Ok(())
        }
        ProfileCmd::EnsureOrder => {
            let map = registry.profiles.ensure_order_indexes().await?;
            out.emit(&map)?;
            Ok(())
        }
        ProfileCmd::Activate { name, password } => {
            // ProfileActivationService composes load + OAuth refresh +
            // chat/OBS propagation + bus emission in a single call.
            // CLI and HTTP share the same orchestrator — wire shape and
            // log volume are identical across transports.
            let outcome = registry
                .profile_activation
                .activate(&name, password.as_deref())
                .await?;
            out.emit(&serde_json::json!({
                "profile": outcome.profile,
                "event": outcome.event,
                "oauthRefreshFailed": outcome.oauth_refresh_failed,
            }))?;
            Ok(())
        }
        ProfileCmd::Decrypt { name, password } => {
            let profile = registry
                .profiles
                .load_with_key_decryption(&name, Some(&password))
                .await?;
            registry
                .profiles
                .save_with_key_encryption(&profile, None)
                .await?;
            out.emit(&serde_json::json!({ "name": name, "decrypted": true }))?;
            Ok(())
        }
        ProfileCmd::Unlock { name, password } => {
            // Validates the password by attempting decryption; the HTTP
            // transport additionally tracks an in-memory unlock set on
            // AppState, but the CLI is a one-shot process so the
            // verification IS the unlock for this invocation.
            registry
                .profiles
                .load_with_key_decryption(&name, Some(&password))
                .await?;
            out.emit(&serde_json::json!({ "name": name, "unlocked": true }))?;
            Ok(())
        }
        ProfileCmd::Lock { name } => {
            out.emit(&serde_json::json!({ "name": name, "locked": true }))?;
            Ok(())
        }
        ProfileCmd::LockedList => {
            out.emit(&serde_json::json!({ "unlocked": Vec::<String>::new() }))?;
            Ok(())
        }
    }
}

//! `spiritstream-cli safety …` — safety features for vulnerable users.
//!
//! `safety panic` runs the full disconnect flow in-process
//! (no HTTP shell-out). `safety blocklist` manages the PII blocklist.

use clap::Subcommand;
use serde::Serialize;

use crate::error::CliError;
use crate::output::Output;
use spiritstream_core::ServiceRegistry;

#[derive(Debug, Subcommand)]
pub enum SafetyCmd {
    /// Trigger panic disconnect: stop every stream, disconnect chat + OBS,
    /// wipe in-memory secret caches, append an audit-log entry.
    Panic,
    /// Manage the per-profile PII blocklist. Operates on the
    /// profile named by `--profile`. Password-protected profiles need
    /// `--password` to load and re-save.
    Blocklist {
        /// Profile to operate on.
        #[arg(long)]
        profile: String,
        /// Password for encrypted profiles. Ignored for plaintext.
        #[arg(long)]
        password: Option<String>,
        #[command(subcommand)]
        action: BlocklistAction,
    },
}

#[derive(Debug, Subcommand)]
pub enum BlocklistAction {
    /// List current blocklist phrases.
    List,
    /// Add a phrase. Match is case-insensitive substring.
    Add { phrase: String },
    /// Remove a phrase.
    Remove { phrase: String },
}

#[derive(Serialize)]
struct SafetyPanicCliResponse {
    streams_stopped: usize,
    elapsed_ms: u64,
}

#[derive(Serialize)]
struct BlocklistResponse {
    profile: String,
    phrases: Vec<String>,
}

pub async fn run(
    cmd: SafetyCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        SafetyCmd::Panic => {
            let result = registry.safety.panic().await?;
            out.emit(&SafetyPanicCliResponse {
                streams_stopped: result.streams_stopped,
                elapsed_ms: result.elapsed_ms,
            })?;
            Ok(())
        }
        SafetyCmd::Blocklist {
            profile,
            password,
            action,
        } => {
            let mut p = registry
                .profiles
                .load_with_key_decryption(&profile, password.as_deref())
                .await?;
            match action {
                BlocklistAction::List => {}
                BlocklistAction::Add { phrase } => {
                    let trimmed = phrase.trim().to_string();
                    if !trimmed.is_empty() && !p.pii_blocklist.iter().any(|x| x == &trimmed) {
                        p.pii_blocklist.push(trimmed);
                        registry
                            .profiles
                            .save_with_key_encryption(&p, password.as_deref())
                            .await?;
                    }
                }
                BlocklistAction::Remove { phrase } => {
                    let before = p.pii_blocklist.len();
                    p.pii_blocklist.retain(|x| x != &phrase);
                    if p.pii_blocklist.len() != before {
                        registry
                            .profiles
                            .save_with_key_encryption(&p, password.as_deref())
                            .await?;
                    }
                }
            }
            out.emit(&BlocklistResponse {
                profile: p.name.clone(),
                phrases: p.pii_blocklist,
            })?;
            Ok(())
        }
    }
}

//! `spiritstream-cli settings …` — global app-wide settings.

use clap::Subcommand;
use serde_json::Value;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum SettingsCmd {
    /// Print resolved global settings as JSON. When `<key>` is provided,
    /// print just that top-level field. Unknown keys exit with an
    /// `argument` error (EX_USAGE).
    Get {
        /// Optional top-level settings key (e.g. `logRetentionDays`).
        key: Option<String>,
    },
    /// Apply field changes provided as one or more `--set key=value` flags.
    /// Values are parsed as JSON when possible (numbers, booleans, strings),
    /// falling back to a raw string when JSON parsing fails. Out-of-range
    /// values surface as `validation_failed` and exit code 7.
    Set {
        #[arg(long = "set", value_name = "KEY=VALUE", required = true)]
        overrides: Vec<String>,
    },
    /// Print the absolute path of the profiles directory.
    ProfilesPath,
}

pub async fn run(
    cmd: SettingsCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        SettingsCmd::Get { key: None } => {
            let settings = registry.settings.load()?;
            out.emit(&settings)?;
            Ok(())
        }
        SettingsCmd::Get { key: Some(key) } => {
            let settings = registry.settings.load()?;
            let json = serde_json::to_value(&settings)
                .map_err(|e| CliError::Serialization(e.to_string()))?;
            match json.get(&key) {
                Some(value) => {
                    out.emit(value)?;
                    Ok(())
                }
                None => Err(CliError::Argument(format!("unknown settings key: {key}"))),
            }
        }
        SettingsCmd::Set { overrides } => {
            let settings = registry.settings.load()?;
            let mut json = serde_json::to_value(&settings)
                .map_err(|e| CliError::Serialization(e.to_string()))?;

            for raw in &overrides {
                let (key, value_str) = raw
                    .split_once('=')
                    .ok_or_else(|| CliError::Argument(format!("expected key=value, got: {raw}")))?;
                let key = key.trim();
                let value_str = value_str.trim();

                let parsed: Value = serde_json::from_str(value_str)
                    .unwrap_or_else(|_| Value::String(value_str.to_owned()));

                let obj = json.as_object_mut().ok_or_else(|| {
                    CliError::Serialization("settings is not a JSON object".into())
                })?;

                if !obj.contains_key(key) {
                    return Err(CliError::Argument(format!("unknown settings key: {key}")));
                }
                obj.insert(key.to_owned(), parsed);
            }

            let updated: spiritstream_core::models::Settings = serde_json::from_value(json)
                .map_err(|e| CliError::Serialization(format!("invalid settings shape: {e}")))?;

            registry.settings.save(&updated)?;
            out.emit(&updated)?;
            Ok(())
        }
        SettingsCmd::ProfilesPath => {
            let path = registry.settings.get_profiles_path();
            out.emit(&serde_json::json!({ "path": path.to_string_lossy() }))?;
            Ok(())
        }
    }
}

//! `spiritstream-cli stream …` — observe and control RTMP streams.

use clap::Subcommand;
use serde::Serialize;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum StreamCmd {
    /// Snapshot of every active stream group.
    Status,
    /// Stop a stream group. If `--group` is omitted, every active group is
    /// stopped (matches the rewrite plan's `stream stop [--group <id>]` UX).
    Stop {
        /// Stream group ID. When omitted, every active group is stopped.
        #[arg(long)]
        group: Option<String>,
    },
    /// Begin a new stream from a loaded profile. The CLI loads the profile,
    /// filters to enabled output groups, and dispatches via `FFmpegHandler`.
    /// Returns the spawned FFmpeg PIDs.
    Start {
        /// Profile name to stream from.
        #[arg(long)]
        profile: String,
        /// Specific output group to start (defaults to every enabled group).
        #[arg(long)]
        group: Option<String>,
        /// Password for encrypted profiles.
        #[arg(long)]
        password: Option<String>,
    },
    /// Re-attempt a previously failed stream group with backoff policy.
    Retry { group_id: String },
    /// Validate a profile's encoding config server-side (decorative — the
    /// same checks run inside `start`). Reads profile JSON from `<file>`.
    Validate { file: std::path::PathBuf },
    /// Print active stream group IDs and count.
    Active,
    /// Report whether `<group-id>` is currently streaming.
    IsActive { group_id: String },
    /// Report whether `<target-id>` is currently disabled (skipped during start).
    TargetDisabled { target_id: String },
    /// Toggle a single target's enabled state and restart its parent group
    /// with the new filter applied.
    ToggleTarget {
        /// Target ID to flip.
        target_id: String,
        /// `true` enables the target, `false` disables it.
        #[arg(long)]
        enabled: bool,
        /// Profile name owning the parent group (the group's incoming URL is
        /// taken from this profile's RTMP input).
        #[arg(long)]
        profile: String,
        /// Parent group ID inside the profile.
        #[arg(long)]
        group: String,
        /// Password for encrypted profiles.
        #[arg(long)]
        password: Option<String>,
    },
}

#[derive(Serialize)]
struct StatusResponse {
    active: Vec<String>,
    count: usize,
}

#[derive(Serialize)]
struct StopResponse {
    stopped: Vec<String>,
}

pub async fn run(
    cmd: StreamCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        StreamCmd::Status => {
            let active = registry.ffmpeg.get_active_group_ids();
            let count = active.len();
            out.emit(&StatusResponse { active, count })?;
            Ok(())
        }
        StreamCmd::Stop { group } => {
            match group {
                Some(id) => {
                    registry.ffmpeg.stop(&id)?;
                    out.emit(&StopResponse { stopped: vec![id] })?;
                }
                None => {
                    let stopped = registry.ffmpeg.get_active_group_ids();
                    registry.ffmpeg.stop_all()?;
                    out.emit(&StopResponse { stopped })?;
                }
            }
            Ok(())
        }
        StreamCmd::Start {
            profile,
            group,
            password,
        } => {
            let p = registry
                .profiles
                .load_with_key_decryption(&profile, password.as_deref())
                .await?;
            let incoming_url = format!(
                "rtmp://{}:{}/{}",
                p.input.bind_address, p.input.port, p.input.application,
            );

            let groups: Vec<spiritstream_core::models::OutputGroup> = match &group {
                Some(id) => p
                    .output_groups
                    .iter()
                    .filter(|g| &g.id == id)
                    .cloned()
                    .collect(),
                None => p
                    .output_groups
                    .iter()
                    .filter(|g| !g.stream_targets.is_empty())
                    .cloned()
                    .collect(),
            };

            if groups.is_empty() {
                return Err(CliError::Argument(format!(
                    "no eligible output groups to start{}",
                    group
                        .as_deref()
                        .map(|g| format!(" (looked for id={g})"))
                        .unwrap_or_default(),
                )));
            }

            let pids =
                registry
                    .ffmpeg
                    .start_all(&groups, &incoming_url, registry.events.clone())?;

            #[derive(Serialize)]
            struct StartResponse {
                pids: Vec<u32>,
            }
            out.emit(&StartResponse { pids })?;
            Ok(())
        }
        StreamCmd::Retry { group_id } => {
            let event_sink = registry.events.clone();
            let ffmpeg = registry.ffmpeg.clone();
            let group_id_clone = group_id.clone();
            let (pid, next_delay) = tokio::task::spawn_blocking(move || {
                ffmpeg.retry_group(&group_id_clone, event_sink)
            })
            .await
            .map_err(|e| CliError::Io(format!("task join error: {e}")))??;

            #[derive(Serialize)]
            struct RetryResponse {
                pid: u32,
                next_delay_secs: Option<u64>,
            }
            out.emit(&RetryResponse {
                pid,
                next_delay_secs: next_delay.map(|d| d.as_secs()),
            })?;
            Ok(())
        }
        StreamCmd::Validate { file } => {
            let body = std::fs::read_to_string(&file)
                .map_err(|e| CliError::Io(format!("read {}: {}", file.display(), e)))?;
            let profile: spiritstream_core::models::Profile = serde_json::from_str(&body)
                .map_err(|e| CliError::Serialization(format!("parse {}: {}", file.display(), e)))?;
            spiritstream_core::services::FFmpegHandler::validate_config(&profile)?;
            out.emit(&serde_json::json!({ "valid": true }))?;
            Ok(())
        }
        StreamCmd::Active => {
            let ids = registry.ffmpeg.get_active_group_ids();
            #[derive(Serialize)]
            struct ActiveResponse {
                ids: Vec<String>,
                count: usize,
            }
            let count = ids.len();
            out.emit(&ActiveResponse { ids, count })?;
            Ok(())
        }
        StreamCmd::IsActive { group_id } => {
            let active = registry.ffmpeg.is_streaming(&group_id);
            out.emit(&serde_json::json!({ "groupId": group_id, "active": active }))?;
            Ok(())
        }
        StreamCmd::TargetDisabled { target_id } => {
            let disabled = registry.ffmpeg.is_target_disabled(&target_id);
            out.emit(&serde_json::json!({ "targetId": target_id, "disabled": disabled }))?;
            Ok(())
        }
        StreamCmd::ToggleTarget {
            target_id,
            enabled,
            profile,
            group,
            password,
        } => {
            let p = registry
                .profiles
                .load_with_key_decryption(&profile, password.as_deref())
                .await?;
            let target_group = p
                .output_groups
                .iter()
                .find(|g| g.id == group)
                .cloned()
                .ok_or_else(|| {
                    CliError::Argument(format!(
                        "output group '{group}' not found in profile '{profile}'"
                    ))
                })?;
            let incoming_url = format!(
                "rtmp://{}:{}/{}",
                p.input.bind_address, p.input.port, p.input.application,
            );
            if enabled {
                registry.ffmpeg.enable_target(&target_id);
            } else {
                registry.ffmpeg.disable_target(&target_id);
            }
            let pid = registry.ffmpeg.restart_group(
                &target_group.id,
                &target_group,
                &incoming_url,
                registry.events.clone(),
            )?;
            out.emit(
                &serde_json::json!({ "pid": pid, "targetId": target_id, "enabled": enabled }),
            )?;
            Ok(())
        }
    }
}

//! `spiritstream-cli system …` — environmental capability probes.

use std::collections::BTreeMap;

use clap::Subcommand;
use serde::Serialize;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum SystemCmd {
    /// List FFmpeg-detected video and audio encoders.
    Encoders,
    /// FFmpeg-specific operations (check installation, download, cancel).
    Ffmpeg {
        #[command(subcommand)]
        action: FfmpegAction,
    },
    /// Print server-tuned client constants (polling intervals, popup
    /// dimensions, per-platform chat char limits, …).
    ClientConfig,
    /// Print the encoder preset matrix (resolution/fps/bitrate options,
    /// per-codec presets, container formats).
    EncoderPresets,
    /// Print recent server log lines (default 500). The frontend Logs view
    /// reads via this surface.
    Logs {
        #[arg(long, default_value_t = 500)]
        lines: usize,
    },
    /// Test an RTMP target by attempting a quick connection.
    TestRtmp { url: String, stream_key: String },
    /// Validate a path points at an FFmpeg binary, return its version string.
    ValidateFfmpegPath { path: std::path::PathBuf },
    /// Print the running app version. Mirrors `GET /api/v1/system/app-version`.
    AppVersion,
    /// Export the current log file to `<out>`. Path must lie inside the
    /// data directory or the user's home. Mirrors
    /// `POST /api/v1/system/logs/export` — the HTTP route takes the
    /// content from the client; the CLI reads it locally.
    LogsExport {
        #[arg(long)]
        out: std::path::PathBuf,
        /// Override the line cap (default: full file).
        #[arg(long)]
        lines: Option<usize>,
    },
    /// Record an app-update failure into the HMAC-chained audit log.
    /// Mirrors `POST /api/v1/system/audit/app-update-failure`.
    AuditUpdateFailure {
        /// Sanitized error message from the updater.
        #[arg(long)]
        detail: String,
    },
    /// Aggregate subsystem health (profiles, settings, themes, audit-log
    /// chain). Mirrors `GET /api/v1/health`. Use `--subsystem <name>` to
    /// narrow to a single subsystem and exit with non-zero on
    /// non-`ok` status.
    Health {
        #[arg(long)]
        subsystem: Option<String>,
    },
    /// Readiness probe — same checks as `health` but reports a single
    /// boolean and exits non-zero when not ready. Mirrors
    /// `GET /api/v1/ready`. The CLI builds the registry synchronously so
    /// "ready" reduces to "every health subsystem reports `Ok`".
    Ready,
}

#[derive(Debug, Subcommand)]
pub enum FfmpegAction {
    /// Probe whether FFmpeg is reachable and report its version.
    Check,
    /// Print the resolved FFmpeg path or `null` if discovery fails.
    Path,
    /// Check whether a newer FFmpeg version is available upstream.
    UpdateCheck {
        #[arg(long)]
        installed_version: Option<String>,
    },
}

#[derive(Serialize)]
struct FfmpegProbeOk {
    available: bool,
    version: String,
}

#[derive(Serialize)]
struct FfmpegProbeMissing {
    available: bool,
    detail: String,
}

pub async fn run(
    cmd: SystemCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        SystemCmd::Encoders => {
            let encoders = spiritstream_core::commands::get_encoders()?;
            out.emit(&encoders)?;
            Ok(())
        }
        SystemCmd::Ffmpeg {
            action: FfmpegAction::Check,
        } => match spiritstream_core::commands::test_ffmpeg() {
            Ok(version) => out.emit(&FfmpegProbeOk {
                available: true,
                version,
            }),
            Err(err) => out.emit(&FfmpegProbeMissing {
                available: false,
                detail: err.to_string(),
            }),
        },
        SystemCmd::Ffmpeg {
            action: FfmpegAction::Path,
        } => {
            use spiritstream_core::services::FFmpegLocator;
            let path = FFmpegLocator::discover(Some(&registry.settings));
            out.emit(&serde_json::json!({
                "path": path.map(|p| p.to_string_lossy().to_string()),
            }))?;
            Ok(())
        }
        SystemCmd::Ffmpeg {
            action: FfmpegAction::UpdateCheck { installed_version },
        } => {
            let info = registry
                .ffmpeg_locator
                .check_version_status(installed_version.as_deref())
                .await;
            out.emit(&info)?;
            Ok(())
        }
        SystemCmd::ClientConfig => {
            // Mirror the HTTP /api/v1/system/client-config payload exactly.
            use spiritstream_core::models::ChatPlatform;
            let mut chat_max_chars = std::collections::HashMap::new();
            for p in [
                ChatPlatform::Twitch,
                ChatPlatform::YouTube,
                ChatPlatform::Trovo,
                ChatPlatform::Kick,
                ChatPlatform::Facebook,
                ChatPlatform::TikTok,
            ] {
                chat_max_chars.insert(p.as_str().to_owned(), p.max_message_chars() as u32);
            }
            out.emit(&serde_json::json!({
                "obsTriggerDelayMs": 2000_u32,
                "autoSaveDelayMs": 500_u32,
                "chatPollIntervalMs": 5000_u32,
                "toastDurationMs": 4000_u32,
                "chatPopupWidth": 420_u32,
                "chatPopupHeight": 720_u32,
                "chatOverlayPollMs": 500_u32,
                "retryBaseDelayMs": 800_u32,
                "chatMaxChars": chat_max_chars,
            }))?;
            Ok(())
        }
        SystemCmd::EncoderPresets => {
            // Static preset matrix shared with HTTP /api/v1/system/encoders/presets.
            let mut presets = std::collections::HashMap::new();
            presets.insert(
                "libx264".to_string(),
                vec![
                    "ultrafast",
                    "superfast",
                    "veryfast",
                    "faster",
                    "fast",
                    "medium",
                    "slow",
                    "slower",
                    "veryslow",
                ]
                .into_iter()
                .map(String::from)
                .collect::<Vec<_>>(),
            );
            presets.insert(
                "libx265".to_string(),
                vec![
                    "ultrafast",
                    "superfast",
                    "veryfast",
                    "faster",
                    "fast",
                    "medium",
                    "slow",
                    "slower",
                    "veryslow",
                ]
                .into_iter()
                .map(String::from)
                .collect::<Vec<_>>(),
            );
            presets.insert(
                "nvenc".to_string(),
                vec!["p1", "p2", "p3", "p4", "p5", "p6", "p7"]
                    .into_iter()
                    .map(String::from)
                    .collect::<Vec<_>>(),
            );
            presets.insert(
                "amf".to_string(),
                vec!["quality", "balanced", "speed"]
                    .into_iter()
                    .map(String::from)
                    .collect::<Vec<_>>(),
            );
            out.emit(&serde_json::json!({
                "resolutions": ["1920x1080","1280x720","2560x1440","3840x2160","854x480"],
                "fpsValues": ["60","30","24","25","50"],
                "audioBitrates": ["320k","256k","192k","160k","128k","96k","64k"],
                "audioChannels": ["1","2","6","8"],
                "audioSampleRates": ["48000","44100","32000"],
                "containerFormats": ["flv","mpegts","mp4"],
                "h264Profiles": ["baseline","main","high"],
                "presets": presets,
            }))?;
            Ok(())
        }
        SystemCmd::Logs { lines } => {
            let logs = spiritstream_core::services::read_recent_logs(&registry.log_dir, lines)?;
            out.emit(&logs)?;
            Ok(())
        }
        SystemCmd::TestRtmp { url, stream_key } => {
            let result = spiritstream_core::commands::test_rtmp_target(url, stream_key)?;
            out.emit(&result)?;
            Ok(())
        }
        SystemCmd::ValidateFfmpegPath { path } => {
            let p = path.to_string_lossy().to_string();
            let validated = spiritstream_core::commands::validate_ffmpeg_path(p)?;
            out.emit(&serde_json::json!({ "version": validated }))?;
            Ok(())
        }
        SystemCmd::AppVersion => {
            // Same source the HTTP `/system/app-version` route returns —
            // the CLI binary carries its own `CARGO_PKG_VERSION` but the
            // release workflow validates every version string matches.
            out.emit(&serde_json::json!({
                "version": env!("CARGO_PKG_VERSION"),
            }))?;
            Ok(())
        }
        SystemCmd::LogsExport { out: out_path, lines } => {
            let allowed: Vec<&std::path::Path> = vec![registry.data_dir.as_path()];
            let validated =
                spiritstream_core::services::validate_path_within_any(&out_path, &allowed)?;
            let cap = lines.unwrap_or(usize::MAX);
            let log_lines =
                spiritstream_core::services::read_recent_logs(&registry.log_dir, cap)?;
            let body = log_lines.join("\n");
            std::fs::write(&validated, &body).map_err(|e| {
                CliError::Io(format!("write {}: {}", validated.display(), e))
            })?;
            out.emit(&serde_json::json!({
                "exported": true,
                "path": validated.to_string_lossy(),
                "lines": log_lines.len(),
            }))?;
            Ok(())
        }
        SystemCmd::AuditUpdateFailure { detail } => {
            registry
                .audit
                .record(spiritstream_core::services::AuditAction::AppUpdateSignatureFailed {
                    detail,
                })?;
            out.emit(&serde_json::json!({ "recorded": true }))?;
            Ok(())
        }
        SystemCmd::Health { subsystem } => {
            let report = compute_health(registry).await;
            match subsystem {
                Some(name) => match report.services.get(&name) {
                    None => Err(CliError::Argument(format!(
                        "unknown subsystem: {name} (valid: {})",
                        report.services.keys().cloned().collect::<Vec<_>>().join(", ")
                    ))),
                    Some(status) => {
                        let entry = serde_json::json!({
                            "status": &report.status,
                            "subsystem": &name,
                            "report": status,
                        });
                        out.emit(&entry)?;
                        if !matches!(status, SubsystemStatus::Ok) {
                            return Err(CliError::Argument(format!(
                                "subsystem '{name}' is not ok"
                            )));
                        }
                        Ok(())
                    }
                },
                None => {
                    out.emit(&report)?;
                    if report.status != "ok" {
                        return Err(CliError::Argument(format!(
                            "system health: {}",
                            report.status
                        )));
                    }
                    Ok(())
                }
            }
        }
        SystemCmd::Ready => {
            let report = compute_health(registry).await;
            let ready = report.status == "ok";
            let failed: Vec<String> = report
                .services
                .iter()
                .filter(|(_, v)| !matches!(v, SubsystemStatus::Ok))
                .map(|(k, _)| k.clone())
                .collect();
            out.emit(&serde_json::json!({
                "ready": ready,
                "failed": failed,
            }))?;
            if !ready {
                // EX_UNAVAILABLE (69) so retry-loop scripts can
                // distinguish "service starting up" from "bad flags."
                return Err(CliError::Unavailable("not ready".into()));
            }
            Ok(())
        }
    }
}

#[derive(Serialize)]
#[serde(rename_all = "snake_case", tag = "state")]
enum SubsystemStatus {
    Ok,
    Degraded { detail: String },
    Disconnected { detail: String },
    Tampered { last_valid_sequence: u64 },
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct HealthReport {
    /// Aggregate status — `"ok"`, `"degraded"`, or `"tampered"`. Same
    /// rollup rule the HTTP `/health` route uses.
    status: String,
    services: BTreeMap<String, SubsystemStatus>,
}

async fn compute_health(registry: &ServiceRegistry) -> HealthReport {
    let mut services: BTreeMap<String, SubsystemStatus> = BTreeMap::new();
    services.insert(
        "profiles".into(),
        match registry.profiles.get_all_names().await {
            Ok(_) => SubsystemStatus::Ok,
            Err(err) => SubsystemStatus::Disconnected {
                detail: err.to_string(),
            },
        },
    );
    services.insert(
        "settings".into(),
        match registry.settings.load() {
            Ok(_) => SubsystemStatus::Ok,
            Err(err) => SubsystemStatus::Disconnected {
                detail: err.to_string(),
            },
        },
    );
    services.insert(
        "themes".into(),
        if registry.themes.list_themes().is_empty() {
            SubsystemStatus::Degraded {
                detail: "no themes loaded".into(),
            }
        } else {
            SubsystemStatus::Ok
        },
    );
    services.insert(
        "audit_log".into(),
        match registry.audit.verify_chain() {
            Ok(spiritstream_core::services::AuditChainStatus::Ok { .. }) => SubsystemStatus::Ok,
            Ok(spiritstream_core::services::AuditChainStatus::Empty) => SubsystemStatus::Ok,
            Ok(spiritstream_core::services::AuditChainStatus::Tampered {
                last_valid_sequence,
                ..
            }) => SubsystemStatus::Tampered {
                last_valid_sequence,
            },
            Err(e) => SubsystemStatus::Disconnected {
                detail: e.to_string(),
            },
        },
    );

    let status = if services
        .values()
        .any(|s| matches!(s, SubsystemStatus::Tampered { .. }))
    {
        "tampered"
    } else if services.values().any(|s| {
        matches!(
            s,
            SubsystemStatus::Disconnected { .. } | SubsystemStatus::Degraded { .. }
        )
    }) {
        "degraded"
    } else {
        "ok"
    };

    HealthReport {
        status: status.into(),
        services,
    }
}

//! `spiritstream-cli theme …` — installed theme catalog.

use clap::Subcommand;
use spiritstream_core::ServiceRegistry;

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Subcommand)]
pub enum ThemeCmd {
    /// List every theme the catalog can serve.
    List,
    /// Resolve a theme's token dictionary by ID.
    Tokens { id: String },
    /// Install a `.spirittheme.json` file into the user theme catalog.
    Install { path: std::path::PathBuf },
    /// Re-sync the project theme directory into the catalog.
    Refresh,
}

pub async fn run(
    cmd: ThemeCmd,
    registry: &ServiceRegistry,
    out: &mut Output,
) -> Result<(), CliError> {
    match cmd {
        ThemeCmd::List => {
            let themes = registry.themes.list_themes();
            out.emit(&themes)?;
            Ok(())
        }
        ThemeCmd::Tokens { id } => {
            let tokens = registry.themes.get_theme_tokens(&id)?;
            out.emit(&tokens)?;
            Ok(())
        }
        ThemeCmd::Install { path } => {
            let summary = registry.themes.install_theme(&path)?;
            out.emit(&summary)?;
            Ok(())
        }
        ThemeCmd::Refresh => {
            registry.themes.sync_project_themes();
            let themes = registry.themes.list_themes();
            out.emit(&themes)?;
            Ok(())
        }
    }
}

//! CLI-level error type that maps `CoreError` (and other failure modes) to
//! stable exit codes consumers can branch on.

use spiritstream_core::CoreError;

#[derive(Debug, thiserror::Error)]
pub enum CliError {
    #[error("{0}")]
    Core(#[from] CoreError),

    #[error("io: {0}")]
    Io(String),

    #[error("serialization: {0}")]
    Serialization(String),

    #[error("invalid argument: {0}")]
    Argument(String),

    /// Service-level "not ready" / "transient failure" — distinct from
    /// `Argument` so retry-loop scripts (`until cli system ready; do
    /// sleep 5; done`) can tell "the service hasn't come up yet" from
    /// "I called you with bad flags." Maps to exit 69 (EX_UNAVAILABLE),
    /// mirroring `CoreError::NetworkError`.
    #[error("service unavailable: {0}")]
    Unavailable(String),
}

impl CliError {
    /// POSIX-style exit code. Inspired by `sysexits.h` where applicable, with
    /// SpiritStream-specific codes for domain failures.
    pub fn exit_code(&self) -> u8 {
        match self {
            CliError::Core(err) => match err {
                CoreError::ProfileNotFound { .. } => 4,
                CoreError::PasswordRequired { .. } => 5,
                CoreError::PasswordIncorrect => 6,
                CoreError::PasswordTooShort { .. } => 7, // EX_USAGE — caller supplied invalid input
                CoreError::InvalidStreamConfig { .. } => 7,
                CoreError::ValidationFailed { .. } => 7,
                CoreError::EncoderUnavailable { .. } => 8,
                CoreError::PortConflict { .. } => 9,
                CoreError::ProfileAlreadyExists { .. } => 9,
                CoreError::FfmpegNotFound => 10,
                CoreError::PathOutsideAllowedRoot { .. } => 13,
                CoreError::NotFound { .. } => 4,
                CoreError::RateLimited { .. } => 14,
                CoreError::Unauthorized => 15,
                CoreError::NoActiveProfile => 16,
                CoreError::ChatPlatformNotConnected { .. } => 17,
                CoreError::ChatSendingDisabled { .. } => 18,
                CoreError::ChatMessageLengthExceeded { .. } => 7,
                CoreError::ChatBlockedByPii { .. } => 19,
                CoreError::NotImplemented { .. } => 78, // EX_CONFIG
                CoreError::NetworkError { .. } => 69,   // EX_UNAVAILABLE
                CoreError::Internal { .. } => 70,       // EX_SOFTWARE
            },
            CliError::Argument(_) => 64,      // EX_USAGE
            CliError::Unavailable(_) => 69,   // EX_UNAVAILABLE
            CliError::Io(_) => 74,            // EX_IOERR
            CliError::Serialization(_) => 65, // EX_DATAERR
        }
    }

    /// Stable error kind string for JSON output. Consumers can branch on this
    /// without needing to parse the human-readable message. For `Core`
    /// failures it delegates to `CoreError::kind()` so the CLI and HTTP
    /// transports surface identical kinds for the same underlying error.
    pub fn kind(&self) -> &'static str {
        match self {
            CliError::Core(err) => err.kind(),
            CliError::Argument(_) => "argument",
            CliError::Unavailable(_) => "unavailable",
            CliError::Io(_) => "io",
            CliError::Serialization(_) => "serialization",
        }
    }
}

impl From<std::io::Error> for CliError {
    fn from(err: std::io::Error) -> Self {
        CliError::Io(err.to_string())
    }
}

//! `spiritstream-cli` — first-class headless client for SpiritStream.
//!
//! Every operation the React UI can perform is reachable from this binary.
//! Commands dispatch **in-process** against `spiritstream-core::ServiceRegistry`
//! — there is no HTTP round-trip. That property is what makes the test
//! substrate under `tests/integration/` reproducible: every test is a shell
//! invocation against a `--data-dir <tmpdir>` install with deterministic JSON
//! output and stable exit codes.
//!
//! Run-of-the-mill commands print one JSON document on stdout. Use `--pretty`
//! for indented output (human review) and `--quiet` to suppress informational
//! log lines on stderr.

mod commands;
mod error;
mod output;
mod registry;

use std::process::ExitCode;

use clap::{Parser, Subcommand};

use crate::error::CliError;
use crate::output::Output;

#[derive(Debug, Parser)]
#[command(
    name = "spiritstream-cli",
    version = env!("CARGO_PKG_VERSION"),
    about = "Headless client for SpiritStream — in-process dispatch into spiritstream-core.",
    long_about = None,
)]
struct Cli {
    /// Override the data directory. Defaults to the platform user data dir
    /// (same lookup as the desktop sidecar), or `$SPIRITSTREAM_DATA_DIR`
    /// if set.
    #[arg(long, global = true, env = "SPIRITSTREAM_DATA_DIR")]
    data_dir: Option<std::path::PathBuf>,

    /// Override the themes directory (mostly useful for tests).
    #[arg(long, global = true, env = "SPIRITSTREAM_THEMES_DIR")]
    themes_dir: Option<std::path::PathBuf>,

    /// Pretty-print JSON output for human reading.
    #[arg(long, global = true)]
    pretty: bool,

    /// Suppress non-error log lines on stderr.
    #[arg(long, global = true)]
    quiet: bool,

    #[command(subcommand)]
    command: Command,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Manage stream profiles.
    Profile {
        #[command(subcommand)]
        command: commands::profile::ProfileCmd,
    },
    /// Observe and control RTMP streams.
    Stream {
        #[command(subcommand)]
        command: commands::stream::StreamCmd,
    },
    /// Chat platform connections and messaging.
    Chat {
        #[command(subcommand)]
        command: commands::chat::ChatCmd,
    },
    /// Inspect system capabilities (encoders, FFmpeg).
    System {
        #[command(subcommand)]
        command: commands::system::SystemCmd,
    },
    /// Inspect or update global settings.
    Settings {
        #[command(subcommand)]
        command: commands::settings::SettingsCmd,
    },
    /// List available themes.
    Theme {
        #[command(subcommand)]
