        }
        Err(e) => {
            if e.to_string().to_lowercase().contains("already connected") {
                log::debug!("Trovo chat already connected");
            } else {
                log::warn!("Failed to auto-connect Trovo chat: {e}");
                event_bus.emit(
                    "chat_auto_connect_failed",
                    json!({ "platform": "trovo", "kind": e.kind(), "error": e.to_string() }),
                );
            }
        }
    }
}

/// Auto-connect TikTok chat — read-only protobuf-over-WebSocket.
/// `session_token: None` because the public stream requires no auth;
/// the connector resolves the room id internally via the upstream
/// `piratetok-live-rs` crate.
pub(crate) async fn connect_tiktok_chat(
    chat_manager: &Arc<ChatManager>,
    chat_settings: &ChatSettings,
    event_bus: &EventBus,
) {
    let config = ChatConfig {
        platform: ChatPlatform::TikTok,
        enabled: true,
        credentials: ChatCredentials::TikTok {
            username: chat_settings.tiktok_username.clone(),
            session_token: None,
        },
    };
    match chat_manager.connect(config).await {
        Ok(()) => {
            log::info!("Auto-connected to TikTok chat");
            event_bus.emit("chat_auto_connected", json!({ "platform": "tiktok" }));
        }
        Err(e) => {
            if e.to_string().to_lowercase().contains("already connected") {
                log::debug!("TikTok chat already connected");
            } else {
                log::warn!("Failed to auto-connect TikTok chat: {e}");
                event_bus.emit(
                    "chat_auto_connect_failed",
                    json!({ "platform": "tiktok", "kind": e.kind(), "error": e.to_string() }),
                );
            }
        }
    }
}

/// Auto-connect Kick chat. Anonymous Pusher subscription works
/// without auth; if `chat_settings.kick_send_enabled` is on and the
/// profile has a Kick OAuth account, the send-path credentials get
/// captured at `connect()` time so outbound chat works without a
/// reconnect dance. `oauth.kick.user_id` doubles as the
/// `broadcaster_user_id` Kick's REST POST expects (Kick's "me" user
/// IS the broadcaster from the sender's perspective).
pub(crate) async fn connect_kick_chat(
    chat_manager: &Arc<ChatManager>,
    chat_settings: &ChatSettings,
    profile_settings: &ProfileSettings,
    event_bus: &EventBus,
) {
    let (oauth_token, broadcaster_user_id) = if chat_settings.kick_send_enabled
        && !profile_settings.oauth.kick.access_token.is_empty()
        && !profile_settings.oauth.kick.user_id.is_empty()
    {
        let broadcaster = profile_settings.oauth.kick.user_id.parse::<u64>().ok();
        (
            Some(profile_settings.oauth.kick.access_token.clone()),
            broadcaster,
        )
    } else {
        (None, None)
    };

    let config = ChatConfig {
        platform: ChatPlatform::Kick,
        enabled: true,
        credentials: ChatCredentials::Kick {
            channel: chat_settings.kick_channel.clone(),
            oauth_token,
            broadcaster_user_id,
        },
    };
    match chat_manager.connect(config).await {
        Ok(()) => {
            log::info!("Auto-connected to Kick chat");
            event_bus.emit("chat_auto_connected", json!({ "platform": "kick" }));
        }
        Err(e) => {
            if e.to_string().to_lowercase().contains("already connected") {
                log::debug!("Kick chat already connected");
            } else {
                log::warn!("Failed to auto-connect Kick chat: {e}");
                event_bus.emit(
                    "chat_auto_connect_failed",
                    json!({ "platform": "kick", "kind": e.kind(), "error": e.to_string() }),
                );
            }
        }
    }
}


/// Auto-disconnect all chat platforms when all streams stop.
pub(crate) async fn auto_disconnect_chat_platforms(
    chat_manager: Arc<ChatManager>,
    event_bus: EventBus,
) {
    if chat_manager.is_any_connected().await {
        match chat_manager.disconnect_all("streams_stopped").await {
            Ok(()) => {
                log::info!("Auto-disconnected all chat platforms");
                event_bus.emit("chat_auto_disconnected", json!({}));
            }
            Err(e) => {
                log::warn!("Failed to auto-disconnect chat: {e}");
            }
        }
    }
}


/// Background task to retry chat connections when a platform drops.
/// Subscribe to the server's own event bus and auto-retry failed streams.
/// Replaces the frontend's `handleAutoRetry` (in `useStreamStats.ts`) which
/// previously listened to `stream_error` and called `api.stream.retry()`.
/// Backend now owns both the policy (in `FFmpegHandler::retry_group`) and
/// the trigger. The frontend just renders `stream_retry_attempt` events.
pub(crate) async fn start_auto_retry_task(state: AppState) {
    let mut rx = state.event_bus.subscribe();
    tokio::spawn(async move {
        loop {
            let evt = match rx.recv().await {
                Ok(e) => e,
                Err(broadcast::error::RecvError::Lagged(_)) => continue,
                Err(broadcast::error::RecvError::Closed) => break,
            };
            if evt.event != "stream_error" {
                continue;
            }
            let Some(group_id) = evt
                .payload
                .get("groupId")
                .and_then(|v| v.as_str())
                .map(String::from)
            else {
                continue;
            };
            // Spawn the retry in a blocking task — retry_group_internal sleeps
            // for the backoff window which must not block the runtime.
            let handler = state.ffmpeg_handler.clone();
            let event_sink: Arc<dyn EventSink> = Arc::new(state.event_bus.clone());
            tokio::task::spawn_blocking(move || {
                if let Err(err) = handler.retry_group(&group_id, event_sink) {
                    log::warn!("[auto_retry] retry_group({group_id}) failed: {err}");
                }
            });
        }
    });
}

pub(crate) async fn start_chat_reconnect_task(state: AppState) {
    tokio::spawn(async move {
        let mut last_attempts: HashMap<ChatPlatform, Instant> = HashMap::new();
        let mut interval = tokio::time::interval(std::time::Duration::from_secs(15));
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);

        loop {
            interval.tick().await;

            if state.ffmpeg_handler.active_count() == 0 {
                continue;
            }

            let statuses = state.chat_manager.get_status().await;
            for status in statuses {
                if status.status != spiritstream_core::models::ChatConnectionStatus::Error {
                    continue;
                }

                if last_attempts
                    .get(&status.platform)
                    .map(|last| last.elapsed() < std::time::Duration::from_secs(30))
                    .unwrap_or(false)
                {
                    continue;
                }
                last_attempts.insert(status.platform, Instant::now());

                let profile_settings = match get_active_profile_settings(&state).await {
                    Some(s) => s,
                    None => {
                        log::warn!("Chat reconnect: no active profile settings");
                        continue;
                    }
                };
                let chat_settings = state.chat_manager.profile_chat_settings().await;

                match status.platform {
                    ChatPlatform::Twitch => {
                        if chat_settings.twitch_channel.is_empty() {
                            continue;
                        }
                        connect_twitch_chat(
                            &state.chat_manager,
                            &chat_settings,
                            &profile_settings,
                            &state.event_bus,
                        )
                        .await;
                    }
                    ChatPlatform::Trovo => {
                        if chat_settings.trovo_channel_id.is_empty() {
                            continue;
                        }
                        connect_trovo_chat(&state.chat_manager, &chat_settings, &state.event_bus)
                            .await;
                    }
                    ChatPlatform::YouTube => {
                        let has_oauth = !chat_settings.youtube_use_api_key
                            && !profile_settings.oauth.youtube.access_token.is_empty();
                        let has_api_key = chat_settings.youtube_use_api_key
                            && !chat_settings.youtube_api_key.is_empty();
                        if chat_settings.youtube_channel_id.is_empty()
                            || (!has_oauth && !has_api_key)
                        {
                            continue;
                        }
                        tokio::spawn(connect_youtube_chat_with_retry(state.clone()));
                    }
                    _ => {}
                }
            }
        }
    });
}

pub(crate) fn parse_bool(value: &str) -> Option<bool> {
    match value.trim().to_lowercase().as_str() {
        "1" | "true" | "yes" | "on" => Some(true),
        "0" | "false" | "no" | "off" => Some(false),
        _ => None,
    }
}

/// Refuse to start in cloud mode without the safety net.
///
/// Three preconditions are checked, all load-bearing for a public
/// deployment:
///
/// 1. **Strong API token**: `SPIRITSTREAM_API_TOKEN` (or, falling back,
///    a profile-stored backend token) must be present and at least 32
///    characters. Anything weaker is brute-force-trivial over the
///    public internet even with the lockout in place.
/// 2. **TLS in front**: the operator must set
///    `SPIRITSTREAM_BEHIND_TLS_PROXY=1` to declare that a reverse
///    proxy (Caddy / Traefik / nginx) terminates TLS in front of the
///    server. Cloud-mode HTTP-only is never acceptable — bearer
///    tokens and session cookies would flow in plaintext.
/// 3. **No CORS wildcard** (H1): `SPIRITSTREAM_CORS_ORIGINS` must not
///    contain `*`. A wildcard in cloud mode lets any origin send
///    credentialed requests, defeating the same-origin guard that the
///    Sec-Fetch-Site CSRF check leans on. Explicit allow-list only.
///
/// `pre_deploy_mode == "cloud"` is the only trigger; localhost dev
/// and `desktop` mode never hit this path.
pub(crate) fn enforce_cloud_mode_preconditions(
    auth_token: &Option<String>,
    tls_declared: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    enforce_cloud_mode_preconditions_with_origins(
        auth_token,
        tls_declared,
        std::env::var("SPIRITSTREAM_CORS_ORIGINS").ok().as_deref(),
    )
}

/// Pure inner used by tests. Takes the CORS env value explicitly so
/// parallel test runs don't trip on shared global env mutation.
pub(crate) fn enforce_cloud_mode_preconditions_with_origins(
    auth_token: &Option<String>,
    tls_declared: bool,
    cors_origins: Option<&str>,
) -> Result<(), Box<dyn std::error::Error>> {
    const MIN_TOKEN_LEN: usize = 32;
    let token_ok = auth_token
        .as_deref()
        .map(|t| t.len() >= MIN_TOKEN_LEN)
        .unwrap_or(false);
    if !token_ok {
        return Err(format!(
            "SPIRITSTREAM_DEPLOY_MODE=cloud refuses to start: \
             SPIRITSTREAM_API_TOKEN must be ≥ {MIN_TOKEN_LEN} characters. \
             Generate one with `openssl rand -base64 32`."
        )
        .into());
    }
    if !tls_declared {
        return Err("SPIRITSTREAM_DEPLOY_MODE=cloud refuses to start: \
             set SPIRITSTREAM_BEHIND_TLS_PROXY=1 once a TLS-terminating \
             reverse proxy (Caddy / Traefik / nginx) is in place. \
             Cloud deployments without TLS leak session tokens in cleartext."
            .into());
    }
    if let Some(value) = cors_origins {
        if value.split(',').any(|entry| entry.trim() == "*") {
            return Err("SPIRITSTREAM_DEPLOY_MODE=cloud refuses to start: \
                 SPIRITSTREAM_CORS_ORIGINS contains '*'. Wildcard CORS in cloud \
                 mode lets any browser origin issue credentialed requests, \
                 bypassing the Sec-Fetch-Site CSRF guard. Set an explicit \
                 allow-list of origins instead."
                .into());
        }
    }
    log::info!(
        "Cloud-mode preconditions satisfied: strong API token + TLS-fronted + explicit CORS allow-list."
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn strong_token() -> Option<String> {
        Some("0123456789abcdef0123456789abcdef".into())
    }

    #[test]
    fn cloud_mode_refuses_cors_wildcard() {
        let err = enforce_cloud_mode_preconditions_with_origins(
            &strong_token(),
            true,
            Some("https://app.example.com, * , https://other.example.com"),
        )
        .expect_err("wildcard CORS must be refused in cloud mode");
        let msg = err.to_string();
        assert!(
            msg.contains("'*'"),
            "error must call out the wildcard offender: {msg}",
        );
    }

    #[test]
    fn cloud_mode_accepts_explicit_origin_list() {
        let result = enforce_cloud_mode_preconditions_with_origins(
            &strong_token(),
            true,
            Some("https://app.example.com,https://admin.example.com"),
        );
        assert!(result.is_ok(), "explicit origins must be accepted: {result:?}");
    }

    #[test]
    fn cloud_mode_accepts_unset_origins() {
        // No SPIRITSTREAM_CORS_ORIGINS at all is fine — CORS layer
        // defaults to no allow-list, which is the most restrictive
        // posture available.
        let result = enforce_cloud_mode_preconditions_with_origins(&strong_token(), true, None);
        assert!(result.is_ok());
    }
}

use std::env;
use std::sync::Arc;

use axum::http::{header, HeaderName, HeaderValue, Method};
use tower_http::cors::{AllowOrigin, CorsLayer};

/// Parse the `SPIRITSTREAM_CORS_ORIGINS` env var into a flat allow-list.
/// Shared by `build_cors_layer` and the CSRF middleware so the policy can
/// never drift between the browser-enforced CORS check and the
/// server-enforced CSRF fallback.
pub(crate) fn allowed_origins_from_env() -> Vec<String> {
    let cors_origins = env::var("SPIRITSTREAM_CORS_ORIGINS")
        .unwrap_or_else(|_| "http://localhost:*,http://127.0.0.1:*,tauri://localhost,http://tauri.localhost,https://tauri.localhost".to_string());
    cors_origins
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

/// True if `origin` matches any pattern in `allowed`. Patterns ending in
/// `:*` wildcard the port (e.g. `http://localhost:*` matches any port).
pub(crate) fn origin_matches(origin: &str, allowed: &[String]) -> bool {
    allowed.iter().any(|pattern| {
        if let Some(prefix) = pattern.strip_suffix(":*") {
            origin.starts_with(prefix) && origin[prefix.len()..].starts_with(':')
        } else {
            origin == pattern
        }
    })
}

pub(crate) fn build_cors_layer(allowed_origins: Arc<Vec<String>>) -> CorsLayer {
    CorsLayer::new()
        .allow_origin(AllowOrigin::predicate(move |origin: &HeaderValue, _| {
            let Ok(origin_str) = origin.to_str() else {
                return false;
            };
            origin_matches(origin_str, &allowed_origins)
        }))
        .allow_methods([
            Method::GET,
            Method::POST,
            Method::PUT,
            Method::PATCH,
            Method::DELETE,
            Method::OPTIONS,
        ])
        .allow_headers([
            header::CONTENT_TYPE,
            header::COOKIE,
            header::AUTHORIZATION,
            // Destructive ops (clear-data, rotate-machine-key,
            // revoke-all-sessions) carry a one-shot confirm token in this
            // header. Without it on the CORS allow-list, the preflight
            // OPTIONS response omits the header and the browser blocks
            // the actual POST with a generic "Load failed". Plain-fetch
            // requests don't show this because they have no custom headers
            // to preflight on.
            HeaderName::from_static("x-confirm-token"),
        ])
        .allow_credentials(true)
}

//! HTTP error mapping for `spiritstream_core::CoreError`.
//!
//! This is the *only* place in the entire HTTP transport where `CoreError`
//! becomes an HTTP status code and a JSON body. Handlers return
//! `Result<Json<T>, ApiError>` and rely on `From<CoreError> for ApiError` so
//! they never write status mapping inline.
//!
//! Wire-shape contract:
//! - Successful responses are the handler's `Json<T>` value directly.
//! - Error responses are `{ kind: "...", details: { ... } }` exactly as
//!   `CoreError` serializes with `#[serde(tag = "kind", content = "details")]`.
//! - `CoreError::Internal` is redacted on the wire — the `context` field is
//!   logged server-side but **never** sent to the client.

use axum::http::{header, HeaderValue, StatusCode};
use axum::response::{IntoResponse, Json, Response};
use serde_json::json;
use spiritstream_core::CoreError;

/// Wrap a `CoreError` so it can be returned from any Axum handler.
#[derive(Debug)]
pub struct ApiError(pub CoreError);

impl From<CoreError> for ApiError {
    fn from(err: CoreError) -> Self {
        ApiError(err)
    }
}

// Chain conversions: any error that has `From<E> for CoreError` becomes an
// `ApiError` without each handler writing `.map_err(...)`. Keeps the wire
// contract (kind/details + redacted Internal) intact while letting handlers
// stay bare `?` instead of inlined adaptor closures.
impl From<serde_json::Error> for ApiError {
    fn from(err: serde_json::Error) -> Self {
        ApiError(CoreError::from(err))
    }
}

impl From<std::io::Error> for ApiError {
    fn from(err: std::io::Error) -> Self {
        ApiError(CoreError::from(err))
    }
}

impl From<tokio::task::JoinError> for ApiError {
    fn from(err: tokio::task::JoinError) -> Self {
        ApiError(CoreError::Internal {
            context: format!("Task join error: {err}"),
        })
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let status = status_for(&self.0);

        // RFC 9110 — 429 responses SHOULD include `Retry-After`. The
        // `CoreError::RateLimited` variant already carries the wait window;
        // surface it here so callers (auth login backoff, future per-endpoint
        // limits) don't have to re-implement header injection per handler.
        let retry_after_header = match &self.0 {
            CoreError::RateLimited { retry_after_secs } => {
                Some(HeaderValue::from_str(&retry_after_secs.to_string()).ok()).flatten()
            }
            _ => None,
        };

        // The `Internal` variant carries `context` that may include service-
        // internal detail (file paths, error messages). Log it server-side
        // and return an opaque body to the client.
        let body = match &self.0 {
            CoreError::Internal { context } => {
                log::error!("internal error: {context}");
                json!({ "kind": "internal" })
            }
            other => {
                // Defense in depth: every other variant gets piped
                // through `redact_payload` before serialisation. If a
                // future variant ever carries a stream key, OAuth
                // token, or anything that matches the redact regexes,
                // the wire body is scrubbed even though no individual
                // variant is supposed to carry secrets today.
                let raw =
                    serde_json::to_value(other).unwrap_or_else(|_| json!({ "kind": "internal" }));
                crate::redact_payload(&raw)
            }
        };

        match retry_after_header {
            Some(value) => (status, [(header::RETRY_AFTER, value)], Json(body)).into_response(),
            None => (status, Json(body)).into_response(),
        }
    }
}

/// HTTP status mapping. Kept as a free function so unit tests can assert it
/// without going through `IntoResponse`.
fn status_for(err: &CoreError) -> StatusCode {
    match err {
        CoreError::ProfileNotFound { .. } => StatusCode::NOT_FOUND,
        CoreError::ProfileAlreadyExists { .. } => StatusCode::CONFLICT,
        CoreError::PasswordRequired { .. } => StatusCode::UNAUTHORIZED,
        CoreError::PasswordIncorrect => StatusCode::UNAUTHORIZED,
        // Weak-password rejection is a client validation failure (400),
        // NOT an authentication failure (401). The user supplied a password
        // we refused to accept — they aren't "wrong" credentials yet.
        CoreError::PasswordTooShort { .. } => StatusCode::BAD_REQUEST,
        CoreError::Unauthorized => StatusCode::UNAUTHORIZED,
        CoreError::NoActiveProfile => StatusCode::CONFLICT,
        CoreError::ChatPlatformNotConnected { .. } => StatusCode::UNPROCESSABLE_ENTITY,
        CoreError::ChatSendingDisabled { .. } => StatusCode::UNPROCESSABLE_ENTITY,
        CoreError::ChatMessageLengthExceeded { .. } => StatusCode::BAD_REQUEST,
        // PII filter rejection. 422 (Unprocessable Entity)
        // mirrors the other "rejected by policy" chat errors. The
        // response carries only the phrase_id, never the matched text.
        CoreError::ChatBlockedByPii { .. } => StatusCode::UNPROCESSABLE_ENTITY,
        CoreError::InvalidStreamConfig { .. } => StatusCode::BAD_REQUEST,
        CoreError::ValidationFailed { .. } => StatusCode::BAD_REQUEST,
        CoreError::EncoderUnavailable { .. } => StatusCode::UNPROCESSABLE_ENTITY,
        CoreError::PortConflict { .. } => StatusCode::CONFLICT,
        CoreError::PathOutsideAllowedRoot { .. } => StatusCode::FORBIDDEN,
        CoreError::NotFound { .. } => StatusCode::NOT_FOUND,
        // FFmpeg is a server-side environment dependency, not request data.
        // RFC 9110: 503 Service Unavailable signals the server is
        // currently unable to handle the request due to a backend condition.
        // 422 (Unprocessable Entity) would imply the client could fix the
        // payload — they can't; FFmpeg has to be installed on the host.
        CoreError::FfmpegNotFound => StatusCode::SERVICE_UNAVAILABLE,
        CoreError::NetworkError { .. } => StatusCode::BAD_GATEWAY,
        CoreError::RateLimited { .. } => StatusCode::TOO_MANY_REQUESTS,
        CoreError::NotImplemented { .. } => StatusCode::NOT_IMPLEMENTED,
        CoreError::Internal { .. } => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use spiritstream_core::errors::ValidationIssue;

    #[test]
    fn status_mapping_pins_user_facing_codes() {
        assert_eq!(
            status_for(&CoreError::ProfileNotFound { name: "x".into() }),
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            status_for(&CoreError::PasswordIncorrect),
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(
            status_for(&CoreError::PortConflict {
                port: 1935,
                owner: "y".into()
            }),
            StatusCode::CONFLICT
        );
        assert_eq!(
            status_for(&CoreError::ValidationFailed {
                reasons: vec![ValidationIssue {
                    code: "x".into(),
                    message: "y".into(),
                    path: None
                }],
            }),
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            status_for(&CoreError::Internal {
                context: "leak-this-server-side-only".into()
            }),
            StatusCode::INTERNAL_SERVER_ERROR
        );
    }

    /// New chat-error variants must serialize to the wire as
    /// `{ kind, details }` so clients can branch on `kind` without parsing
    /// the human-readable message. Pins the variant tag + payload shape
    /// against accidental renames or schema drift.
    #[test]
    fn chat_platform_not_connected_wire_shape() {
        let err = CoreError::ChatPlatformNotConnected {
            platform: "twitch".into(),
        };
        let body = serde_json::to_value(&err).expect("variant must serialize");
        assert_eq!(body["kind"], "chat_platform_not_connected");
        assert_eq!(body["details"]["platform"], "twitch");
        assert_eq!(status_for(&err), StatusCode::UNPROCESSABLE_ENTITY);
    }

    #[test]
    fn chat_sending_disabled_wire_shape() {
        let err = CoreError::ChatSendingDisabled {
            platform: "youtube".into(),
        };
        let body = serde_json::to_value(&err).expect("variant must serialize");
        assert_eq!(body["kind"], "chat_sending_disabled");
        assert_eq!(body["details"]["platform"], "youtube");
        assert_eq!(status_for(&err), StatusCode::UNPROCESSABLE_ENTITY);
    }

    #[test]
    fn chat_message_length_exceeded_wire_shape() {
        let err = CoreError::ChatMessageLengthExceeded {
            platform: "twitch".into(),
            limit: 500,
            actual: 612,
        };
        let body = serde_json::to_value(&err).expect("variant must serialize");
        assert_eq!(body["kind"], "chat_message_length_exceeded");
        assert_eq!(body["details"]["platform"], "twitch");
        assert_eq!(body["details"]["limit"], 500);
        assert_eq!(body["details"]["actual"], 612);
        assert_eq!(status_for(&err), StatusCode::BAD_REQUEST);
    }

    /// `NoActiveProfile` is the "client picked a profile-dependent
    /// action but no profile is active" variant. No payload — clients branch
    /// on `kind` alone. HTTP maps to 409 so it's distinguishable from
    /// `Unauthorized` (401) which means "re-authenticate".
    #[test]
    fn no_active_profile_wire_shape() {
        let err = CoreError::NoActiveProfile;
        let body = serde_json::to_value(&err).expect("variant must serialize");
        assert_eq!(body["kind"], "no_active_profile");
        assert_eq!(status_for(&err), StatusCode::CONFLICT);
    }

    #[test]
    fn internal_variant_is_redacted_in_body() {
        let resp = ApiError(CoreError::Internal {
            context: "do not leak".into(),
        })
        .into_response();
        assert_eq!(resp.status(), StatusCode::INTERNAL_SERVER_ERROR);
        // Body inspection happens via the integration test in http_surface.rs;
        // here we just confirm the status mapping + that conversion didn't panic.
    }
}

use serde::Serialize;
use serde_json::Value;
use tokio::sync::broadcast;

use spiritstream_core::services::EventSink;

#[derive(Clone, Serialize)]
pub(crate) struct ServerEvent {
    pub(crate) event: String,
    pub(crate) payload: Value,
}

#[derive(Clone)]
pub(crate) struct EventBus {
    sender: broadcast::Sender<ServerEvent>,
}

impl EventBus {
    pub(crate) fn new() -> Self {
        let (sender, _) = broadcast::channel(256);
        Self { sender }
    }

    pub(crate) fn subscribe(&self) -> broadcast::Receiver<ServerEvent> {
        self.sender.subscribe()
    }
}

impl EventSink for EventBus {
    fn emit(&self, event: &str, payload: Value) {
        let _ = self.sender.send(ServerEvent {
            event: event.to_string(),
            payload,
        });
    }
}

