use std::fs::OpenOptions;
use std::io::Write;
use std::sync::Mutex;

use chrono::Local;
use log::{Level, LevelFilter, Log, Metadata, Record};
use serde_json::json;

use crate::events::EventBus;
use crate::redaction::mask_sensitive;
use spiritstream_core::services::EventSink;

pub(crate) struct ServerLogger {
    file: Mutex<std::fs::File>,
    event_bus: EventBus,
    level: LevelFilter,
}

impl ServerLogger {
    pub(crate) fn new(
        log_dir: &std::path::Path,
        event_bus: EventBus,
    ) -> Result<Self, Box<dyn std::error::Error>> {
        let log_path = log_dir.join("spiritstream-server.log");
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(log_path)?;
        Ok(Self {
            file: Mutex::new(file),
            event_bus,
            level: LevelFilter::Info,
        })
    }
}

impl Log for ServerLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.level() <= self.level
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }

        let timestamp = Local::now();
        let target = record.target();
        let level = record.level();
        let raw_message = format!("{}", record.args());
        // Every log line passes through `mask_sensitive`
        // before it hits disk so token-shaped strings, RTMP keys, and
        // ${TOKEN} expansions can't leak via the log file. Enforced at
        // the boundary, not per call site.
        let message = mask_sensitive(&raw_message);

        // Structured JSON output when SPIRITSTREAM_LOG_FORMAT=json.
        // Default stays bracketed-text for human-readable tail-following
        // during development. Both formats apply redaction identically.
        let json_format = std::env::var("SPIRITSTREAM_LOG_FORMAT")
            .map(|v| v.eq_ignore_ascii_case("json"))
            .unwrap_or(false);
        let line = if json_format {
            // Hand-roll JSON so we don't take a serde dep for an
            // already-load-bearing fast path. Field order is stable
            // for downstream log shippers.
            format!(
                r#"{{"ts":"{}","level":"{}","target":"{}","msg":{}}}"#,
                timestamp.to_rfc3339(),
                level,
                target.replace('"', "\\\""),
                serde_json::to_string(&message).unwrap_or_else(|_| "\"\"".into()),
            )
        } else {
            let date = timestamp.format("%Y-%m-%d");
            let time = timestamp.format("%H:%M:%S");
            format!("[{date}][{time}][{target}][{level}] {message}")
        };

        if let Ok(mut file) = self.file.try_lock() {
            if let Err(e) = writeln!(file, "{line}") {
                eprintln!("Failed to write log: {e}");
            }
            // Flush after every write to ensure logs persist on crash.
            if let Err(e) = file.flush() {
                eprintln!("Failed to flush log: {e}");
            }
        }

        let level_number = match level {
            Level::Error => 1,
            Level::Warn => 2,
            Level::Info => 3,
            Level::Debug => 4,
            Level::Trace => 5,
        };

        self.event_bus.emit(
            "log://log",
            json!({ "level": level_number, "message": message, "target": target }),
        );
    }

    fn flush(&self) {
        if let Ok(mut file) = self.file.try_lock() {
            let _ = file.flush();
        }
    }
}

pub(crate) fn init_logger(
    log_dir: &std::path::Path,
    event_bus: EventBus,
) -> Result<(), Box<dyn std::error::Error>> {
    let logger = ServerLogger::new(log_dir, event_bus)?;
    log::set_boxed_logger(Box::new(logger))?;
    log::set_max_level(LevelFilter::Info);
    Ok(())
}

use std::net::SocketAddr;

use axum::{
    extract::{ConnectInfo, State},
    http::{header, HeaderMap, HeaderValue, Method, Request, StatusCode},
    middleware::Next,
    response::{IntoResponse, Response},
    Json,
};
use tower_cookies::Cookies;

use crate::auth_helpers::{bearer_token, verify_token};
use crate::cors::origin_matches;
use crate::rate_limit::KeyedLimiter;
use crate::{AppState, InvokeResponse, AUTH_COOKIE_NAME};

/// Authentication middleware - check for valid session cookie.
pub(crate) async fn auth_middleware(
    State(state): State<AppState>,
    cookies: Cookies,
    headers: HeaderMap,
    request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    // If no token configured, allow all requests
    if state.auth_token.is_none() {
        return next.run(request).await;
    }

    // Cookie must exist AND be in the active-session set.
    // The MutexGuard MUST drop before any `await` or the future stops
    // being `Send`; we compute the predicate first, then await.
    let session_valid = cookies
        .get(AUTH_COOKIE_NAME)
        .map(|c| {
            let sessions = state
                .active_sessions
                .lock()
                .unwrap_or_else(|e| e.into_inner());
            sessions.contains(c.value())
        })
        .unwrap_or(false);
    if session_valid {
        return next.run(request).await;
    }

    // Also accept Bearer token for backwards compatibility and programmatic access
    if let Some(token) = bearer_token(&headers) {
        if let Some(expected) = state.auth_token.as_deref() {
            if verify_token(expected, token) {
                return next.run(request).await;
            }
        }
    }

    // No valid session
    let response = InvokeResponse {
        ok: false,
        data: None,
        error: Some("Authentication required".to_string()),
    };
    (StatusCode::UNAUTHORIZED, Json(response)).into_response()
}

/// Per-endpoint rate limiting middleware.
///
/// Inspects the route and picks the corresponding `KeyedLimiter` from
/// [`crate::rate_limit::EndpointRateLimiters`]. The key is the auth subject
/// when an auth cookie or Bearer token is present, otherwise the peer IP
/// from `ConnectInfo` (or `"unknown"` if the server is reached through a
/// path that doesn't surface `ConnectInfo` — primarily test harnesses).
///
/// Failures are returned as 429 with a JSON body matching the
/// `InvokeResponse` envelope so existing CLI parsers keep working.
pub(crate) async fn rate_limit_middleware(
    State(state): State<AppState>,
    ConnectInfo(addr): ConnectInfo<SocketAddr>,
    cookies: Cookies,
    headers: HeaderMap,
    request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    let path = request.uri().path();
    let method = request.method();

    let (limiter, key) = select_limiter(&state, path, method, &cookies, &headers, addr);

    match limiter.check_key(&key) {
        Ok(_) => next.run(request).await,
        Err(_) => {
            let response = InvokeResponse {
                ok: false,
                data: None,
                error: Some("Rate limit exceeded. Please try again later.".to_string()),
            };
            (StatusCode::TOO_MANY_REQUESTS, Json(response)).into_response()
        }
    }
}

/// Resolve the `(limiter, key)` pair for a request. Login uses peer IP
/// because the caller is by definition unauthenticated; every other
/// quota is keyed on the auth-subject hash so an attacker who steals one
/// token can't burn the entire shared budget.
fn select_limiter<'a>(
    state: &'a AppState,
    path: &str,
    method: &Method,
    cookies: &Cookies,
    headers: &HeaderMap,
    peer: SocketAddr,
) -> (&'a KeyedLimiter, String) {
    let peer_ip = peer.ip().to_string();
    let subject = subject_key(cookies, headers).unwrap_or_else(|| peer_ip.clone());

    if method == Method::POST && path == "/api/v1/auth/login" {
        return (&state.endpoint_limiters.login, peer_ip);
    }
    if method == Method::POST && path == "/api/v1/chat/messages" {
        return (&state.endpoint_limiters.chat_send, subject);
    }
    if method == Method::POST && path == "/api/v1/streams" {
        return (&state.endpoint_limiters.stream_start, subject);
    }
    if method == Method::POST && path.starts_with("/api/v1/oauth/") && path.ends_with("/flow") {
        return (&state.endpoint_limiters.oauth_flow, subject);
    }
    if method == Method::POST && path == "/api/v1/security/confirm-token" {
        return (&state.endpoint_limiters.confirm_token, subject);
    }
    if method == Method::POST && path == "/api/v1/security/sessions/revoke-all" {
        return (&state.endpoint_limiters.revoke_sessions, subject);
    }
    if method == Method::POST && path == "/api/v1/security/machine-key/rotate" {
        return (&state.endpoint_limiters.machine_key_rotate, subject);
    }
    (&state.endpoint_limiters.default_auth, subject)
}

/// Derive a stable rate-limit subject key from the request's
/// authentication material. Returns `None` when no auth material is
/// present — callers fall back to peer IP. The key is a SHA-256 of the
/// token bytes (truncated for compactness) so the secret never appears
/// in the limiter's in-memory state.
fn subject_key(cookies: &Cookies, headers: &HeaderMap) -> Option<String> {
    use sha2::{Digest, Sha256};

    let token = cookies
        .get(AUTH_COOKIE_NAME)
        .map(|c| c.value().to_string())
        .or_else(|| bearer_token(headers).map(|t| t.to_string()))?;

    let mut hasher = Sha256::new();
    hasher.update(token.as_bytes());
    let digest = hasher.finalize();
    Some(hex::encode(&digest[..16])) // 128-bit prefix is plenty for keying
}

/// Request-ID middleware. Generates a UUID v7 (time-ordered)
/// at the transport entry if the client didn't send one, then echoes
/// it back as `X-Request-Id` on the response. Downstream handlers can
/// read the value via the request extension; the value also flows into
/// `tracing` spans once the tracing migration runs.
pub(crate) async fn request_id_middleware(
    mut request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    let header_name = "x-request-id";
    let incoming = request
        .headers()
        .get(header_name)
        .and_then(|v| v.to_str().ok())
        .and_then(|s| {
            if s.len() <= 64 && !s.is_empty() {
                Some(s.to_string())
            } else {
                None
            }
        });
    let rid = RequestId(incoming.unwrap_or_else(|| uuid::Uuid::now_v7().to_string()));
    // Store on the request extension so handlers can pull it out via
    // `Extension<RequestId>`.
    request.extensions_mut().insert(rid.clone());

    let mut response = next.run(request).await;
    // Echo the canonical id on the response by reading the struct
    // field through `RequestId::as_str` — the field accessor is the
    // public contract `Extension<RequestId>` consumers use too.
    if let Ok(value) = HeaderValue::from_str(rid.as_str()) {
        response.headers_mut().insert("x-request-id", value);
    }
    response
}

/// Per-request correlation id. Constructed in `request_id_middleware`,
/// stored in the request extension, and echoed on the response via the
/// `X-Request-Id` header. Handlers extract it with `Extension<RequestId>`
/// when they want to thread the id into logs or audit entries.
#[derive(Debug, Clone)]
pub(crate) struct RequestId(pub String);

impl RequestId {
    pub(crate) fn as_str(&self) -> &str {
        &self.0
    }
}

/// CSRF guard.
///
/// Defends against cross-site request forgery on every state-changing
/// request (POST/PUT/PATCH/DELETE) and on WebSocket upgrades — a forged
/// upgrade equals a forged push channel, so we treat it the same as a
/// mutating request even though the underlying HTTP method is GET.
///
/// Policy:
/// 1. Pure-read methods (GET/HEAD/OPTIONS) without a WebSocket upgrade are
///    waved through — the browser will not run an authorized cross-site
///    mutation through them.
/// 2. `Sec-Fetch-Site` is the primary signal. `same-origin`, `same-site`,
///    and `none` (direct user action — typed URL, bookmark, redirect from
///    address bar) all pass. `cross-site` and `cross-origin` fall through
///    to the Origin allow-list so the Tauri 2 webview
///    (`tauri://localhost`, `https://tauri.localhost`) still works.
/// 3. The Origin allow-list is the secondary signal. It is also the only
///    check when `Sec-Fetch-Site` is absent (older browsers, CLI tools).
/// 4. Requests with neither header are allowed — these are CLI tools and
///    fall through to the existing `auth_middleware` token check.
///
/// Sources: OWASP CSRF cheat sheet (2024), MDN Sec-Fetch-Site.
pub(crate) async fn csrf_middleware(
    State(state): State<AppState>,
    request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    let method = request.method().clone();
    let headers = request.headers();

    let is_ws_upgrade = headers
        .get(header::UPGRADE)
        .and_then(|v| v.to_str().ok())
        .map(|s| s.eq_ignore_ascii_case("websocket"))
        .unwrap_or(false);

    let is_state_changing = matches!(
        method,
        Method::POST | Method::PUT | Method::PATCH | Method::DELETE
    );

    if !is_state_changing && !is_ws_upgrade {
        return next.run(request).await;
    }

    let sec_fetch_site = headers.get("Sec-Fetch-Site").and_then(|v| v.to_str().ok());
    let origin = headers.get(header::ORIGIN).and_then(|v| v.to_str().ok());

    let allowed = match sec_fetch_site {
        Some("same-origin") | Some("same-site") | Some("none") => true,
        Some(_) => origin
            .map(|o| origin_matches(o, &state.allowed_origins))
            .unwrap_or(false),
        None => match origin {
            Some(o) => origin_matches(o, &state.allowed_origins),
            None => true, // CLI tool — defer to auth_middleware
        },
    };

    if !allowed {
        let response = InvokeResponse {
            ok: false,
            data: None,
            error: Some("CSRF: request origin not allowed".to_string()),
        };
        return (StatusCode::FORBIDDEN, Json(response)).into_response();
    }

    next.run(request).await
}

use std::env;
use std::num::NonZeroU32;

use governor::{
    clock::DefaultClock, state::keyed::DefaultKeyedStateStore, Quota, RateLimiter,
};

use crate::DEFAULT_RATE_LIMIT_PER_MINUTE;

/// Per-endpoint rate limiter keyed by auth-subject (or peer IP
/// when no auth is available). One per high-risk route plus a `default_auth`
/// catch-all for everything else.
pub(crate) type KeyedLimiter =
    RateLimiter<String, DefaultKeyedStateStore<String>, DefaultClock>;

/// Per-endpoint rate limit configuration.
///
/// Each high-risk endpoint has its own keyed rate limiter. The `default`
/// catch-all replaces the prior single global governor quota. Burst sizes
/// follow the plan's recommended initial values; quotas can be tuned with
/// telemetry once observability lands.
pub(crate) struct EndpointRateLimiters {
    /// `POST /api/v1/auth/login` — 5/min keyed on peer IP. Per-account
    /// exponential backoff lives in `AuthService`.
    pub login: KeyedLimiter,
    /// `POST /api/v1/chat/messages` — 20/min sustained, burst 5,
    /// keyed on auth subject.
    pub chat_send: KeyedLimiter,
    /// `POST /api/v1/streams` — 10/min sustained, burst 2, keyed on
    /// auth subject. FFmpeg spawn is expensive.
    pub stream_start: KeyedLimiter,
    /// `POST /api/v1/oauth/*/flow` — 5/min keyed on auth subject.
    pub oauth_flow: KeyedLimiter,
    /// `POST /api/v1/security/confirm-token` — 5/min keyed on auth
    /// subject. Each destructive intent (clear_data, rotate_machine_key,
    /// enable_facebook_chat, …) gates on a freshly-issued token, so the
    /// legitimate user only needs a handful per minute. Tight bucket
    /// prevents an attacker who steals a token from flooding the
    /// confirm-token endpoint with noise to drown out the legit user's
    /// next destructive op behind a 429.
    pub confirm_token: KeyedLimiter,
    /// `POST /api/v1/security/sessions/revoke-all` — 3/min keyed on
    /// auth subject. Emergency "log everyone out" — should never need
    /// more than a few per minute. Keeps an attacker who steals a
    /// session from blocking the user's panic-revoke.
    pub revoke_sessions: KeyedLimiter,
    /// `POST /api/v1/security/machine-key/rotate` — 2/min keyed on
    /// auth subject. Extremely rare destructive op; tight bucket.
    pub machine_key_rotate: KeyedLimiter,
    /// Catch-all for every other authenticated request. Replaces the
    /// prior single global `NotKeyed` quota.
    pub default_auth: KeyedLimiter,
}

impl EndpointRateLimiters {
    pub(crate) fn from_env() -> Self {
        let default_quota = env::var("SPIRITSTREAM_RATE_LIMIT")
            .ok()
            .and_then(|v| v.parse::<u32>().ok())
            .and_then(NonZeroU32::new)
            .unwrap_or_else(|| NonZeroU32::new(DEFAULT_RATE_LIMIT_PER_MINUTE).unwrap());

        Self {
            login: RateLimiter::keyed(Quota::per_minute(NonZeroU32::new(5).unwrap())),
            chat_send: RateLimiter::keyed(
                Quota::per_minute(NonZeroU32::new(20).unwrap())
                    .allow_burst(NonZeroU32::new(5).unwrap()),
            ),
            stream_start: RateLimiter::keyed(
                Quota::per_minute(NonZeroU32::new(10).unwrap())
                    .allow_burst(NonZeroU32::new(2).unwrap()),
            ),
            oauth_flow: RateLimiter::keyed(Quota::per_minute(NonZeroU32::new(5).unwrap())),
            confirm_token: RateLimiter::keyed(Quota::per_minute(NonZeroU32::new(5).unwrap())),
            revoke_sessions: RateLimiter::keyed(Quota::per_minute(NonZeroU32::new(3).unwrap())),
            machine_key_rotate: RateLimiter::keyed(Quota::per_minute(NonZeroU32::new(2).unwrap())),
            default_auth: RateLimiter::keyed(Quota::per_minute(default_quota)),
        }
    }
}

use serde_json::Value;

/// Mask sensitive patterns in arbitrary text before logging.
///
/// Four pattern families are recognised:
/// 1. Token-shaped values that follow a keyword (`token=…`, `Authorization: …`,
///    `password: …`, etc.) — the trailing value is replaced with `[REDACTED]`.
/// 2. RTMP URLs of the form `rtmp[s]://host[:port]/app/STREAM_KEY` — the
///    trailing path segment (the stream key) is masked. Twitch and YouTube
///    embed the secret key as the last URL segment, so any RTMP URL in
///    logs that survives without masking leaks the broadcast key.
/// 3. FFmpeg-style `${TOKEN}` template expansions — the contents inside
///    the braces are replaced with `[REDACTED]` so command-line dumps
///    of templated args don't ship the secret.
/// 4. `ENC::` (V1) and `ENC2::` (V2) ciphertext blobs — replaced with
///    `[ENCRYPTED]` so encrypted-at-rest values don't appear verbatim.
pub(crate) fn mask_sensitive(text: &str) -> String {
    use regex::Regex;
    use std::sync::OnceLock;

    static TOKEN_RE: OnceLock<Regex> = OnceLock::new();
    static ENC_RE: OnceLock<Regex> = OnceLock::new();
    static RTMP_RE: OnceLock<Regex> = OnceLock::new();
    static TEMPLATE_RE: OnceLock<Regex> = OnceLock::new();

    let token_re = TOKEN_RE.get_or_init(|| {
        Regex::new(r#"(?i)(token|key|password|secret|bearer|oauth|access_token|refresh_token|authorization)[=:\s]+['"]?([A-Za-z0-9_\-./+]{20,})['"]?"#).unwrap()
    });
    let enc_re = ENC_RE.get_or_init(|| Regex::new(r#"ENC2?::[A-Za-z0-9+/=]{10,}"#).unwrap());
    let rtmp_re = RTMP_RE.get_or_init(|| {
        // rtmp[s]://host[:port]/app/STREAM_KEY[?query]
        // Captures up to and including the application path, then masks
        // the trailing stream-key segment. Allows query strings to
        // survive (useful for debugging) but redacts the key.
        Regex::new(r"(?i)(rtmps?://[^\s/]+(?:/[^\s/?#]+){1,2}/)([^\s/?#]+)").unwrap()
    });
    let template_re = TEMPLATE_RE.get_or_init(|| Regex::new(r"\$\{([^}]+)\}").unwrap());

    let result = token_re.replace_all(text, "$1=[REDACTED]");
    let result = enc_re.replace_all(&result, "[ENCRYPTED]");
    let result = rtmp_re.replace_all(&result, "$1[REDACTED]");
    template_re
        .replace_all(&result, "${[REDACTED]}")
        .to_string()
}

/// Redact sensitive keys from a JSON payload before logging.
pub(crate) fn redact_payload(value: &Value) -> Value {
    const REDACT_KEYS: &[&str] = &[
        "token",
        "key",
        "password",
        "secret",
        "oauth",
        "accessToken",
        "refreshToken",
        "oauthToken",
        "apiKey",
        "access_token",
        "refresh_token",
        "session_token",
        "webhookUrl",
    ];

    match value {
        Value::Object(map) => {
            let mut redacted = serde_json::Map::new();
            for (k, v) in map {
                let lower = k.to_lowercase();
                if REDACT_KEYS
                    .iter()
                    .any(|s| lower.contains(&s.to_lowercase()))
                {
                    if let Value::String(s) = v {
                        if !s.is_empty() {
                            redacted.insert(k.clone(), Value::String("[REDACTED]".to_string()));
                        } else {
                            redacted.insert(k.clone(), v.clone());
                        }
                    } else {
                        redacted.insert(k.clone(), Value::String("[REDACTED]".to_string()));
                    }
                } else {
                    redacted.insert(k.clone(), redact_payload(v));
                }
            }
            Value::Object(redacted)
        }
        Value::Array(arr) => Value::Array(arr.iter().map(redact_payload).collect()),
        other => other.clone(),
    }
}

/// Session-cookie hardening mode.
///
/// Selected at startup from `SPIRITSTREAM_COOKIE_MODE` (or auto-detected from
/// bind address and `SPIRITSTREAM_DEPLOY_MODE`). Controls the `Secure` and
/// `SameSite` attributes on the auth cookie:
///
/// * `SameOrigin` — Tauri 2 webview or Docker single-tenant. The UI and API
///   share an origin; strictest cookie policy applies.
///   `Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=604800`.
/// * `CrossOrigin` — browser UI served from a different host than the API
///   (e.g. cloud deploy with separate UI domain). `Strict` would drop the
///   cookie on cross-site navigation back to the UI, so `Lax` is used.
///   `Secure; HttpOnly; SameSite=Lax; Path=/; Max-Age=604800`.
/// * `LocalhostDev` — loopback HTTP development. `Secure` is dropped because
///   the browser refuses Secure cookies over plain HTTP, but `HttpOnly` and
///   `SameSite=Strict` still apply.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum SessionCookieMode {
    SameOrigin,
    CrossOrigin,
    LocalhostDev,
}

impl SessionCookieMode {
    /// Pure decision function — given an optional `SPIRITSTREAM_COOKIE_MODE`
    /// override, the bind host, and the deploy mode, return the cookie
    /// mode. Production callers read the env var once at startup and
    /// pass it in; tests pass it directly to avoid env-mutation races.
    pub(crate) fn detect(host: &str, deploy_mode: Option<&str>, explicit: Option<&str>) -> Self {
        if let Some(explicit) = explicit {
            match explicit.to_ascii_lowercase().as_str() {
                "same_origin" | "same-origin" | "sameorigin" => return Self::SameOrigin,
                "cross_origin" | "cross-origin" | "crossorigin" => return Self::CrossOrigin,
                "localhost_dev" | "localhost-dev" | "localhostdev" | "dev" => {
                    return Self::LocalhostDev
                }
                _ => {} // unrecognised — fall through to auto-detect
            }
        }
        if matches!(deploy_mode, Some(m) if m.eq_ignore_ascii_case("cloud")) {
            return Self::CrossOrigin;
        }
        if is_loopback_host(host) {
            return Self::LocalhostDev;
        }
        Self::SameOrigin
    }

    pub(crate) fn secure(self) -> bool {
        !matches!(self, Self::LocalhostDev)
    }

    pub(crate) fn same_site(self) -> tower_cookies::cookie::SameSite {
        match self {
            Self::CrossOrigin => tower_cookies::cookie::SameSite::Lax,
            _ => tower_cookies::cookie::SameSite::Strict,
        }
    }
}

pub(crate) fn is_loopback_host(host: &str) -> bool {
    matches!(host, "127.0.0.1" | "::1" | "localhost" | "0.0.0.0") || host.starts_with("127.")
}

//! `HttpTransport` — the typed wrapper that satisfies
//! `spiritstream_core::traits::Transport` for the Axum-backed HTTP surface.
//!
//! The bulk of the runtime logic still lives in `pub async fn run()` in
//! `lib.rs`; this struct exists so the `Transport` trait contract is honored
//! (every transport adapter has a concrete `impl Transport`). The
//! `spiritstream-server` binary delegates to `HttpTransport::serve` which
//! delegates to `run`. When a graceful-shutdown channel and ServiceRegistry-
//! based constructor land, the body of `run` moves
//! into `HttpTransport::serve` and `run` shrinks to a single call.

use std::sync::Arc;

use async_trait::async_trait;
use spiritstream_core::{traits::Transport, CoreError};

/// HTTP transport adapter. Today it owns no state of its own; future phases
/// thread a shutdown signal and an externally-built `ServiceRegistry` here.
#[derive(Debug, Default, Clone)]
pub struct HttpTransport;

impl HttpTransport {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl Transport for HttpTransport {
    async fn serve(self: Arc<Self>) -> Result<(), CoreError> {
        crate::run().await.map_err(|e| CoreError::Internal {
            context: format!("http transport: {e}"),
        })
    }

    async fn shutdown(&self) {
        // Wire a watch/Notify-based shutdown handle in a future change.
        // For now `serve` runs until the process receives a signal.
    }
}

//! Audit log read endpoint — `/api/v1/audit/log`.
//!
//! Reads + paginates the HMAC-chained audit log produced by
//! `AuditLogService`, plus a tamper-status banner field that drives
//! the red banner in the audit log UI.

use axum::{extract::State, Json};
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

use spiritstream_core::services::AuditChainStatus;

use crate::AppState;

/// Wire-mirror of [`AuditChainStatus`] with `ToSchema` for OpenAPI.
/// utoipa is a transport-only dep — keeping `ToSchema` on a core type
/// would leak the transport into core. The variants and field shapes
/// must stay in lockstep; the `From<AuditChainStatus>` impl below is
/// the single conversion point so any drift surfaces at compile time.
///
/// Serialises as a discriminated union on `state` so the TS client
/// reads `chain.state === 'tampered'` directly:
///
/// ```json
/// {"state": "ok", "entriesVerified": 42}
/// {"state": "tampered", "lastValidSequence": 5, "reason": "hmac mismatch at seq 6"}
/// {"state": "empty"}
/// ```
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(tag = "state", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum AuditChainStatusWire {
    /// Every entry's HMAC verified.
    Ok { entries_verified: u64 },
    /// Verification failed at the named sequence. The red banner
    /// displays `lastValidSequence` so the user knows how much of the
    /// log they can still trust.
    Tampered {
        last_valid_sequence: u64,
        reason: String,
    },
    /// Log file does not exist yet (fresh install).
    Empty,
}

impl From<AuditChainStatus> for AuditChainStatusWire {
    fn from(value: AuditChainStatus) -> Self {
        match value {
            AuditChainStatus::Ok { entries_verified } => {
                AuditChainStatusWire::Ok { entries_verified }
            }
            AuditChainStatus::Tampered {
                last_valid_sequence,
                reason,
            } => AuditChainStatusWire::Tampered {
                last_valid_sequence,
                reason,
            },
            AuditChainStatus::Empty => AuditChainStatusWire::Empty,
        }
    }
}

// ---------------------------------------------------------------------------
// Audit log — read endpoint.
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
pub struct AuditLogQuery {
    /// Skip this many leading entries (oldest first). Defaults to 0.
    #[serde(default)]
    skip: usize,
    /// Maximum entries to return. Defaults to 200. Hard-capped at 1000
    /// so a careless client can't OOM the server.
    #[serde(default)]
    limit: Option<usize>,
    /// When set, only entries whose `action.kind` matches this string
    /// are returned. Used to filter by kind
    /// (panic_triggered, chat_message_pii_blocked, oauth_refresh, …).
    #[serde(default)]
    kind: Option<String>,
}

#[derive(Serialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct AuditLogResponse {
    /// Total entries that survive the filter (before paging).
    pub total: usize,
    /// Page slice (oldest-first within the returned window).
    pub entries: Vec<serde_json::Value>,
    /// HMAC chain status. The audit-log UI inspects this on
    /// every fetch; a `tampered` value triggers the red banner.
    /// Always computed server-side against the on-disk log;
    /// clients cannot influence it.
    pub chain: AuditChainStatusWire,
}

/// `GET /api/v1/audit/log` — paginated, filterable read of the audit
/// log. Entries are serialised as-is from
/// [`spiritstream_core::services::AuditEntry`]. The response is wrapped
/// in an HMAC-verification status (`tampered: bool` + last known-good
/// sequence) so the UI can render the red banner.
#[utoipa::path(
    get,
    path = "/audit/log",
    tag = "safety",
    params(
        ("skip" = Option<usize>, Query, description = "Skip N entries (oldest first)."),
        ("limit" = Option<usize>, Query, description = "Max entries per page (≤ 1000)."),
        ("kind" = Option<String>, Query, description = "Filter by action kind."),
    ),
    responses(
        (status = 200, description = "Audit entries.", body = AuditLogResponse),
        (status = 500, description = "Internal error.", body = ApiErrorBody),
    ),
    security(("session_cookie" = []), ("bearer" = [])),
)]
pub async fn v1_audit_log(
    State(state): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<AuditLogQuery>,
) -> Result<Json<AuditLogResponse>, crate::ApiError> {
    // Verify the HMAC chain before serving entries. We surface the
    // chain status — Ok / Tampered / Empty — to the client either way
    // so the UI can show the tamper banner even when the user has
    // filtered the page to an empty result.
    //
    // G3: an Err from `verify_chain` is an I/O / read failure (the
    // chain file couldn't even be opened), NOT a tamper. Pre-G3 we
    // conflated the two by force-bucketing every Err into a
    // synthetic `Tampered { last_valid_sequence: 0, reason: ... }`
    // payload — that masked permission/disk errors as security events.
    // Now we propagate the read failure as 500 so operators see it
    // for what it is.
    let chain_status = state.audit.verify_chain()?;
    let chain: AuditChainStatusWire = chain_status.into();

    let entries = state.audit.entries()?;
    let filtered: Vec<serde_json::Value> = entries
        .into_iter()
        .filter(|e| match &q.kind {
            None => true,
            Some(k) => action_kind_str(&e.action) == k.as_str(),
        })
        .map(|e| serde_json::to_value(&e).unwrap_or(serde_json::Value::Null))
        .collect();
    let total = filtered.len();
    let skip = q.skip.min(total);
    let limit = q.limit.unwrap_or(200).min(1000);
    let page = filtered.into_iter().skip(skip).take(limit).collect();
    Ok(Json(AuditLogResponse {
        total,
        entries: page,
        chain,
    }))
}

fn action_kind_str(action: &spiritstream_core::services::AuditAction) -> &'static str {
    use spiritstream_core::services::AuditAction::*;
    match action {
        PanicTriggered { .. } => "panic_triggered",
        ChatMessagePiiBlocked { .. } => "chat_message_pii_blocked",
        ProfileSaved { .. } => "profile_saved",
        ProfileDeleted { .. } => "profile_deleted",
        OauthRefresh { .. } => "oauth_refresh",
        OauthRefreshUnusualLocation { .. } => "oauth_refresh_unusual_location",
        MachineKeyRotated { .. } => "machine_key_rotated",
        AnonymousModeToggled { .. } => "anonymous_mode_toggled",
        AppStarted => "app_started",
        AppStopped => "app_stopped",
        AuditLogTamperDetected { .. } => "audit_log_tamper_detected",
        ThemeValidationFailed { .. } => "theme_validation_failed",
        AppUpdateSignatureFailed { .. } => "app_update_signature_failed",
        ChatMessageSent { .. } => "chat_message_sent",
        ChatPlatformConnected { .. } => "chat_platform_connected",
        ChatPlatformDisconnected { .. } => "chat_platform_disconnected",
        DiscordWebhookSent { .. } => "discord_webhook_sent",
        SessionRevoked { .. } => "session_revoked",
        ConfirmTokenIssued { .. } => "confirm_token_issued",
    }
}

//! Chat log status / export / search handlers.
//!
//! K5 split: pulled out of `v1/chat.rs` so the orchestrator stays
//! under the 600 LOC ceiling. Each handler operates on the rotating
//! per-hour `chatlog_*.jsonl` files written by `ChatManager`.

use axum::{extract::State, Json};
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

use crate::AppState;

use super::{ChatAckResponse, ChatLogStatusWire};

#[utoipa::path(get, path = "/chat/log", tag = "chat",
    responses((status = 200, body = ChatLogStatusWire)),
    security(("session_cookie" = []), ("bearer" = [])))]
pub async fn v1_chat_log_status_proxy(
    State(state): State<AppState>,
) -> Result<Json<ChatLogStatusWire>, crate::ApiError> {
    let start_ms = state.chat_manager.log_session_start_ms();
    Ok(Json(ChatLogStatusWire {
        active: start_ms.is_some(),
        started_at: start_ms.unwrap_or(0),
    }))
}

#[derive(Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct ChatExportRequest {
    pub path: String,
}

#[utoipa::path(post, path = "/chat/log/export", tag = "chat",
    request_body = ChatExportRequest,
    responses(
        (status = 200, description = "Chat log exported.", body = ChatAckResponse),
        (status = 400, body = ApiErrorBody, description = "No active chat session."),
        (status = 403, body = ApiErrorBody, description = "Export path outside allowed root."),
        (status = 500, body = ApiErrorBody, description = "Internal error writing export."),
    ),
    security(("session_cookie" = []), ("bearer" = [])))]
pub async fn v1_chat_export_log_proxy(
    State(state): State<AppState>,
    axum::Json(req): axum::Json<ChatExportRequest>,
) -> Result<Json<ChatAckResponse>, crate::ApiError> {
    use chrono::{Local, TimeZone};
    use spiritstream_core::models::ChatMessage;
    use std::fs::File;
    use std::io::{BufRead, BufReader, BufWriter, Write};

    // Validate the user-supplied export path stays inside the
    // data dir or home dir before opening — path_validator catches `..`
    // traversal + symlink escapes.
    let export_path = std::path::PathBuf::from(&req.path);
    let mut allowed_dirs: Vec<&std::path::Path> = vec![state.app_data_dir.as_path()];
    if let Some(ref home) = state.home_dir {
        allowed_dirs.push(home.as_path());
    }
    spiritstream_core::services::validate_path_within_any(&export_path, &allowed_dirs)?;

    let start_ms = state.chat_manager.log_session_start_ms().ok_or_else(|| {
        spiritstream_core::CoreError::ValidationFailed {
            reasons: vec![spiritstream_core::errors::ValidationIssue {
                code: "no_active_chat_session".into(),
                message: "No active chat session to export".into(),
                path: None,
            }],
        }
    })?;
    state.chat_manager.flush_chat_logs().await?;
    let end_ms = Local::now().timestamp_millis();
    let start_dt = Local
        .timestamp_millis_opt(start_ms)
        .single()
        .unwrap_or_else(Local::now);
    let end_dt = Local
        .timestamp_millis_opt(end_ms)
        .single()
        .unwrap_or_else(Local::now);
    let hour_keys = crate::build_hour_keys(start_dt, end_dt);
    let mut writer = BufWriter::new(File::create(&req.path).map_err(|e| {
        spiritstream_core::CoreError::Internal {
            context: format!("Failed to create export file: {e}"),
        }
    })?);
    for key in hour_keys {
        let src_path = state.log_dir.join(format!("chatlog_{}.jsonl", key));
        if !src_path.exists() {
            continue;
        }
        let file = File::open(&src_path).map_err(|e| spiritstream_core::CoreError::Internal {
            context: format!("Failed to read chat log {}: {e}", src_path.display()),
        })?;
        let reader = BufReader::new(file);
        for line in reader.lines() {
            let line = line.map_err(|e| spiritstream_core::CoreError::Internal {
                context: format!("Failed to read chat log: {e}"),
            })?;
            if line.trim().is_empty() {
                continue;
            }
            if let Ok(message) = serde_json::from_str::<ChatMessage>(&line) {
                if message.timestamp >= start_ms && message.timestamp <= end_ms {
                    writer.write_all(line.as_bytes()).map_err(|e| {
                        spiritstream_core::CoreError::Internal {
                            context: format!("Failed to write export file: {e}"),
                        }
                    })?;
                    writer.write_all(b"\n").map_err(|e| {
                        spiritstream_core::CoreError::Internal {
                            context: format!("Failed to write export file: {e}"),
                        }
                    })?;
                }
            }
        }
    }
    writer
        .flush()
        .map_err(|e| spiritstream_core::CoreError::Internal {
            context: format!("Failed to finalize export file: {e}"),
        })?;
    Ok(Json(ChatAckResponse {}))
}

#[derive(Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct ChatSearchRequest {
    pub query: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub limit: Option<usize>,
}

// G5: search response is the fully-typed `Vec<ChatMessageWire>`. The
// wire mirror lives in `v1/chat_message_wire.rs` and is byte-identical
// to the ts-rs export at `@spiritstream/types/ChatMessage`. Replaces
// the prior `Vec<serde_json::Value>` placeholder.
#[utoipa::path(post, path = "/chat/log/search", tag = "chat",
    request_body = ChatSearchRequest,
    responses((status = 200, body = Vec<crate::v1::ChatMessageWire>,
        description = "Matching ChatMessage entries.")),
    security(("session_cookie" = []), ("bearer" = [])))]
pub async fn v1_chat_search_session_proxy(
    State(state): State<AppState>,
    axum::Json(req): axum::Json<ChatSearchRequest>,
) -> Result<Json<Vec<crate::v1::ChatMessageWire>>, crate::ApiError> {
    use chrono::{Local, TimeZone};
    use spiritstream_core::models::ChatMessage;
    use std::fs::File;
    use std::io::{BufRead, BufReader};

    let limit = req.limit.unwrap_or(500);
    let start_ms = state.chat_manager.log_session_start_ms().ok_or_else(|| {
        spiritstream_core::CoreError::ValidationFailed {
            reasons: vec![spiritstream_core::errors::ValidationIssue {
                code: "no_active_chat_session".into(),
                message: "No active chat session to search".into(),
                path: None,
            }],
        }
    })?;
    let query = req.query.trim().to_lowercase();
    if query.is_empty() {
        return Ok(Json(Vec::new()));
    }
    let end_ms = Local::now().timestamp_millis();
    let start_dt = Local
        .timestamp_millis_opt(start_ms)
        .single()
        .unwrap_or_else(Local::now);
    let end_dt = Local
        .timestamp_millis_opt(end_ms)
        .single()
        .unwrap_or_else(Local::now);
    let hour_keys = crate::build_hour_keys(start_dt, end_dt);
    let mut matches: Vec<ChatMessage> = Vec::new();
    for key in hour_keys {
        if matches.len() >= limit {
            break;
        }
        let src_path = state.log_dir.join(format!("chatlog_{}.jsonl", key));
        if !src_path.exists() {
            continue;
        }
        let file = File::open(&src_path).map_err(|e| spiritstream_core::CoreError::Internal {
            context: format!("Failed to read chat log {}: {e}", src_path.display()),
        })?;
        let reader = BufReader::new(file);
        for line in reader.lines() {
            if matches.len() >= limit {
                break;
            }
            let line = line.map_err(|e| spiritstream_core::CoreError::Internal {
                context: format!("Failed to read chat log: {e}"),
            })?;
            if line.trim().is_empty() {
                continue;
            }
            let message = match serde_json::from_str::<ChatMessage>(&line) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if message.timestamp < start_ms || message.timestamp > end_ms {
                continue;
            }
            let username = message.username.to_lowercase();
            let text = message.message.to_lowercase();
            if username.contains(&query) || text.contains(&query) {
                matches.push(message);
            }
        }
    }
    Ok(Json(
        matches.into_iter().map(Into::into).collect::<Vec<crate::v1::ChatMessageWire>>(),
    ))
}

//! Wire-mirror types for the chat surface — utoipa is transport-only,
//! so `ToSchema` lives on these mirrors rather than the core types.
//!
//! K5 split: pulled out of `v1/chat.rs` so the handlers file stays
//! under the 600 LOC ceiling. Same pattern as `v1/audit::AuditChainStatusWire`.

use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

use spiritstream_core::models::{
    ChatConfig, ChatConnectionStatus, ChatCredentials, ChatLogStatus, ChatPlatform,
    ChatPlatformStatus, ChatSendResult, TwitchAuth, YouTubeAuth,
};

/// Mirror of [`ChatPlatform`] with `ToSchema`.
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum ChatPlatformWire {
    Twitch,
    #[serde(rename = "tiktok")]
    TikTok,
    YouTube,
    Trovo,
    Kick,
    Facebook,
