    axum::extract::Path(name): axum::extract::Path<String>,
) -> Json<ProfileLockResponse> {
    let mut unlocked = state.unlocked_profiles.lock().await;
    unlocked.remove(&name);
    Json(ProfileLockResponse { name, locked: true })
}

